var NATE_SR_QUESTIONS=[{id:"ns_0001",categoria:"NATE_SR_CHILLERS",pregunta:"Un Chiller centr\xEDfugo con R-123 presenta una presi\xF3n de condensaci\xF3n inusualmente alta, pero el flujo de agua y la temperatura de entrada son nominales. \xBFCu\xE1l es el paso de diagn\xF3stico m\xE1s cr\xEDtico?",opciones:["Verificar la acumulaci\xF3n de gases no condensables y el funcionamiento de la unidad de purga.","Realizar una limpieza qu\xEDmica de los tubos del condensador para eliminar el fouling biol\xF3gico.","Ajustar la carga de refrigerante bas\xE1ndose en el subenfriamiento a la salida del condensador.","Comprobar la calibraci\xF3n de los sensores de presi\xF3n de descarga y de saturaci\xF3n del sistema."],respuesta_correcta:0,explicacion:"En chillers con R-123 (baja presi\xF3n), los gases no condensables (aire) elevan la presi\xF3n de condensaci\xF3n. La unidad de purga es el primer componente a verificar ya que su funci\xF3n es extraer estos gases del sistema."},{id:"ns_0002",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, se observa que el separador de aceite est\xE1 caliente pero la l\xEDnea de retorno de aceite al colector est\xE1 fr\xEDa. \xBFQu\xE9 indica este s\xEDntoma t\xE9cnico?",opciones:["El flotador interno del separador de aceite se encuentra bloqueado en la posici\xF3n de cerrado.","La v\xE1lvula diferencial de presi\xF3n del dep\xF3sito de aceite est\xE1 permitiendo un bypass excesivo.","Existe una migraci\xF3n de refrigerante l\xEDquido hacia el c\xE1rter de los compresores de baja etapa.","El elemento filtrante del separador est\xE1 saturado y requiere un reemplazo de servicio urgente."],respuesta_correcta:0,explicacion:"Si el separador est\xE1 caliente (recibe gas de descarga) pero la l\xEDnea de retorno est\xE1 fr\xEDa, el flotador est\xE1 trabado cerrado e impide que el aceite separado fluya de regreso al dep\xF3sito o los compresores."},{id:"ns_0003",categoria:"NATE_SR_CEO",pregunta:"Desde la perspectiva de gesti\xF3n financiera, \xBFcu\xE1l es el impacto principal de un alto \xEDndice de 'callbacks' en una empresa de servicios HVAC de gran escala?",opciones:["La erosi\xF3n del margen de beneficio neto debido a la duplicaci\xF3n de costos laborales directos.","El incremento en el costo de oportunidad por la p\xE9rdida de nuevas llamadas de ventas de alta.","La reducci\xF3n de la moral del equipo t\xE9cnico al ser asignados a corregir errores de sus colegas.","El aumento en las primas de seguros de responsabilidad civil por riesgos de da\xF1os a la propiedad."],respuesta_correcta:0,explicacion:"Los callbacks duplican costos de mano de obra directa (segundo viaje, segundo diagn\xF3stico) sin generar ingresos adicionales, erosionando directamente el margen de beneficio neto de la empresa."},{id:"ns_0004",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema Multi-split Inverter muestra un error de comunicaci\xF3n tras 20 minutos de operaci\xF3n. El voltaje entre S2 y S3 fluct\xFAa entre 0 y 30VDC. \xBFCu\xE1l es la causa probable?",opciones:["Interferencia electromagn\xE9tica causada por cables de comunicaci\xF3n no blindados cerca de AC.","Un fallo t\xE9rmico en el m\xF3dulo de potencia (IPM) de la unidad exterior al alcanzar carga alta.","La inversi\xF3n accidental de la polaridad en los cables de interconexi\xF3n entre las unidades.","Una fuga de corriente a tierra a trav\xE9s del devanado del motor del ventilador del evaporador."],respuesta_correcta:0,explicacion:"Los cables de comunicaci\xF3n no blindados cerca de l\xEDneas de AC captan interferencia electromagn\xE9tica (EMI), lo que corrompe la se\xF1al digital entre unidades y causa errores intermitentes tras estabilizarse la carga."},{id:"ns_0005",categoria:"NATE_SR_HEATPUMP",pregunta:"Durante el ciclo de deshielo en una bomba de calor, el soplador interior sigue operando pero el aire sale fr\xEDo. \xBFQu\xE9 componente del sistema ha fallado en activarse?",opciones:["El rel\xE9 de calefacci\xF3n auxiliar que compensa la ca\xEDda de temperatura durante el defrost.","La v\xE1lvula inversora que no logr\xF3 cambiar a la posici\xF3n de refrigeraci\xF3n para el deshielo.","El interruptor de presi\xF3n de alta que deber\xEDa detener el ventilador interior por seguridad.","El sensor de temperatura de la tuber\xEDa exterior que determina el fin del ciclo de deshielo."],respuesta_correcta:0,explicacion:"Durante el defrost, el sistema cambia a modo refrigeracion para calentar el serpentin exterior. El calefactor auxiliar (strip heat) debe activarse para compensar el aire frio; si su rele falla, el aire llega frio al interior."},{id:"ns_0006",categoria:"NATE_SR_CHILLERS",pregunta:"Se observa un aumento en el 'superheat' del vapor de succi\xF3n en un chiller de tornillo con inundaci\xF3n de evaporador. \xBFQu\xE9 ajuste de control es el m\xE1s adecuado?",opciones:["Verificar el nivel de l\xEDquido en el evaporador y calibrar el sensor de nivel ultras\xF3nico.","Incrementar la apertura de la v\xE1lvula de expansi\xF3n para saturar m\xE1s tubos del evaporador.","Reducir la velocidad del compresor para permitir que el refrigerante absorba m\xE1s calor total.","Purgar el exceso de aceite acumulado en el evaporador que est\xE1 aislando la transferencia."],respuesta_correcta:0,explicacion:"En un evaporador inundado, el superheat alto indica que el nivel de l\xEDquido no cubre suficientes tubos. El sensor de nivel ultras\xF3nico controla la alimentaci\xF3n de refrigerante, y su calibraci\xF3n incorrecta causa bajo nivel y alto superheat."},{id:"ns_0007",categoria:"NATE_SR_MANAGEMENT",pregunta:"Al supervisar una cuadrilla, nota que los t\xE9cnicos omiten la prueba de nitr\xF3geno a 500 PSI en sistemas de R-410A. \xBFCu\xE1l es el argumento t\xE9cnico m\xE1s s\xF3lido para corregirlos?",opciones:["La presi\xF3n de trabajo operativa puede exceder las presiones de prueba bajas, ocultando fugas.","El nitr\xF3geno a baja presi\xF3n no es suficiente para desplazar la humedad atrapada en el aceite.","Las normativas EPA exigen estrictamente el uso de presiones de prueba de grado industrial.","El uso de presiones inferiores invalida la garant\xEDa del fabricante sobre la estanqueidad total."],respuesta_correcta:0,explicacion:"El R-410A opera a presiones mucho m\xE1s altas que otros refrigerantes (alrededor de 400+ PSI en descarga). Si se prueba a baja presi\xF3n, fugas que solo aparecen bajo presi\xF3n operativa quedar\xE1n ocultas y causar\xE1n p\xE9rdida de gas en campo."},{id:"ns_0008",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete de 20 toneladas con dos etapas de enfriamiento, la primera etapa funciona pero la segunda no arranca a pesar del llamado del termostato. \xBFQu\xE9 revisar\xEDa primero?",opciones:["La l\xF3gica del controlador de economizador que puede estar bloqueando la segunda etapa mec\xE1nica.","El diferencial de presi\xF3n del interruptor de flujo de aire que solo permite una etapa por seguridad.","La continuidad de la bobina del contactor de la segunda etapa bajo condiciones de carga real.","El sensor de temperatura de aire de retorno que podr\xEDa estar detectando una carga insuficiente."],respuesta_correcta:0,explicacion:"En unidades paquete con economizador, el controlador puede bloquear la segunda etapa mec\xE1nica si detecta que el aire exterior libre puede satisfacer la demanda. Es la causa m\xE1s com\xFAn de que una etapa no arranque a pesar de la se\xF1al del termostato."},{id:"ns_0009",categoria:"NATE_SR_RACK",pregunta:"Un rack de baja temperatura experimenta un aumento en la presi\xF3n de succi\xF3n durante la noche. \xBFQu\xE9 factor ambiental o t\xE9cnico es el sospechoso m\xE1s probable?",opciones:["Un fallo en el ventilador del condensador remoto que reduce la capacidad de rechazo de calor.","La entrada en ciclo de deshielo simult\xE1neo de varias vitrinas debido a una mala programaci\xF3n.","Una v\xE1lvula de retenci\xF3n defectuosa en la descarga de un compresor que est\xE1 fuera de servicio.","El ajuste incorrecto de la v\xE1lvula EPR (Evaporator Pressure Regulator) en la l\xEDnea principal."],respuesta_correcta:1,explicacion:"Cuando varias vitrinas entran en deshielo simult\xE1neamente durante la noche, liberan vapor caliente al cabezal de succi\xF3n y elevan la presi\xF3n. Una programaci\xF3n escalonada de deshielos evita este problema."},{id:"ns_0010",categoria:"NATE_SR_CEO",pregunta:"Un CEO decide implementar un sistema de incentivos basado en la 'Eficiencia de Facturaci\xF3n' (Billable Efficiency). \xBFQu\xE9 m\xE9trica define mejor este concepto?",opciones:["El porcentaje de horas facturadas al cliente frente al total de horas laboradas por el t\xE9cnico.","La cantidad total de ingresos generados por cada t\xE9cnico en relaci\xF3n al costo de su veh\xEDculo.","El n\xFAmero de reparaciones exitosas realizadas en el primer intento sin necesidad de retorno.","La reducci\xF3n porcentual en el inventario de piezas no utilizadas que se mantienen en la van."],respuesta_correcta:0,explicacion:"La Eficiencia de Facturaci\xF3n (Billable Efficiency) mide el porcentaje de horas que el t\xE9cnico factura al cliente vs. las horas totales que la empresa le paga, revelando cu\xE1nto tiempo productivo realmente genera ingresos."},{id:"ns_0011",categoria:"NATE_SR_CHILLERS",pregunta:"En un chiller centr\xEDfugo, el fen\xF3meno de 'Surge' (pumping) ocurre principalmente cuando existe una discrepancia cr\xEDtica entre:",opciones:["La elevaci\xF3n de presi\xF3n requerida por el condensador y la capacidad de flujo del impulsor.","La temperatura del agua de entrada al evaporador y el punto de consigna del termostato.","El nivel de aceite en el c\xE1rter y la presi\xF3n de lubricaci\xF3n en los cojinetes de alta velocidad.","La densidad del refrigerante l\xEDquido y la apertura de la v\xE1lvula de expansi\xF3n electr\xF3nica."],respuesta_correcta:0,explicacion:"El surge ocurre cuando el compresor centr\xEDfugo no puede generar suficiente elevaci\xF3n de presi\xF3n (lift) para vencer la diferencia entre condensador y evaporador, causando una reversi\xF3n del flujo de gas en el impulsor."},{id:"ns_0012",categoria:"NATE_SR_RACK",pregunta:"Se detecta una alta temperatura de descarga en un compresor de un rack paralelo, pero las presiones son normales. \xBFQu\xE9 debe revisar el t\xE9cnico Senior?",opciones:["El sobrecalentamiento excesivo en la succi\xF3n o una falla en las v\xE1lvulas internas del plato.","La saturaci\xF3n del filtro deshidratador que limita el flujo de refrigerante hacia el evaporador.","El ajuste del interruptor de seguridad de alta presi\xF3n que podr\xEDa estar actuando prematuramente.","La velocidad del ventilador del condensador que no est\xE1 evacuando el calor de forma eficiente."],respuesta_correcta:0,explicacion:"Con presiones normales pero descarga alta, la causa m\xE1s probable es un sobrecalentamiento excesivo de succi\xF3n o v\xE1lvulas de plato da\xF1adas que permiten re-compresi\xF3n interna, elevando la temperatura de descarga sin alterar las presiones del sistema."},{id:"ns_0013",categoria:"NATE_SR_CEO",pregunta:"Un CEO analiza un reporte donde el 'Average Ticket' ha bajado un 20% a pesar de tener el mismo volumen de llamadas. \xBFCu\xE1l es la causa operativa m\xE1s probable?",opciones:["Los t\xE9cnicos est\xE1n realizando reparaciones menores en lugar de identificar fallas sist\xE9micas.","El costo de las piezas ha disminuido gracias a una mejor negociaci\xF3n con los proveedores.","El departamento de despacho est\xE1 enviando a los t\xE9cnicos m\xE1s cercanos en lugar de los m\xE1s aptos.","La competencia ha reducido sus precios obligando a la empresa a realizar descuentos directos."],respuesta_correcta:0,explicacion:"Cuando el Average Ticket baja sin cambios en volumen, generalmente significa que los t\xE9cnicos est\xE1n haciendo reparaciones r\xE1pidas y superficiales en lugar de diagnosticar la causa ra\xEDz del problema."},{id:"ns_0014",categoria:"NATE_SR_MINISPLIT",pregunta:"Al instalar un sistema VRF, se encuentra que la tuber\xEDa de comunicaci\xF3n excede la longitud m\xE1xima permitida. \xBFQu\xE9 riesgo t\xE9cnico es el m\xE1s cr\xEDtico?",opciones:["La ca\xEDda de voltaje en la se\xF1al de datos causar\xE1 errores de sincronizaci\xF3n intermitentes.","El retorno de aceite al compresor ser\xE1 insuficiente causando una falla mec\xE1nica prematura.","La carga de refrigerante adicional requerida exceder\xE1 la capacidad del tanque receptor.","El tiempo de respuesta de las v\xE1lvulas de expansi\xF3n ser\xE1 demasiado lento para la carga."],respuesta_correcta:0,explicacion:"Cuando la tuber\xEDa de comunicaci\xF3n excede la longitud m\xE1xima, la resistencia del cable causa ca\xEDda de voltaje en la se\xF1al de datos, generando errores de sincronizaci\xF3n entre la unidad exterior y las interiores."},{id:"ns_0015",categoria:"NATE_SR_HVAC",pregunta:"Un sistema de conductos presenta ruidos de 'booming' al arrancar el soplador. Desde una perspectiva de dise\xF1o Senior, \xBFcu\xE1l es la soluci\xF3n t\xE9cnica?",opciones:["Instalar refuerzos en cruz en los paneles de los conductos o a\xF1adir juntas de expansi\xF3n.","Aumentar la velocidad del motor del soplador para estabilizar la presi\xF3n est\xE1tica interna.","Reemplazar el filtro de aire por uno de menor ca\xEDda de presi\xF3n para reducir la turbulencia.","Cerrar parcialmente las rejillas de suministro para equilibrar la contrapresi\xF3n del sistema."],respuesta_correcta:0,explicacion:"Los ruidos de 'booming' ocurren cuando los paneles del conducto flexionan por cambios bruscos de presi\xF3n al arrancar el soplador. Los refuerzos en cruz rigidizan los paneles y las juntas de expansi\xF3n absorben el movimiento, eliminando la vibraci\xF3n."},{id:"ns_0016",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calefacci\xF3n, una bomba de calor se bloquea por alta presi\xF3n. El filtro est\xE1 limpio y el soplador funciona. \xBFQu\xE9 componente est\xE1 fallando?",opciones:["La v\xE1lvula de expansi\xF3n de la unidad interior est\xE1 bloqueada o el orificio est\xE1 obstruido.","La v\xE1lvula inversora no est\xE1 desviando suficiente gas caliente hacia el serpent\xEDn exterior.","El sensor de temperatura ambiente exterior est\xE1 enviando una se\xF1al de fr\xEDo extremo falsa.","El acumulador de succi\xF3n tiene un exceso de aceite que reduce el volumen \xFAtil de gas."],respuesta_correcta:0,explicacion:"En modo calor, el serpentin interior es el condensador. Si la TXV interior o el orificio esta bloqueado, el refrigerante no puede fluir y la presion de descarga sube hasta disparar el switch de alta presion."},{id:"ns_0017",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un l\xEDder de cuadrilla nota que los t\xE9cnicos no est\xE1n utilizando la bomba de vac\xEDo de 2 etapas correctamente. \xBFCu\xE1l es el error de procedimiento m\xE1s com\xFAn?",opciones:["No cambiar el aceite de la bomba despu\xE9s de cada proceso de evacuaci\xF3n en sistemas grandes.","Utilizar mangueras de carga est\xE1ndar de 1/4 en lugar de mangueras de vac\xEDo de gran di\xE1metro.","Conectar el vacu\xF3metro directamente a la bomba en lugar de hacerlo en el punto m\xE1s alejado.","Abrir el lastre de gas (gas ballast) durante todo el proceso de vac\xEDo en lugar de solo al inicio."],respuesta_correcta:1,explicacion:'Las mangueras de 1/4" crean una restricci\xF3n severa que limita la capacidad de evacuaci\xF3n de la bomba. Mangueras de mayor di\xE1metro (3/8" o 1/2") permiten un flujo adecuado para alcanzar vac\xEDo profundo en tiempo razonable.'},{id:"ns_0018",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete con economizador introduce aire exterior cuando no deber\xEDa. \xBFQu\xE9 l\xF3gica de control Senior explica este comportamiento err\xE1tico?",opciones:["El sensor de entalp\xEDa exterior est\xE1 defectuoso o mal calibrado respecto a la humedad.","El motor del damper ha perdido el torque necesario para cerrar contra la presi\xF3n del aire.","El termostato de la zona est\xE1 configurado en modo ocupado permanentemente por el usuario.","El interruptor de l\xEDmite de aire mezclado est\xE1 puenteado para evitar paros por congelaci\xF3n."],respuesta_correcta:0,explicacion:"Un sensor de entalp\xEDa defectuoso env\xEDa lecturas err\xF3neas al controlador, haci\xE9ndole creer que el aire exterior es favorable cuando en realidad no lo es. Esto causa que el damper abra innecesariamente, introduciendo aire caliente o h\xFAmedo."},{id:"ns_0019",categoria:"NATE_SR_CHILLERS",pregunta:"Al realizar una prueba de espectro de vibraci\xF3n en un chiller, se detecta una frecuencia inusual en los cojinetes. \xBFQu\xE9 acci\xF3n debe tomar un CEO?",opciones:["Programar un paro preventivo inmediato para evitar un fallo catastr\xF3fico del equipo.","Ignorar la lectura hasta que el aumento en el consumo el\xE9ctrico confirme el desgaste.","Aumentar la viscosidad del aceite lubricante para amortiguar la vibraci\xF3n detectada.","Delegar la decisi\xF3n al t\xE9cnico de nivel b\xE1sico que realiza el mantenimiento de rutina."],respuesta_correcta:0,explicacion:"Una frecuencia anormal de vibraci\xF3n en cojinetes indica desgaste inminente. Un paro preventivo inmediato evita un fallo catastr\xF3fico que podr\xEDa destruir el compresor y causar una p\xE9rdida total del equipo."},{id:"ns_0020",categoria:"NATE_SR_RACK",pregunta:"En un sistema de refrigeraci\xF3n de CO2 (Transcr\xEDtico), la presi\xF3n de gas de salida excede el punto cr\xEDtico. \xBFC\xF3mo debe responder el sistema de control?",opciones:["Modulando la v\xE1lvula de alta presi\xF3n para optimizar el enfriamiento del gas en el gas-cooler.","Apagando los compresores inmediatamente para evitar una explosi\xF3n por sobrepresi\xF3n de gas.","Inyectando refrigerante l\xEDquido directamente en la succi\xF3n para bajar la entalp\xEDa del gas.","Abriendo las v\xE1lvulas de bypass hacia el recibidor para igualar las presiones de etapa."],respuesta_correcta:0,explicacion:"En operaci\xF3n transcr\xEDtica del CO2, el control modula la v\xE1lvula de alta presi\xF3n para optimizar la presi\xF3n del gas-cooler y maximizar la eficiencia del ciclo, ya que por encima del punto cr\xEDtico el CO2 no se condensa sino que se enfr\xEDa como gas denso."},{id:"ns_0021",categoria:"NATE_SR_CEO",pregunta:"Si una empresa HVAC decide subcontratar la instalaci\xF3n de ductos, \xBFcu\xE1l es el riesgo financiero m\xE1s latente para el CEO?",opciones:["La p\xE9rdida de control sobre la calidad final que impacta directamente en las garant\xEDas.","El aumento en los costos fijos de la empresa al tener que pagar facturas externas fijas.","La dificultad para programar las visitas de mantenimiento preventivo con los clientes.","La reducci\xF3n en la compra de materiales por volumen que afecta los descuentos de f\xE1brica."],respuesta_correcta:0,explicacion:"Al subcontratar instalaciones, el CEO pierde control directo sobre la calidad del trabajo, lo que puede resultar en reclamos de garant\xEDa costosos que la empresa debe asumir ante el cliente final."},{id:"ns_0022",categoria:"NATE_SR_HVAC",pregunta:"Un motor ECM de velocidad variable no arranca. Al medir la se\xF1al de control, hay 24V presentes. \xBFQu\xE9 debe diagnosticar un Senior?",opciones:["El m\xF3dulo de control del motor ha fallado internamente debido a picos de voltaje.","Los rodamientos del motor est\xE1n bloqueados mec\xE1nicamente por falta de lubricaci\xF3n.","El termostato no est\xE1 enviando la se\xF1al de PWM necesaria para definir la velocidad.","El capacitor de marcha est\xE1 desvalorizado y no provee el torque inicial de arranque."],respuesta_correcta:0,explicacion:"Los motores ECM requieren una se\xF1al PWM del termostato o placa de control para definir la velocidad de operaci\xF3n. Tener 24V presentes solo confirma alimentaci\xF3n, pero si el m\xF3dulo interno fall\xF3 por picos de voltaje, el motor no puede procesar la se\xF1al ni arrancar."},{id:"ns_0023",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller de absorci\xF3n utiliza Bromuro de Litio. Si la soluci\xF3n se cristaliza, \xBFcu\xE1l es la causa operativa m\xE1s frecuente?",opciones:["Una ca\xEDda repentina de la temperatura de la soluci\xF3n durante un paro de emergencia.","Un exceso de calor en el generador que evapora demasiado refrigerante del sistema.","La infiltraci\xF3n de aire atmosf\xE9rico que reduce la eficiencia del proceso de absorci\xF3n.","El uso de agua de enfriamiento con una dureza mineral por encima de los l\xEDmites."],respuesta_correcta:0,explicacion:"La cristalizaci\xF3n del LiBr ocurre cuando la concentraci\xF3n de la soluci\xF3n aumenta excesivamente. Una ca\xEDda repentina de temperatura durante un paro de emergencia reduce la solubilidad del LiBr, provocando cristalizaci\xF3n."},{id:"ns_0024",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema inverter reporta error de sobrecorriente en el compresor. Al medir las bobinas, todas dan 1.2 Ohms. \xBFQu\xE9 concluye un Senior?",opciones:["El compresor est\xE1 mec\xE1nicamente trabado o el IPM de la placa exterior est\xE1 da\xF1ado.","Existe un cortocircuito entre las espiras del motor que no se refleja en la resistencia.","La carga de refrigerante es insuficiente, causando que el compresor trabaje forzado.","Los cables de alimentaci\xF3n tienen una secci\xF3n transversal inadecuada para la corriente."],respuesta_correcta:0,explicacion:"Si las tres bobinas miden igual (1.2 Ohms) el motor est\xE1 el\xE9ctricamente sano; el error de sobrecorriente apunta a un compresor mec\xE1nicamente trabado o un IPM da\xF1ado que env\xEDa corriente excesiva al motor."},{id:"ns_0025",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor geot\xE9rmica, el diferencial de temperatura del lazo de agua es de solo $2^{\\circ}F$. \xBFQu\xE9 indica este valor?",opciones:["El flujo de agua es excesivo o la transferencia de calor en el intercambiador es nula.","La bomba de circulaci\xF3n est\xE1 fallando y no mueve el volumen de agua necesario.","El intercambiador de calor de placas tiene una fuga interna entre refrigerante y agua.","La temperatura del subsuelo es demasiado alta para el modo de operaci\xF3n actual."],respuesta_correcta:0,explicacion:"Un diferencial de solo 2F entre entrada y salida del lazo indica flujo de agua excesivo o nula transferencia de calor en el intercambiador. Lo normal es un delta de 10-12F en geotermica."},{id:"ns_0026",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior observa que sus ayudantes no usan 'brazing shield' al soldar cerca de v\xE1lvulas de servicio. \xBFCu\xE1l es la consecuencia?",opciones:["El calor excesivo destruye los sellos internos de tefl\xF3n causando fugas permanentes.","La formaci\xF3n de escamas de \xF3xido en el interior de la tuber\xEDa obstruir\xE1 los filtros.","El debilitamiento estructural del cobre en el punto de uni\xF3n por recocido excesivo.","La alteraci\xF3n de la composici\xF3n qu\xEDmica de la soldadura de plata por sobrecalentamiento."],respuesta_correcta:0,explicacion:"Las v\xE1lvulas de servicio contienen sellos internos de tefl\xF3n o nylon que se derriten a temperaturas relativamente bajas. Sin brazing shield, el calor de la antorcha da\xF1a estos sellos y provoca fugas que solo se detectan despu\xE9s de cargar el sistema."},{id:"ns_0027",categoria:"NATE_SR_PACKAGE",pregunta:"Al realizar un retrofit de refrigerante en una unidad paquete vieja, \xBFcu\xE1l es la mayor preocupaci\xF3n t\xE9cnica para un Senior?",opciones:["La compatibilidad del aceite mineral original con el nuevo refrigerante HFC/HFO.","La capacidad del condensador para manejar las nuevas presiones de descarga altas.","El ajuste de las v\xE1lvulas de expansi\xF3n t\xE9rmicas para el nuevo diagrama de presi\xF3n.","El impacto en la eficiencia energ\xE9tica estacional (SEER) tras el cambio de gas."],respuesta_correcta:0,explicacion:"Los refrigerantes HFC/HFO no son miscibles con aceite mineral, lo que causa falta de lubricaci\xF3n y falla del compresor. Es obligatorio cambiar a aceite POE o AB antes de cargar el nuevo refrigerante."},{id:"ns_0028",categoria:"NATE_SR_RACK",pregunta:"Un rack de media temperatura usa descongelaci\xF3n por gas caliente. Una vitrina no descongela. \xBFQu\xE9 componente revisar\xEDa?",opciones:["La v\xE1lvula de retenci\xF3n en el cabezal de drenaje o la solenoide de gas caliente.","El reloj de deshielo principal que controla la rotaci\xF3n de los sectores del rack.","La presi\xF3n del recibidor que podr\xEDa estar por debajo del diferencial de empuje.","El sensor de temperatura de ambiente que bloquea el deshielo por falta de carga."],respuesta_correcta:0,explicacion:"Si solo una vitrina no descongela, el problema es local: la solenoide de gas caliente de esa vitrina puede no estar abriendo, o la v\xE1lvula de retenci\xF3n (check) en el drenaje impide que el gas caliente fluya por el evaporador."},{id:"ns_0029",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC busca reducir el 'Liability Risk'. \xBFCu\xE1l de estas pol\xEDticas es la m\xE1s efectiva?",opciones:["Documentaci\xF3n fotogr\xE1fica obligatoria de antes y despu\xE9s en cada orden de trabajo.","Comprar herramientas de marca premium para reducir la probabilidad de accidentes.","Contratar solo t\xE9cnicos con m\xE1s de 15 a\xF1os de experiencia probada en el campo.","Instalar rastreadores GPS en las unidades para monitorear la velocidad de manejo."],respuesta_correcta:0,explicacion:"La documentaci\xF3n fotogr\xE1fica de antes y despu\xE9s crea evidencia objetiva que protege a la empresa contra reclamos falsos y demuestra el estado previo del equipo ante cualquier disputa legal."},{id:"ns_0030",categoria:"NATE_SR_HVAC",pregunta:"Un sistema presenta un bajo sobrecalentamiento y un bajo subenfriamiento simult\xE1neamente. \xBFQu\xE9 indica este escenario?",opciones:["Una v\xE1lvula de expansi\xF3n sobredimensionada o que ha perdido el control del flujo.","Una restricci\xF3n parcial en la l\xEDnea de l\xEDquido antes del dispositivo de expansi\xF3n.","Una falta severa de carga de refrigerante combinada con baja carga t\xE9rmica.","El compresor tiene una eficiencia volum\xE9trica baja debido a desgaste de anillos."],respuesta_correcta:0,explicacion:"Bajo sobrecalentamiento indica exceso de refrigerante en el evaporador, y bajo subenfriamiento indica poco l\xEDquido en el condensador. Una TXV sobredimensionada alimenta demasiado refrigerante al evaporador, vaciando el condensador y reduciendo ambos valores simult\xE1neamente."},{id:"ns_0031",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller enfriado por aire opera con una temperatura de descarga excesiva. El condensador est\xE1 limpio y los ventiladores giran a RPM nominales. \xBFQu\xE9 debe investigar el Senior?",opciones:["La presencia de gases no condensables atrapados en la parte superior del condensador.","El ajuste del set-point del controlador que regula la velocidad de los ventiladores.","Una posible inundaci\xF3n de refrigerante l\xEDquido en el acumulador de la l\xEDnea de succi\xF3n.","La ca\xEDda de presi\xF3n de agua a trav\xE9s del evaporador debido a una bomba defectuosa."],respuesta_correcta:0,explicacion:"Si el condensador est\xE1 limpio y los ventiladores funcionan correctamente, los gases no condensables atrapados en la parte superior del condensador son la causa m\xE1s probable de una temperatura de descarga excesiva."},{id:"ns_0032",categoria:"NATE_SR_RACK",pregunta:"En un rack con compresores tipo scroll, se escucha un ruido met\xE1lico agudo tras un ciclo de deshielo. \xBFCu\xE1l es la preocupaci\xF3n t\xE9cnica inmediata del l\xEDder?",opciones:["Un retorno de refrigerante l\xEDquido que causa un esfuerzo mec\xE1nico en las espirales.","La falta de aceite debido a una falla en el sistema de gesti\xF3n de retorno del rack.","Una rotaci\xF3n inversa del compresor causada por una falla en el rel\xE9 de secuencia.","El desprendimiento de part\xEDculas met\xE1licas del filtro de succi\xF3n hacia la c\xE1mara."],respuesta_correcta:0,explicacion:"Tras un deshielo, el refrigerante l\xEDquido acumulado puede regresar al compresor scroll causando golpe de l\xEDquido (slugging). Las espirales del scroll no toleran l\xEDquido incompresible y producen un ruido met\xE1lico agudo caracter\xEDstico."},{id:"ns_0033",categoria:"NATE_SR_CEO",pregunta:"Al evaluar el 'Cost of Goods Sold' (COGS), un CEO nota un aumento del 15% en suministros gen\xE9ricos. \xBFQu\xE9 acci\xF3n estrat\xE9gica recomienda para el control?",opciones:["Centralizar las compras y establecer un sistema de inventario por c\xF3digo de barras.","Reducir el salario variable de los t\xE9cnicos para compensar el gasto extra en piezas.","Cambiar a proveedores locales de menor costo sin evaluar la calidad de los materiales.","Eliminar el stock de las camionetas y obligar al t\xE9cnico a ir a la tienda por cada pieza."],respuesta_correcta:0,explicacion:"Centralizar las compras y usar un sistema de inventario con c\xF3digo de barras permite controlar el consumo, detectar fugas de material y negociar mejores precios por volumen con proveedores."},{id:"ns_0034",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema Inverter de 1 a 1 presenta una presi\xF3n de succi\xF3n muy baja y un sobrecalentamiento de 30\xB0F. \xBFQu\xE9 indica este escenario t\xE9cnico?",opciones:["Existe una restricci\xF3n severa en el orificio de la v\xE1lvula de expansi\xF3n electr\xF3nica.","El sistema tiene una carga excesiva de refrigerante que inunda el serpent\xEDn interior.","El motor del ventilador del evaporador est\xE1 girando a una velocidad insuficiente.","La placa de control exterior est\xE1 enviando una se\xF1al err\xF3nea de modulaci\xF3n al IPM."],respuesta_correcta:0,explicacion:"Una presi\xF3n de succi\xF3n muy baja con sobrecalentamiento alto (30\xB0F) indica que el refrigerante no fluye adecuadamente al evaporador, t\xEDpico de una restricci\xF3n severa en la v\xE1lvula de expansi\xF3n electr\xF3nica (EEV)."},{id:"ns_0035",categoria:"NATE_SR_HVAC",pregunta:"Se instala un sistema de zonificaci\xF3n (Zoning) y el cliente se queja de flujo de aire excesivo en zonas peque\xF1as. \xBFCu\xE1l es el error de dise\xF1o?",opciones:["La omisi\xF3n de un ducto de bypass con damper barom\xE9trico o un soplador con ECM.","El uso de rejillas de suministro sobredimensionadas para el tama\xF1o de la habitaci\xF3n.","Un termostato mal ubicado que no detecta el cambio de temperatura de la zona.","La falta de aislamiento t\xE9rmico en los conductos que atraviesan \xE1reas no acondicionadas."],respuesta_correcta:0,explicacion:"Sin un ducto de bypass o un soplador ECM que module el flujo, cuando las zonas peque\xF1as son las \xFAnicas demandando, todo el volumen de aire del sistema se fuerza a trav\xE9s de conductos reducidos, creando exceso de presi\xF3n y flujo en esas zonas."},{id:"ns_0036",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor tiene una l\xEDnea de succi\xF3n escarchada hasta el compresor. \xBFQu\xE9 componente defectuoso causar\xEDa esto?",opciones:["La v\xE1lvula de expansi\xF3n exterior (TXV) que est\xE1 atascada en posici\xF3n abierta total.","La v\xE1lvula inversora que est\xE1 fugando gas caliente internamente hacia la succi\xF3n.","El sensor de defrost que no activa el ciclo de descongelamiento por temperatura.","El ventilador interior que tiene el capacitor de marcha degradado o desvalorizado."],respuesta_correcta:0,explicacion:"Una TXV exterior atascada abierta permite paso excesivo de refrigerante liquido, inundando el serpentin exterior y causando que el liquido no evaporado regrese por la succion hasta escarchar la linea y el compresor."},{id:"ns_0037",categoria:"NATE_SR_MANAGEMENT",pregunta:"Durante un entrenamiento de seguridad OSHA, un l\xEDder Senior enfatiza el uso de doble bloqueo (LOTO). \xBFEn qu\xE9 situaci\xF3n es m\xE1s cr\xEDtico este protocolo?",opciones:["Al realizar el reemplazo de un compresor en un rack que tiene m\xFAltiples fuentes.","Al limpiar los serpentines de un condensador con agua a presi\xF3n en una unidad paquete.","Al cambiar un filtro deshidratador en una unidad residencial de 3 toneladas est\xE1ndar.","Al verificar el voltaje de control en el transformador de una manejadora de aire."],respuesta_correcta:0,explicacion:"Un rack comercial puede tener m\xFAltiples fuentes de energ\xEDa el\xE9ctrica (circuitos de compresores, ventiladores, controles). El LOTO (Lock Out/Tag Out) doble es cr\xEDtico cuando hay varias fuentes que podr\xEDan energizar el equipo accidentalmente mientras se trabaja."},{id:"ns_0038",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de 15 toneladas presenta un Delta T de solo 10\xB0F en enfriamiento. El flujo de aire es nominal. \xBFQu\xE9 debe revisar el Senior?",opciones:["La eficiencia volum\xE9trica de los compresores y la posible mezcla en la inversora.","La limpieza del filtro de aire y la obstrucci\xF3n de los difusores de suministro.","La carga de refrigerante bas\xE1ndose \xFAnicamente en la presi\xF3n de alta del sistema.","La configuraci\xF3n de los jumpers en la placa de control para la velocidad del motor."],respuesta_correcta:0,explicacion:"Con flujo de aire normal, un Delta T bajo (10\xB0F vs. 18-22\xB0F esperado) indica falta de capacidad de enfriamiento. La causa m\xE1s probable es baja eficiencia volum\xE9trica del compresor o v\xE1lvulas internas da\xF1adas que permiten bypass de gas."},{id:"ns_0039",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo de baja temperatura, el acumulador de succi\xF3n est\xE1 constantemente lleno de l\xEDquido. \xBFCu\xE1l es el riesgo operativo?",opciones:["La diluci\xF3n del aceite lubricante que provoca el desgaste acelerado de los cojinetes.","El aumento excesivo del consumo el\xE9ctrico por la compresi\xF3n de vapor saturado.","La apertura de las v\xE1lvulas de seguridad del rack por un aumento de presi\xF3n s\xFAbito.","La congelaci\xF3n del retorno de aceite que bloquea el suministro a los compresores."],respuesta_correcta:0,explicacion:"Un acumulador constantemente lleno de l\xEDquido indica exceso de retorno de refrigerante que diluye el aceite lubricante en los c\xE1rteres. Esto reduce la viscosidad del aceite y acelera el desgaste de cojinetes y partes m\xF3viles."},{id:"ns_0040",categoria:"NATE_SR_CEO",pregunta:"Como CEO, \xBFcu\xE1l es el impacto legal principal de no mantener registros de recuperaci\xF3n de refrigerante seg\xFAn la Secci\xF3n 608 de la EPA?",opciones:["Multas civiles federales sustanciales por cada d\xEDa de incumplimiento de registro.","La cancelaci\xF3n autom\xE1tica de la licencia de contratista estatal de la empresa.","La p\xE9rdida de la garant\xEDa de f\xE1brica en todos los equipos instalados ese a\xF1o.","El aumento de las tasas de inter\xE9s en los pr\xE9stamos bancarios para capital de trabajo."],respuesta_correcta:0,explicacion:"La EPA impone multas civiles federales significativas (hasta $44,539 por d\xEDa por violaci\xF3n bajo la Clean Air Act Secci\xF3n 608) por no mantener registros adecuados de recuperaci\xF3n de refrigerante."},{id:"ns_0041",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'low oil pressure differential'. El nivel de aceite es correcto. \xBFQu\xE9 componente t\xE9cnico es el sospechoso?",opciones:["La bomba de aceite mec\xE1nica o el sensor de presi\xF3n diferencial defectuoso.","El calentador de c\xE1rter que no est\xE1 evaporando el refrigerante del aceite.","La v\xE1lvula de expansi\xF3n que est\xE1 alimentando demasiado l\xEDquido al evaporador.","El filtro de succi\xF3n del compresor que tiene una ca\xEDda de presi\xF3n excesiva."],respuesta_correcta:0,explicacion:"Con nivel de aceite correcto, una baja presi\xF3n diferencial de aceite apunta a una bomba de aceite defectuosa que no genera suficiente presi\xF3n, o un sensor de presi\xF3n diferencial que lee incorrectamente."},{id:"ns_0042",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRF tiene un error de 'Master/Slave address conflict'. \xBFCu\xE1l es el procedimiento de resoluci\xF3n Senior?",opciones:["Resetear los dip-switches de cada unidad interior y reiniciar el sistema completo.","Reemplazar la placa electr\xF3nica de la unidad exterior por una versi\xF3n m\xE1s nueva.","Cambiar el cableado de comunicaci\xF3n por uno de mayor calibre para reducir ruido.","Desconectar la alimentaci\xF3n el\xE9ctrica de las unidades interiores durante 24 horas."],respuesta_correcta:0,explicacion:"El conflicto de direcciones Master/Slave se resuelve reseteando los dip-switches de cada unidad interior para reasignar direcciones \xFAnicas seg\xFAn el manual, y luego reiniciando el sistema completo."},{id:"ns_0043",categoria:"NATE_SR_HVAC",pregunta:"Un compresor residencial falla por 'acid burn'. Al instalar el nuevo, \xBFcu\xE1l es el paso de seguridad t\xE9cnica innegociable?",opciones:["Instalar un filtro de succi\xF3n de alta capacidad y realizar cambios de aceite.","Aumentar la carga de refrigerante un 10% para diluir los restos de \xE1cido residual.","Sustituir toda la l\xEDnea de cobre de la casa para asegurar la pureza del sistema.","Utilizar un fundente de soldadura m\xE1s fuerte para evitar fugas en las uniones."],respuesta_correcta:0,explicacion:"Cuando un compresor falla por 'acid burn', los \xE1cidos contaminan todo el sistema. Un filtro de succi\xF3n de alta capacidad atrapa los residuos \xE1cidos y part\xEDculas, y los cambios de aceite posteriores eliminan la contaminaci\xF3n remanente para proteger el compresor nuevo."},{id:"ns_0044",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete con gas, se detecta mon\xF3xido de carbono en el flujo de aire. \xBFQu\xE9 diagn\xF3stico t\xE9cnico confirma la falla?",opciones:["Una fractura en el intercambiador de calor que permite la mezcla de gases.","Un sensor de llama sucio que causa una combusti\xF3n incompleta en el quemador.","Una presi\xF3n de gas de entrada demasiado alta para el dise\xF1o del colector.","La falta de ventilaci\xF3n adecuada en el cuarto de m\xE1quinas donde est\xE1 el equipo."],respuesta_correcta:0,explicacion:"La presencia de CO en el flujo de aire de suministro indica que los productos de combusti\xF3n est\xE1n cruzando al lado del aire acondicionado. Esto solo ocurre cuando hay una grieta o fractura en el intercambiador de calor, lo cual es una emergencia de seguridad."},{id:"ns_0045",categoria:"NATE_SR_CEO",pregunta:"Un CEO eval\xFAa la compra de software de gesti\xF3n de campo (FSM). \xBFCu\xE1l es el principal beneficio operativo buscado?",opciones:["La optimizaci\xF3n de rutas y la visibilidad en tiempo real de la productividad t\xE9cnica.","La capacidad de rastrear las conversaciones privadas de los t\xE9cnicos con clientes.","El ahorro en el costo de impresi\xF3n de facturas y formularios de servicio f\xEDsicos.","La reducci\xF3n de la necesidad de tener un equipo de soporte t\xE9cnico en la oficina."],respuesta_correcta:0,explicacion:"El software FSM (Field Service Management) optimiza rutas de despacho y da visibilidad en tiempo real sobre la ubicaci\xF3n y productividad de cada t\xE9cnico, mejorando la eficiencia operativa."},{id:"ns_0046",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un ciclo de calefacci\xF3n muy corto (short-cycling). El termostato es nuevo. \xBFQu\xE9 factor mec\xE1nico es la causa?",opciones:["El interruptor de alta presi\xF3n est\xE1 actuando debido a un flujo de aire insuficiente.","La v\xE1lvula inversora se est\xE1 moviendo aleatoriamente por una falla en la bobina.","El acumulador de succi\xF3n est\xE1 congelado impidiendo el flujo de vapor constante.","El sensor de temperatura exterior est\xE1 ubicado bajo la luz solar directa siempre."],respuesta_correcta:0,explicacion:"Si el flujo de aire es insuficiente, la presion de condensacion sube rapidamente en modo calor, disparando el switch de alta presion y causando ciclos cortos repetitivos (short-cycling)."},{id:"ns_0047",categoria:"NATE_SR_RACK",pregunta:"Se observa burbujeo en la mirilla de un rack, pero el subenfriamiento es de 15\xB0F. \xBFQu\xE9 diagn\xF3stico dar\xEDa un Senior?",opciones:["Existe una restricci\xF3n importante antes de la mirilla o el filtro est\xE1 saturado.","El sistema tiene una falta de carga de refrigerante a pesar del subenfriamiento.","La temperatura del aire en el condensador es demasiado alta para el refrigerante.","El ventilador del recibidor de l\xEDquido no est\xE1 funcionando para enfriar el gas."],respuesta_correcta:0,explicacion:"Si el subenfriamiento es adecuado (15\xB0F) pero hay burbujas en la mirilla, la causa es una ca\xEDda de presi\xF3n (restricci\xF3n) antes de la mirilla, como un filtro deshidratador saturado, que genera flash gas localizado sin que falte refrigerante."},{id:"ns_0048",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior reporta que su ayudante no sabe usar el mult\xEDmetro. \xBFCu\xE1l es la responsabilidad administrativa inmediata?",opciones:["Retirar al ayudante de tareas el\xE9ctricas y programar una capacitaci\xF3n pr\xE1ctica.","Asignar al ayudante a tareas de limpieza exclusivamente para evitar accidentes.","Despedir al ayudante por falta de conocimientos b\xE1sicos necesarios para el puesto.","Darle un manual de usuario al ayudante y pedirle que lo lea durante su almuerzo."],respuesta_correcta:0,explicacion:"La prioridad es la seguridad: un t\xE9cnico sin dominio del mult\xEDmetro puede electrocutarse o da\xF1ar equipos. Retirarlo de tareas el\xE9ctricas elimina el riesgo inmediato, y programar capacitaci\xF3n asegura que desarrolle la competencia necesaria."},{id:"ns_0049",categoria:"NATE_SR_CHILLERS",pregunta:"En un chiller de tornillo, el compresor opera continuamente en el nivel m\xE1s bajo de capacidad. \xBFQu\xE9 impacto tiene esto a largo plazo?",opciones:["Una gesti\xF3n deficiente del aceite y posibles problemas de lubricaci\xF3n interna.","Un aumento en la eficiencia energ\xE9tica debido al bajo consumo de corriente.","La formaci\xF3n de hielo en el evaporador por el bajo flujo de refrigerante total.","El sobrecalentamiento del motor por la falta de enfriamiento por gas de succi\xF3n."],respuesta_correcta:0,explicacion:"La operaci\xF3n continua a capacidad m\xEDnima en compresores de tornillo causa una mala gesti\xF3n del aceite, ya que el flujo de gas es insuficiente para arrastrar y recircular el aceite correctamente por el sistema."},{id:"ns_0050",categoria:"NATE_SR_HVAC",pregunta:"Un sistema de 5 toneladas utiliza un orificio fijo. Si la carga t\xE9rmica aumenta dr\xE1sticamente, \xBFc\xF3mo reaccionar\xE1 el sobrecalentamiento?",opciones:["El sobrecalentamiento aumentar\xE1 significativamente debido a la evaporaci\xF3n r\xE1pida.","El sobrecalentamiento bajar\xE1 porque el orificio enviar\xE1 m\xE1s l\xEDquido por presi\xF3n.","El sobrecalentamiento se mantendr\xE1 igual ya que el orificio es un punto fijo.","El sobrecalentamiento fluctuar\xE1 violentamente hasta que el sistema se estabilice."],respuesta_correcta:0,explicacion:"Con un orificio fijo, el flujo de refrigerante no se ajusta autom\xE1ticamente. Al aumentar la carga t\xE9rmica, el refrigerante se evapora m\xE1s r\xE1pido en el evaporador pero el orificio no puede compensar, resultando en un sobrecalentamiento m\xE1s alto por la evaporaci\xF3n acelerada."},{id:"ns_0051",categoria:"NATE_SR_CEO",pregunta:"Un CEO decide expandirse al mercado comercial de chillers. \xBFCu\xE1l es el desaf\xEDo de flujo de caja m\xE1s importante?",opciones:["El ciclo de facturaci\xF3n prolongado y los costos de materiales de alto valor inicial.","La dificultad para encontrar t\xE9cnicos que quieran trabajar en techos industriales.","La variabilidad del clima que afecta la demanda de reparaciones de emergencia.","El costo de la publicidad en medios digitales para atraer clientes industriales."],respuesta_correcta:0,explicacion:"Los proyectos de chillers comerciales requieren materiales de alto costo por adelantado y los ciclos de facturaci\xF3n son largos (30-90 d\xEDas), creando una presi\xF3n severa sobre el flujo de caja."},{id:"ns_0052",categoria:"NATE_SR_MINISPLIT",pregunta:"Durante el vaciado de un sistema VRF, el t\xE9cnico no puede bajar de 1000 micrones. No hay fugas. \xBFCu\xE1l es el problema?",opciones:["Humedad atrapada o refrigerante disuelto en el aceite del compresor del sistema.","La bomba de vac\xEDo no tiene la capacidad de CFM necesaria para el volumen total.","Las v\xE1lvulas de servicio est\xE1n cerradas impidiendo la evacuaci\xF3n de las l\xEDneas.","El vacu\xF3metro digital est\xE1 descalibrado por la presencia de aceite en el sensor."],respuesta_correcta:0,explicacion:"Si no hay fugas y el vac\xEDo no baja de 1000 micrones, la causa es humedad atrapada o refrigerante disuelto en el aceite que se desgasifica lentamente, impidiendo alcanzar el vac\xEDo profundo requerido."},{id:"ns_0053",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, la v\xE1lvula inversora hace un ruido de 'chattering'. \xBFCu\xE1l es la causa el\xE9ctrica m\xE1s probable?",opciones:["Bajo voltaje en el circuito de control de 24V o una bobina de solenoide d\xE9bil.","Falta de presi\xF3n diferencial de refrigerante para mover el pist\xF3n de la v\xE1lvula.","Una se\xF1al de termostato que est\xE1 alternando r\xE1pidamente entre calor y fr\xEDo.","El uso de un transformador de 40VA que est\xE1 operando al l\xEDmite de su capacidad."],respuesta_correcta:0,explicacion:"El chattering de la valvula inversora ocurre cuando la bobina solenoide no recibe suficiente voltaje (bajo voltaje en 24V) para mantener el piston piloto en posicion, causando vibracion entre las dos posiciones."},{id:"ns_0054",categoria:"NATE_SR_RACK",pregunta:"Un condensador evaporativo en un sistema de rack presenta incrustaciones blancas. \xBFQu\xE9 debe corregir el Senior?",opciones:["El sistema de tratamiento qu\xEDmico del agua y la tasa de purga (blowdown).","La velocidad de los ventiladores para reducir la evaporaci\xF3n directa del agua.","El tipo de boquillas de aspersi\xF3n para asegurar un patr\xF3n de mojado uniforme.","La carga de refrigerante para bajar la temperatura de entrada al condensador."],respuesta_correcta:0,explicacion:"Las incrustaciones blancas son dep\xF3sitos minerales (calcio/magnesio) causados por agua dura y una tasa de purga insuficiente. Se debe corregir el tratamiento qu\xEDmico del agua y aumentar el blowdown para controlar la concentraci\xF3n de minerales."},{id:"ns_0055",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior detecta que un compa\xF1ero est\xE1 robando piezas del inventario. \xBFCu\xE1l es la acci\xF3n profesional correcta?",opciones:["Reportar el hallazgo de inmediato a la gerencia con la evidencia recolectada.","Confrontar al compa\xF1ero en privado y pedirle que devuelva las piezas robadas.","Ignorar la situaci\xF3n para evitar conflictos internos en el equipo de trabajo.","Hablar con los otros t\xE9cnicos para ver si ellos tambi\xE9n han notado el robo."],respuesta_correcta:0,explicacion:"La cadena de mando y la integridad profesional exigen reportar inmediatamente a la gerencia con evidencia. Confrontar directamente o ignorar puede escalar el problema, comprometer la investigaci\xF3n o hacer c\xF3mplice al observador."},{id:"ns_0056",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo tiene una purga de aire excesiva. El sistema opera a presi\xF3n positiva. \xBFQu\xE9 indica esto?",opciones:["Una fuga en el lado de alta que permite la salida de gas pero no entrada de aire.","El sistema de purga est\xE1 defectuoso y est\xE1 detectando falsos no condensables.","El refrigerante utilizado es R-134a y el sistema tiene una fuga en el evaporador.","La temperatura del agua de la torre es demasiado baja para el condensador."],respuesta_correcta:1,explicacion:"Si el sistema opera a presi\xF3n positiva (R-134a), el aire no puede infiltrarse. Una purga excesiva indica que el sistema de purga est\xE1 defectuoso y detecta falsos no condensables cuando en realidad no hay infiltraci\xF3n de aire."},{id:"ns_0057",categoria:"NATE_SR_HVAC",pregunta:"Al medir la presi\xF3n est\xE1tica total externa (TESP), el valor es de 1.1 pulg. W.C. en un sistema nominal de 0.5. \xBFConsecuencia?",opciones:["Falla prematura del motor del soplador y reducci\xF3n dr\xE1stica de la capacidad.","Aumento en la eficiencia del intercambio de calor por la mayor presi\xF3n de aire.","Menor consumo el\xE9ctrico del motor debido a la restricci\xF3n del flujo de aire.","Mejora en la filtraci\xF3n de aire gracias a la mayor velocidad por el filtro."],respuesta_correcta:0,explicacion:'Una TESP de 1.1" W.C. es m\xE1s del doble del nominal de 0.5". Esta restricci\xF3n excesiva reduce dr\xE1sticamente el flujo de aire (CFM), causando sobrecarga del motor del soplador y p\xE9rdida significativa de capacidad de enfriamiento o calefacci\xF3n del sistema.'},{id:"ns_0058",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de doble etapa tiene el compresor de la etapa 1 quemado. \xBFPuede operar solo con la etapa 2?",opciones:["No, la l\xF3gica de control y el flujo de refrigerante suelen estar interconectados.","S\xED, siempre que se puentee el interruptor de seguridad de la primera etapa.","S\xED, pero la eficiencia bajar\xE1 y el termostato no podr\xE1 alcanzar el set-point.","No, porque el aceite del sistema se acumular\xEDa en el compresor que no opera."],respuesta_correcta:0,explicacion:"En la mayor\xEDa de unidades paquete de doble etapa, la l\xF3gica de control requiere que la etapa 1 opere antes de activar la etapa 2. Adem\xE1s, si comparten circuito de refrigerante, el compresor da\xF1ado puede causar restricciones o migraci\xF3n de refrigerante."},{id:"ns_0059",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere aumentar el valor de reventa de su empresa HVAC. \xBFQu\xE9 m\xE9trica es la m\xE1s atractiva para un comprador?",opciones:["El n\xFAmero de contratos de mantenimiento preventivo activos (Recurring Revenue).","La cantidad de camionetas nuevas compradas en el \xFAltimo ejercicio fiscal.","La facturaci\xF3n total bruta anual sin considerar el margen de utilidad neta.","El n\xFAmero de seguidores en las redes sociales de la empresa de servicios."],respuesta_correcta:0,explicacion:"Los contratos de mantenimiento preventivo generan ingresos recurrentes predecibles (Recurring Revenue), que es la m\xE9trica m\xE1s atractiva para compradores porque garantiza flujo de caja futuro."},{id:"ns_0060",categoria:"NATE_SR_RACK",pregunta:"En un rack de refrigeraci\xF3n, \xBFcu\xE1l es la funci\xF3n primordial de la v\xE1lvula EPR (Evaporator Pressure Regulator)?",opciones:["Mantener una presi\xF3n m\xEDnima en el evaporador para evitar la congelaci\xF3n del producto.","Regular el flujo de gas caliente durante el proceso de deshielo de las vitrinas.","Prevenir que el l\xEDquido regrese al compresor durante periodos de baja carga.","Igualar las presiones entre los diferentes compresores que forman el rack paralelo."],respuesta_correcta:0,explicacion:"La v\xE1lvula EPR mantiene una presi\xF3n m\xEDnima en el evaporador independientemente de la presi\xF3n de succi\xF3n del rack. Esto evita que la temperatura del evaporador baje demasiado y congele productos sensibles como l\xE1cteos o vegetales."},{id:"ns_0061",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una aproximaci\xF3n (approach) del condensador de 2\xB0F. El Senior concluye que:",opciones:["El condensador est\xE1 operando con una eficiencia de transferencia de calor excelente.","Existe una carga excesiva de refrigerante que inunda los tubos del condensador.","El flujo de agua de la torre es insuficiente y el Delta T es demasiado alto.","Los tubos del condensador requieren una limpieza mec\xE1nica por acumulaci\xF3n de lodo."],respuesta_correcta:0,explicacion:"Un approach de condensador de 2\xB0F (diferencia entre temperatura de saturaci\xF3n del refrigerante y salida del agua) indica una transferencia de calor excelente, con tubos limpios y flujo de agua adecuado."},{id:"ns_0062",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema multi-split tiene una unidad interior que no enfr\xEDa, pero las otras s\xED. \xBFQu\xE9 revisar\xEDa el Senior?",opciones:["La v\xE1lvula de expansi\xF3n electr\xF3nica (EEV) dedicada a esa unidad en la exterior.","La carga total de refrigerante del sistema que podr\xEDa estar ligeramente baja.","El sensor de temperatura de la unidad exterior que regula el compresor inverter.","La comunicaci\xF3n general entre el mando a distancia y el receptor de la unidad."],respuesta_correcta:0,explicacion:"En un multi-split, cada unidad interior tiene su propia v\xE1lvula de expansi\xF3n electr\xF3nica (EEV). Si solo una no enfr\xEDa, la EEV dedicada a esa unidad est\xE1 cerrada o defectuosa."},{id:"ns_0063",categoria:"NATE_SR_HVAC",pregunta:"Al realizar un vac\xEDo, el sistema se estabiliza en 1500 micrones y no sube m\xE1s. \xBFQu\xE9 diagn\xF3stico es correcto?",opciones:["Hay humedad remanente en el sistema que se est\xE1 evaporando lentamente.","Existe una fuga peque\xF1a en el sistema que iguala la capacidad de la bomba.","El aceite de la bomba de vac\xEDo est\xE1 saturado y necesita ser cambiado.","El vacu\xF3metro est\xE1 sucio y no puede leer presiones por debajo de ese nivel."],respuesta_correcta:0,explicacion:"Cuando el vac\xEDo se estabiliza en 1500 micrones sin subir, indica humedad remanente evapor\xE1ndose lentamente dentro del sistema. Una fuga har\xEDa que la presi\xF3n suba continuamente, mientras que la humedad mantiene un equilibrio de presi\xF3n de vapor constante."},{id:"ns_0064",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en defrost no derrite el hielo completamente. \xBFQu\xE9 sensor est\xE1 mal configurado o fallido?",opciones:["El sensor de temperatura de la tuber\xEDa del serpent\xEDn exterior (Defrost Terminator).","El sensor de temperatura ambiente exterior que bloquea el ciclo por calor.","El interruptor de baja presi\xF3n que detiene el compresor durante el deshielo.","El termostato de la habitaci\xF3n que no activa las resistencias durante el ciclo."],respuesta_correcta:0,explicacion:"El sensor de temperatura del serpentin exterior (defrost terminator) determina cuando el hielo se ha derretido. Si esta mal calibrado o fallido, termina el ciclo de deshielo prematuramente sin completar el proceso."},{id:"ns_0065",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un l\xEDder de cuadrilla asigna a dos t\xE9cnicos a un trabajo de 4 horas. Si tardan 8 horas, \xBFqu\xE9 m\xE9trica se afecta m\xE1s?",opciones:["La eficiencia de la mano de obra y el margen de ganancia de ese proyecto.","El costo de los materiales utilizados durante las horas adicionales de trabajo.","La satisfacci\xF3n del cliente por haber pasado m\xE1s tiempo revisando el equipo.","La garant\xEDa del fabricante del equipo que se instal\xF3 durante ese periodo."],respuesta_correcta:0,explicacion:"Duplicar las horas estimadas significa el doble de costo de mano de obra sin ingresos adicionales. La eficiencia laboral (labor efficiency) impacta directamente el margen de ganancia del proyecto, que es la m\xE9trica financiera m\xE1s sensible."},{id:"ns_0066",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete tiene un compresor que arranca pero se apaga por 'Internal Overload'. El voltaje es correcto. \xBFCausa?",opciones:["Un sobrecalentamiento excesivo del gas de succi\xF3n que no enfr\xEDa el motor.","Un capacitor de arranque defectuoso que deja el devanado de arranque activo.","La falta de una trampa de aceite en la l\xEDnea de succi\xF3n que sube al techo.","Un sensor de temperatura de descarga que est\xE1 desconectado en la placa."],respuesta_correcta:0,explicacion:"El gas de succi\xF3n enfr\xEDa el devanado del motor del compresor herm\xE9tico. Si el sobrecalentamiento es excesivo, el gas llega demasiado caliente y no puede disipar el calor del motor, activando el protector t\xE9rmico interno (Internal Overload)."},{id:"ns_0067",categoria:"NATE_SR_RACK",pregunta:"En un sistema de rack, el receptor de l\xEDquido vibra violentamente. \xBFQu\xE9 problema hidr\xE1ulico est\xE1 ocurriendo?",opciones:["Un fen\xF3meno de 'Flash Gas' debido a una ca\xEDda de presi\xF3n excesiva en la l\xEDnea.","El retorno de aceite est\xE1 creando turbulencia en la superficie del refrigerante.","La v\xE1lvula de alivio est\xE1 a punto de abrirse por una presi\xF3n de descarga alta.","El nivel de l\xEDquido es tan alto que no hay espacio para la expansi\xF3n del gas."],respuesta_correcta:0,explicacion:"La vibraci\xF3n violenta del recibidor indica formaci\xF3n s\xFAbita de flash gas dentro del recipiente, causada por una ca\xEDda de presi\xF3n excesiva. La ebullici\xF3n r\xE1pida del refrigerante genera ondas de presi\xF3n que hacen vibrar el recipiente."},{id:"ns_0068",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que el 'Account Receivable' tiene facturas de m\xE1s de 90 d\xEDas. \xBFCu\xE1l es el riesgo de negocio?",opciones:["Una crisis de liquidez que impide pagar la n\xF3mina y a los proveedores a tiempo.","La necesidad de contratar m\xE1s personal de ventas para cubrir la falta de dinero.","Un aumento en la carga impositiva sobre ingresos que a\xFAn no han sido cobrados.","La degradaci\xF3n de la imagen de la empresa ante los clientes que no han pagado."],respuesta_correcta:0,explicacion:"Facturas sin cobrar por m\xE1s de 90 d\xEDas crean una crisis de liquidez real: la empresa no tiene efectivo para cubrir n\xF3mina y proveedores, aunque en papel tenga ingresos altos."},{id:"ns_0069",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con evaporador inundado tiene un bajo nivel de refrigerante. \xBFCu\xE1l es el s\xEDntoma principal?",opciones:["Una temperatura de salida del agua helada m\xE1s alta que el set-point.","Un aumento en el sobrecalentamiento del gas de succi\xF3n del compresor.","La formaci\xF3n de escarcha en la carcasa del evaporador por baja presi\xF3n.","Un consumo de amperaje extremadamente alto en el motor del compresor."],respuesta_correcta:0,explicacion:"En un evaporador inundado, el bajo nivel de refrigerante reduce el \xE1rea de contacto con los tubos de agua. El resultado directo es que el agua helada sale m\xE1s caliente que el set-point deseado."},{id:"ns_0070",categoria:"NATE_SR_HVAC",pregunta:"Al usar una TXV, el bulbo sensor se suelta de la l\xEDnea de succi\xF3n. \xBFQu\xE9 le sucede al evaporador?",opciones:["Se inunda de l\xEDquido refrigerante porque la v\xE1lvula se abre completamente.","Se queda sin refrigerante (starving) porque la v\xE1lvula se cierra por presi\xF3n.","La presi\xF3n de succi\xF3n baja dr\xE1sticamente y el compresor se apaga por LPS.","El sobrecalentamiento aumenta hasta que el compresor falla por alta temperatura."],respuesta_correcta:0,explicacion:"El bulbo sensor de la TXV mide la temperatura de la l\xEDnea de succi\xF3n para regular el flujo. Si se suelta, el bulbo sensa la temperatura ambiente (m\xE1s alta), lo que hace que la v\xE1lvula interprete que necesita m\xE1s refrigerante y se abra completamente, inundando el evaporador."},{id:"ns_0071",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Customer Acquisition Cost' (CAC). \xBFQu\xE9 canal es t\xE9cnicamente m\xE1s eficiente?",opciones:["El programa de referidos de clientes actuales satisfechos con el servicio.","La publicidad pagada en televisi\xF3n local durante las noticias de la tarde.","La compra de bases de datos de correos electr\xF3nicos de clientes potenciales.","El patrocinio de equipos deportivos locales para aumentar el reconocimiento."],respuesta_correcta:0,explicacion:"Los programas de referidos de clientes satisfechos tienen el CAC m\xE1s bajo porque aprovechan la confianza existente sin costos significativos de publicidad o marketing."},{id:"ns_0072",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema inverter muestra el error 'IPM Intelligent Power Module fault'. \xBFQu\xE9 prueba f\xEDsica realiza el Senior?",opciones:["Medir la resistencia y continuidad de los terminales U, V, W del compresor.","Verificar el voltaje de entrada de 240VAC en los terminales L1 y L2 de la placa.","Cambiar el capacitor de arranque por uno de mayor capacitancia para probar.","Puentear el sensor de temperatura de descarga para ver si el error desaparece."],respuesta_correcta:0,explicacion:"Ante un error de IPM, el Senior mide resistencia y continuidad en los terminales U, V, W del compresor para descartar un devanado abierto, cortocircuitado o aterrizado que cause sobrecorriente al m\xF3dulo."},{id:"ns_0073",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor geot\xE9rmica tiene aire en el lazo cerrado. \xBFCu\xE1l es el efecto en la bomba de circulaci\xF3n?",opciones:["Cavitaci\xF3n y p\xE9rdida de flujo, resultando en paros por alta o baja presi\xF3n.","Un aumento en la presi\xF3n est\xE1tica del agua que mejora la transferencia t\xE9rmica.","La reducci\xF3n del consumo el\xE9ctrico de la bomba al mover un fluido menos denso.","El aumento de la temperatura del agua debido a la fricci\xF3n del aire en los tubos."],respuesta_correcta:0,explicacion:"El aire atrapado en el lazo cerrado causa cavitacion en la bomba de circulacion, reduciendo drasticamente el flujo de agua. Sin flujo adecuado, las presiones del refrigerante se descontrolan causando paros por alta o baja presion."},{id:"ns_0074",categoria:"NATE_SR_RACK",pregunta:"En un rack, el controlador indica 'Oil Failure' en tres compresores a la vez. \xBFQu\xE9 componente central fall\xF3?",opciones:["El separador de aceite principal o la v\xE1lvula de presi\xF3n diferencial del dep\xF3sito.","Los sensores de nivel individuales de cada c\xE1rter de los tres compresores.","La bomba de aceite mec\xE1nica de cada uno de los compresores afectados.","El filtro deshidratador de la l\xEDnea de l\xEDquido que alimenta a las vitrinas."],respuesta_correcta:0,explicacion:"Cuando m\xFAltiples compresores reportan falla de aceite simult\xE1neamente, el problema es un componente centralizado del sistema de aceite: el separador principal o la v\xE1lvula diferencial del dep\xF3sito, ya que alimentan a todos los compresores."},{id:"ns_0075",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior debe decidir entre reparar un equipo de 20 a\xF1os o vender uno nuevo. \xBFQu\xE9 factor es decisivo?",opciones:["El costo de la reparaci\xF3n frente al valor residual y la eficiencia operativa.","La disponibilidad de piezas est\xE9ticas como paneles y rejillas originales.","La preferencia personal del t\xE9cnico por trabajar con tecnolog\xEDa m\xE1s antigua.","El tiempo que tardar\xE1 en llegar el equipo nuevo desde el almac\xE9n central."],respuesta_correcta:0,explicacion:"La decisi\xF3n reparar vs. reemplazar se basa en an\xE1lisis costo-beneficio: si el costo de reparaci\xF3n se acerca o supera el valor residual del equipo, y la eficiencia operativa (SEER) es muy inferior a equipos modernos, el reemplazo es la mejor inversi\xF3n."},{id:"ns_0076",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo experimenta una 'ca\xEDda de presi\xF3n del evaporador' baja. \xBFCu\xE1l es la causa probable?",opciones:["Tubos del evaporador limpios o un flujo de agua superior al dise\xF1o nominal.","Incrustaciones severas en el lado del agua que obstruyen el paso del fluido.","Falta de refrigerante l\xEDquido que no cubre la totalidad de los tubos internos.","Una v\xE1lvula de mariposa en la l\xEDnea de agua que est\xE1 parcialmente cerrada."],respuesta_correcta:0,explicacion:"Una ca\xEDda de presi\xF3n baja en el lado del agua indica poca resistencia al flujo. Tubos limpios o flujo de agua superior al nominal reducen la fricci\xF3n, resultando en menor ca\xEDda de presi\xF3n."},{id:"ns_0077",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial con R-410A tiene una presi\xF3n de succi\xF3n de 100 PSI y descarga de 300 PSI. \xBFEstado?",opciones:["Falta de carga de refrigerante o baja carga t\xE9rmica en el evaporador.","Carga correcta de refrigerante operando en condiciones de dise\xF1o normales.","Exceso de carga de refrigerante o restricci\xF3n en el condensador exterior.","Compresor con v\xE1lvulas internas da\xF1adas que no puede bombear eficientemente."],respuesta_correcta:0,explicacion:"Con R-410A, una succi\xF3n de 100 PSI equivale a aproximadamente 30\xB0F de saturaci\xF3n, lo cual es bajo. La descarga de 300 PSI tambi\xE9n es relativamente baja. Esto indica falta de carga de refrigerante o baja carga t\xE9rmica que impide que las presiones suban a niveles normales."},{id:"ns_0078",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete utiliza un motor de soplador accionado por correa. La correa rechina al arrancar. \xBFAcci\xF3n?",opciones:["Ajustar la tensi\xF3n de la correa y verificar la alineaci\xF3n de las poleas.","Aplicar lubricante en aerosol sobre la correa para reducir la fricci\xF3n inicial.","Reemplazar el motor por uno de mayor caballaje para soportar el arranque.","Aumentar el di\xE1metro de la polea del motor para reducir la velocidad final."],respuesta_correcta:0,explicacion:"El rechinar de una correa al arranque indica tensi\xF3n insuficiente (la correa patina sobre la polea) o desalineaci\xF3n entre poleas. Ajustar la tensi\xF3n y verificar la alineaci\xF3n es el procedimiento correcto antes de considerar reemplazar la correa."},{id:"ns_0079",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar la retenci\xF3n de t\xE9cnicos Senior. \xBFQu\xE9 estrategia es la m\xE1s valorada?",opciones:["Un plan de carrera claro con certificaciones pagadas y bonos por desempe\xF1o.","Proporcionar camionetas \xFAltimo modelo con sistemas de sonido premium.","Aumentar el n\xFAmero de horas extras obligatorias para incrementar sus ingresos.","Organizar eventos sociales mensuales con asistencia obligatoria fuera de horas."],respuesta_correcta:0,explicacion:"Un plan de carrera claro con certificaciones pagadas y bonos por desempe\xF1o demuestra inversi\xF3n en el crecimiento profesional del t\xE9cnico, siendo el factor de retenci\xF3n m\xE1s valorado a largo plazo."},{id:"ns_0080",categoria:"NATE_SR_RACK",pregunta:"Se encuentra l\xEDquido en el cabezal de succi\xF3n de un rack de media temperatura. \xBFQu\xE9 v\xE1lvula fall\xF3?",opciones:["Una v\xE1lvula de expansi\xF3n (TXV) de una de las vitrinas est\xE1 atascada abierta.","La v\xE1lvula solenoide de la l\xEDnea de l\xEDquido general no cierra en el paro.","La v\xE1lvula de alivio del receptor est\xE1 permitiendo el paso de gas al rack.","La v\xE1lvula diferencial de aceite est\xE1 inyectando refrigerante al sistema."],respuesta_correcta:0,explicacion:"Una TXV atascada en posici\xF3n abierta permite el paso descontrolado de refrigerante l\xEDquido al evaporador, que no se evapora completamente y llega como l\xEDquido al cabezal de succi\xF3n del rack, poniendo en riesgo los compresores."},{id:"ns_0081",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga de aire constante y opera con R-123. \xBFCu\xE1l es el riesgo de seguridad qu\xEDmica?",opciones:["La formaci\xF3n de \xE1cidos corrosivos dentro del sistema por la mezcla de aire y aceite.","La liberaci\xF3n de cloro a la atm\xF3sfera que da\xF1a la capa de ozono directamente.","El aumento de la inflamabilidad del refrigerante debido a la presi\xF3n del aire.","La asfixia del personal en la sala de m\xE1quinas por el desplazamiento del ox\xEDgeno."],respuesta_correcta:0,explicacion:"Cuando el aire se mezcla con R-123 y aceite a altas temperaturas, se forman \xE1cidos clorh\xEDdrico y fluorh\xEDdrico que corroen componentes internos del sistema, incluyendo los devanados del motor."},{id:"ns_0082",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRF reporta 'Communication error' solo cuando el compresor arranca. \xBFDiagn\xF3stico?",opciones:["Ruido el\xE9ctrico (EMI) que interfiere con la se\xF1al por falta de blindaje o tierra.","La placa de comunicaci\xF3n est\xE1 da\xF1ada y se bloquea por el consumo del motor.","El compresor est\xE1 aterrizado y env\xEDa voltaje a trav\xE9s del chasis a la placa.","La longitud de los cables excede los l\xEDmites y la se\xF1al llega muy d\xE9bil."],respuesta_correcta:0,explicacion:"Cuando el error de comunicaci\xF3n solo ocurre al arrancar el compresor, la causa es ruido electromagn\xE9tico (EMI) generado por el arranque del motor inverter, que interfiere con la se\xF1al de datos por falta de blindaje o tierra."},{id:"ns_0083",categoria:"NATE_SR_HVAC",pregunta:"Un sistema de conductos de fibra de vidrio muestra moho interno. \xBFQu\xE9 factor operativo lo caus\xF3?",opciones:["Operar el sistema con baja velocidad de aire permitiendo condensaci\xF3n interna.","El uso de filtros HEPA que restringen demasiado el flujo de aire del sistema.","Una carga de refrigerante excesiva que enfr\xEDa demasiado el serpent\xEDn interior.","La instalaci\xF3n de luces UV despu\xE9s del serpent\xEDn en lugar de antes del mismo."],respuesta_correcta:0,explicacion:"Operar con baja velocidad de aire permite que la temperatura del aire dentro del conducto caiga por debajo del punto de roc\xEDo, causando condensaci\xF3n en la superficie interior de la fibra de vidrio. Esta humedad persistente crea el ambiente ideal para el crecimiento de moho."},{id:"ns_0084",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, la temperatura del aire de suministro en modo calor es de 85\xB0F. \xBFEs normal?",opciones:["S\xED, las bombas de calor entregan aire a temperaturas m\xE1s bajas que los hornos.","No, la temperatura deber\xEDa estar por encima de los 110\xB0F para ser eficiente.","Depende de si las resistencias el\xE9ctricas de apoyo est\xE1n activadas o no.","No, indica que la v\xE1lvula inversora est\xE1 fugando gas caliente internamente."],respuesta_correcta:0,explicacion:"Las bombas de calor entregan aire entre 85-95F en modo calor, a diferencia de los hornos de gas que entregan 120-140F. Esto es normal porque la bomba transfiere calor del exterior en vez de generarlo por combustion."},{id:"ns_0085",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera la instalaci\xF3n de un rooftop de 50 toneladas. \xBFCu\xE1l es el riesgo de seguridad m\xE1s alto?",opciones:["La maniobra de izaje con gr\xFAa y la estabilidad de la estructura del techo.","La conexi\xF3n el\xE9ctrica de alto voltaje sin el equipo de protecci\xF3n personal.","La manipulaci\xF3n de cilindros de refrigerante de gran tama\xF1o bajo el sol.","El riesgo de ca\xEDdas desde el borde del techo si no hay barandales instalados."],respuesta_correcta:0,explicacion:"El izaje con gr\xFAa de un equipo de 50 toneladas involucra cargas extremadamente pesadas suspendidas a gran altura. Una falla en la maniobra puede causar el colapso de la estructura del techo o la ca\xEDda del equipo, con consecuencias fatales."},{id:"ns_0086",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete tiene un economizador. En un d\xEDa de 50\xB0F exterior, el compresor arranca. \xBFPor qu\xE9?",opciones:["El sensor de entalp\xEDa detect\xF3 que el aire exterior est\xE1 demasiado h\xFAmedo.","El motor del damper est\xE1 atascado en la posici\xF3n de aire de retorno 100%.","El controlador del economizador no tiene energ\xEDa o el fusible est\xE1 fundido.","El termostato de la zona est\xE1 configurado para ignorar el aire exterior."],respuesta_correcta:0,explicacion:"Aunque 50\xB0F parece ideal para enfriamiento gratuito, si la humedad exterior es alta, la entalp\xEDa total del aire excede el umbral. El sensor de entalp\xEDa correctamente bloquea el economizador y activa el compresor para evitar introducir aire h\xFAmedo."},{id:"ns_0087",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-404A. Se sospecha de 'Refrigerant Glide' tras una fuga lenta. \xBFQu\xE9 debe hacer el Senior?",opciones:["Recuperar todo el refrigerante restante y cargar con refrigerante virgen.","Simplemente completar la carga hasta que las presiones vuelvan a la normalidad.","A\xF1adir solo el componente m\xE1s vol\xE1til de la mezcla para equilibrar el gas.","Cambiar el filtro deshidratador y esperar a que la mezcla se estabilice sola."],respuesta_correcta:0,explicacion:"Aunque el R-404A es casi azeotr\xF3pico, tras una fuga lenta la composici\xF3n puede alterarse. El procedimiento correcto es recuperar toda la carga restante y recargar con refrigerante virgen para garantizar la composici\xF3n correcta de la mezcla."},{id:"ns_0088",categoria:"NATE_SR_CEO",pregunta:"Un CEO eval\xFAa el 'Return on Investment' (ROI) de una campa\xF1a de Google Ads. \xBFQu\xE9 dato es clave?",opciones:["La conversi\xF3n de clics en \xF3rdenes de trabajo cerradas con margen de utilidad.","El n\xFAmero total de impresiones de los anuncios en las b\xFAsquedas locales.","El costo por clic (CPC) comparado con el promedio de la industria nacional.","La cantidad de llamadas telef\xF3nicas recibidas, independientemente del resultado."],respuesta_correcta:0,explicacion:"El verdadero ROI de Google Ads se mide por la conversi\xF3n final: cu\xE1ntos clics se transformaron en \xF3rdenes de trabajo cerradas con margen de utilidad, no solo en impresiones o clics."},{id:"ns_0089",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'high discharge temperature'. El condensador es de agua. \xBFQu\xE9 revisa?",opciones:["El flujo de agua de la torre y la temperatura de entrada al condensador.","La velocidad del compresor y el ajuste de los \xE1labes de entrada (vanes).","La carga de refrigerante l\xEDquido en el evaporador por el m\xE9todo del visor.","El estado de la v\xE1lvula de expansi\xF3n y el sobrecalentamiento de la succi\xF3n."],respuesta_correcta:0,explicacion:"En un chiller enfriado por agua con alta temperatura de descarga, lo primero es verificar el flujo y temperatura del agua de la torre, ya que son los factores principales que determinan la presi\xF3n de condensaci\xF3n."},{id:"ns_0090",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 450 PSI con R-410A. \xBFQu\xE9 indica la descarga?",opciones:["Incondensables en el sistema o un condensador extremadamente sucio.","Una carga de refrigerante perfecta para un d\xEDa de alta temperatura ambiental.","Que el compresor est\xE1 funcionando al 100% de su capacidad volum\xE9trica.","Una restricci\xF3n en la v\xE1lvula de expansi\xF3n que eleva la presi\xF3n de alta."],respuesta_correcta:0,explicacion:"Con R-410A, 450 PSI de descarga es anormalmente alto y equivale a una temperatura de condensaci\xF3n de aproximadamente 130\xB0F. Esto indica incondensables (aire/nitr\xF3geno) atrapados en el sistema o un condensador extremadamente sucio que impide la transferencia de calor."},{id:"ns_0091",categoria:"NATE_SR_CEO",pregunta:"Para mejorar el 'First Time Fix Rate', \xBFqu\xE9 acci\xF3n administrativa es la m\xE1s efectiva?",opciones:["Asegurar que las camionetas tengan un stock de piezas cr\xEDticas basado en datos.","Descontar el tiempo del segundo viaje del salario del t\xE9cnico responsable.","Comprar herramientas de diagn\xF3stico m\xE1s caras para todos los t\xE9cnicos junior.","Obligar a los t\xE9cnicos a llamar a soporte t\xE9cnico en cada diagn\xF3stico de campo."],respuesta_correcta:0,explicacion:"Mantener un stock de piezas cr\xEDticas basado en datos hist\xF3ricos de fallas permite al t\xE9cnico resolver el problema en la primera visita, mejorando el First Time Fix Rate directamente."},{id:"ns_0092",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split gotea agua por la unidad interior. El drenaje est\xE1 limpio. \xBFQu\xE9 causa t\xE9cnica es probable?",opciones:["Un bajo nivel de refrigerante que causa escarcha parcial y goteo fuera de la bandeja.","El ventilador interior est\xE1 girando demasiado r\xE1pido y succiona las gotas de agua.","La bandeja de condensado est\xE1 nivelada perfectamente en lugar de tener inclinaci\xF3n.","El filtro de aire est\xE1 demasiado limpio y permite que el aire pase con mucha humedad."],respuesta_correcta:0,explicacion:"Con el drenaje limpio, un nivel bajo de refrigerante causa escarcha parcial en el serpent\xEDn; al derretirse, el agua cae fuera de la bandeja de condensado porque la distribuci\xF3n de escarcha es irregular."},{id:"ns_0093",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor hace un ruido fuerte al terminar el defrost. \xBFQu\xE9 est\xE1 ocurriendo f\xEDsicamente?",opciones:["La v\xE1lvula inversora cambia de posici\xF3n y las presiones se igualan bruscamente.","El compresor est\xE1 sufriendo un 'slugging' de l\xEDquido al volver al modo calor.","El ventilador exterior golpea el hielo acumulado que no se alcanz\xF3 a derretir.","Las resistencias el\xE9ctricas se apagan de golpe causando una contracci\xF3n t\xE9rmica."],respuesta_correcta:0,explicacion:"Al terminar el defrost, la valvula inversora cambia de refrigeracion a calefaccion. Este cambio brusco ecualiza las presiones de alta y baja repentinamente, creando un ruido fuerte pero normal en el sistema."},{id:"ns_0094",categoria:"NATE_SR_RACK",pregunta:"En un rack, el nivel de aceite en el separador es alto pero bajo en los compresores. \xBFQu\xE9 revisa?",opciones:["El filtro de la l\xEDnea de retorno de aceite o la v\xE1lvula reguladora de nivel.","La carga de refrigerante l\xEDquido que podr\xEDa estar atrapando el aceite abajo.","La temperatura de descarga que es demasiado baja para separar el aceite.","La velocidad de los compresores que no generan suficiente arrastre de gas."],respuesta_correcta:0,explicacion:"Si el separador tiene aceite suficiente pero los compresores no, la obstrucci\xF3n est\xE1 en el camino de retorno: un filtro tapado en la l\xEDnea de aceite o una v\xE1lvula reguladora de nivel que no abre correctamente impiden el flujo de aceite hacia los c\xE1rteres."},{id:"ns_0095",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un cliente se queja de un t\xE9cnico Senior por su actitud. \xBFC\xF3mo debe proceder el CEO?",opciones:["Escuchar al cliente, investigar la versi\xF3n del t\xE9cnico y tomar medidas justas.","Despedir al t\xE9cnico de inmediato para mantener la reputaci\xF3n de la empresa.","Ignorar al cliente asumiendo que el t\xE9cnico Senior siempre tiene la raz\xF3n.","Ofrecer un descuento del 50% al cliente sin investigar lo que realmente pas\xF3."],respuesta_correcta:0,explicacion:"El liderazgo justo requiere escuchar ambas partes antes de actuar. Investigar los hechos protege tanto la relaci\xF3n con el cliente como los derechos del empleado, y permite tomar decisiones informadas que fortalecen la cultura de la empresa."},{id:"ns_0096",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una 'falla de flujo de agua'. La bomba est\xE1 encendida. \xBFQu\xE9 debe verificar?",opciones:["El interruptor de flujo (flow switch) o el diferencial de presi\xF3n en el evaporador.","El sentido de rotaci\xF3n del motor del compresor centr\xEDfugo del sistema.","La carga de refrigerante que puede estar congelando el agua en los tubos.","La apertura de las v\xE1lvulas de expansi\xF3n del circuito de refrigeraci\xF3n."],respuesta_correcta:0,explicacion:"Con la bomba encendida, una falla de flujo indica un problema con el interruptor de flujo (flow switch) o el diferencial de presi\xF3n del evaporador, no con el equipo de refrigeraci\xF3n en s\xED."},{id:"ns_0097",categoria:"NATE_SR_HVAC",pregunta:"Un motor de condensador PSC falla. El t\xE9cnico instala uno nuevo pero gira al rev\xE9s. \xBFCausa?",opciones:["Los cables del capacitor est\xE1n invertidos o el motor es de rotaci\xF3n incorrecta.","El voltaje de entrada est\xE1 en desfase con el capacitor de marcha instalado.","El ventilador est\xE1 instalado al rev\xE9s sobre el eje del motor del condensador.","La placa de control est\xE1 enviando una se\xF1al de polaridad invertida al motor."],respuesta_correcta:0,explicacion:"En un motor PSC, el capacitor crea el desfase de fase entre los devanados de arranque y marcha para determinar la direcci\xF3n de rotaci\xF3n. Si los cables del capacitor se conectan invertidos o el motor tiene rotaci\xF3n opuesta al original, el motor girar\xE1 al rev\xE9s."},{id:"ns_0098",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete industrial no tiene calefacci\xF3n. El ignitor brilla pero no hay llama. \xBFQu\xE9 revisa?",opciones:["La v\xE1lvula de gas o el suministro de presi\xF3n de gas hacia la unidad.","El sensor de flama que no est\xE1 detectando la incandescencia del ignitor.","El motor del inductor que no est\xE1 creando el vac\xEDo necesario en el switch.","El termostato de la zona que no est\xE1 enviando la se\xF1al de 24V al terminal W."],respuesta_correcta:0,explicacion:"Si el ignitor brilla, la secuencia de encendido lleg\xF3 hasta ese punto correctamente (inductor, switch de presi\xF3n, placa). Si no hay llama, el problema es que no llega gas al quemador: v\xE1lvula de gas cerrada, defectuosa, o sin presi\xF3n de suministro."},{id:"ns_0099",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC es responsable de la seguridad del empleado. \xBFQu\xE9 documento es vital ante OSHA?",opciones:["El registro de capacitaciones de seguridad y el manual de procesos de LOTO.","El contrato de arrendamiento de las oficinas y el almac\xE9n de la empresa.","La lista de precios actualizada que se le entrega a los clientes finales.","El reporte de mantenimiento preventivo de las camionetas de la flota."],respuesta_correcta:0,explicacion:"OSHA requiere documentaci\xF3n de capacitaciones de seguridad y procedimientos LOTO (Lockout/Tagout) como evidencia de cumplimiento; su ausencia es la causa m\xE1s com\xFAn de multas graves."},{id:"ns_0100",categoria:"NATE_SR_RACK",pregunta:"En un sistema de rack con CO2, \xBFqu\xE9 sucede si se pierde la energ\xEDa por mucho tiempo?",opciones:["La presi\xF3n aumenta por encima de los l\xEDmites y las v\xE1lvulas de alivio se abren.","El refrigerante se congela dentro de las tuber\xEDas da\xF1ando los evaporadores.","El aceite se separa del refrigerante y bloquea permanentemente los capilares.","El sistema entra en un vac\xEDo profundo que permite la entrada de humedad externa."],respuesta_correcta:0,explicacion:"El CO2 tiene una presi\xF3n de saturaci\xF3n muy alta. Sin compresores funcionando, la temperatura del refrigerante sube con el ambiente, la presi\xF3n aumenta r\xE1pidamente y supera los l\xEDmites del sistema, forzando la apertura de las v\xE1lvulas de alivio."},{id:"ns_0101",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con compresor de tornillo presenta una vibraci\xF3n excesiva solo cuando opera al 25% de carga. \xBFQu\xE9 debe evaluar el Senior?",opciones:["La alineaci\xF3n de la v\xE1lvula de corredera (slide valve) y la inyecci\xF3n de aceite.","El equilibrio est\xE1tico de los rotores del compresor en condiciones de alta carga.","La resonancia estructural de la base del equipo con la frecuencia del motor.","La viscosidad del aceite que se vuelve demasiado baja por la mezcla de gas."],respuesta_correcta:0,explicacion:"A 25% de carga, la v\xE1lvula de corredera (slide valve) opera en una posici\xF3n extrema donde la inyecci\xF3n de aceite y la alineaci\xF3n son cr\xEDticas. Una mala posici\xF3n causa vibraciones por flujo irregular."},{id:"ns_0102",categoria:"NATE_SR_RACK",pregunta:"En un rack de refrigeraci\xF3n, \xBFcu\xE1l es el prop\xF3sito de instalar una v\xE1lvula 'Check' en la l\xEDnea de descarga de cada compresor?",opciones:["Prevenir la migraci\xF3n de refrigerante l\xEDquido desde el condensador al compresor parado.","Evitar que la presi\xF3n de succi\xF3n aumente dr\xE1sticamente durante el ciclo de deshielo.","Mantener una presi\xF3n m\xEDnima de aceite en el c\xE1rter durante el arranque en fr\xEDo.","Reducir las pulsaciones de gas que pueden da\xF1ar el separador de aceite principal."],respuesta_correcta:0,explicacion:"La v\xE1lvula check en la descarga evita que el refrigerante de alta presi\xF3n y el l\xEDquido del condensador migren hacia un compresor apagado. Sin ella, el compresor parado se inundar\xEDa de l\xEDquido causando golpe de l\xEDquido al arrancar."},{id:"ns_0103",categoria:"NATE_SR_CEO",pregunta:"Si el margen de contribuci\xF3n de un departamento de instalaciones es del 10%, \xBFqu\xE9 acci\xF3n estrat\xE9gica debe tomar el CEO?",opciones:["Analizar los costos de mano de obra indirecta y renegociar precios con proveedores.","Aumentar el presupuesto de marketing para obtener m\xE1s volumen de instalaciones.","Reducir el precio de venta para ganar m\xE1s cuota de mercado frente a la competencia.","Eliminar el departamento de inmediato para centrarse solo en el \xE1rea de servicio."],respuesta_correcta:0,explicacion:"Un margen de contribuci\xF3n del 10% en instalaciones es cr\xEDticamente bajo; el CEO debe analizar costos indirectos de mano de obra y renegociar con proveedores antes de tomar decisiones dr\xE1sticas."},{id:"ns_0104",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema Multi-split tiene una unidad interior que sopla aire a temperatura ambiente mientras las dem\xE1s enfr\xEDan. \xBFQu\xE9 indica esto?",opciones:["La bobina de la v\xE1lvula de expansi\xF3n electr\xF3nica (EEV) de esa unidad est\xE1 abierta.","El sensor de temperatura de aire de retorno de esa unidad est\xE1 fuera de rango.","El compresor inverter no tiene la capacidad suficiente para alimentar todas las zonas.","Hay una obstrucci\xF3n f\xEDsica en el filtro de aire de esa unidad interior espec\xEDfica."],respuesta_correcta:0,explicacion:"Si una unidad interior sopla aire ambiente mientras las dem\xE1s enfr\xEDan, significa que no recibe refrigerante. La bobina de la EEV abierta (sin energ\xEDa) mantiene la v\xE1lvula cerrada, bloqueando el flujo a esa unidad."},{id:"ns_0105",categoria:"NATE_SR_HVAC",pregunta:"Al realizar una prueba de combusti\xF3n en un horno de gas, se detecta un exceso de aire del 80%. \xBFQu\xE9 ajuste t\xE9cnico es necesario?",opciones:["Reducir la velocidad del inductor o ajustar los obturadores de aire primario.","Aumentar la presi\xF3n de gas en el manifold para compensar el exceso de ox\xEDgeno.","Reemplazar los quemadores por unos de menor orificio para reducir la potencia.","Limpiar el intercambiador de calor para mejorar el tiro natural de la chimenea."],respuesta_correcta:0,explicacion:"Un exceso de aire del 80% significa demasiado ox\xEDgeno en la mezcla de combusti\xF3n, lo que reduce la eficiencia y enfr\xEDa la llama. La soluci\xF3n es reducir la entrada de aire ajustando los obturadores primarios o la velocidad del inductor para optimizar la relaci\xF3n aire-combustible."},{id:"ns_0106",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor presenta escarcha solo en la parte inferior del serpent\xEDn exterior en modo calor. \xBFCu\xE1l es el diagn\xF3stico?",opciones:["Falta de refrigerante que causa una evaporaci\xF3n incompleta en el serpent\xEDn.","El ventilador exterior est\xE1 girando demasiado lento debido a un capacitor d\xE9bil.","La v\xE1lvula de expansi\xF3n exterior est\xE1 inundando el serpent\xEDn con exceso de l\xEDquido.","Es un comportamiento normal debido a la humedad relativa alta en el ambiente."],respuesta_correcta:0,explicacion:"Escarcha solo en la parte inferior del serpentin indica falta de refrigerante. Con carga baja, el refrigerante se evapora antes de llegar a las secciones superiores, dejando solo la parte inferior fria y escarchada."},{id:"ns_0107",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior nota que la cuadrilla usa el mismo vacu\xF3metro para sistemas con aceite mineral y POE. \xBFPor qu\xE9 es un error?",opciones:["La contaminaci\xF3n cruzada de aceites puede degradar las propiedades del aceite POE.","El vacu\xF3metro dar\xE1 lecturas falsas debido a la diferencia de densidad de los aceites.","El aceite mineral da\xF1a permanentemente el sensor t\xE9rmico de los vacu\xF3metros digitales.","Las normativas de la EPA proh\xEDben compartir herramientas de medici\xF3n entre sistemas."],respuesta_correcta:0,explicacion:"El aceite POE (poliol\xE9ster) es higrosc\xF3pico y altamente sensible a contaminantes. Residuos de aceite mineral en el vacu\xF3metro o mangueras pueden contaminar un sistema POE, degradando su lubricaci\xF3n y causando fallas prematuras del compresor."},{id:"ns_0108",categoria:"NATE_SR_PACKAGE",pregunta:"En un Rooftop con VFD en el soplador, el motor falla por da\xF1o en los rodamientos tras 6 meses. \xBFQu\xE9 caus\xF3 esto?",opciones:["Corrientes par\xE1sitas (shaft currents) que fluyen a trav\xE9s de los rodamientos a tierra.","La tensi\xF3n de la correa era excesiva para la velocidad de operaci\xF3n del variador.","Falta de lubricaci\xF3n de f\xE1brica en un motor dise\xF1ado para operar a bajas RPM.","El variador de frecuencia est\xE1 descalibrado y genera un torque excesivo al arranque."],respuesta_correcta:0,explicacion:"Los VFD generan voltajes de modo com\xFAn en la onda PWM que inducen corrientes par\xE1sitas a trav\xE9s del eje del motor hacia los rodamientos. Esto causa erosi\xF3n el\xE9ctrica (fluting) en las pistas, destruyendo los rodamientos prematuramente. Se requieren rodamientos aislados o anillos de puesta a tierra del eje."},{id:"ns_0109",categoria:"NATE_SR_RACK",pregunta:"Un rack de media temperatura usa una v\xE1lvula de bypass de gas caliente para control de capacidad. Si la v\xE1lvula falla abierta:",opciones:["La presi\xF3n de succi\xF3n aumentar\xE1 y el compresor podr\xEDa sobrecalentarse r\xE1pidamente.","El sistema se bloquear\xE1 por baja presi\xF3n al no recibir suficiente gas de retorno.","Las vitrinas se congelar\xE1n debido al exceso de refrigerante en los evaporadores.","El separador de aceite se llenar\xE1 de l\xEDquido causando una falla de lubricaci\xF3n."],respuesta_correcta:0,explicacion:"Una v\xE1lvula de bypass de gas caliente abierta continuamente inyecta gas de descarga caliente directamente a la succi\xF3n, elevando la presi\xF3n y temperatura de succi\xF3n. El compresor recircula gas caliente sin hacer trabajo \xFAtil y se sobrecalienta."},{id:"ns_0110",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC quiere implementar 'Tiered Pricing'. \xBFCu\xE1l es el objetivo principal de esta estrategia?",opciones:["Ofrecer opciones al cliente para aumentar el valor promedio de cada transacci\xF3n.","Reducir el costo operativo al estandarizar los tipos de reparaciones permitidas.","Eliminar la necesidad de que el t\xE9cnico explique los beneficios de cada pieza.","Cumplir con las regulaciones estatales sobre la transparencia de precios de servicios."],respuesta_correcta:0,explicacion:"El Tiered Pricing (Good/Better/Best) ofrece al cliente opciones de diferentes niveles, lo que psicol\xF3gicamente aumenta el valor promedio de cada transacci\xF3n al presentar la opci\xF3n intermedia como ideal."},{id:"ns_0111",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo opera en 'free cooling'. \xBFQu\xE9 condici\xF3n f\xEDsica permite que este proceso ocurra?",opciones:["La presi\xF3n del condensador es menor que la del evaporador debido al agua fr\xEDa.","El compresor gira a una velocidad m\xEDnima para mover solo el refrigerante gaseoso.","Las bombas de agua helada aumentan su flujo para compensar la falta de compresi\xF3n.","El refrigerante se inyecta directamente en la torre de enfriamiento para ser enfriado."],respuesta_correcta:0,explicacion:"El free cooling ocurre cuando el agua de torre est\xE1 tan fr\xEDa que la presi\xF3n del condensador cae por debajo de la del evaporador, permitiendo la circulaci\xF3n natural del refrigerante sin compresi\xF3n mec\xE1nica."},{id:"ns_0112",categoria:"NATE_SR_HVAC",pregunta:"Se encuentra una ca\xEDda de voltaje de 10V entre el contactor y el compresor. \xBFQu\xE9 debe hacer el Senior?",opciones:["Limpiar o reemplazar los contactos del contactor que presentan una alta resistencia.","Instalar un capacitor de arranque (Hard Start Kit) para compensar la ca\xEDda de tensi\xF3n.","Reemplazar el cableado por uno de mayor calibre desde el panel el\xE9ctrico principal.","Verificar si la empresa el\xE9ctrica est\xE1 suministrando un voltaje inestable a la casa."],respuesta_correcta:0,explicacion:"Una ca\xEDda de 10V entre el contactor y el compresor indica alta resistencia en los contactos del contactor, probablemente por picaduras o arco el\xE9ctrico. Contactos deteriorados generan calor excesivo y reducen el voltaje entregado al compresor, causando sobrecargas."},{id:"ns_0113",categoria:"NATE_SR_CEO",pregunta:"Un CEO detecta que el 'Technician Turnover' es del 40% anual. \xBFCu\xE1l es el costo oculto m\xE1s significativo?",opciones:["La p\xE9rdida de conocimiento institucional y la disminuci\xF3n de la lealtad del cliente.","El gasto directo en anuncios de reclutamiento y uniformes para los nuevos empleados.","La necesidad de comprar m\xE1s herramientas b\xE1sicas para los t\xE9cnicos que entran.","El aumento de las primas de seguro por tener conductores nuevos sin experiencia."],respuesta_correcta:0,explicacion:"La rotaci\xF3n del 40% destruye el conocimiento institucional acumulado y debilita la relaci\xF3n t\xE9cnico-cliente, un costo oculto que supera con creces los gastos visibles de reclutamiento."},{id:"ns_0114",categoria:"NATE_SR_MINISPLIT",pregunta:"En un sistema inverter, el puente rectificador falla repetidamente. \xBFQu\xE9 causa externa debe investigar el t\xE9cnico?",opciones:["Picos de voltaje transitorios o falta de una conexi\xF3n a tierra f\xEDsica adecuada.","Un compresor con un devanado parcialmente cortocircuitado que demanda corriente.","El uso de un protector de sobrevoltaje que no es compatible con sistemas inverter.","Una temperatura ambiente excesiva en el compartimento de la placa electr\xF3nica."],respuesta_correcta:0,explicacion:"Los picos de voltaje transitorios y la falta de tierra adecuada someten al puente rectificador a sobrevoltajes que exceden su capacidad, causando fallas repetitivas en este componente."},{id:"ns_0115",categoria:"NATE_SR_RACK",pregunta:"Un sistema de rack utiliza R-744 (CO2). En el enfriador de gas (gas cooler), el fluido sale a 95\xB0F. \xBFEstado del sistema?",opciones:["Operaci\xF3n transcr\xEDtica donde el gas no se condensa pero se enfr\xEDa a alta presi\xF3n.","Operaci\xF3n subcr\xEDtica normal donde el gas se ha convertido totalmente en l\xEDquido.","Fallo del ventilador del condensador que impide la licuefacci\xF3n del refrigerante.","Carga insuficiente de CO2 que impide que el sistema alcance la presi\xF3n de dise\xF1o."],respuesta_correcta:0,explicacion:"A 95\xB0F el CO2 est\xE1 por encima de su punto cr\xEDtico (87.8\xB0F), por lo que opera en modo transcr\xEDtico. En esta condici\xF3n el CO2 no se condensa; solo se enfr\xEDa como gas supercr\xEDtico denso en el gas-cooler."},{id:"ns_0116",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete tiene un Delta P de aceite bajo. El t\xE9cnico agrega aceite pero el problema persiste. \xBFQu\xE9 sigue?",opciones:["Verificar si hay refrigerante l\xEDquido diluyendo el aceite en el c\xE1rter del compresor.","Cambiar la bomba de aceite mec\xE1nica por una de mayor desplazamiento volum\xE9trico.","Limpiar el cedazo de succi\xF3n de aceite que podr\xEDa estar obstruido por carbonilla.","Drenar el exceso de aceite agregado para evitar un golpe de l\xEDquido en el cilindro."],respuesta_correcta:0,explicacion:"Cuando agregar aceite no resuelve el Delta P bajo, la causa m\xE1s com\xFAn es migraci\xF3n de refrigerante l\xEDquido al c\xE1rter. El refrigerante diluye el aceite, reduce su viscosidad y la bomba no puede generar presi\xF3n diferencial suficiente para la lubricaci\xF3n."},{id:"ns_0117",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior debe entrenar a un Junior en el uso de la tabla P/T. \xBFCu\xE1l es el concepto clave a ense\xF1ar?",opciones:["La relaci\xF3n entre presi\xF3n y temperatura solo es v\xE1lida en un estado de saturaci\xF3n.","La tabla P/T se usa para determinar el sobrecalentamiento en cualquier punto.","Siempre se debe restar la presi\xF3n atmosf\xE9rica antes de buscar el valor en la tabla.","Los refrigerantes con glide (mezclas) tienen una sola columna para el punto de burbuja."],respuesta_correcta:0,explicacion:"La tabla P/T refleja la relaci\xF3n presi\xF3n-temperatura \xFAnicamente en estado de saturaci\xF3n (mezcla l\xEDquido-vapor). Si el refrigerante est\xE1 sobrecalentado o subenfriado, la tabla no aplica directamente; entender esto es la base del diagn\xF3stico HVACR."},{id:"ns_0118",categoria:"NATE_SR_CHILLERS",pregunta:"Se detecta una fuga en el evaporador de un chiller de baja presi\xF3n (R-123). \xBFCu\xE1l es el s\xEDntoma inmediato?",opciones:["La unidad de purga opera con mucha frecuencia para expulsar el aire infiltrado.","La presi\xF3n de descarga aumenta debido a la p\xE9rdida de masa de refrigerante.","El agua helada se contamina con aceite y empieza a oler a qu\xEDmico en el edificio.","El compresor se apaga por alta temperatura de aceite debido a la falta de enfriamiento."],respuesta_correcta:0,explicacion:"El R-123 opera bajo presi\xF3n atmosf\xE9rica (vac\xEDo). Una fuga en el evaporador permite la entrada de aire, y la unidad de purga trabaja con mayor frecuencia para expulsar el aire infiltrado."},{id:"ns_0119",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor utiliza una TXV con orificio de bypass. Si el bypass se bloquea, \xBFqu\xE9 sucede en modo calor?",opciones:["El sistema se bloquea por baja presi\xF3n ya que no fluye refrigerante al exterior.","La presi\xF3n de descarga sube al m\xE1ximo porque el l\xEDquido no puede retornar.","El compresor empieza a zumbar pero no puede mover el refrigerante en el ciclo.","La v\xE1lvula inversora se queda en una posici\xF3n intermedia por falta de diferencial."],respuesta_correcta:0,explicacion:"En sistemas con TXV y orificio de bypass, el bypass permite el flujo en modo calor. Si se bloquea, no hay flujo al serpentin exterior y la presion baja cae drasticamente hasta activar el switch de baja presion."},{id:"ns_0120",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere aumentar el 'Gross Profit Margin'. \xBFCu\xE1l de estas acciones impacta m\xE1s r\xE1pido?",opciones:["Mejorar la precisi\xF3n de los presupuestos para reducir el desperdicio de materiales.","Contratar a m\xE1s personal administrativo para gestionar mejor las facturas de cobro.","Comprar uniformes m\xE1s econ\xF3micos para reducir el gasto general de la empresa.","Aumentar el l\xEDmite de cr\xE9dito de los clientes para fomentar compras m\xE1s grandes."],respuesta_correcta:0,explicacion:"Mejorar la precisi\xF3n de presupuestos reduce el desperdicio de materiales y el tiempo improductivo, impactando directamente el Gross Profit Margin de forma inmediata y medible."},{id:"ns_0121",categoria:"NATE_SR_RACK",pregunta:"En un rack, el sensor de presi\xF3n de succi\xF3n falla y marca 0 PSI constantes. \xBFQu\xE9 acci\xF3n toma el controlador?",opciones:["Apaga todos los compresores por seguridad para prevenir da\xF1os mec\xE1nicos graves.","Arranca todos los compresores al 100% asumiendo una carga m\xE1xima de dise\xF1o.","Ignora la lectura y opera bas\xE1ndose en la temperatura de retorno de las vitrinas.","Activa una alarma pero sigue operando el \xFAltimo compresor que estaba encendido."],respuesta_correcta:0,explicacion:"Cuando el sensor de presi\xF3n de succi\xF3n reporta una lectura anormal de 0 PSI, el controlador interpreta una condici\xF3n peligrosa y apaga todos los compresores como medida de seguridad (fail-safe) para prevenir operaci\xF3n sin control."},{id:"ns_0122",categoria:"NATE_SR_MINISPLIT",pregunta:"Al instalar un Mini-split, el t\xE9cnico nota que el cable de comunicaci\xF3n tiene un empalme. \xBFCu\xE1l es la postura del Senior?",opciones:["Prohibir los empalmes, ya que alteran la impedancia y causan errores de datos.","Permitir el empalme siempre que se use soldadura de esta\xF1o y tubo termocontr\xE1ctil.","Aceptar el empalme si se realiza dentro de una caja de conexiones accesible.","Permitirlo solo si el tramo total de cable no excede los 50 pies de longitud."],respuesta_correcta:0,explicacion:"Los empalmes en el cable de comunicaci\xF3n alteran la impedancia de la l\xEDnea y generan reflexiones de se\xF1al, causando errores de datos. El Senior exige un cable continuo sin empalmes."},{id:"ns_0123",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta un Delta T de 28\xB0F y baja presi\xF3n de succi\xF3n. El flujo de aire parece bajo. \xBFCausa?",opciones:["Un evaporador sucio o un filtro de aire con una ca\xEDda de presi\xF3n excesiva.","Falta de refrigerante que provoca un enfriamiento desigual en el serpent\xEDn.","Una v\xE1lvula de expansi\xF3n (TXV) que est\xE1 inyectando demasiado refrigerante.","El compresor tiene las v\xE1lvulas de descarga rotas y no succiona correctamente."],respuesta_correcta:0,explicacion:"Un Delta T alto de 28\xB0F con baja succi\xF3n indica que poco aire pasa por el evaporador. Un evaporador sucio o filtro restrictivo reducen el CFM, lo que causa mayor ca\xEDda de temperatura del aire que s\xED pasa y menor absorci\xF3n total de calor, bajando la presi\xF3n de succi\xF3n."},{id:"ns_0124",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene tubos de cobre con recubrimiento de pol\xEDmero. \xBFCu\xE1l es la ventaja t\xE9cnica principal?",opciones:["Prevenir la corrosi\xF3n galv\xE1nica y el fouling biol\xF3gico en el lado del agua.","Aumentar la transferencia t\xE9rmica por encima de la conductividad del cobre puro.","Permitir que el refrigerante opere a presiones m\xE1s altas sin riesgo de ruptura.","Reducir el peso total del intercambiador de calor para facilitar su transporte."],respuesta_correcta:0,explicacion:"El recubrimiento de pol\xEDmero en tubos de cobre act\xFAa como barrera contra la corrosi\xF3n galv\xE1nica y previene la adhesi\xF3n de biofilm y fouling biol\xF3gico en el lado del agua."},{id:"ns_0125",categoria:"NATE_SR_CEO",pregunta:"Un CEO analiza el 'Customer Lifetime Value' (CLV). \xBFQu\xE9 grupo de clientes suele tener el CLV m\xE1s alto?",opciones:["Clientes con contratos de mantenimiento preventivo y actualizaciones de sistema.","Clientes que solo llaman para reparaciones de emergencia en d\xEDas festivos.","Nuevos propietarios de viviendas que buscan la opci\xF3n de instalaci\xF3n m\xE1s barata.","Empresas constructoras que compran equipos por volumen para edificios nuevos."],respuesta_correcta:0,explicacion:"Los clientes con contratos de mantenimiento preventivo generan ingresos recurrentes durante a\xF1os y son m\xE1s propensos a comprar actualizaciones de sistema, maximizando el CLV."},{id:"ns_0126",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calefacci\xF3n, el acumulador de succi\xF3n de una bomba de calor se llena de escarcha. \xBFQu\xE9 indica?",opciones:["Operaci\xF3n normal donde el acumulador protege al compresor del l\xEDquido fr\xEDo.","Una falla total de la v\xE1lvula inversora que se qued\xF3 en modo refrigeraci\xF3n.","Que el sistema tiene una sobrecarga de refrigerante l\xEDquida muy peligrosa.","El ventilador interior se detuvo y no hay intercambio de calor en la casa."],respuesta_correcta:0,explicacion:"En modo calefaccion, algo de escarcha en el acumulador es normal. El acumulador retiene refrigerante liquido que no se evaporo completamente en el serpentin exterior, protegiendolo de entrar al compresor en estado liquido."},{id:"ns_0127",categoria:"NATE_SR_RACK",pregunta:"Un sistema de rack utiliza un 'Subcooler' mec\xE1nico. \xBFCu\xE1l es el beneficio directo para el Senior?",opciones:["Aumentar la capacidad de enfriamiento de las vitrinas y reducir el flash gas.","Bajar la presi\xF3n de descarga de los compresores para ahorrar energ\xEDa el\xE9ctrica.","Prevenir que el aceite se caliente demasiado antes de entrar al separador.","Eliminar la necesidad de usar v\xE1lvulas de expansi\xF3n t\xE9rmicas en los servicios."],respuesta_correcta:0,explicacion:"El subcooler enfr\xEDa el refrigerante l\xEDquido por debajo de su temperatura de saturaci\xF3n, reduciendo la formaci\xF3n de flash gas en la v\xE1lvula de expansi\xF3n. Esto aumenta directamente la capacidad frigor\xEDfica disponible en los evaporadores."},{id:"ns_0128",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de 10 toneladas tiene dos circuitos independientes. El circuito 1 est\xE1 muerto. \xBFRiesgo?",opciones:["El serpent\xEDn del evaporador se congelar\xE1 parcialmente debido al flujo de aire desigual.","El compresor del circuito 2 se quemar\xE1 por trabajar el doble de tiempo nominal.","El economizador dejar\xE1 de funcionar porque detecta un desequilibrio t\xE9rmico.","La humedad en el edificio aumentar\xE1 dr\xE1sticamente al no haber deshumidificaci\xF3n."],respuesta_correcta:0,explicacion:"Con un circuito muerto, la mitad del serpent\xEDn del evaporador no tiene refrigerante pero sigue recibiendo flujo de aire. La otra mitad trabaja a carga m\xE1xima con todo el flujo, causando temperaturas de evaporaci\xF3n muy bajas que congelan esa secci\xF3n del serpent\xEDn."},{id:"ns_0129",categoria:"NATE_SR_MANAGEMENT",pregunta:"Como l\xEDder Senior, \xBFcu\xE1l es la mejor forma de verificar que un sistema est\xE1 libre de humedad?",opciones:["Realizar una prueba de ca\xEDda de vac\xEDo (standing vacuum test) y llegar a 500 micrones.","Observar que el visor de l\xEDquido (sight glass) cambie de color amarillo a verde.","Purgar un poco de refrigerante a la atm\xF3sfera y verificar si sale vapor de agua.","Dejar la bomba de vac\xEDo encendida durante exactamente 24 horas seguidas."],respuesta_correcta:0,explicacion:"El standing vacuum test a 500 micrones o menos confirma que la humedad fue eliminada. Si el vac\xEDo se mantiene estable tras apagar la bomba, el sistema est\xE1 seco y estanco. El visor de l\xEDquido solo detecta humedad despu\xE9s de cargar refrigerante."},{id:"ns_0130",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga 'non-condensable' de alta eficiencia. \xBFQu\xE9 hace con el refrigerante recuperado?",opciones:["Lo separa del aire y lo devuelve autom\xE1ticamente al evaporador del chiller.","Lo almacena en un cilindro externo para ser reciclado por el t\xE9cnico despu\xE9s.","Lo quema mediante una resistencia el\xE9ctrica para evitar su liberaci\xF3n al aire.","Lo mezcla con el aceite de lubricaci\xF3n para mantener la viscosidad correcta."],respuesta_correcta:0,explicacion:"La purga de alta eficiencia separa el refrigerante del aire mediante condensaci\xF3n, y devuelve autom\xE1ticamente el refrigerante recuperado al evaporador para minimizar las p\xE9rdidas del sistema."},{id:"ns_0131",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRF tiene una fuga en una de las 10 unidades interiores. \xBFCu\xE1l es el procedimiento Senior?",opciones:["Aislar la unidad mediante las v\xE1lvulas del colector (branch box) y reparar.","Recuperar el refrigerante de todo el sistema para poder soldar esa unidad.","Puentear la unidad en el software y dejar que el sistema opere con las otras 9.","A\xF1adir sellador de fugas l\xEDquido al sistema para evitar el paro de las zonas."],respuesta_correcta:0,explicacion:"En sistemas VRF, las v\xE1lvulas del colector (branch box) permiten aislar una unidad individual sin recuperar todo el refrigerante del sistema, permitiendo reparar la fuga sin afectar las dem\xE1s zonas."},{id:"ns_0132",categoria:"NATE_SR_HVAC",pregunta:"Un compresor hace un ruido de 'clattering' durante el arranque. \xBFQu\xE9 problema mec\xE1nico indica?",opciones:["Arranque inundado (flooded start) con refrigerante l\xEDquido en el c\xE1rter.","Un capacitor de marcha que est\xE1 defectuoso y causa una vibraci\xF3n el\xE9ctrica.","Que el compresor est\xE1 girando en sentido contrario por una falla de fase.","Desgaste en los bujes superiores que permite que el rotor golpee el estator."],respuesta_correcta:0,explicacion:"El ruido de 'clattering' al arrancar indica que refrigerante l\xEDquido migr\xF3 al c\xE1rter durante el ciclo de apagado. Al arrancar, el aceite espumoso con l\xEDquido se succiona violentamente hacia los cilindros, causando golpes mec\xE1nicos (slugging) hasta que el l\xEDquido se evapora."},{id:"ns_0133",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar el 'Current Ratio' de la empresa. \xBFQu\xE9 acci\xF3n debe priorizar?",opciones:["Convertir activos de inventario obsoleto en efectivo y pagar deudas cortas.","Pedir un pr\xE9stamo a 10 a\xF1os para comprar un nuevo edificio administrativo.","Aumentar el salario de los t\xE9cnicos senior para mejorar la productividad.","Ofrecer descuentos a los clientes que paguen por adelantado sus servicios."],respuesta_correcta:0,explicacion:"Convertir inventario obsoleto en efectivo y pagar deudas a corto plazo mejora directamente el Current Ratio al aumentar activos corrientes l\xEDquidos y reducir pasivos corrientes."},{id:"ns_0134",categoria:"NATE_SR_RACK",pregunta:"Se observa que una v\xE1lvula EPR est\xE1 vibrando y haciendo ruido. \xBFCu\xE1l es el ajuste Senior?",opciones:["Ajustar el resorte de la v\xE1lvula para cambiar su frecuencia natural de oscilaci\xF3n.","Cerrar la v\xE1lvula completamente y dejar que el sistema opere por presi\xF3n de rack.","Instalar una trampa de aceite justo antes de la v\xE1lvula para amortiguar el gas.","Cambiar la v\xE1lvula por una de menor capacidad para aumentar la velocidad del gas."],respuesta_correcta:0,explicacion:"La vibraci\xF3n de una v\xE1lvula EPR indica que est\xE1 operando cerca de su punto de inestabilidad. Ajustar la tensi\xF3n del resorte cambia su frecuencia natural y elimina la resonancia con el flujo de gas, deteniendo la vibraci\xF3n."},{id:"ns_0135",categoria:"NATE_SR_PACKAGE",pregunta:"En un Rooftop, el sensor de 'Mixed Air' falla. \xBFC\xF3mo afecta esto al economizador?",opciones:["El damper se mover\xE1 a una posici\xF3n de seguridad (generalmente 100% retorno).","El economizador se abrir\xE1 al 100% para evitar el sobrecalentamiento del equipo.","Los compresores se apagar\xE1n inmediatamente para prevenir la congelaci\xF3n.","La placa de control ignorar\xE1 el sensor y operar\xE1 por tiempo de funcionamiento."],respuesta_correcta:0,explicacion:"El sensor de aire mezclado (Mixed Air) previene la congelaci\xF3n del serpent\xEDn al controlar la mezcla de aire exterior y retorno. Si falla, el controlador del economizador entra en modo de seguridad cerrando el damper de aire exterior (100% retorno) para evitar introducir aire fr\xEDo sin control."},{id:"ns_0136",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un approach de evaporador de 0\xB0F. \xBFQu\xE9 conclusi\xF3n t\xE9cnica es correcta?",opciones:["El sensor de temperatura est\xE1 descalibrado o hay refrigerante l\xEDquido en la succi\xF3n.","El sistema est\xE1 operando en su punto m\xE1ximo de eficiencia termodin\xE1mica.","Los tubos del evaporador han sido limpiados recientemente con \xE1cido fuerte.","El flujo de agua a trav\xE9s del evaporador es exactamente el doble del nominal."],respuesta_correcta:0,explicacion:"Un approach de 0\xB0F es f\xEDsicamente improbable en operaci\xF3n normal. Indica un sensor de temperatura descalibrado o presencia de refrigerante l\xEDquido en la succi\xF3n que falsea las lecturas."},{id:"ns_0137",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Junior pregunta por qu\xE9 soldar con nitr\xF3geno. El Senior responde que es para evitar:",opciones:["La formaci\xF3n de escamas de \xF3xido c\xFAprico que tapan las v\xE1lvulas de expansi\xF3n.","Que el cobre se debilite y se vuelva quebradizo por el exceso de calor.","La entrada de humedad atmosf\xE9rica al sistema durante el proceso de soldadura.","Que la soldadura de plata se oxide y pierda sus propiedades de adherencia."],respuesta_correcta:0,explicacion:"Al soldar sin nitr\xF3geno, el ox\xEDgeno del aire reacciona con el cobre caliente formando escamas de \xF3xido c\xFAprico (holl\xEDn negro) dentro de la tuber\xEDa. Estas part\xEDculas se desprenden y obstruyen filtros, TXVs y orificios, causando fallas del sistema."},{id:"ns_0138",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, la temperatura de descarga es de 230\xB0F. \xBFCu\xE1l es el l\xEDmite del Senior?",opciones:["225\xB0F; por encima de esto, el aceite empieza a carbonizarse y fallar\xE1.","250\xB0F; es la temperatura normal de operaci\xF3n para sistemas con R-410A.","200\xB0F; cualquier valor superior indica una falta de carga de refrigerante.","275\xB0F; el compresor tiene un protector t\xE9rmico que actuar\xE1 en este punto."],respuesta_correcta:0,explicacion:"El limite seguro de temperatura de descarga es aproximadamente 225F. Por encima de este valor, el aceite lubricante comienza a carbonizarse, perdiendo sus propiedades y eventualmente causando falla del compresor."},{id:"ns_0139",categoria:"NATE_SR_RACK",pregunta:"Se detecta que el 'Heat Reclaim' de un supermercado no calienta el agua. \xBFQu\xE9 revisa?",opciones:["La v\xE1lvula de tres v\xEDas que desv\xEDa el gas caliente hacia el intercambiador.","La presi\xF3n del receptor de l\xEDquido que podr\xEDa estar demasiado alta para el flujo.","El nivel de aceite en el rack que podr\xEDa estar bloqueando el intercambio de calor.","La velocidad de los ventiladores del condensador principal del sistema de rack."],respuesta_correcta:0,explicacion:"El sistema de Heat Reclaim depende de una v\xE1lvula de tres v\xEDas que desv\xEDa el gas caliente de descarga hacia el intercambiador de calor del agua. Si esta v\xE1lvula falla o no abre, el gas caliente va directo al condensador sin calentar el agua."},{id:"ns_0140",categoria:"NATE_SR_CEO",pregunta:"Un CEO debe asegurar que todos los t\xE9cnicos tengan la certificaci\xF3n EPA 608. \xBFPor qu\xE9?",opciones:["Para evitar multas federales y permitir la compra legal de refrigerantes.","Porque es un requisito para que la empresa pueda cotizar en la bolsa.","Para reducir el costo de los seguros de salud de los empleados t\xE9cnicos.","Porque los fabricantes no venden equipos a empresas sin t\xE9cnicos certificados."],respuesta_correcta:0,explicacion:"La certificaci\xF3n EPA 608 es un requisito federal para manejar refrigerantes; sin ella, la empresa enfrenta multas severas y los t\xE9cnicos no pueden comprar refrigerante legalmente."},{id:"ns_0141",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una ca\xEDda de presi\xF3n de agua muy alta en el condensador. \xBFCausa probable?",opciones:["Obstrucci\xF3n por escombros o incrustaciones en los tubos del intercambiador.","La bomba de agua de la torre est\xE1 girando a una velocidad excesiva.","El refrigerante est\xE1 congelando el agua dentro de los tubos del condensador.","Las v\xE1lvulas de aislamiento del condensador est\xE1n completamente abiertas."],respuesta_correcta:0,explicacion:"Una ca\xEDda de presi\xF3n de agua muy alta en el condensador indica obstrucci\xF3n en los tubos por escombros, incrustaciones minerales o lodo que restringen el paso del agua."},{id:"ns_0142",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split reporta un c\xF3digo de error de 'DC Voltage Low'. \xBFQu\xE9 componente revisa?",opciones:["Los capacitores de filtrado en la placa de potencia de la unidad exterior.","El voltaje de la bater\xEDa del control remoto inal\xE1mbrico de la unidad interior.","La continuidad de los fusibles t\xE9rmicos dentro del motor del ventilador.","El transformador de 24V que alimenta la placa de control principal."],respuesta_correcta:0,explicacion:"El error 'DC Voltage Low' indica que el bus de voltaje DC interno est\xE1 ca\xEDdo. Los capacitores de filtrado en la placa de potencia son los responsables de mantener ese voltaje estable tras la rectificaci\xF3n."},{id:"ns_0143",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene un sobrecalentamiento de 2\xB0F y un subenfriamiento de 20\xB0F. \xBFDiagn\xF3stico?",opciones:["Sistema sobrecargado de refrigerante que inunda el evaporador.","V\xE1lvula de expansi\xF3n (TXV) bloqueada en la posici\xF3n de cerrado.","Filtro de aire sucio que reduce la carga t\xE9rmica en el evaporador.","El compresor est\xE1 perdiendo eficiencia y no succiona refrigerante."],respuesta_correcta:0,explicacion:"Un sobrecalentamiento de 2\xB0F indica que el evaporador est\xE1 casi inundado de l\xEDquido, y un subenfriamiento de 20\xB0F indica exceso de l\xEDquido acumulado en el condensador. Ambos s\xEDntomas juntos confirman una sobrecarga de refrigerante en el sistema."},{id:"ns_0144",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete con calefacci\xF3n el\xE9ctrica, un elemento no calienta. \xBFQu\xE9 revisa?",opciones:["El secuenciador o el contactor que activa ese banco de resistencias.","El termostato de seguridad de l\xEDmite de aire que est\xE1 abierto por calor.","El interruptor de flujo de aire que detecta una presi\xF3n est\xE1tica baja.","La configuraci\xF3n del ventilador que no est\xE1 en modo 'G' durante el calor."],respuesta_correcta:0,explicacion:"En calefacci\xF3n el\xE9ctrica, cada banco de resistencias se activa mediante un secuenciador o contactor individual. Si solo un elemento no calienta, el problema est\xE1 en el componente que controla ese banco espec\xEDfico, no en los controles de seguridad generales."},{id:"ns_0145",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere implementar un programa de mantenimiento preventivo. \xBFCu\xE1l es el KPI de \xE9xito?",opciones:["El aumento en la tasa de renovaci\xF3n de contratos a\xF1o tras a\xF1o.","La cantidad de filtros de aire comprados mensualmente por la empresa.","El n\xFAmero de quejas de clientes recibidas a trav\xE9s de la p\xE1gina web.","La reducci\xF3n en la cantidad de millas recorridas por las camionetas."],respuesta_correcta:0,explicacion:"La tasa de renovaci\xF3n de contratos mide directamente si los clientes valoran el servicio de mantenimiento preventivo lo suficiente para seguir pagando, siendo el KPI de \xE9xito m\xE1s relevante."},{id:"ns_0146",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor tiene una succi\xF3n de 50 PSI con R-410A. \xBFProblema?",opciones:["Baja absorci\xF3n de calor en el serpent\xEDn exterior por hielo o falla de motor.","Falla de la v\xE1lvula inversora que est\xE1 enviando gas a la descarga directa.","El termostato interior est\xE1 configurado a una temperatura muy baja.","Es una presi\xF3n normal de funcionamiento cuando hace mucho fr\xEDo afuera."],respuesta_correcta:0,explicacion:"Con R-410A, una succion de 50 PSI corresponde a aproximadamente 10F de saturacion, lo cual es muy bajo. Indica que el serpentin exterior no absorbe suficiente calor, ya sea por hielo o falla del ventilador exterior."},{id:"ns_0147",categoria:"NATE_SR_RACK",pregunta:"En un rack, la mirilla del separador de aceite est\xE1 vac\xEDa durante la carga m\xE1xima. \xBFQu\xE9 hace?",opciones:["Verificar si el aceite est\xE1 atrapado en los evaporadores o en el condensador.","Agregar 2 galones de aceite POE de inmediato para proteger los compresores.","Apagar el rack y esperar a que el aceite regrese por gravedad al sistema.","Aumentar la presi\xF3n del recibidor para forzar el aceite hacia los c\xE1rteres."],respuesta_correcta:0,explicacion:"Antes de agregar aceite, se debe verificar d\xF3nde est\xE1 el aceite existente. A carga m\xE1xima, el aceite puede estar atrapado en evaporadores o condensador por baja velocidad de gas. Agregar aceite sin diagn\xF3stico puede causar exceso cuando el aceite regrese."},{id:"ns_0148",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior observa que un ayudante no usa gafas de seguridad al recuperar gas. \xBFPor qu\xE9?",opciones:["El refrigerante l\xEDquido puede causar congelaci\xF3n instant\xE1nea y ceguera.","El aceite del sistema es altamente \xE1cido y puede irritar la piel de la cara.","La presi\xF3n del gas puede hacer que la manguera golpee el ojo del t\xE9cnico.","Es una regla de la empresa que no tiene un impacto t\xE9cnico real en la vista."],respuesta_correcta:0,explicacion:"El refrigerante en estado l\xEDquido se evapora instant\xE1neamente al contacto con la piel o los ojos, causando quemaduras por congelaci\xF3n severas. Un salpic\xF3n en los ojos puede provocar ceguera permanente, por eso las gafas de seguridad son obligatorias."},{id:"ns_0149",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo tiene una falla de 'surge' a baja carga. \xBFQu\xE9 ajuste realiza?",opciones:["Ajustar los \xE1labes de entrada (vanes) o usar un variador de frecuencia.","Incrementar el set-point de temperatura de salida del agua helada.","Abrir la v\xE1lvula de expansi\xF3n para aumentar la masa de refrigerante.","Limpiar los tubos del condensador para bajar la presi\xF3n de descarga."],respuesta_correcta:0,explicacion:"El surge a baja carga se corrige ajustando los \xE1labes de entrada (vanes) para mantener el flujo m\xEDnimo de gas, o usando un VFD para reducir la velocidad del compresor y mantener la relaci\xF3n de presiones."},{id:"ns_0150",categoria:"NATE_SR_HVAC",pregunta:"Un motor de soplador PSC zumba pero no gira. Si se ayuda con la mano, arranca. \xBFQu\xE9 falla?",opciones:["El capacitor de marcha est\xE1 abierto o ha perdido su capacitancia.","El devanado de trabajo del motor tiene un cortocircuito interno.","La placa de control no est\xE1 enviando el voltaje de fase correcto.","Los rodamientos del motor est\xE1n secos y requieren lubricaci\xF3n."],respuesta_correcta:0,explicacion:"Un motor PSC necesita el capacitor para crear el desfase de fase necesario entre el devanado de arranque y el de marcha. Si el capacitor est\xE1 abierto o sin capacitancia, el motor zumba porque recibe corriente pero no puede generar el par de arranque rotacional."},{id:"ns_0151",categoria:"NATE_SR_CEO",pregunta:"Un CEO eval\xFAa el 'Debt-to-Equity Ratio'. Si el valor es de 3.0, \xBFqu\xE9 significa?",opciones:["La empresa tiene mucha deuda en relaci\xF3n con el capital de los socios.","La empresa es muy rentable y tiene un flujo de caja excelente actualmente.","Los activos de la empresa son tres veces superiores a sus deudas totales.","La empresa califica para cr\xE9ditos bancarios con las tasas m\xE1s bajas."],respuesta_correcta:0,explicacion:"Un Debt-to-Equity Ratio de 3.0 significa que por cada d\xF3lar de capital propio, la empresa tiene $3 de deuda, indicando un apalancamiento muy alto y riesgo financiero significativo."},{id:"ns_0152",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no modula su velocidad y opera siempre al 100%. \xBFQu\xE9 revisa?",opciones:["El termistor de temperatura ambiente o la configuraci\xF3n del control remoto.","La placa de potencia exterior que tiene un transistor IGBT bloqueado.","La carga de refrigerante que es excesiva y fuerza al compresor al m\xE1ximo.","El motor del ventilador interior que no reporta sus RPM a la placa principal."],respuesta_correcta:0,explicacion:"Si el inverter no modula y opera siempre al 100%, el termistor de temperatura ambiente puede estar descalibrado o el control remoto mal configurado, haciendo que el sistema crea que nunca alcanza el setpoint."},{id:"ns_0153",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor con R-410A, \xBFcu\xE1l es el prop\xF3sito del 'Crancase Heater'?",opciones:["Evitar la migraci\xF3n de refrigerante al aceite durante los periodos de paro.","Mantener el refrigerante en estado gaseoso para facilitar el arranque r\xE1pido.","Aumentar la temperatura del gas de descarga para mejorar la calefacci\xF3n.","Reducir la viscosidad del aceite para que fluya mejor hacia los cojinetes."],respuesta_correcta:0,explicacion:"El calentador de carter (crankcase heater) mantiene el aceite del compresor caliente durante los periodos de paro. Esto evita que el refrigerante liquido migre al carter y diluya el aceite, previniendo slugging al arrancar."},{id:"ns_0154",categoria:"NATE_SR_RACK",pregunta:"Un rack paralelo tiene un compresor que vibra mucho m\xE1s que los otros. \xBFQu\xE9 revisa?",opciones:["Los soportes antivibratorios de goma o la nivelaci\xF3n del compresor.","Si ese compresor est\xE1 retornando m\xE1s l\xEDquido que los dem\xE1s del grupo.","La presi\xF3n de aceite de ese compresor espec\xEDfico comparada con el rack.","La configuraci\xF3n del variador de frecuencia que controla a ese compresor."],respuesta_correcta:0,explicacion:"Si solo un compresor vibra excesivamente mientras los dem\xE1s operan normal, la causa m\xE1s probable es mec\xE1nica: soportes antivibratorios (grommets) desgastados o rotos, o una mala nivelaci\xF3n del compresor en la base del rack."},{id:"ns_0155",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un cliente pide un descuento porque el t\xE9cnico Senior tard\xF3 10 minutos. \xBFQu\xE9 dice el l\xEDder?",opciones:["Explica que el cobro es por el conocimiento y la soluci\xF3n, no por el tiempo.","Acepta el descuento para evitar una mala rese\xF1a en las redes sociales.","Le dice al cliente que el t\xE9cnico es experto y por eso fue tan r\xE1pido.","Cobra solo la pieza y regala la mano de obra para mantener la relaci\xF3n."],respuesta_correcta:0,explicacion:"El valor del servicio t\xE9cnico radica en el conocimiento, la experiencia y la soluci\xF3n del problema, no en las horas invertidas. Un diagn\xF3stico r\xE1pido refleja a\xF1os de experiencia y formaci\xF3n, y eso es lo que el cliente paga."},{id:"ns_0156",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga manual. \xBFC\xF3mo sabe el Senior que hay aire dentro?",opciones:["La presi\xF3n del condensador es mayor que la presi\xF3n de saturaci\xF3n del gas.","La temperatura del agua helada empieza a subir sin raz\xF3n aparente.","El compresor hace un ruido met\xE1lico debido a la compresi\xF3n del aire.","El visor de l\xEDquido muestra burbujas constantes a pesar de la carga total."],respuesta_correcta:0,explicacion:"La presencia de gases no condensables (aire) eleva la presi\xF3n del condensador por encima de la presi\xF3n de saturaci\xF3n correspondiente a la temperatura del refrigerante. Esta diferencia confirma la presencia de aire."},{id:"ns_0157",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 150 PSI y descarga de 350 PSI con R-410A. \xBFC\xF3mo est\xE1?",opciones:["Presiones normales para un d\xEDa caluroso con una carga t\xE9rmica alta.","Falta de refrigerante que impide que la descarga suba a niveles normales.","Exceso de refrigerante que eleva la presi\xF3n de succi\xF3n por encima del l\xEDmite.","Compresor defectuoso que no logra crear el diferencial de presi\xF3n adecuado."],respuesta_correcta:0,explicacion:"Con R-410A, una succi\xF3n de 150 PSI equivale a ~48\xB0F de saturaci\xF3n y 350 PSI de descarga equivale a ~100\xB0F de condensaci\xF3n. Estas son presiones normales para un d\xEDa caluroso con carga t\xE9rmica alta, indicando operaci\xF3n correcta del sistema."},{id:"ns_0158",categoria:"NATE_SR_PACKAGE",pregunta:"En un Rooftop, el damper de alivio barom\xE9trico est\xE1 siempre abierto. \xBFConsecuencia?",opciones:["P\xE9rdida de presi\xF3n positiva en el edificio e infiltraci\xF3n de aire exterior.","Congelaci\xF3n del serpent\xEDn del evaporador por falta de carga t\xE9rmica.","Aumento del consumo de gas en el horno durante el ciclo de calefacci\xF3n.","Falla del motor del soplador por operar con una presi\xF3n est\xE1tica baja."],respuesta_correcta:0,explicacion:"El damper barom\xE9trico debe abrir solo cuando la presi\xF3n del edificio es positiva para aliviar el exceso. Si queda abierto permanentemente, el aire acondicionado del edificio se escapa al exterior, eliminando la presi\xF3n positiva y permitiendo infiltraci\xF3n descontrolada de aire exterior sin tratar."},{id:"ns_0159",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere incentivar a los t\xE9cnicos a vender m\xE1s. \xBFCu\xE1l es el riesgo de \xE9tica?",opciones:["Que los t\xE9cnicos recomienden reparaciones o equipos innecesarios al cliente.","Que los t\xE9cnicos se distraigan y tarden m\xE1s tiempo en realizar las reparaciones.","Que los clientes se quejen por sentir una presi\xF3n de venta durante el servicio.","Que el inventario de las camionetas se agote m\xE1s r\xE1pido de lo presupuestado."],respuesta_correcta:0,explicacion:"Cuando los t\xE9cnicos tienen incentivos de venta agresivos, el mayor riesgo \xE9tico es que recomienden reparaciones o equipos innecesarios, da\xF1ando la confianza del cliente y la reputaci\xF3n."},{id:"ns_0160",categoria:"NATE_SR_RACK",pregunta:"Un rack usa descongelaci\xF3n el\xE9ctrica. El contactor se quema cada mes. \xBFQu\xE9 revisa?",opciones:["Si el amperaje de las resistencias excede la capacidad del contactor.","Si el voltaje de la bobina del contactor es de 120V en lugar de 24V.","Si el reloj de deshielo est\xE1 configurado para ciclos demasiado largos.","Si los cables de alimentaci\xF3n de las resistencias tienen el calibre correcto."],respuesta_correcta:0,explicacion:"Un contactor que se quema repetidamente indica que el amperaje de las resistencias de deshielo excede la capacidad nominal del contactor. Los contactos se sobrecalientan y sueldan, requiriendo un contactor de mayor capacidad o divisi\xF3n de circuitos."},{id:"ns_0161",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Motor High Temp'. El agua est\xE1 fr\xEDa. \xBFQu\xE9 revisa?",opciones:["La l\xEDnea de enfriamiento del motor (refrigerante l\xEDquido) y su filtro.","La viscosidad del aceite que podr\xEDa estar causando fricci\xF3n en el motor.","El flujo de agua en el condensador que podr\xEDa ser insuficiente para enfriar.","Si el compresor est\xE1 operando con un voltaje excesivamente alto o bajo."],respuesta_correcta:0,explicacion:"En chillers centr\xEDfugos, el motor se enfr\xEDa con refrigerante l\xEDquido. Si la l\xEDnea de enfriamiento o su filtro est\xE1n bloqueados, el motor se sobrecalienta aunque el agua del sistema est\xE9 fr\xEDa."},{id:"ns_0162",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter muestra el error 'Outdoor Fan Motor error'. \xBFQu\xE9 prueba?",opciones:["Si el ventilador gira libremente y el voltaje de la placa al motor.","El capacitor de arranque del motor del ventilador de la unidad exterior.","La continuidad de los cables de se\xF1al del termostato hacia la unidad.","La carga de refrigerante que podr\xEDa estar bloqueando el flujo de aire."],respuesta_correcta:0,explicacion:"Ante un error de motor del ventilador exterior, el Senior verifica primero si gira libremente (sin obstrucci\xF3n mec\xE1nica) y luego mide el voltaje que la placa env\xEDa al motor para confirmar si es falla mec\xE1nica o electr\xF3nica."},{id:"ns_0163",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una TXV. El sobrecalentamiento es de 25\xB0F y el subenfriamiento de 2\xB0F. \xBFCausa?",opciones:["Falta de refrigerante en el sistema (undercharged).","V\xE1lvula de expansi\xF3n (TXV) bloqueada o fallida.","Restricci\xF3n en el filtro deshidratador de la l\xEDnea de l\xEDquido.","Exceso de flujo de aire a trav\xE9s del serpent\xEDn del evaporador."],respuesta_correcta:0,explicacion:"Un sobrecalentamiento alto de 25\xB0F indica que el evaporador no recibe suficiente refrigerante, y un subenfriamiento bajo de 2\xB0F indica que hay poco l\xEDquido en el condensador. Ambos s\xEDntomas juntos son se\xF1al cl\xE1sica de un sistema con falta de carga (undercharged)."},{id:"ns_0164",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete, el compresor no arranca pero el ventilador s\xED. \xBFQu\xE9 revisa?",opciones:["El contactor del compresor y los interruptores de seguridad (HP/LP).","El fusible de la placa de control que alimenta al motor del soplador.","El sensor de temperatura de aire de retorno que activa la calefacci\xF3n.","La presi\xF3n de gas de entrada si la unidad es de tipo dual (gas/electric)."],respuesta_correcta:0,explicacion:"Si el ventilador opera pero el compresor no, el circuito de control de baja tensi\xF3n funciona. El problema est\xE1 en el circuito del compresor: el contactor puede no estar cerrando, o un interruptor de seguridad de alta o baja presi\xF3n est\xE1 abierto bloqueando el arranque."},{id:"ns_0165",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota un aumento en el 'Days Sales Outstanding' (DSO). \xBFQu\xE9 significa?",opciones:["Los clientes est\xE1n tardando m\xE1s tiempo en pagar sus facturas a la empresa.","La empresa est\xE1 vendiendo m\xE1s servicios cada d\xEDa de lo que hab\xEDa planeado.","Los t\xE9cnicos est\xE1n terminando los trabajos m\xE1s r\xE1pido que el mes anterior.","El costo de ventas ha disminuido gracias a una mejor eficiencia operativa."],respuesta_correcta:0,explicacion:"Un DSO creciente indica que los clientes est\xE1n tardando m\xE1s en pagar sus facturas, lo que reduce el efectivo disponible y puede causar problemas de liquidez operativa."},{id:"ns_0166",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo refrigeraci\xF3n tiene una presi\xF3n de alta de 500 PSI. \xBFCausa?",opciones:["Condensador exterior sucio o falla del ventilador de la unidad exterior.","Evaporador interior sucio que reduce la absorci\xF3n de calor en la casa.","V\xE1lvula inversora que no cambi\xF3 de posici\xF3n y sigue en modo calefacci\xF3n.","Restricci\xF3n en la v\xE1lvula de expansi\xF3n de la unidad interior del sistema."],respuesta_correcta:0,explicacion:"En modo refrigeracion, el serpentin exterior es el condensador. Una presion de 500 PSI con R-410A indica que el condensador no puede rechazar el calor, tipicamente por suciedad o falla del ventilador exterior."},{id:"ns_0167",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 indica una mirilla de aceite con espuma persistente?",opciones:["Presencia de refrigerante l\xEDquido diluido en el aceite del c\xE1rter.","Que el aceite est\xE1 limpio y circulando a la velocidad de dise\xF1o correcta.","Que el separador de aceite est\xE1 funcionando con una eficiencia del 100%.","Que el calentador de c\xE1rter est\xE1 funcionando y evaporando el refrigerante."],respuesta_correcta:0,explicacion:"La espuma persistente en la mirilla de aceite indica que hay refrigerante l\xEDquido disuelto en el aceite. Al arrancar el compresor, la ca\xEDda de presi\xF3n del c\xE1rter hace que el refrigerante hierva dentro del aceite, creando espuma."},{id:"ns_0168",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior debe explicar el 'GWP' a un cliente. \xBFQu\xE9 significa?",opciones:["El potencial de calentamiento global del refrigerante usado en el equipo.","La garant\xEDa de piezas y mano de obra que ofrece el fabricante del sistema.","La eficiencia energ\xE9tica total del equipo en condiciones extremas de calor.","La presi\xF3n m\xE1xima de trabajo que puede soportar el serpent\xEDn de cobre."],respuesta_correcta:0,explicacion:"GWP (Global Warming Potential) mide cu\xE1nto contribuye un refrigerante al calentamiento global comparado con el CO2. Es un factor clave en la transici\xF3n a refrigerantes de bajo impacto ambiental como el R-32 o R-454B."},{id:"ns_0169",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga 'smart'. \xBFCu\xE1ndo decide purgar el sistema?",opciones:["Cuando detecta un diferencial entre la presi\xF3n real y la de saturaci\xF3n.","Cada 24 horas de operaci\xF3n continua del compresor para evitar fallos.","Cuando el operador presiona el bot\xF3n de purga manual en el panel frontal.","Cuando la temperatura del refrigerante l\xEDquido baja de los 40 grados F."],respuesta_correcta:0,explicacion:"La purga inteligente (smart) compara la presi\xF3n real del sistema con la presi\xF3n de saturaci\xF3n te\xF3rica a la temperatura medida. Si hay diferencial, indica no condensables y activa la purga autom\xE1ticamente."},{id:"ns_0170",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 120 PSI y el compresor est\xE1 caliente. \xBFQu\xE9 falta?",opciones:["Sobrecalentamiento correcto para enfriar el motor del compresor.","M\xE1s refrigerante para subir la presi\xF3n de succi\xF3n a 150 PSI nominal.","Un ventilador de condensador m\xE1s potente para bajar la temperatura.","Aceite lubricante en el c\xE1rter para reducir la fricci\xF3n de los pistones."],respuesta_correcta:0,explicacion:"Una succi\xF3n de 120 PSI con R-410A equivale a ~38\xB0F de saturaci\xF3n. Si el compresor est\xE1 caliente, es porque no tiene suficiente sobrecalentamiento de gas fr\xEDo para enfriar el motor interno. El refrigerante que regresa al compresor es lo que enfr\xEDa los devanados."},{id:"ns_0171",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Overhead'. \xBFCu\xE1l de estas es una medida directa?",opciones:["Reducir el alquiler de la oficina o el personal administrativo no t\xE9cnico.","Bajar el precio de los filtros de aire que se venden a los clientes finales.","Eliminar el uso de nitr\xF3geno durante las soldaduras de las instalaciones.","Aumentar la cuota de ventas de los t\xE9cnicos para generar m\xE1s ingresos brutos."],respuesta_correcta:0,explicacion:"El Overhead incluye costos indirectos como alquiler y personal administrativo; reducir estos gastos fijos no t\xE9cnicos es la forma m\xE1s directa de bajar el Overhead."},{id:"ns_0172",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no enciende y no hay c\xF3digos de error. \xBFQu\xE9 revisa?",opciones:["El fusible de la unidad interior y el voltaje de llegada de la l\xEDnea el\xE9ctrica.","La carga de refrigerante por peso para descartar una fuga total de gas.","Si el compresor est\xE1 aterrizado midiendo la resistencia contra la carcasa.","La placa electr\xF3nica de la unidad exterior por si hay rastros de quemaduras."],respuesta_correcta:0,explicacion:"Sin c\xF3digos de error, el sistema probablemente no recibe energ\xEDa. El Senior revisa primero el fusible de la placa interior y confirma que llegan 240VAC, ya que sin alimentaci\xF3n no hay diagn\xF3stico electr\xF3nico posible."},{id:"ns_0173",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un ruido de soplido constante en la inversora. \xBFCausa?",opciones:["Fuga interna de gas de la descarga hacia la succi\xF3n a trav\xE9s de la v\xE1lvula.","El refrigerante l\xEDquido est\xE1 pasando por la v\xE1lvula a una velocidad alta.","La bobina de la solenoide est\xE1 vibrando contra el cuerpo de la v\xE1lvula.","Es un sonido normal del flujo de refrigerante en sistemas de alta capacidad."],respuesta_correcta:0,explicacion:"Un ruido de soplido constante en la valvula inversora indica fuga interna. El gas de alta presion (descarga) pasa hacia el lado de baja presion (succion), reduciendo la eficiencia y causando el ruido caracteristico."},{id:"ns_0174",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFcu\xE1l es la funci\xF3n de la v\xE1lvula 'Holdback' o de presi\xF3n de condensaci\xF3n?",opciones:["Mantener una presi\xF3n m\xEDnima en el condensador durante climas muy fr\xEDos.","Evitar que el l\xEDquido regrese al separador de aceite durante el deshielo.","Regular el flujo de refrigerante hacia los evaporadores de baja temperatura.","Proteger al recibidor de una sobrepresi\xF3n causada por una falla del ventilador."],respuesta_correcta:0,explicacion:"La v\xE1lvula holdback mantiene una presi\xF3n m\xEDnima de condensaci\xF3n en climas fr\xEDos. Sin ella, la presi\xF3n de descarga bajar\xEDa tanto que las v\xE1lvulas de expansi\xF3n no tendr\xEDan suficiente diferencial de presi\xF3n para alimentar l\xEDquido a los evaporadores."},{id:"ns_0175",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior recibe una llamada de un t\xE9cnico Junior que est\xE1 perdido. \xBFAcci\xF3n?",opciones:["Guiarlo paso a paso por tel\xE9fono usando un proceso de diagn\xF3stico l\xF3gico.","Decirle que lea el manual y que no lo llame hasta que tenga una soluci\xF3n.","Ir personalmente al sitio y hacer el trabajo por el Junior para ahorrar tiempo.","Decirle al cliente que el Junior no sabe y que enviar\xE1 a otra persona despu\xE9s."],respuesta_correcta:0,explicacion:"Guiar al Junior por tel\xE9fono con un proceso l\xF3gico de diagn\xF3stico desarrolla sus habilidades mientras resuelve el problema del cliente. Es la mejor combinaci\xF3n de mentor\xEDa, eficiencia y servicio profesional."},{id:"ns_0176",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un approach de condensador de 15\xB0F. \xBFQu\xE9 hace el Senior?",opciones:["Programar una limpieza mec\xE1nica de los tubos del condensador de inmediato.","Agregar refrigerante hasta que el approach baje a los 2 grados nominales.","Aumentar la velocidad de la bomba de agua para mejorar la transferencia.","Ignorar el valor si la temperatura de salida del agua helada es la correcta."],respuesta_correcta:0,explicacion:"Un approach de condensador de 15\xB0F (normal es 2-5\xB0F) indica tubos sucios con fouling severo que reduce dr\xE1sticamente la transferencia de calor. Se requiere limpieza mec\xE1nica inmediata."},{id:"ns_0177",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 100 PSI y descarga de 450 PSI con R-410A. \xBFProblema?",opciones:["Restricci\xF3n en la l\xEDnea de l\xEDquido o condensador extremadamente sucio.","Falta de refrigerante l\xEDquido en el sistema para enfriar el evaporador.","V\xE1lvula de expansi\xF3n (TXV) bloqueada en la posici\xF3n de abierta total.","Compresor perdiendo eficiencia volum\xE9trica por desgaste de los pistones."],respuesta_correcta:0,explicacion:"Succi\xF3n de 100 PSI (baja) con descarga de 450 PSI (muy alta) indica una restricci\xF3n en el lado de alta que impide el flujo normal de refrigerante. Esto puede ser una restricci\xF3n en la l\xEDnea de l\xEDquido o un condensador extremadamente sucio que no disipa el calor."},{id:"ns_0178",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete, el ventilador de condensador no para nunca. \xBFQu\xE9 revisa?",opciones:["El contactor del ventilador que est\xE1 pegado mec\xE1nicamente o soldado.","El termostato de la zona que est\xE1 configurado en modo 'Fan ON' siempre.","La placa de control que tiene un sensor de temperatura de ambiente roto.","La carga de refrigerante que es tan alta que mantiene el switch de alta activo."],respuesta_correcta:0,explicacion:"Si el ventilador del condensador no se detiene nunca, la causa directa m\xE1s probable es un contactor con los contactos soldados (pegados). Esto mantiene el circuito cerrado permanentemente, independientemente de la se\xF1al de control."},{id:"ns_0179",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere comprar otra empresa HVAC. \xBFQu\xE9 es lo primero que audita?",opciones:["La rentabilidad real y la calidad de los contratos de servicio existentes.","El estado f\xEDsico de las camionetas y las herramientas de los t\xE9cnicos.","El dise\xF1o del logotipo y la presencia de la marca en los medios locales.","La cantidad de empleados que tienen m\xE1s de 5 a\xF1os trabajando en el sitio."],respuesta_correcta:0,explicacion:"Al adquirir otra empresa HVAC, lo primero que se audita es la rentabilidad real y la calidad de los contratos de servicio existentes, ya que determinan el valor verdadero del negocio."},{id:"ns_0180",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFQu\xE9 precauci\xF3n toma el Senior al cargar gas?",opciones:["Cargar siempre en estado l\xEDquido para evitar el fraccionamiento de la mezcla.","Cargar en estado gaseoso para no da\xF1ar las v\xE1lvulas de los compresores.","Utilizar aceite mineral para asegurar que el refrigerante sea miscible.","No cargar m\xE1s de 50 libras a la vez para evitar picos de presi\xF3n alta."],respuesta_correcta:0,explicacion:"El R-448A es una mezcla zeotr\xF3pica de m\xFAltiples componentes con diferentes puntos de ebullici\xF3n. Si se carga en fase gaseosa, los componentes m\xE1s vol\xE1tiles salen primero del cilindro, alterando la composici\xF3n. Cargar en l\xEDquido mantiene la mezcla intacta."},{id:"ns_0181",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Reversal'. \xBFQu\xE9 sucede si se ignora?",opciones:["El compresor girar\xE1 al rev\xE9s y no bombear\xE1 aceite ni refrigerante l\xEDquido.","La unidad funcionar\xE1 al 50% de su capacidad nominal debido al desfase.","El motor se quemar\xE1 instant\xE1neamente al intentar vencer la inercia de carga.","Las v\xE1lvulas de expansi\xF3n se cerrar\xE1n por seguridad al detectar el error."],respuesta_correcta:0,explicacion:"La inversi\xF3n de fases causa que el compresor gire al rev\xE9s, impidiendo el bombeo de aceite a los cojinetes y la circulaci\xF3n de refrigerante. Esto causa da\xF1o mec\xE1nico inmediato por falta de lubricaci\xF3n."},{id:"ns_0182",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. \xBFCausa?",opciones:["El drenaje tiene una contrapendiente o est\xE1 parcialmente obstruido arriba.","La bomba de condensado integrada ha fallado y no puede evacuar el agua.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido.","La humedad en la habitaci\xF3n es superior al 90% y satura el serpent\xEDn."],respuesta_correcta:0,explicacion:"Si el goteo ocurre solo cuando el compresor para, el agua acumulada durante la operaci\xF3n no drena correctamente. Una contrapendiente o obstrucci\xF3n parcial alta en el tubo de drenaje retiene agua que se libera al cesar la vibraci\xF3n."},{id:"ns_0183",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene un 'Static Pressure' de 0.9 en el suministro y 0.2 en retorno. \xBFProblema?",opciones:["Restricci\xF3n severa en los conductos de suministro o difusores cerrados.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o."],respuesta_correcta:0,explicacion:'Una presi\xF3n est\xE1tica de 0.9" en suministro versus solo 0.2" en retorno indica que la mayor parte de la restricci\xF3n est\xE1 en el lado de suministro. Conductos de suministro subdimensionados, aplastados o difusores cerrados causan esta distribuci\xF3n desproporcionada de presi\xF3n.'},{id:"ns_0184",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre los 20\xB0F y 30\xB0F.","S\xED, las bombas de calor siempre tienen un diferencial menor que los hornos.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en modo calor es insuficiente. Lo normal es 20-30F. Un diferencial bajo indica problemas como falta de refrigerante, flujo de aire excesivo, o absorcion deficiente de calor exterior."},{id:"ns_0185",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. \xBFQu\xE9 paso es vital post-quemadura?",opciones:["Realizar una prueba de acidez del aceite y usar filtros de succi\xF3n de limpieza.","A\xF1adir un aditivo sellador de fugas para prevenir fallas futuras en las l\xEDneas.","Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.","Aumentar la carga de refrigerante un 5% para ayudar a enfriar el motor nuevo."],respuesta_correcta:0,explicacion:"Tras una quemadura de compresor, el aceite se descompone y genera \xE1cidos que contaminan todo el sistema. La prueba de acidez confirma el nivel de contaminaci\xF3n, y los filtros de succi\xF3n de limpieza atrapan residuos para proteger el compresor nuevo."},{id:"ns_0186",categoria:"NATE_SR_PACKAGE",pregunta:"En un Rooftop, el economizador parpadea con un c\xF3digo de 'Enthalpy sensor fault'. \xBFQu\xE9 hace?",opciones:["El economizador operar\xE1 basado solo en la temperatura de bulbo seco.","El economizador se cerrar\xE1 completamente para evitar aire h\xFAmedo fuera.","Los compresores se bloquear\xE1n hasta que el sensor sea reemplazado hoy.","El sistema usar\xE1 el sensor de aire de retorno como referencia temporal."],respuesta_correcta:0,explicacion:"La mayor\xEDa de controladores de economizador modernos tienen un modo de respaldo (fallback). Cuando el sensor de entalp\xEDa falla, el sistema degrada a control por temperatura de bulbo seco solamente, permitiendo operaci\xF3n continua con menor eficiencia pero sin detener el equipo."},{id:"ns_0187",categoria:"NATE_SR_RACK",pregunta:"Un rack de baja temperatura tiene una presi\xF3n de succi\xF3n muy inestable. \xBFQu\xE9 revisa?",opciones:["La configuraci\xF3n de los pasos de capacidad de los compresores (steps).","Si el separador de aceite est\xE1 retornando aceite de forma intermitente.","La carga de refrigerante que podr\xEDa estar en el l\xEDmite de la burbuja.","Si las v\xE1lvulas solenoide de las vitrinas est\xE1n ciclando por temperatura."],respuesta_correcta:0,explicacion:"Una presi\xF3n de succi\xF3n inestable en un rack generalmente indica que los pasos de capacidad (compresores entrando/saliendo) est\xE1n mal configurados. Un diferencial insuficiente o steps demasiado agresivos causan oscilaciones constantes de presi\xF3n."},{id:"ns_0188",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar la reputaci\xF3n en l\xEDnea. \xBFQu\xE9 estrategia es la m\xE1s org\xE1nica?",opciones:["Pedir a los t\xE9cnicos que soliciten una rese\xF1a al terminar un trabajo exitoso.","Pagar a una agencia externa para que genere rese\xF1as positivas artificiales.","Ofrecer un descuento en la factura a cambio de una calificaci\xF3n de 5 estrellas.","Responder solo a las rese\xF1as negativas para tratar de que el cliente las borre."],respuesta_correcta:0,explicacion:"Pedir rese\xF1as org\xE1nicas a clientes satisfechos al terminar un trabajo exitoso es la estrategia m\xE1s aut\xE9ntica y sostenible para mejorar la reputaci\xF3n en l\xEDnea."},{id:"ns_0189",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo usa R-134a. \xBFPor qu\xE9 no necesita unidad de purga?",opciones:["Porque opera a presi\xF3n positiva y el aire no puede entrar al sistema.","Porque el R-134a absorbe el aire y lo mezcla con el aceite lubricante.","Porque el compresor centr\xEDfugo destruye las burbujas de aire al girar.","Porque la temperatura del evaporador nunca baja del punto de congelaci\xF3n."],respuesta_correcta:0,explicacion:"El R-134a opera a presi\xF3n positiva en todo el sistema (evaporador y condensador). Al no tener presiones de vac\xEDo, el aire exterior no puede infiltrarse, eliminando la necesidad de unidad de purga."},{id:"ns_0190",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene un sobrecalentamiento de 30\xB0F y subenfriamiento de 15\xB0F. \xBFDiagn\xF3stico?",opciones:["Restricci\xF3n en el dispositivo de expansi\xF3n o filtro deshidratador sucio.","Falta de carga de refrigerante que afecta la saturaci\xF3n del evaporador.","Exceso de carga de refrigerante que inunda el condensador exterior.","Falla del ventilador interior que reduce la carga t\xE9rmica en el sistema."],respuesta_correcta:0,explicacion:"Un sobrecalentamiento alto de 30\xB0F indica insuficiente refrigerante en el evaporador, mientras que un subenfriamiento de 15\xB0F es aceptable. La combinaci\xF3n apunta a una restricci\xF3n en el dispositivo de expansi\xF3n o filtro deshidratador que impide el paso adecuado de refrigerante l\xEDquido."},{id:"ns_0191",categoria:"NATE_SR_CEO",pregunta:"Un CEO decide implementar un 'Tool Account' para sus t\xE9cnicos. \xBFCu\xE1l es el beneficio?",opciones:["Asegurar que los t\xE9cnicos tengan herramientas propias y las cuiden mejor.","Reducir el gasto de la empresa en herramientas b\xE1sicas que se pierden.","Permitir que el t\xE9cnico compre herramientas de lujo con su propio dinero.","Deducir el costo de las herramientas de los impuestos corporativos anuales."],respuesta_correcta:0,explicacion:"El Tool Account incentiva al t\xE9cnico a poseer y mantener sus propias herramientas en buen estado, lo que aumenta su responsabilidad y reduce p\xE9rdidas o descuido."},{id:"ns_0192",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRF tiene un ruido de expansi\xF3n fuerte en las unidades interiores. \xBFCausa?",opciones:["Falta de carga de refrigerante que causa vapor en la l\xEDnea de l\xEDquido.","La placa de control est\xE1 moviendo la EEV demasiado r\xE1pido entre pasos.","El aceite del sistema es demasiado espeso y causa fricci\xF3n en la v\xE1lvula.","Es un comportamiento normal cuando el sistema opera a m\xE1xima frecuencia."],respuesta_correcta:0,explicacion:"Un ruido de expansi\xF3n (hissing) fuerte en unidades interiores VRF indica falta de carga de refrigerante, lo que genera burbujas de vapor (flash gas) en la l\xEDnea de l\xEDquido antes de la v\xE1lvula de expansi\xF3n."},{id:"ns_0193",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor geot\xE9rmica tiene una falla de 'High Pressure'. El lazo es abierto. \xBFCausa?",opciones:["Incrustaciones de minerales en el intercambiador de calor de agua/gas.","La bomba del pozo se detuvo o el filtro de sedimentos est\xE1 obstruido.","La temperatura del subsuelo ha subido por encima de los 80 grados F.","Hay una fuga de refrigerante hacia el agua del pozo por una ruptura."],respuesta_correcta:0,explicacion:"En un sistema geotermico de lazo abierto, las incrustaciones minerales del agua del pozo reducen la transferencia de calor en el intercambiador, elevando la presion de descarga hasta disparar el switch de alta presion."},{id:"ns_0194",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si la v\xE1lvula diferencial de aceite est\xE1 mal ajustada (muy alta)?",opciones:["Se inyecta demasiado aceite al c\xE1rter y puede causar da\xF1os mec\xE1nicos.","No habr\xE1 suficiente presi\xF3n para que el aceite regrese a los compresores.","El separador de aceite se desbordar\xE1 hacia la l\xEDnea de descarga del rack.","La temperatura del aceite bajar\xE1 por debajo del punto de lubricaci\xF3n."],respuesta_correcta:0,explicacion:"Una v\xE1lvula diferencial ajustada muy alta permite un flujo excesivo de aceite hacia los c\xE1rteres. El exceso de aceite puede causar golpe de l\xEDquido hidr\xE1ulico, da\xF1o en las v\xE1lvulas de plato, y problemas mec\xE1nicos en los compresores."},{id:"ns_0195",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior detecta un error de dise\xF1o en un plano de conductos. \xBFQu\xE9 hace?",opciones:["Notificar al ingeniero de dise\xF1o y sugerir una correcci\xF3n basada en campo.","Instalar el sistema como dice el plano para no tener responsabilidad legal.","Corregir el dise\xF1o por su cuenta sin avisar a nadie para terminar r\xE1pido.","Decirle al cliente que el ingeniero no sabe nada y que \xE9l lo har\xE1 mejor."],respuesta_correcta:0,explicacion:"Notificar al ingeniero mantiene la comunicaci\xF3n profesional y la cadena de responsabilidad. El t\xE9cnico Senior aporta experiencia de campo valiosa, pero los cambios de dise\xF1o deben ser aprobados por el ingeniero responsable del proyecto."},{id:"ns_0196",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que expulsa refrigerante l\xEDquido. \xBFQu\xE9 componente fall\xF3?",opciones:["La v\xE1lvula de flotador o el orificio de separaci\xF3n de la unidad de purga.","El compresor centr\xEDfugo que est\xE1 enviando l\xEDquido hacia el condensador.","El sensor de presi\xF3n de la purga que est\xE1 enviando una se\xF1al err\xF3nea.","El calentador de la purga que no est\xE1 evaporando el l\xEDquido recolectado."],respuesta_correcta:0,explicacion:"La v\xE1lvula de flotador de la purga controla la separaci\xF3n entre l\xEDquido y gas. Si falla, permite que refrigerante l\xEDquido pase directamente a la salida de la purga en vez de solo gases."},{id:"ns_0197",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 115 PSI y descarga de 320 PSI con R-410A. \xBFC\xF3mo est\xE1?",opciones:["Funcionamiento normal para un d\xEDa con temperatura exterior moderada.","Falta de refrigerante l\xEDquido que impide que la descarga suba m\xE1s.","Evaporador sucio que reduce la presi\xF3n de succi\xF3n por debajo de 120.","Compresor con desgaste moderado que a\xFAn mantiene el diferencial \xFAtil."],respuesta_correcta:0,explicacion:"Con R-410A, succi\xF3n de 115 PSI (~36\xB0F sat.) y descarga de 320 PSI (~90\xB0F sat.) son valores normales para un d\xEDa con temperatura exterior moderada (alrededor de 75-80\xB0F). El diferencial de presi\xF3n es adecuado y el sistema opera dentro de par\xE1metros de dise\xF1o."},{id:"ns_0198",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete, el serpent\xEDn del evaporador se congela. El filtro est\xE1 limpio. \xBFQu\xE9 sigue?",opciones:["Verificar la velocidad del motor del soplador y la carga de refrigerante.","Reemplazar la v\xE1lvula de expansi\xF3n t\xE9rmica (TXV) por una nueva hoy.","Instalar un termostato de descongelaci\xF3n para que pare el compresor.","Agregar refrigerante hasta que la presi\xF3n de succi\xF3n suba a 130 PSI."],respuesta_correcta:0,explicacion:"Con filtro limpio, la congelaci\xF3n del evaporador se debe a flujo de aire insuficiente (motor lento, correa floja) o carga de refrigerante baja que reduce la presi\xF3n/temperatura de evaporaci\xF3n por debajo de 32\xB0F. Ambas causas deben verificarse antes de reemplazar componentes."},{id:"ns_0199",categoria:"NATE_SR_CEO",pregunta:"Un CEO debe cumplir con la ley FLSA (Fair Labor Standards Act). \xBFQu\xE9 regula?",opciones:["El pago de horas extras y el salario m\xEDnimo para los empleados t\xE9cnicos.","La seguridad de los t\xE9cnicos en el sitio de trabajo y el uso de EPP.","La certificaci\xF3n de los equipos HVAC seg\xFAn su eficiencia energ\xE9tica.","El manejo y disposici\xF3n final de los refrigerantes usados en el campo."],respuesta_correcta:0,explicacion:"La FLSA (Fair Labor Standards Act) regula el pago de salario m\xEDnimo y horas extras obligatorias; su incumplimiento expone a la empresa a demandas colectivas costosas."},{id:"ns_0200",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-407A. El t\xE9cnico mezcla con R-404A por error. \xBFConsecuencia?",opciones:["La relaci\xF3n presi\xF3n/temperatura ser\xE1 impredecible y el sistema fallar\xE1.","El sistema funcionar\xE1 bien ya que ambos refrigerantes son del tipo HFC.","La eficiencia aumentar\xE1 un 5% pero el compresor har\xE1 un poco m\xE1s de ruido.","El aceite se separar\xE1 del refrigerante y los compresores se bloquear\xE1n."],respuesta_correcta:0,explicacion:"Mezclar dos refrigerantes diferentes crea una mezcla desconocida con propiedades termodin\xE1micas impredecibles. La relaci\xF3n presi\xF3n/temperatura cambia, los controles no pueden calibrarse, y el sistema opera de forma err\xE1tica y eventualmente falla."},{id:"ns_0201",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta una ca\xEDda de presi\xF3n excesiva en el evaporador, pero el flujo de agua es nominal. \xBFCu\xE1l es la sospecha del Senior?",opciones:["Obstrucci\xF3n parcial en el cedazo (strainer) de entrada o tubos con lodo.","La bomba de agua helada est\xE1 girando a m\xE1s RPM de las que indica la placa.","El refrigerante est\xE1 inundando los tubos superiores del intercambiador.","Las v\xE1lvulas de mariposa de aislamiento est\xE1n vibrando por turbulencia."],respuesta_correcta:0,explicacion:"Con flujo de agua nominal, una ca\xEDda de presi\xF3n excesiva en el evaporador indica obstrucci\xF3n parcial en el cedazo (strainer) de entrada o acumulaci\xF3n de lodo en los tubos del intercambiador."},{id:"ns_0202",categoria:"NATE_SR_RACK",pregunta:"En un sistema de rack paralelo, \xBFqu\xE9 fen\xF3meno ocurre si la presi\xF3n del recibidor cae por debajo de la presi\xF3n de dise\xF1o del l\xEDquido?",opciones:["Formaci\xF3n de gas flash en la l\xEDnea de l\xEDquido que afecta a las vitrinas.","Aumento s\xFAbito del nivel de aceite en el separador de descarga principal.","Cierre autom\xE1tico de todas las v\xE1lvulas de expansi\xF3n por falta de flujo.","El subenfriamiento aumenta dr\xE1sticamente para compensar la baja presi\xF3n."],respuesta_correcta:0,explicacion:"Cuando la presi\xF3n del recibidor baja demasiado, el refrigerante l\xEDquido pierde subenfriamiento y se forma gas flash en la l\xEDnea de l\xEDquido. Esto reduce el flujo efectivo de l\xEDquido a las vitrinas y causa problemas de alimentaci\xF3n en las TXV."},{id:"ns_0203",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC analiza el 'Break-Even Point'. Si los costos fijos suben, \xBFqu\xE9 debe suceder para mantener la misma utilidad?",opciones:["El volumen de ventas debe aumentar o el margen de contribuci\xF3n subir.","El costo de la mano de obra directa debe incrementarse proporcionalmente.","La empresa debe reducir el precio de sus servicios para ser m\xE1s competitiva.","Los activos fijos deben venderse para capitalizar la operaci\xF3n de campo."],respuesta_correcta:0,explicacion:"Si los costos fijos suben, la empresa necesita vender m\xE1s unidades o aumentar el margen de contribuci\xF3n por unidad para alcanzar y superar el punto de equilibrio."},{id:"ns_0204",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRF muestra un error de 'Suction Pipe Thermistor'. El sensor mide 10k Ohms a 77\xB0F. \xBFCu\xE1l es la conclusi\xF3n?",opciones:["El sensor est\xE1 en buen estado; el problema reside en la placa o el cableado.","El sensor est\xE1 fuera de rango y debe reemplazarse por uno de 50k Ohms.","Existe una fuga de refrigerante que est\xE1 enfriando el sensor err\xE1ticamente.","La unidad exterior est\xE1 enviando un voltaje incorrecto al bus de sensores."],respuesta_correcta:0,explicacion:"Un termistor t\xEDpico de 10k Ohms a 77\xB0F (25\xB0C) est\xE1 dentro del rango normal. Si el sistema reporta error con un sensor en buen estado, el problema est\xE1 en la placa de control o en el cableado entre el sensor y la placa."},{id:"ns_0205",categoria:"NATE_SR_HVAC",pregunta:"En un sistema con conductos, un valor de 'Static Pressure' de retorno de 0.8 pulg. W.C. indica generalmente que:",opciones:["El sistema de filtraci\xF3n es insuficiente o los conductos est\xE1n mal dise\xF1ados.","El motor del soplador tiene demasiada fuerza y est\xE1 succionando aire de m\xE1s.","Las rejillas de suministro est\xE1n cerradas y el aire rebota hacia el retorno.","El serpent\xEDn del evaporador est\xE1 limpio y permite un flujo de aire libre."],respuesta_correcta:0,explicacion:'Una presi\xF3n est\xE1tica de retorno de 0.8" W.C. es excesivamente alta y se\xF1ala restricciones significativas en el lado de retorno. Filtros insuficientes, conductos de retorno subdimensionados o mal dise\xF1ados crean esta restricci\xF3n que reduce el flujo total de aire del sistema.'},{id:"ns_0206",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor activa las resistencias de apoyo innecesariamente. \xBFQu\xE9 ajuste Senior es el primero?",opciones:["Verificar el 'Outdoor Ambient Lockout' y el diferencial del termostato.","Cambiar el contactor de las resistencias por uno de menor amperaje total.","Aumentar la carga de refrigerante para que el compresor genere m\xE1s calor.","Desconectar f\xEDsicamente el cable 'W' del termostato durante el invierno."],respuesta_correcta:0,explicacion:"El outdoor ambient lockout impide que las resistencias se activen por encima de cierta temperatura exterior. Si esta mal configurado, las resistencias se encienden innecesariamente, desperdiciando energia."},{id:"ns_0207",categoria:"NATE_SR_MANAGEMENT",pregunta:"Al supervisar una instalaci\xF3n, nota que no usan un torque de apriete espec\xEDfico en las tuercas flare. \xBFCu\xE1l es el riesgo?",opciones:["Fugas de refrigerante por deformaci\xF3n del cobre o por falta de sello.","Aumento del ruido por vibraci\xF3n mec\xE1nica en las l\xEDneas de interconexi\xF3n.","P\xE9rdida de la garant\xEDa del fabricante solo si el equipo deja de enfriar.","Dificultad para remover la unidad en el futuro si se requiere un servicio."],respuesta_correcta:0,explicacion:"Un torque insuficiente no sella correctamente la conexi\xF3n flare, causando fugas lentas. Un torque excesivo deforma el cobre y rompe el sello. Usar torqu\xEDmetro con las especificaciones del fabricante garantiza conexiones herm\xE9ticas."},{id:"ns_0208",categoria:"NATE_SR_PACKAGE",pregunta:"Un Rooftop de 25 toneladas tiene un motor de soplador que quema fusibles al arrancar. \xBFQu\xE9 prueba mec\xE1nica hace?",opciones:["Verificar la tensi\xF3n de las correas y el estado de los rodamientos del eje.","Cambiar el capacitor de arranque aunque el motor sea del tipo trif\xE1sico.","Aumentar el tama\xF1o de los fusibles para permitir el pico de corriente inicial.","Medir el voltaje en el secundario del transformador de control de 24V."],respuesta_correcta:0,explicacion:"Un motor que quema fusibles al arrancar indica excesiva corriente de rotor bloqueado. La causa mec\xE1nica m\xE1s com\xFAn es una correa demasiado tensa o rodamientos del eje da\xF1ados que impiden el giro libre del motor, aumentando el amperaje de arranque m\xE1s all\xE1 del l\xEDmite del fusible."},{id:"ns_0209",categoria:"NATE_SR_RACK",pregunta:"En un rack con CO2 transcr\xEDtico, \xBFcu\xE1l es la funci\xF3n de la v\xE1lvula 'Flash Gas Bypass'?",opciones:["Controlar la presi\xF3n del recibidor enviando el exceso de gas a la succi\xF3n.","Inyectar refrigerante l\xEDquido en la descarga para bajar la temperatura total.","Evacuar el aceite atrapado en el gas-cooler hacia el c\xE1rter de los compresores.","Regular el flujo de gas hacia las vitrinas de baja temperatura en el sistema."],respuesta_correcta:0,explicacion:"En un sistema CO2 transcr\xEDtico, al expandir el fluido supercr\xEDtico se genera gas flash en el recibidor. La v\xE1lvula de flash gas bypass env\xEDa ese exceso de gas a la succi\xF3n, controlando la presi\xF3n del recibidor y mejorando la eficiencia."},{id:"ns_0210",categoria:"NATE_SR_CEO",pregunta:"Un CEO implementa un sistema de 'Flat Rate Pricing'. \xBFCu\xE1l es el beneficio para el cliente final?",opciones:["Conocer el costo total del servicio antes de que se realice cualquier reparaci\xF3n.","Pagar menos por hora de trabajo si el t\xE9cnico es m\xE1s lento que el promedio.","Garantizar que solo se utilicen piezas de la marca original en su equipo HVAC.","Recibir una auditor\xEDa de eficiencia energ\xE9tica gratuita con cada llamada de servicio."],respuesta_correcta:0,explicacion:"El Flat Rate Pricing permite al cliente conocer el costo total antes de aprobar la reparaci\xF3n, eliminando la incertidumbre y generando confianza en la transparencia del servicio."},{id:"ns_0211",categoria:"NATE_SR_CHILLERS",pregunta:"Se detecta presencia de agua en el refrigerante de un chiller. \xBFCu\xE1l es la consecuencia qu\xEDmica?",opciones:["Formaci\xF3n de \xE1cidos corrosivos que atacan el barniz de los devanados del motor.","Aumento de la capacidad frigor\xEDfica debido a la mayor densidad de la mezcla.","Reducci\xF3n de la presi\xF3n de condensaci\xF3n por el efecto de enfriamiento del agua.","Mejora en la lubricaci\xF3n de los cojinetes al reducir la viscosidad del aceite."],respuesta_correcta:0,explicacion:"El agua en el refrigerante reacciona con el aceite y el refrigerante a altas temperaturas, formando \xE1cidos corrosivos (HCl, HF) que atacan el barniz aislante de los devanados del motor del compresor."},{id:"ns_0212",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial con TXV presenta 'hunting' (oscilaci\xF3n de presi\xF3n). \xBFCu\xE1l es el ajuste Senior?",opciones:["Verificar la ubicaci\xF3n y el aislamiento t\xE9rmico del bulbo sensor de la v\xE1lvula.","Cerrar la v\xE1lvula de expansi\xF3n dos vueltas para reducir el flujo de l\xEDquido.","Cambiar el filtro de aire por uno de mayor restricci\xF3n para estabilizar la carga.","Purgar un poco de refrigerante para reducir la presi\xF3n en el lado de alta."],respuesta_correcta:0,explicacion:"El 'hunting' de una TXV generalmente se debe a una mala ubicaci\xF3n o falta de aislamiento del bulbo sensor. Si el bulbo no hace buen contacto con la l\xEDnea de succi\xF3n o est\xE1 expuesto a temperaturas ambientales, lee se\xF1ales err\xE1ticas que causan la oscilaci\xF3n de apertura/cierre."},{id:"ns_0213",categoria:"NATE_SR_CEO",pregunta:"Para reducir los accidentes laborales, un CEO debe enfocarse en:",opciones:["La cultura de seguridad proactiva y el entrenamiento constante en procesos.","Sancionar econ\xF3micamente a cada t\xE9cnico que sufra un percance en el campo.","Comprar solo herramientas manuales para evitar el uso de electricidad en obra.","Reducir las horas de trabajo para que los t\xE9cnicos no sufran de fatiga cr\xF3nica."],respuesta_correcta:0,explicacion:"Una cultura de seguridad proactiva con entrenamiento constante previene accidentes desde la ra\xEDz; las sanciones solo generan ocultamiento de incidentes sin resolver el problema."},{id:"ns_0214",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema Multi-split tiene una fuga de aceite en una tuerca flare, pero no hay fuga de gas. \xBFEs posible?",opciones:["No, si hay fuga de aceite, la presi\xF3n del refrigerante forzosamente escapar\xE1.","S\xED, es una se\xF1al de que el sistema tiene un exceso de lubricante acumulado.","S\xED, ocurre cuando el sistema est\xE1 apagado y el aceite se asienta en la junta.","No, el aceite solo sale si el refrigerante act\xFAa como veh\xEDculo de transporte."],respuesta_correcta:0,explicacion:"Si hay fuga de aceite en una tuerca flare, el refrigerante presurizado tambi\xE9n escapar\xE1 ya que el aceite viaja mezclado con el gas. No puede haber fuga de aceite sin fuga de refrigerante en un sistema presurizado."},{id:"ns_0215",categoria:"NATE_SR_RACK",pregunta:"En un rack con descongelaci\xF3n por aire (Off-cycle), \xBFcu\xE1l es el par\xE1metro cr\xEDtico para el Senior?",opciones:["La duraci\xF3n del ciclo debe ser suficiente para derretir el hielo por aire ambiente.","La presi\xF3n de descarga debe subir para calentar indirectamente los evaporadores.","Los ventiladores del evaporador deben apagarse para evitar el choque t\xE9rmico.","La v\xE1lvula de expansi\xF3n debe permanecer abierta para mantener el flujo interno."],respuesta_correcta:0,explicacion:"En descongelaci\xF3n off-cycle, el evaporador se apaga y el hielo se derrite con el aire ambiente de la vitrina. El par\xE1metro cr\xEDtico es que la duraci\xF3n del ciclo sea suficiente para completar el deshielo antes de que la temperatura del producto suba demasiado."},{id:"ns_0216",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de 5 toneladas muestra un sobrecalentamiento de 45\xB0F. \xBFQu\xE9 indica?",opciones:["Una falta severa de refrigerante o una restricci\xF3n en el dispositivo de expansi\xF3n.","Que el serpent\xEDn del evaporador est\xE1 inundado de l\xEDquido y no hay intercambio.","Un exceso de carga de refrigerante que est\xE1 regresando al compresor sin gas.","Que el motor del ventilador del condensador est\xE1 girando a demasiadas RPM."],respuesta_correcta:0,explicacion:"Un sobrecalentamiento de 45\xB0F (normal es 8-14\xB0F) significa que el refrigerante se evapor\xF3 mucho antes de llegar al final del serpent\xEDn. Esto indica falta severa de refrigerante (fuga) o una restricci\xF3n en la TXV/pist\xF3n que no permite suficiente flujo de l\xEDquido al evaporador."},{id:"ns_0217",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Junior rompe una pieza costosa por descuido. \xBFC\xF3mo debe manejarlo el Senior?",opciones:["Explicar el error, mostrar la forma correcta y documentar para capacitaci\xF3n futura.","Obligar al Junior a pagar la pieza con su salario para que aprenda la lecci\xF3n.","Ocultar el error al cliente y a la gerencia para proteger al equipo de trabajo.","Hacer que el Junior trabaje horas extra sin pago hasta compensar el costo real."],respuesta_correcta:0,explicacion:"El liderazgo efectivo transforma errores en oportunidades de aprendizaje. Explicar qu\xE9 sali\xF3 mal, mostrar la t\xE9cnica correcta y documentar el incidente mejora las habilidades del equipo y previene que el error se repita."},{id:"ns_0218",categoria:"NATE_SR_CHILLERS",pregunta:"En un chiller enfriado por agua, el approach del evaporador sube de 2\xB0F a 10\xB0F. \xBFQu\xE9 hace?",opciones:["Realizar una limpieza qu\xEDmica o mec\xE1nica de los tubos del evaporador de inmediato.","Agregar m\xE1s refrigerante l\xEDquido para cubrir m\xE1s superficie de tubos internos.","Aumentar el flujo de agua helada mediante el ajuste del variador de la bomba.","Reducir el set-point de temperatura para forzar una mayor transferencia t\xE9rmica."],respuesta_correcta:0,explicacion:"Un aumento del approach del evaporador de 2\xB0F a 10\xB0F indica fouling significativo en los tubos que reduce la transferencia t\xE9rmica. Se requiere limpieza qu\xEDmica o mec\xE1nica inmediata."},{id:"ns_0219",categoria:"NATE_SR_HEATPUMP",pregunta:"Un sistema de bomba de calor tiene un acumulador de succi\xF3n. \xBFCu\xE1ndo es m\xE1s probable que act\xFAe?",opciones:["Al final del ciclo de deshielo cuando el l\xEDquido regresa bruscamente al compresor.","Durante los d\xEDas m\xE1s calurosos del verano cuando la presi\xF3n de alta es m\xE1xima.","Cuando el termostato cambia de modo calor a modo fr\xEDo en menos de un minuto.","Cuando las resistencias el\xE9ctricas se activan para ayudar al compresor en carga."],respuesta_correcta:0,explicacion:"El acumulador actua principalmente al terminar el defrost, cuando la valvula inversora cambia de refrigeracion a calefaccion. En ese momento, el refrigerante liquido puede regresar bruscamente hacia el compresor."},{id:"ns_0220",categoria:"NATE_SR_CEO",pregunta:"Para maximizar el 'Net Profit', un CEO debe priorizar:",opciones:["La eficiencia operativa y la reducci\xF3n de callbacks o re-visitas t\xE9cnicas.","La compra de las camionetas m\xE1s lujosas para proyectar una imagen de \xE9xito.","Aumentar el n\xFAmero de empleados sin importar la carga de trabajo actual.","Reducir dr\xE1sticamente los precios para eliminar a todos los competidores locales."],respuesta_correcta:0,explicacion:"La eficiencia operativa y la eliminaci\xF3n de callbacks reducen costos directos sin sacrificar ingresos, siendo la v\xEDa m\xE1s s\xF3lida para maximizar el Net Profit de la empresa."},{id:"ns_0221",categoria:"NATE_SR_RACK",pregunta:"Se observa aceite en el visor de la l\xEDnea de succi\xF3n de un rack. \xBFQu\xE9 indica al Senior?",opciones:["Velocidad de gas adecuada para el retorno de aceite desde los evaporadores.","Falla en el separador de aceite que permite el paso hacia el lado de baja.","Nivel excesivo de aceite en el c\xE1rter del compresor de la etapa de alta.","Obstrucci\xF3n en el cedazo de la l\xEDnea de retorno de aceite hacia el dep\xF3sito."],respuesta_correcta:0,explicacion:"Ver aceite fluyendo en la mirilla de succi\xF3n indica que la velocidad del gas es suficiente para arrastrar el aceite de regreso desde los evaporadores. Es una se\xF1al positiva de que el retorno de aceite est\xE1 funcionando correctamente."},{id:"ns_0222",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema inverter reporta error de comunicaci\xF3n (E6/U4). \xBFQu\xE9 voltaje busca entre S2 y S3?",opciones:["Un voltaje DC pulsante que fluct\xFAa r\xE1pidamente entre 0V y 24V (aprox).","Un voltaje AC constante de 24V proveniente del transformador de control.","Un voltaje DC estable de exactamente 5V para alimentar los microchips.","Cero voltios, ya que la comunicaci\xF3n es por frecuencia y no por voltaje."],respuesta_correcta:0,explicacion:"La comunicaci\xF3n entre unidades en sistemas inverter utiliza se\xF1ales DC pulsantes que fluct\xFAan r\xE1pidamente entre 0V y ~24V para transmitir datos. Un voltaje constante indicar\xEDa fallo de comunicaci\xF3n."},{id:"ns_0223",categoria:"NATE_SR_HVAC",pregunta:"Un motor de soplador ECM est\xE1 'haciendo hunting' (sube y baja RPM). \xBFCu\xE1l es la causa?",opciones:["Alta presi\xF3n est\xE1tica o restricciones severas en el sistema de conductos.","El termostato est\xE1 enviando se\xF1ales contradictorias de velocidad a la placa.","El capacitor de marcha est\xE1 fallando y no mantiene el torque del motor.","La humedad en el aire est\xE1 afectando los sensores magn\xE9ticos internos del ECM."],respuesta_correcta:0,explicacion:"Los motores ECM est\xE1n dise\xF1ados para mantener un flujo de aire constante (CFM). Cuando la presi\xF3n est\xE1tica es alta, el ECM aumenta sus RPM para compensar, pero al alcanzar su l\xEDmite y no poder mantener el flujo, comienza a oscilar entre diferentes velocidades (hunting)."},{id:"ns_0224",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con R-134a tiene una presi\xF3n de succi\xF3n de 35 PSI. \xBFCu\xE1l es el riesgo?",opciones:["Congelaci\xF3n de los tubos del evaporador ya que la saturaci\xF3n est\xE1 bajo 32\xB0F.","Sobrecalentamiento del motor por falta de masa de refrigerante para enfriarlo.","Falla mec\xE1nica por falta de lubricaci\xF3n al no haber suficiente arrastre de aceite.","Aumento excesivo del consumo el\xE9ctrico al intentar comprimir gas muy ralo."],respuesta_correcta:0,explicacion:"A 35 PSI de succi\xF3n, la temperatura de saturaci\xF3n del R-134a est\xE1 por debajo de 32\xB0F (punto de congelaci\xF3n del agua), creando riesgo de congelaci\xF3n de los tubos del evaporador."},{id:"ns_0225",categoria:"NATE_SR_CEO",pregunta:"Al analizar el 'Cost Per Lead' (CPL), un CEO nota que las redes sociales son baratas pero no cierran ventas. \xBFAcci\xF3n?",opciones:["Reevaluar el 'Targeting' o mejorar el proceso de calificaci\xF3n de prospectos.","Triplicar la inversi\xF3n en redes sociales para forzar estad\xEDsticamente una venta.","Cerrar todas las cuentas de redes sociales y volver a los anuncios impresos.","Culpar al departamento de ventas por no saber convencer a los seguidores."],respuesta_correcta:0,explicacion:"Si las redes sociales generan leads baratos pero no cierran ventas, el problema est\xE1 en el targeting o en el proceso de calificaci\xF3n de prospectos, no en el canal en s\xED."},{id:"ns_0226",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calefacci\xF3n, una bomba de calor tiene un subenfriamiento de 30\xB0F. \xBFQu\xE9 indica?",opciones:["Sobrecarga de refrigerante o una restricci\xF3n en la v\xE1lvula de expansi\xF3n interior.","Falta de refrigerante que impide que el l\xEDquido se acumule en el condensador.","Funcionamiento \xF3ptimo considerando las bajas temperaturas del aire exterior.","Que la v\xE1lvula inversora est\xE1 desviando gas caliente directamente a la succi\xF3n."],respuesta_correcta:0,explicacion:"Un subenfriamiento de 30F es excesivamente alto (lo normal es 8-15F). Indica sobrecarga de refrigerante que acumula demasiado liquido en el condensador, o una restriccion en la TXV que impide el flujo normal."},{id:"ns_0227",categoria:"NATE_SR_RACK",pregunta:"Un rack usa un controlador electr\xF3nico de aceite. Si el LED parpadea en rojo, \xBFqu\xE9 significa?",opciones:["Falla de lubricaci\xF3n detectada; el compresor ser\xE1 bloqueado por seguridad.","El nivel de aceite est\xE1 en el punto ideal y el sistema est\xE1 en espera.","El sistema est\xE1 inyectando aceite activamente para recuperar el nivel nominal.","El sensor de nivel est\xE1 sucio y requiere limpieza manual con solvente POE."],respuesta_correcta:0,explicacion:"En controladores electr\xF3nicos de aceite, un LED rojo parpadeante indica una condici\xF3n de falla de lubricaci\xF3n (oil failure). El controlador bloquear\xE1 el compresor despu\xE9s del tiempo de retardo programado para proteger los cojinetes y partes m\xF3viles."},{id:"ns_0228",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete industrial de 50 toneladas tiene un economizador que no abre. \xBFQu\xE9 revisa?",opciones:["La se\xF1al de entalp\xEDa y el ajuste del set-point del controlador de aire exterior.","La carga de refrigerante del circuito n\xFAmero uno que activa los dampers.","La tensi\xF3n de la correa del motor del soplador que genera la presi\xF3n est\xE1tica.","El sensor de temperatura de descarga del compresor que bloquea el aire fr\xEDo."],respuesta_correcta:0,explicacion:"Si el economizador no abre, lo primero es verificar la se\xF1al que recibe del sensor de entalp\xEDa exterior y el set-point del controlador. Si el sensor est\xE1 mal calibrado o el set-point es demasiado bajo, el controlador nunca dar\xE1 la orden de abrir el damper de aire exterior."},{id:"ns_0229",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un cliente afirma que el sistema nuevo gasta m\xE1s luz que el viejo de hace 20 a\xF1os. \xBFQu\xE9 hace?",opciones:["Auditar el consumo real, revisar configuraciones y verificar el sellado de ductos.","Decirle al cliente que es imposible y que su medidor de luz debe estar fallando.","Cambiar el equipo por otro modelo sin realizar pruebas previas de diagn\xF3stico.","Explicar que los equipos modernos tardan m\xE1s tiempo en enfriar por dise\xF1o SEER."],respuesta_correcta:0,explicacion:"Un equipo nuevo con SEER alto deber\xEDa consumir menos. Si el cliente reporta lo contrario, hay que investigar: ductos con fugas, configuraci\xF3n incorrecta del termostato, problemas de carga, o carga t\xE9rmica aumentada. La auditor\xEDa revela la causa real."},{id:"ns_0230",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo vibra violentamente al apagar. \xBFQu\xE9 componente t\xE9cnico previene da\xF1os graves por rotaci\xF3n inversa?",opciones:["La v\xE1lvula de retenci\xF3n de descarga y el sistema de lubricaci\xF3n por inercia.","El freno electromagn\xE9tico integrado en el estator del motor del compresor.","Los \xE1labes de entrada que se cierran herm\xE9ticamente al detectar el paro.","El bypass de gas caliente que iguala las presiones de forma instant\xE1nea."],respuesta_correcta:0,explicacion:"La v\xE1lvula de retenci\xF3n de descarga previene la rotaci\xF3n inversa del impulsor al apagar el chiller, mientras el sistema de lubricaci\xF3n por inercia mantiene aceite en los cojinetes durante la desaceleraci\xF3n."},{id:"ns_0231",categoria:"NATE_SR_RACK",pregunta:"En un rack, la v\xE1lvula de presi\xF3n diferencial de aceite est\xE1 ajustada a 20 PSI, pero el compresor se apaga por 'Oil Trip'. \xBFQu\xE9 revisa?",opciones:["La ca\xEDda de presi\xF3n en el filtro de aceite y la espuma en el c\xE1rter.","El voltaje de alimentaci\xF3n del solenoide que inyecta aceite al sistema.","Si el separador de aceite tiene el flotador perforado y se encuentra hundido.","La calibraci\xF3n del transductor de presi\xF3n de descarga del rack paralelo."],respuesta_correcta:0,explicacion:"Si el diferencial est\xE1 bien ajustado pero hay oil trip, la presi\xF3n neta de aceite se pierde por otro motivo. Un filtro de aceite tapado crea una ca\xEDda de presi\xF3n que reduce el diferencial efectivo, y espuma en el c\xE1rter (refrigerante disuelto) impide la lubricaci\xF3n correcta."},{id:"ns_0232",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC observa que el 'Gross Margin' es alto, pero el 'Net Profit' es negativo. \xBFD\xF3nde reside el problema?",opciones:["En los costos indirectos excesivos, como renta, administraci\xF3n o deudas.","En que los t\xE9cnicos est\xE1n cobrando muy poco por las piezas de repuesto.","En que el costo de los materiales ha subido dr\xE1sticamente este trimestre.","En que la empresa no est\xE1 realizando suficientes llamadas de servicio."],respuesta_correcta:0,explicacion:"Si el Gross Margin es alto pero el Net Profit es negativo, los costos indirectos (renta, administraci\xF3n, intereses de deuda) est\xE1n consumiendo toda la utilidad bruta."},{id:"ns_0233",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split presenta un error de 'Overcurrent' intermitente solo en d\xEDas de calor extremo. \xBFQu\xE9 causa Senior es probable?",opciones:["Aletas del condensador dobladas o sucias que elevan la presi\xF3n de descarga.","Una placa electr\xF3nica defectuosa que no modula la frecuencia correctamente.","Cables de alimentaci\xF3n con un calibre inferior al requerido por la carga.","Un compresor que tiene un desgaste mec\xE1nico interno en los rodamientos."],respuesta_correcta:0,explicacion:"En d\xEDas de calor extremo, las aletas del condensador sucias o dobladas impiden la disipaci\xF3n de calor, elevando la presi\xF3n de descarga y forzando al compresor a consumir m\xE1s corriente, disparando la protecci\xF3n de sobrecorriente."},{id:"ns_0234",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial usa R-410A y tiene una succi\xF3n de 160 PSI con 0\xB0F de sobrecalentamiento. \xBFQu\xE9 est\xE1 ocurriendo?",opciones:["Inundaci\xF3n del evaporador por refrigerante l\xEDquido regresando al compresor.","Una falta de carga que impide que el refrigerante se evapore totalmente.","El motor del ventilador interior est\xE1 girando a una velocidad excesiva.","La v\xE1lvula de expansi\xF3n est\xE1 bloqueada y no permite el paso de l\xEDquido."],respuesta_correcta:0,explicacion:"Una succi\xF3n de 160 PSI con R-410A es alta (~52\xB0F sat.) y un sobrecalentamiento de 0\xB0F significa que no hay absorci\xF3n de calor adicional despu\xE9s del evaporador. Esto indica que refrigerante l\xEDquido est\xE1 regresando al compresor (flood-back), riesgo de da\xF1o mec\xE1nico por slugging."},{id:"ns_0235",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, la v\xE1lvula inversora no cambia a modo calor. El t\xE9cnico mide 24V en la solenoide. \xBFQu\xE9 sigue?",opciones:["Verificar el diferencial de presi\xF3n entre alta y baja para mover el pist\xF3n.","Reemplazar el termostato asumiendo que la se\xF1al de 24V es de bajo amperaje.","Golpear la v\xE1lvula con un martillo para liberar el pist\xF3n interno trabado.","Cambiar la placa de control exterior que activa el rel\xE9 de la inversora."],respuesta_correcta:0,explicacion:"Si hay 24V en la solenoide pero la valvula no cambia, el problema es mecanico. Se debe verificar que exista suficiente diferencial de presion entre alta y baja para que la presion piloto mueva el piston principal."},{id:"ns_0236",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un l\xEDder nota que sus t\xE9cnicos no est\xE1n pesando la carga de refrigerante en sistemas cr\xEDticos. \xBFCu\xE1l es la consecuencia?",opciones:["Baja eficiencia y posible da\xF1o al compresor por sobrecarga o falta de gas.","Aumento en el tiempo de servicio sin una mejora real en el diagn\xF3stico.","Multas inmediatas por parte de la EPA al no usar b\xE1sculas certificadas.","P\xE9rdida de la certificaci\xF3n NATE de los t\xE9cnicos por malas pr\xE1cticas."],respuesta_correcta:0,explicacion:"Los sistemas de carga cr\xEDtica requieren la cantidad exacta de refrigerante especificada por el fabricante. Sobrecarga causa alta presi\xF3n de descarga y da\xF1o al compresor; falta de gas causa sobrecalentamiento excesivo y lubricaci\xF3n deficiente."},{id:"ns_0237",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete industrial de 30 toneladas tiene compresores 'Tandem'. Si uno falla el\xE9ctricamente, \xBFqu\xE9 hace?",opciones:["Aislar el compresor fallido y verificar el nivel de aceite en el restante.","Puentear el contactor para que ambos arranquen al mismo tiempo siempre.","Cambiar ambos compresores ya que los circuitos de aceite est\xE1n unidos.","Reducir el flujo de aire del soplador para compensar la falta de capacidad."],respuesta_correcta:0,explicacion:"En compresores tandem que comparten circuito de aceite, cuando uno falla el\xE9ctricamente, se debe aislar para evitar que contamine al otro. Es cr\xEDtico verificar el nivel de aceite del compresor operativo, ya que con un solo compresor funcionando la distribuci\xF3n de aceite cambia."},{id:"ns_0238",categoria:"NATE_SR_RACK",pregunta:"Se encuentra l\xEDquido en el cabezal de succi\xF3n de un rack tras un deshielo. \xBFQu\xE9 ajuste de control es necesario?",opciones:["Aumentar el tiempo de 'Pump Down' o de goteo antes de abrir la succi\xF3n.","Cerrar las v\xE1lvulas de expansi\xF3n de todas las vitrinas durante el defrost.","Instalar un acumulador de succi\xF3n tres veces m\xE1s grande que el actual.","Bajar el set-point de presi\xF3n de succi\xF3n del rack para evaporar el l\xEDquido."],respuesta_correcta:0,explicacion:"Tras un deshielo, el refrigerante condensado en el evaporador puede regresar como l\xEDquido. Aumentar el tiempo de pump-down o goteo (drip time) permite que el l\xEDquido se evapore dentro del evaporador antes de abrir la succi\xF3n al rack."},{id:"ns_0239",categoria:"NATE_SR_CEO",pregunta:"Un CEO decide tercerizar el mantenimiento de la flota de veh\xEDculos. \xBFCu\xE1l es el objetivo estrat\xE9gico?",opciones:["Eliminar costos fijos de taller y enfocar recursos en la actividad principal.","Reducir el costo del combustible mediante el uso de aditivos especializados.","Evitar que los t\xE9cnicos pierdan tiempo limpiando sus propias camionetas.","Incrementar el valor de reventa de los veh\xEDculos al tener sellos de agencia."],respuesta_correcta:0,explicacion:"Tercerizar el mantenimiento de flota elimina costos fijos de taller propio y permite que la empresa se enfoque en su actividad principal: servicios HVAC."},{id:"ns_0240",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una aproximaci\xF3n (approach) negativa del evaporador. \xBFC\xF3mo interpreta esto el Senior?",opciones:["Error de calibraci\xF3n en los sensores de temperatura o presi\xF3n del sistema.","Eficiencia de transferencia de calor superior a los l\xEDmites f\xEDsicos te\xF3ricos.","El flujo de agua es tan alto que el sensor no alcanza a leer la realidad.","El refrigerante est\xE1 saliendo sobrecalentado antes de entrar al compresor."],respuesta_correcta:0,explicacion:"Un approach negativo del evaporador es f\xEDsicamente imposible en condiciones normales. Esto siempre indica un error de calibraci\xF3n en los sensores de temperatura o presi\xF3n del sistema."},{id:"ns_0241",categoria:"NATE_SR_HVAC",pregunta:"Se detecta un 'Voltage Imbalance' del 5% en un motor trif\xE1sico. \xBFCu\xE1l es el impacto t\xE9cnico?",opciones:["Aumento dr\xE1stico en la temperatura de los devanados y reducci\xF3n de vida.","El motor girar\xE1 m\xE1s r\xE1pido pero con un torque de arranque muy inferior.","Los fusibles de una fase se quemar\xE1n constantemente por el bajo voltaje.","El motor consumir\xE1 menos amperaje total al estar las fases desequilibradas."],respuesta_correcta:0,explicacion:"Un desbalance de voltaje del 5% en un motor trif\xE1sico causa un aumento de temperatura en los devanados de aproximadamente el 50% sobre lo normal. Este calor excesivo degrada r\xE1pidamente el aislamiento del motor, reduciendo dram\xE1ticamente su vida \xFAtil."},{id:"ns_0242",categoria:"NATE_SR_CEO",pregunta:"Al realizar trabajos en altura, un CEO debe asegurar que se use el sistema de protecci\xF3n contra ca\xEDdas. \xBFCu\xE1ndo es obligatorio?",opciones:["En cualquier borde no protegido que est\xE9 a 6 pies o m\xE1s del nivel inferior.","Solo cuando el t\xE9cnico est\xE1 trabajando directamente sobre una escalera.","Cuando la velocidad del viento en el techo excede las 20 millas por hora.","\xDAnicamente si el cliente lo solicita expl\xEDcitamente en el contrato de obra."],respuesta_correcta:0,explicacion:"OSHA exige protecci\xF3n contra ca\xEDdas en cualquier borde no protegido a 6 pies (1.83m) o m\xE1s del nivel inferior, siendo una de las normativas m\xE1s estrictas en construcci\xF3n."},{id:"ns_0243",categoria:"NATE_SR_MINISPLIT",pregunta:"Un VRF tiene una fuga de refrigerante y el sistema se bloquea. \xBFPor qu\xE9 no se debe usar detector de fugas de tinte?",opciones:["Puede da\xF1ar las v\xE1lvulas de expansi\xF3n electr\xF3nica y alterar el aceite POE.","El tinte es invisible bajo las luces LED que usan los t\xE9cnicos modernos.","El costo del tinte es superior al costo de recuperar y recargar el sistema.","Las normativas de la EPA proh\xEDben el uso de tintes en sistemas Inverter."],respuesta_correcta:0,explicacion:"El tinte detector de fugas puede da\xF1ar las v\xE1lvulas de expansi\xF3n electr\xF3nica (EEV) de precisi\xF3n y contaminar el aceite POE del sistema VRF, comprometiendo la lubricaci\xF3n del compresor."},{id:"ns_0244",categoria:"NATE_SR_RACK",pregunta:"Un rack de baja temperatura usa R-404A. Durante el servicio, el t\xE9cnico encuentra un 'glide' significativo. \xBFQu\xE9 hace?",opciones:["Recuperar la carga completa y cargar con refrigerante virgen en l\xEDquido.","Completar la carga con R-404A en fase gaseosa para equilibrar la mezcla.","A\xF1adir solo R-125 al sistema para compensar la p\xE9rdida de presi\xF3n alta.","No hacer nada, ya que el glide es despreciable en sistemas de rack paralelo."],respuesta_correcta:0,explicacion:"Un glide significativo en R-404A indica fraccionamiento de la mezcla por fuga. La \xFAnica soluci\xF3n correcta es recuperar toda la carga contaminada y recargar con refrigerante virgen en fase l\xEDquida para restaurar la composici\xF3n original de la mezcla."},{id:"ns_0245",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete con gas, el inductor arranca pero no hay ignici\xF3n. El switch de presi\xF3n est\xE1 cerrado. \xBFQu\xE9 sigue?",opciones:["Verificar el ignitor y la placa de control para ver si env\xEDa los 120V.","Reemplazar el motor del inductor asumiendo que no tiene suficiente fuerza.","Limpiar el sensor de flama con una lija met\xE1lica de grano muy fino.","Cerrar la llave de gas para evitar una acumulaci\xF3n peligrosa de combustible."],respuesta_correcta:0,explicacion:"Con el inductor funcionando y el switch de presi\xF3n cerrado, la secuencia de ignici\xF3n avanza al ignitor. Si no hay ignici\xF3n, se debe verificar que la placa de control env\xEDa 120V al ignitor y que el ignitor no est\xE1 fracturado o con alta resistencia. Sin ignitor funcional, la v\xE1lvula de gas no abrir\xE1."},{id:"ns_0246",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un sistema donde el cliente instal\xF3 su propio termostato 'Smart'. El sistema no enciende. \xBFCausa?",opciones:["Falta del cable com\xFAn (C) o da\xF1o en el fusible de 3A de la placa de control.","Incompatibilidad del Wi-Fi de la casa con la frecuencia del compresor AC.","El termostato requiere una actualizaci\xF3n de software para leer los 24V.","El cliente puente\xF3 los terminales R y C quemando el transformador de 24V."],respuesta_correcta:0,explicacion:"Los termostatos inteligentes requieren el cable C (com\xFAn) para alimentaci\xF3n continua. Sin este cable, el termostato no tiene suficiente energ\xEDa. Adem\xE1s, una conexi\xF3n incorrecta frecuentemente quema el fusible de 3A en la placa de control del equipo."},{id:"ns_0247",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Low Water Flow'. Se purga aire de la bomba y el flujo vuelve. \xBFQu\xE9 caus\xF3 el aire?",opciones:["Fuga en el sello de la bomba o nivel bajo en el tanque de expansi\xF3n.","El refrigerante se evapor\xF3 dentro de los tubos por una baja presi\xF3n.","La torre de enfriamiento est\xE1 operando con una temperatura muy alta.","La v\xE1lvula de expansi\xF3n est\xE1 inyectando gas en lugar de l\xEDquido al sistema."],respuesta_correcta:0,explicacion:"El aire en el sistema de agua proviene de fugas en el sello de la bomba (que aspira aire al parar) o de un nivel bajo en el tanque de expansi\xF3n que permite la entrada de aire al circuito."},{id:"ns_0248",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor geot\xE9rmica muestra baja presi\xF3n de succi\xF3n en modo fr\xEDo. \xBFQu\xE9 revisa en el lazo de agua?",opciones:["El flujo de agua de la bomba de circulaci\xF3n y la limpieza del filtro.","La temperatura del aire de retorno en la manejadora de aire interior.","Si el anticongelante (glicol) est\xE1 degradado y ha perdido su viscosidad.","La presi\xF3n de nitr\xF3geno en el tanque de expansi\xF3n hidroneum\xE1tico."],respuesta_correcta:0,explicacion:"En modo frio de una geotermica, baja succion indica mala absorcion de calor en el intercambiador agua-refrigerante. Lo primero es verificar el flujo de la bomba de circulacion y la limpieza del filtro de agua."},{id:"ns_0249",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Customer Churn'. \xBFQu\xE9 m\xE9trica de servicio debe monitorear m\xE1s?",opciones:["El tiempo de respuesta a emergencias y el \xEDndice de satisfacci\xF3n (NPS).","La cantidad de anuncios impresos en las revistas locales de decoraci\xF3n.","El margen de ganancia por cada filtro de aire vendido en los contratos.","La edad promedio de la flota de veh\xEDculos que visitan a los clientes."],respuesta_correcta:0,explicacion:"El tiempo de respuesta a emergencias y el NPS (Net Promoter Score) son indicadores directos de la satisfacci\xF3n del cliente, y su deterioro es la causa principal del churn."},{id:"ns_0250",categoria:"NATE_SR_RACK",pregunta:"Se observa que un rack paralelo tiene una presi\xF3n de descarga muy baja en invierno. \xBFPor qu\xE9 es un problema?",opciones:["Las v\xE1lvulas de expansi\xF3n no tendr\xE1n suficiente diferencial para alimentar l\xEDquido.","El aceite se enfriar\xE1 demasiado y se volver\xE1 s\xF3lido dentro del separador.","Los compresores consumir\xE1n m\xE1s energ\xEDa al intentar subir la presi\xF3n artificialmente.","El recibidor de l\xEDquido se vaciar\xE1 debido a la contracci\xF3n del refrigerante."],respuesta_correcta:0,explicacion:"Una presi\xF3n de descarga baja reduce el diferencial de presi\xF3n disponible en las v\xE1lvulas de expansi\xF3n (TXV). Sin suficiente diferencial, las v\xE1lvulas no pueden alimentar l\xEDquido adecuadamente a los evaporadores y las vitrinas pierden capacidad."},{id:"ns_0251",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller de tornillo tiene una falla de 'High Discharge Temp'. El aceite est\xE1 negro. \xBFQu\xE9 concluye el Senior?",opciones:["El aceite se ha carbonizado debido a temperaturas excesivas y falta de flujo.","Es normal que el aceite POE cambie a color negro tras un a\xF1o de operaci\xF3n.","El filtro deshidratador est\xE1 soltando part\xEDculas de carb\xF3n activado al sistema.","El motor del compresor se quem\xF3 y el holl\xEDn contamin\xF3 todo el lubricante."],respuesta_correcta:0,explicacion:"El aceite negro indica carbonizaci\xF3n por temperaturas excesivas y degradaci\xF3n t\xE9rmica. Combinado con alta temperatura de descarga, confirma que el aceite ha sufrido descomposici\xF3n qu\xEDmica severa."},{id:"ns_0252",categoria:"NATE_SR_HVAC",pregunta:"Un t\xE9cnico mide un 'Capacitor' de 35/5 MFD y obtiene 31/4. \xBFCu\xE1l es la decisi\xF3n Senior?",opciones:["Reemplazarlo inmediatamente, ya que est\xE1 fuera del 6% de tolerancia est\xE1ndar.","Dejarlo instalado hasta que el motor del compresor falle por completo.","A\xF1adir un capacitor de arranque en paralelo para compensar la p\xE9rdida.","Limpiar los terminales del capacitor para ver si la lectura mejora."],respuesta_correcta:0,explicacion:"Un capacitor de 35 MFD que mide 31 MFD ha perdido m\xE1s del 11% de su capacitancia, muy por encima del 6% de tolerancia est\xE1ndar. Un capacitor d\xE9bil causa bajo torque, sobrecalentamiento del motor y eventual falla. Debe reemplazarse preventivamente."},{id:"ns_0253",categoria:"NATE_SR_CEO",pregunta:"Un CEO decide implementar 'Flat Rate'. \xBFCu\xE1l es el impacto en la productividad del t\xE9cnico?",opciones:["Aumenta la velocidad al eliminar la necesidad de calcular precios en el sitio.","Reduce la calidad del trabajo porque los t\xE9cnicos intentan terminar m\xE1s r\xE1pido.","Disminuye la productividad al requerir m\xE1s papeleo administrativo por visita.","No tiene impacto, ya que el t\xE9cnico sigue trabajando a su propio ritmo habitual."],respuesta_correcta:0,explicacion:"El Flat Rate elimina la necesidad de calcular precios en el sitio, permitiendo al t\xE9cnico enfocarse en el diagn\xF3stico y la presentaci\xF3n de opciones, lo que acelera cada visita."},{id:"ns_0254",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no responde al control remoto. El t\xE9cnico prueba con uno nuevo y sigue igual. \xBFQu\xE9 sigue?",opciones:["Verificar la placa receptora de la unidad interior y el cableado de se\xF1al.","Cambiar la placa principal exterior asumiendo que bloquea el receptor.","Sustituir las bater\xEDas del control remoto aunque parezcan estar nuevas.","Resetear el breaker de la unidad durante 10 minutos para borrar el error."],respuesta_correcta:0,explicacion:"Si un control remoto nuevo tampoco funciona, el problema no es el emisor sino el receptor. El Senior verifica la placa receptora de infrarrojos de la unidad interior y el cableado de se\xF1al hacia la placa principal."},{id:"ns_0255",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calefacci\xF3n, una bomba de calor tiene una presi\xF3n de succi\xF3n de 100 PSI y descarga de 400 PSI con R-410A a 40\xB0F exterior. \xBFEstado?",opciones:["Funcionamiento normal considerando las presiones de saturaci\xF3n en modo calor.","Falta de refrigerante que impide que la descarga suba a los 600 PSI ideales.","Exceso de carga que est\xE1 elevando la succi\xF3n por encima de los 80 PSI.","V\xE1lvula inversora da\xF1ada que est\xE1 permitiendo un bypass interno de gas."],respuesta_correcta:0,explicacion:"Con R-410A a 40F exterior, una succion de 100 PSI y descarga de 400 PSI son valores normales para modo calefaccion. Corresponden a temperaturas de saturacion adecuadas para las condiciones de operacion."},{id:"ns_0256",categoria:"NATE_SR_RACK",pregunta:"Un rack usa 'Hot Gas Defrost'. Una vitrina se queda con hielo tras el ciclo. \xBFQu\xE9 revisa?",opciones:["La v\xE1lvula solenoide de gas caliente y el cheque de la l\xEDnea de l\xEDquido.","El ventilador del evaporador que debe estar apagado durante el deshielo.","La presi\xF3n del recibidor que podr\xEDa estar demasiado baja para el empuje.","Si el reloj de deshielo tiene configurado un tiempo de goteo muy largo."],respuesta_correcta:0,explicacion:"Si una vitrina espec\xEDfica no descongela con gas caliente, la solenoide de gas caliente puede no estar abriendo, o la v\xE1lvula check de la l\xEDnea de l\xEDquido puede estar impidiendo el flujo inverso necesario para que el gas caliente circule por el evaporador."},{id:"ns_0257",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Junior usa una antorcha de acetileno sin nitr\xF3geno. El Senior lo detiene por:",opciones:["La oxidaci\xF3n interna que crear\xE1 holl\xEDn y tapar\xE1 los filtros y v\xE1lvulas.","El riesgo de incendio al no haber un gas inerte que desplace el ox\xEDgeno.","La deformaci\xF3n del tubo de cobre por el calor excesivo de la llama pura.","La p\xE9rdida de las propiedades de la soldadura de plata al oxidarse el cobre."],respuesta_correcta:0,explicacion:"Sin purga de nitr\xF3geno, el ox\xEDgeno dentro de la tuber\xEDa reacciona con el cobre a altas temperaturas formando \xF3xido c\xFAprico (holl\xEDn negro). Estas escamas se desprenden y obstruyen filtros deshidratadores, TXVs y orificios del sistema."},{id:"ns_0258",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una ca\xEDda de presi\xF3n de agua de 15 PSI en el evaporador. \xBFC\xF3mo verifica el flujo?",opciones:["Consultando la curva de la bomba y la tabla de dise\xF1o del fabricante.","Midiendo la temperatura de salida del agua con un term\xF3metro l\xE1ser.","Observando el movimiento del agua en el tanque de expansi\xF3n abierto.","Contando las revoluciones por minuto del motor de la bomba de agua helada."],respuesta_correcta:0,explicacion:"La ca\xEDda de presi\xF3n de agua se correlaciona con el flujo seg\xFAn las curvas del fabricante. Consultando la curva de la bomba y la tabla de dise\xF1o, se puede verificar si el flujo corresponde al diferencial medido."},{id:"ns_0259",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta ruidos de 'Water Hammering' en las l\xEDneas de refrigerante. \xBFCausa?",opciones:["L\xEDquido refrigerante regresando al compresor o falta de soportes en tuber\xEDa.","Aire atrapado en el sistema que no fue evacuado durante el proceso de vac\xEDo.","Una v\xE1lvula de expansi\xF3n que abre y cierra violentamente por falta de carga.","El uso de tuber\xEDa de succi\xF3n con un di\xE1metro mayor al especificado por dise\xF1o."],respuesta_correcta:0,explicacion:"El 'water hammering' en l\xEDneas de refrigerante se produce cuando refrigerante l\xEDquido viaja a alta velocidad y golpea contra curvas o componentes, o cuando la tuber\xEDa vibra por falta de soportes adecuados. El l\xEDquido regresando al compresor es la causa m\xE1s com\xFAn y peligrosa."},{id:"ns_0260",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar la retenci\xF3n de clientes. \xBFCu\xE1l es el impacto de un programa de mantenimiento?",opciones:["Aumenta la lealtad, reduce las emergencias y genera ingresos recurrentes.","Permite cobrar m\xE1s caro por las reparaciones de emergencia al cliente fiel.","Reduce la necesidad de tener t\xE9cnicos Senior, ya que el equipo estar\xE1 nuevo.","Elimina la competencia al obligar al cliente a firmar un contrato de exclusividad."],respuesta_correcta:0,explicacion:"Un programa de mantenimiento preventivo aumenta la lealtad del cliente, reduce emergencias costosas y genera ingresos recurrentes predecibles para la empresa."},{id:"ns_0261",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se prefiere un condensador remoto con ventiladores VFD?",opciones:["Mantiene una presi\xF3n de descarga estable y reduce el consumo el\xE9ctrico.","Permite que el rack funcione sin necesidad de un separador de aceite.","Elimina el ruido en el \xE1rea de ventas al alejar los motores del edificio.","Facilita la carga de refrigerante al no depender de la temperatura ambiente."],respuesta_correcta:0,explicacion:"Los ventiladores con VFD (variador de frecuencia) modulan su velocidad seg\xFAn la presi\xF3n de descarga, manteniendo una presi\xF3n estable en todas las condiciones ambientales. Adem\xE1s, a velocidades reducidas consumen significativamente menos energ\xEDa el\xE9ctrica."},{id:"ns_0262",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Surge'. El Senior nota que la temperatura del agua de la torre es de 45\xB0F. \xBFCausa?",opciones:["La temperatura del agua es demasiado baja, causando baja presi\xF3n de condensaci\xF3n.","El agua est\xE1 demasiado fr\xEDa y est\xE1 congelando el refrigerante en los tubos.","La torre est\xE1 enviando agua con aire hacia el condensador del chiller.","Los ventiladores de la torre est\xE1n girando en sentido contrario al dise\xF1o."],respuesta_correcta:0,explicacion:"Agua de torre a 45\xB0F es demasiado fr\xEDa, causando baja presi\xF3n de condensaci\xF3n. La diferencia de presi\xF3n entre condensador y evaporador se reduce al punto donde el impulsor centr\xEDfugo entra en surge."},{id:"ns_0263",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter muestra el error 'P4' (Inverter Fin Temp Error). \xBFQu\xE9 hace?",opciones:["Limpiar el disipador de calor de la placa exterior y revisar la pasta t\xE9rmica.","Cambiar el motor del ventilador interior por uno de mayor flujo de aire.","Sustituir el compresor asumiendo que el bobinado est\xE1 sobrecalentado.","Puentear el sensor de temperatura del disipador para que la placa opere."],respuesta_correcta:0,explicacion:"El error P4 (IPM Overheat) indica sobrecalentamiento del m\xF3dulo de potencia. Limpiar el disipador de calor y revisar/reemplazar la pasta t\xE9rmica restablece la transferencia de calor adecuada del IPM."},{id:"ns_0264",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor tiene la l\xEDnea de l\xEDquido caliente y la succi\xF3n escarchada. \xBFQu\xE9 revisa?",opciones:["El flujo de aire exterior y si el serpent\xEDn exterior est\xE1 bloqueado por suciedad.","La v\xE1lvula inversora que podr\xEDa estar parcialmente movida hacia refrigeraci\xF3n.","Si el filtro de aire interior est\xE1 sucio, reduciendo la transferencia de calor.","La carga de refrigerante que probablemente es excesiva para el modo calor."],respuesta_correcta:0,explicacion:"La linea de liquido caliente indica que el condensador interior funciona. La succion escarchada indica que el serpentin exterior no absorbe suficiente calor, por suciedad o bloqueo del flujo de aire exterior."},{id:"ns_0265",categoria:"NATE_SR_CEO",pregunta:"Un CEO eval\xFAa el 'Average Ticket'. \xBFC\xF3mo puede subir este valor sin subir precios?",opciones:["Capacitando a los t\xE9cnicos en la identificaci\xF3n de accesorios y mejoras.","Obligando a los t\xE9cnicos a tardar m\xE1s tiempo en cada llamada de servicio.","Cargando una tarifa extra por el uso de herramientas especializadas en sitio.","Eliminando los descuentos por pronto pago que se ofrecen a los clientes."],respuesta_correcta:0,explicacion:"Capacitar a los t\xE9cnicos para identificar oportunidades de mejora (filtros UV, termostatos inteligentes, protectores de voltaje) sube el Average Ticket sin aumentar los precios base."},{id:"ns_0266",categoria:"NATE_SR_RACK",pregunta:"Un rack de media temperatura usa R-22. El cliente quiere convertirlo a R-407A. \xBFQu\xE9 es cr\xEDtico?",opciones:["Cambiar el aceite mineral por POE y sustituir todos los sellos de elast\xF3mero.","Reemplazar todos los compresores ya que el R-407A da\xF1ar\xE1 los pistones.","Simplemente vaciar el R-22 y cargar el R-407A sin hacer cambios f\xEDsicos.","Instalar un condensador dos veces m\xE1s grande para manejar la nueva presi\xF3n."],respuesta_correcta:0,explicacion:"El R-407A requiere aceite POE (poliol \xE9ster) que es compatible con HFC, a diferencia del aceite mineral usado con R-22. Adem\xE1s, los sellos de elast\xF3mero deben cambiarse porque el R-407A puede deteriorar los materiales dise\xF1ados para R-22."},{id:"ns_0267",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que una unidad nueva tiene un serpent\xEDn con fuga de f\xE1brica. \xBFQu\xE9 hace el Senior?",opciones:["Documentar con fotos, procesar la garant\xEDa y pedir el reemplazo al proveedor.","Reparar la fuga con soldadura de plata para no perder tiempo en la obra.","Decirle al cliente que el equipo es de mala calidad y que compre otra marca.","Cargar el sistema con un sellador de fugas para que el cliente no se d\xE9 cuenta."],respuesta_correcta:0,explicacion:"Un defecto de f\xE1brica debe procesarse como garant\xEDa. Documentar con fotos protege a la empresa y al cliente, asegura el reemplazo sin costo, y mantiene la integridad del equipo nuevo sin reparaciones que podr\xEDan comprometer su vida \xFAtil."},{id:"ns_0268",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con evaporador de placas presenta una falla de 'Freeze Protection'. \xBFCausa?",opciones:["Bajo flujo de agua o set-point de presi\xF3n de succi\xF3n demasiado bajo.","Carga de refrigerante excesiva que enfr\xEDa demasiado el agua del proceso.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total.","El sensor de temperatura de salida del agua est\xE1 tocando la tuber\xEDa caliente."],respuesta_correcta:0,explicacion:"En evaporadores de placas, el espacio es reducido y el riesgo de congelaci\xF3n es alto. Un bajo flujo de agua o set-point de succi\xF3n muy bajo causa que el refrigerante enfr\xEDe el agua por debajo de 32\xB0F."},{id:"ns_0269",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de descarga que oscila r\xEDtmicamente. \xBFQu\xE9 revisa?",opciones:["Aire en el sistema o una v\xE1lvula de expansi\xF3n con el bulbo mal ubicado.","El capacitor de marcha del compresor que est\xE1 perdiendo fuerza motriz.","Si el motor del ventilador del condensador est\xE1 ciclando por temperatura.","La estabilidad del voltaje que suministra la empresa el\xE9ctrica local."],respuesta_correcta:0,explicacion:"Una descarga que oscila r\xEDtmicamente indica aire (incondensables) atrapado en el sistema que se comprime y expande, o una TXV con el bulbo mal ubicado que causa ciclos repetitivos de apertura y cierre. Ambos producen fluctuaciones predecibles en la presi\xF3n de descarga."},{id:"ns_0270",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de 10 toneladas tiene un Delta T de aire de 30\xB0F. \xBFQu\xE9 indica?",opciones:["Bajo flujo de aire a trav\xE9s del evaporador debido a filtros o conductos.","Funcionamiento excepcional del sistema con una capacidad de enfriamiento alta.","Falta de refrigerante que causa que el aire se enfr\xEDe de forma desigual.","Exceso de velocidad del ventilador del soplador que genera turbulencia."],respuesta_correcta:0,explicacion:"Un Delta T de 30\xB0F (normal es 18-22\xB0F) indica que el aire permanece demasiado tiempo en contacto con el serpent\xEDn por bajo flujo de aire. Menos CFM sobre el evaporador = mayor ca\xEDda de temperatura por unidad de aire, causado t\xEDpicamente por filtros sucios, conductos restringidos o soplador lento."},{id:"ns_0271",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar el 'Cash Flow'. \xBFCu\xE1l es la medida m\xE1s efectiva?",opciones:["Cobrar en el momento del servicio y reducir los t\xE9rminos de cr\xE9dito a 30 d\xEDas.","Pedir un pr\xE9stamo bancario a largo plazo para cubrir los gastos operativos.","Aumentar el inventario de piezas en las camionetas para no ir a la tienda.","Reducir el salario de los t\xE9cnicos junior para ahorrar en la n\xF3mina semanal."],respuesta_correcta:0,explicacion:"Cobrar en el momento del servicio y reducir los t\xE9rminos de cr\xE9dito a 30 d\xEDas m\xE1ximo acelera la entrada de efectivo, mejorando directamente el flujo de caja operativo."},{id:"ns_0272",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFcu\xE1l es la funci\xF3n del 'Oil Reservoir' o dep\xF3sito de aceite?",opciones:["Almacenar el aceite separado del gas para distribuirlo seg\xFAn la demanda.","Enfriar el aceite mediante un intercambiador de placas antes de los motores.","Separar el refrigerante l\xEDquido que pudo haberse mezclado con el lubricante.","Mantener la presi\xF3n de descarga constante para el retorno de aceite al rack."],respuesta_correcta:0,explicacion:"El dep\xF3sito de aceite (oil reservoir) almacena el aceite recuperado por el separador y lo distribuye a los compresores seg\xFAn la demanda, mediante v\xE1lvulas reguladoras de nivel. Act\xFAa como reserva centralizada para todo el rack paralelo."},{id:"ns_0273",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un approach de condensador de 1\xB0F. \xBFQu\xE9 concluye el Senior?",opciones:["Transferencia de calor excelente; el condensador est\xE1 perfectamente limpio.","Falta de refrigerante l\xEDquido; no hay suficiente masa para el intercambio.","Flujo de agua excesivo que est\xE1 falseando la lectura del sensor t\xE9rmico.","El sensor de temperatura de salida del agua est\xE1 defectuoso o mal puesto."],respuesta_correcta:0,explicacion:"Un approach de condensador de 1\xB0F indica una excelente transferencia de calor, con tubos perfectamente limpios y una diferencia m\xEDnima entre la temperatura de saturaci\xF3n y la salida del agua."},{id:"ns_0274",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter muestra el error 'High Pressure Protection' en calefacci\xF3n. \xBFCausa?",opciones:["Filtro de aire interior sucio o ventilador interior a baja velocidad.","Condensador exterior bloqueado por hojas o suciedad del ambiente.","Carga de refrigerante insuficiente para alcanzar la presi\xF3n de dise\xF1o.","V\xE1lvula de expansi\xF3n electr\xF3nica (EEV) bloqueada en posici\xF3n cerrada."],respuesta_correcta:0,explicacion:"En modo calefacci\xF3n, el serpent\xEDn interior act\xFAa como condensador. Un filtro sucio o ventilador lento reduce el flujo de aire, la presi\xF3n de condensaci\xF3n sube excesivamente y activa la protecci\xF3n de alta presi\xF3n."},{id:"ns_0275",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFpor qu\xE9 el compresor se apaga durante el ciclo de deshielo?",opciones:["No se apaga; el compresor sigue operando para calentar el serpent\xEDn exterior.","Se apaga por seguridad para evitar un golpe de l\xEDquido al revertir la v\xE1lvula.","Para ahorrar energ\xEDa ya que las resistencias el\xE9ctricas est\xE1n encendidas.","Para permitir que el hielo se derrita por la temperatura del aire ambiente."],respuesta_correcta:0,explicacion:"Durante el defrost, el compresor NO se apaga. Continua operando para bombear gas caliente de descarga al serpentin exterior, derritiendo el hielo acumulado. El sistema opera en modo refrigeracion temporalmente."},{id:"ns_0276",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Junior instala una unidad y no conecta la tierra f\xEDsica. El Senior le advierte que:",opciones:["Es un riesgo mortal de descarga el\xE9ctrica y puede da\xF1ar las placas electr\xF3nicas.","El compresor consumir\xE1 m\xE1s amperaje al no tener una referencia de neutro.","La garant\xEDa del fabricante se anula si no hay una conexi\xF3n a tierra certificada.","El equipo har\xE1 m\xE1s ruido debido a la falta de masa para las vibraciones."],respuesta_correcta:0,explicacion:"La tierra f\xEDsica proporciona un camino seguro para corrientes de fuga, protegiendo a las personas de descargas el\xE9ctricas letales. Sin tierra, el chasis del equipo puede quedar energizado. Adem\xE1s, las placas electr\xF3nicas son vulnerables a da\xF1os por descargas est\xE1ticas."},{id:"ns_0277",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo usa un variador de frecuencia (VFD). \xBFCu\xE1l es el beneficio a baja carga?",opciones:["Prevenir el surge bajando la velocidad del motor y ajustando los vanes.","Aumentar la presi\xF3n de descarga para mejorar la eficiencia del condensador.","Eliminar la necesidad de usar una unidad de purga en sistemas de baja presi\xF3n.","Reducir el flujo de agua helada para mantener la temperatura de salida constante."],respuesta_correcta:0,explicacion:"El VFD permite reducir la velocidad del compresor a baja carga, previniendo el surge al mantener una velocidad de gas adecuada en el impulsor mientras se ajustan los vanes de entrada."},{id:"ns_0278",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. El subenfriamiento es 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido en el sistema (undercharged).","V\xE1lvula de expansi\xF3n (TXV) fallida en posici\xF3n abierta total.","Condensador exterior sucio que no permite el subenfriamiento.","Evaporador interior congelado que bloquea el flujo de calor."],respuesta_correcta:0,explicacion:"Un subenfriamiento de 0\xB0F significa que no hay l\xEDquido subenfriado saliendo del condensador, solo vapor o mezcla bif\xE1sica. Con presiones que no son extremas, esto indica claramente que el sistema no tiene suficiente refrigerante para llenar el condensador con l\xEDquido (undercharged)."},{id:"ns_0279",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC quiere entrar al mercado de 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos."],respuesta_correcta:0,explicacion:"El mercado de Smart Homes requiere t\xE9cnicos que dominen redes Wi-Fi, protocolos IoT (Zigbee, Z-Wave) e integraci\xF3n de dispositivos, habilidades que van m\xE1s all\xE1 del HVAC tradicional."},{id:"ns_0280",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 indica una temperatura de succi\xF3n muy alta en el cabezal?",opciones:["Sobrecalentamiento excesivo que puede da\xF1ar la lubricaci\xF3n de los compresores.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de evaporaci\xF3n.","Falta de refrigerante l\xEDquido en el recibidor principal del rack paralelo.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n cerradas por temperatura."],respuesta_correcta:0,explicacion:"Una temperatura de succi\xF3n muy alta indica sobrecalentamiento excesivo del gas de retorno. Esto reduce la capacidad de enfriamiento del motor del compresor y degrada las propiedades del aceite lubricante, acelerando el desgaste mec\xE1nico."},{id:"ns_0281",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Loss'. \xBFQu\xE9 componente el\xE9ctrico protege al motor?",opciones:["El monitor de fase o el rel\xE9 de sobrecarga de estado s\xF3lido del sistema.","Los fusibles de retardo de tiempo instalados en la desconexi\xF3n principal.","El interruptor termomagn\xE9tico de la placa de control de 120 voltios.","El contactor magn\xE9tico que se abrir\xE1 por falta de voltaje en la bobina."],respuesta_correcta:0,explicacion:"El monitor de fase o rel\xE9 de sobrecarga de estado s\xF3lido detecta la p\xE9rdida de fase y desconecta el motor antes de que sufra da\xF1o. Los fusibles solo protegen contra cortocircuitos, no p\xE9rdida de fase."},{id:"ns_0282",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter tiene una fuga en el serpent\xEDn interior. El cliente pide repararlo. \xBFQu\xE9 dice el Senior?",opciones:["Es mejor reemplazar el serpent\xEDn completo debido a la complejidad de soldar aluminio.","Se puede reparar con ep\xF3xico especial para refrigeraci\xF3n sin retirar la unidad.","La soldadura de plata funcionar\xE1 perfectamente si se usa el fundente adecuado.","No es reparable; el sistema completo debe ser desechado por normativas ambientales."],respuesta_correcta:0,explicacion:"Los serpentines interiores de mini-split suelen ser de aluminio, un material dif\xEDcil de soldar en campo. Es m\xE1s confiable y seguro reemplazar el serpent\xEDn completo que intentar una reparaci\xF3n de soldadura."},{id:"ns_0283",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica total de 1.2 pulg. W.C. \xBFQu\xE9 le sucede al motor ECM?",opciones:["Intentar\xE1 subir las RPM para mantener el flujo de aire, aumentando el consumo y ruido.","Se apagar\xE1 por seguridad para evitar que el exceso de presi\xF3n rompa los conductos.","Bajar\xE1 la velocidad autom\xE1ticamente para proteger los rodamientos del motor.","No le sucede nada, ya que los motores ECM est\xE1n dise\xF1ados para cualquier presi\xF3n."],respuesta_correcta:0,explicacion:"Los motores ECM son de velocidad variable y est\xE1n programados para entregar un CFM constante. Ante alta presi\xF3n est\xE1tica, el ECM aumenta autom\xE1ticamente las RPM para mantener el flujo objetivo, lo que incrementa el consumo el\xE9ctrico y genera m\xE1s ruido en el sistema."},{id:"ns_0284",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFcu\xE1l es la funci\xF3n del 'Defrost Control Board'?",opciones:["Monitorear tiempo y temperatura para revertir la v\xE1lvula y quitar el hielo.","Encender las resistencias el\xE9ctricas cuando la temperatura exterior baja de 30\xB0F.","Asegurar que el compresor no arranque si la presi\xF3n de alta es muy elevada.","Regular la velocidad del ventilador interior seg\xFAn la demanda de calefacci\xF3n."],respuesta_correcta:0,explicacion:"La placa de defrost monitorea tiempo acumulado de operacion y temperatura del serpentin exterior. Cuando ambas condiciones se cumplen, inicia el deshielo revirtiendo la valvula inversora a modo refrigeracion."},{id:"ns_0285",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un equipo de 10 t\xE9cnicos. Nota que el inventario de gas desaparece. \xBFAcci\xF3n?",opciones:["Implementar un registro de peso de cilindros al inicio y final de cada d\xEDa.","Descontar el costo del refrigerante faltante de forma equitativa a todos.","Cerrar con llave el almac\xE9n de gas y solo el Senior puede entregar cilindros.","Instalar c\xE1maras en todas las camionetas para ver qu\xE9 hacen los t\xE9cnicos."],respuesta_correcta:0,explicacion:"Un registro diario de peso de cilindros es una medida de control de inventario precisa y justa. Permite identificar discrepancias, rastrear el consumo por t\xE9cnico y trabajo, y detectar p\xE9rdidas sin acusar injustamente a nadie."},{id:"ns_0286",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. \xBFEstado?",opciones:["Funcionamiento correcto; la purga est\xE1 separando los no condensables.","Falla en el serpent\xEDn de condensaci\xF3n interno de la unidad de purga.","El sistema tiene una fuga masiva de agua hacia el lado del refrigerante.","La temperatura del evaporador es demasiado alta para que la purga trabaje."],respuesta_correcta:0,explicacion:"Una purga que expulsa mucho aire pero poco refrigerante est\xE1 funcionando correctamente, ya que su dise\xF1o separa los gases no condensables del refrigerante y solo expulsa el aire."},{id:"ns_0287",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si el 'Oil Separator' se queda pegado en posici\xF3n abierta?",opciones:["Gas caliente de descarga pasar\xE1 directamente al dep\xF3sito de aceite y la succi\xF3n.","El rack se quedar\xE1 sin aceite en pocos minutos al no poder separarlo del gas.","Los compresores se apagar\xE1n por alta presi\xF3n al bloquearse el flujo de gas.","El nivel de aceite en los c\xE1rteres subir\xE1 tanto que da\xF1ar\xE1 los pistones."],respuesta_correcta:0,explicacion:"Si el flotador del separador se queda abierto, gas caliente de descarga a alta presi\xF3n pasa directamente al dep\xF3sito de aceite y puede llegar a la succi\xF3n. Esto crea un bypass que reduce la capacidad del sistema y sobrecalienta los compresores."},{id:"ns_0288",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. \xBFQu\xE9 KPI usa?",opciones:["El n\xFAmero de llamadas de nuevos clientes que mencionan haber visto la unidad.","La cantidad de millas recorridas por cada veh\xEDculo en zonas residenciales.","El costo total del dise\xF1o y la instalaci\xF3n del r\xF3tulo dividido entre 12 meses.","El aumento en la velocidad promedio de los t\xE9cnicos al conducir camionetas nuevas."],respuesta_correcta:0,explicacion:"El KPI m\xE1s directo para medir la efectividad de camionetas rotuladas es el n\xFAmero de llamadas de nuevos clientes que mencionan haber visto la unidad en su vecindario."},{id:"ns_0289",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con condensador de agua tiene 'High Condensing Pressure'. \xBFQu\xE9 revisa primero?",opciones:["La temperatura del agua de la torre y si la bomba de condensador funciona.","La carga de refrigerante l\xEDquido bas\xE1ndose en el visor del evaporador.","Si la v\xE1lvula de expansi\xF3n est\xE1 inyectando demasiado l\xEDquido al sistema.","El estado de los filtros de aire de la manejadora de aire del edificio."],respuesta_correcta:0,explicacion:"En un condensador enfriado por agua, la alta presi\xF3n de condensaci\xF3n se relaciona directamente con la temperatura del agua de torre y el funcionamiento de la bomba de condensador como primer punto de diagn\xF3stico."},{id:"ns_0290",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 125 PSI y descarga de 400 PSI con R-410A. El aire sale a 60\xB0F. \xBFEstado?",opciones:["Funcionamiento normal bajo condiciones de carga t\xE9rmica est\xE1ndar.","Falta de refrigerante que impide que la temperatura del aire baje a 55\xB0F.","Exceso de carga que est\xE1 elevando la presi\xF3n de descarga innecesariamente.","Compresor con eficiencia reducida que no logra enfriar el aire correctamente."],respuesta_correcta:0,explicacion:"Con R-410A, succi\xF3n de 125 PSI (~40\xB0F sat.) y descarga de 400 PSI (~109\xB0F sat.) son valores normales. Una temperatura de suministro de 60\xB0F indica un Delta T adecuado de ~15-20\xB0F sobre la saturaci\xF3n del evaporador, confirmando operaci\xF3n normal."},{id:"ns_0291",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. \xBFQu\xE9 estrategia lanza?",opciones:["Un programa de membres\xEDas de mantenimiento para convertir clientes en recurrentes.","Aumentar el precio de la primera visita para maximizar la ganancia inmediata.","Gastar m\xE1s dinero en anuncios de Google para atraer siempre clientes nuevos.","Despedir a los t\xE9cnicos que no logren vender un sistema nuevo en cada visita."],respuesta_correcta:0,explicacion:"Un programa de membres\xEDas de mantenimiento convierte clientes de una sola vez en recurrentes, generando ingresos predecibles y aumentando el Customer Lifetime Value."},{id:"ns_0292",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. \xBFQu\xE9 revisa?",opciones:["Carga de refrigerante baja o una restricci\xF3n en la v\xE1lvula de expansi\xF3n.","Si el ventilador interior est\xE1 sucio y no sopla suficiente aire fr\xEDo.","El voltaje de la l\xEDnea el\xE9ctrica que podr\xEDa estar por debajo de los 200V.","Si el control remoto est\xE1 configurado en una temperatura demasiado baja."],respuesta_correcta:0,explicacion:"Una carga baja de refrigerante o una restricci\xF3n en la EEV causa sobrecalentamiento excesivo del gas de descarga del compresor, activando la protecci\xF3n de temperatura de descarga."},{id:"ns_0293",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si la v\xE1lvula de retenci\xF3n del condensador falla abierta?",opciones:["El refrigerante har\xE1 bypass a la TXV en modo calor, impidiendo el calentamiento.","El sistema funcionar\xE1 mejor al haber menos restricci\xF3n al flujo de l\xEDquido.","La presi\xF3n de descarga subir\xE1 hasta que el switch de alta apague el equipo.","El compresor se quemar\xE1 por el retorno de l\xEDquido masivo durante el arranque."],respuesta_correcta:0,explicacion:"La check valve esta en paralelo con la TXV. Si falla abierta, en modo calor el refrigerante hace bypass por la check valve en vez de pasar por la TXV, sin restriccion ni calentamiento adecuado."},{id:"ns_0294",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula 'Quench' o de inyecci\xF3n de l\xEDquido?",opciones:["Para enfriar el gas de succi\xF3n y evitar que la descarga da\xF1e el aceite.","Para aumentar la presi\xF3n de succi\xF3n cuando la carga en las vitrinas es baja.","Para limpiar el interior de los compresores de acumulaciones de carbonilla.","Para ayudar al retorno de aceite desde los evaporadores m\xE1s lejanos."],respuesta_correcta:0,explicacion:"La v\xE1lvula Quench inyecta una peque\xF1a cantidad de refrigerante l\xEDquido en la succi\xF3n o descarga para enfriar el gas y reducir la temperatura de descarga. Esto protege el aceite lubricante de la degradaci\xF3n t\xE9rmica por temperaturas excesivas."},{id:"ns_0295",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior debe decidir si usar una aspiradora de agua o una bomba para un drenaje. \xBFCriterio?",opciones:["El volumen de agua y la accesibilidad para la eliminaci\xF3n segura del fluido.","Cu\xE1l de las dos herramientas es m\xE1s nueva y hace menos ruido al operar.","La preferencia del cliente sobre qu\xE9 herramienta quiere ver en su casa.","Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo."],respuesta_correcta:0,explicacion:"La selecci\xF3n de herramienta debe basarse en factores t\xE9cnicos: el volumen de agua a remover determina la capacidad necesaria, y la accesibilidad del drenaje determina qu\xE9 equipo puede llegar al punto de acumulaci\xF3n para una eliminaci\xF3n segura."},{id:"ns_0296",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que marca 'Water Detected'. \xBFQu\xE9 acci\xF3n es urgente?",opciones:["Realizar una prueba de presi\xF3n a los tubos del evaporador para buscar rupturas.","Cambiar el filtro deshidratador de la purga y seguir operando el sistema.","Aumentar la temperatura del agua helada para evitar que el vapor se condense.","Drenar el aceite del compresor y reemplazarlo por aceite con aditivo secante."],respuesta_correcta:0,explicacion:"La detecci\xF3n de agua por la purga indica una posible ruptura en los tubos del evaporador. Se requiere una prueba de presi\xF3n urgente para localizar la fuga y evitar contaminaci\xF3n del refrigerante."},{id:"ns_0297",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 130 PSI y descarga de 380 PSI. El subenfriamiento es 12\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y el subenfriamiento est\xE1n en rango.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser de 15\xB0F m\xEDnimo.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno.","Compresor fallando; la diferencia de presi\xF3n entre succi\xF3n y descarga es baja."],respuesta_correcta:0,explicacion:"Con R-410A, succi\xF3n de 130 PSI (~42\xB0F sat.) y descarga de 380 PSI (~104\xB0F sat.) son normales. Un subenfriamiento de 12\xB0F est\xE1 dentro del rango t\xEDpico de 10-15\xB0F para sistemas con TXV, confirmando una carga de refrigerante correcta y operaci\xF3n \xF3ptima."},{id:"ns_0298",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete, el contactor del compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["El voltaje en la bobina (24V) y si hay suciedad u \xF3xido en el n\xFAcleo.","Si los contactos principales est\xE1n quemados o soldados entre s\xED.","El capacitor de arranque del compresor que podr\xEDa estar descargado.","La continuidad de los fusibles de potencia de la l\xEDnea de 240 voltios."],respuesta_correcta:0,explicacion:"Un contactor que zumba sin cerrar indica que la bobina recibe voltaje insuficiente para generar la fuerza magn\xE9tica necesaria, o que el n\xFAcleo tiene suciedad/\xF3xido que impide el cierre mec\xE1nico. Verificar el voltaje de la bobina y la limpieza del n\xFAcleo es el primer paso diagn\xF3stico."},{id:"ns_0299",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico est\xE1 cobrando 'por fuera' a los clientes. \xBFAcci\xF3n?",opciones:["Despido inmediato y posible acci\xF3n legal seg\xFAn el contrato de trabajo.","Hablar con el t\xE9cnico y pedirle una comisi\xF3n por esos trabajos extras.","Ignorar la situaci\xF3n si el t\xE9cnico es el que m\xE1s dinero genera a la empresa.","Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas de trabajo."],respuesta_correcta:0,explicacion:"Cobrar por fuera es fraude contra la empresa; el despido inmediato y la acci\xF3n legal protegen la integridad del negocio y env\xEDan un mensaje claro de tolerancia cero."},{id:"ns_0300",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFPor qu\xE9 es fundamental cargar l\xEDquido en el recibidor?",opciones:["Para evitar el fraccionamiento de la mezcla y asegurar la composici\xF3n correcta.","Para que el refrigerante se mezcle m\xE1s r\xE1pido con el aceite POE del rack.","Para prevenir que las v\xE1lvulas de descarga de los compresores se calienten.","Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal."],respuesta_correcta:0,explicacion:"El R-448A es una mezcla zeotr\xF3pica; si se carga en fase gaseosa, los componentes m\xE1s vol\xE1tiles se evaporan primero y la composici\xF3n del cilindro cambia. Cargar en fase l\xEDquida garantiza que todos los componentes entren al sistema en la proporci\xF3n correcta."},{id:"ns_0301",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo opera con una presi\xF3n de condensaci\xF3n que fluct\xFAa r\xEDtmicamente. El flujo de agua es estable. \xBFQu\xE9 diagn\xF3stico Senior aplica?",opciones:["Presencia de gases incondensables o una carga de refrigerante excesiva.","Descalibraci\xF3n del sensor de temperatura de aproximaci\xF3n del evaporador.","Falla en el rodamiento de empuje (thrust bearing) del eje principal.","Efecto de cavitaci\xF3n en la bomba de agua de la torre de enfriamiento."],respuesta_correcta:0,explicacion:"Fluctuaciones r\xEDtmicas en la presi\xF3n de condensaci\xF3n, con flujo de agua estable, indican gases no condensables que se comprimen y expanden, o una sobrecarga de refrigerante que causa inundaci\xF3n intermitente."},{id:"ns_0302",categoria:"NATE_SR_RACK",pregunta:"En un rack de refrigeraci\xF3n, \xBFcu\xE1l es el s\xEDntoma principal de una v\xE1lvula reguladora de presi\xF3n de c\xE1rter (CPR) mal ajustada (muy alta)?",opciones:["Sobrecarga del motor del compresor durante el arranque tras un deshielo.","Reducci\xF3n de la capacidad de enfriamiento en todas las vitrinas conectadas.","Aumento del retorno de aceite l\xEDquido directamente al cabezal de succi\xF3n.","Ciclos cortos por baja presi\xF3n de succi\xF3n debido a la restricci\xF3n de gas."],respuesta_correcta:0,explicacion:"La CPR limita la presi\xF3n m\xE1xima de succi\xF3n que llega al compresor para proteger el motor. Si est\xE1 ajustada muy alta, permite el paso de demasiado gas durante el pull-down post-deshielo, sobrecargando el motor del compresor."},{id:"ns_0303",categoria:"NATE_SR_CEO",pregunta:"Un CEO eval\xFAa el 'Labor Burden'. \xBFQu\xE9 elementos deben incluirse para un c\xE1lculo real de costo por hora t\xE9cnica?",opciones:["Impuestos sobre n\xF3mina, seguros, beneficios, uniformes y tiempo no facturable.","\xDAnicamente el salario base por hora multiplicado por las horas de la jornada.","El costo de las herramientas manuales y el combustible usado en la camioneta.","La comisi\xF3n por ventas y el bono de productividad trimestral del empleado."],respuesta_correcta:0,explicacion:"El Labor Burden real incluye impuestos sobre n\xF3mina, seguros, beneficios, uniformes y tiempo no facturable; usar solo el salario base subestima gravemente el costo por hora."},{id:"ns_0304",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRF presenta un error de 'Inverter DC Link Overvoltage'. \xBFQu\xE9 factor el\xE9ctrico externo es el culpable m\xE1s probable?",opciones:["Una p\xE9rdida del neutro o un desequilibrio severo en las fases de entrada.","Un compresor con los devanados parcialmente quemados que genera retorno.","El uso de un generador el\xE9ctrico con una frecuencia de salida inestable.","Un ventilador de condensador bloqueado que eleva la carga del compresor."],respuesta_correcta:0,explicacion:"La p\xE9rdida del neutro o un desequilibrio severo de fases causa picos de voltaje en el bus DC del inverter que exceden el l\xEDmite del circuito, disparando el error de sobrevoltaje DC Link."},{id:"ns_0305",categoria:"NATE_SR_HVAC",pregunta:"Al realizar un balanceo de aire, se encuentra que una habitaci\xF3n tiene presi\xF3n positiva excesiva. \xBFCu\xE1l es la correcci\xF3n t\xE9cnica?",opciones:["Aumentar el tama\xF1o del conducto de retorno o instalar una rejilla de transferencia.","Reducir el di\xE1metro del conducto de suministro para bajar el volumen de CFM.","Instalar un damper motorizado que cierre al detectar presi\xF3n en la habitaci\xF3n.","Aumentar la velocidad del soplador para forzar la salida del aire por las puertas."],respuesta_correcta:0,explicacion:"Presi\xF3n positiva en una habitaci\xF3n significa que entra m\xE1s aire del que sale. La soluci\xF3n es agregar un camino de retorno adecuado, ya sea aumentando el conducto de retorno o instalando una rejilla de transferencia, para que el aire pueda circular de vuelta al sistema."},{id:"ns_0306",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor presenta una temperatura de descarga de 240\xB0F con R-410A. \xBFQu\xE9 acci\xF3n es prioritaria?",opciones:["Verificar falta de refrigerante o una restricci\xF3n en la TXV exterior.","Instalar un enfriador de aceite externo para proteger los rodamientos.","Reducir el flujo de aire interior para aumentar la presi\xF3n de condensaci\xF3n.","Ignorar el valor si el sobrecalentamiento de succi\xF3n es menor a 15\xB0F."],respuesta_correcta:0,explicacion:"Una temperatura de descarga de 240F con R-410A es peligrosamente alta (limite 225F). La prioridad es verificar falta de refrigerante o una restriccion en la TXV que limita el flujo y reduce el enfriamiento del gas."},{id:"ns_0307",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior observa que su equipo recupera refrigerante en cilindros llenos al 95%. \xBFCu\xE1l es el riesgo de seguridad?",opciones:["Explosi\xF3n por expansi\xF3n hidrost\xE1tica si la temperatura ambiente aumenta.","Contaminaci\xF3n del refrigerante recuperado por falta de espacio gaseoso.","Da\xF1o mec\xE1nico a la m\xE1quina recuperadora por exceso de contrapresi\xF3n.","Multas de la EPA por exceder el l\xEDmite legal de transporte de materiales."],respuesta_correcta:0,explicacion:"Los cilindros de recuperaci\xF3n no deben llenarse m\xE1s del 80% de su capacidad. Si la temperatura sube, el l\xEDquido se expande y sin espacio gaseoso de seguridad, la presi\xF3n hidrost\xE1tica puede causar una explosi\xF3n catastr\xF3fica del cilindro."},{id:"ns_0308",categoria:"NATE_SR_PACKAGE",pregunta:"Un Rooftop tiene un economizador con control de 'Diferencial de Entalp\xEDa'. \xBFQu\xE9 comparan los sensores?",opciones:["La energ\xEDa total (calor + humedad) del aire exterior vs. el aire de retorno.","La temperatura de bulbo seco exterior vs. la temperatura de bulbo h\xFAmedo.","La humedad relativa de la zona vs. el punto de roc\xEDo del serpent\xEDn interior.","La presi\xF3n est\xE1tica del suministro vs. la presi\xF3n barom\xE9trica del exterior."],respuesta_correcta:0,explicacion:"El control de diferencial de entalp\xEDa compara la energ\xEDa total (calor sensible + calor latente por humedad) del aire exterior contra el aire de retorno. Solo abre el economizador cuando la entalp\xEDa exterior es menor, garantizando un ahorro energ\xE9tico real incluyendo el efecto de la humedad."},{id:"ns_0309",categoria:"NATE_SR_RACK",pregunta:"En un sistema de rack paralelo, el 'Master Controller' falla. \xBFQu\xE9 modo de operaci\xF3n deben tener los compresores?",opciones:["Operaci\xF3n manual mediante presostatos mec\xE1nicos de respaldo (fail-safe).","Apagado total para evitar que los compresores operen sin control de aceite.","Ciclo de tiempo fijo (5 minutos encendido, 5 apagado) para mantener fr\xEDo.","Arranque simult\xE1neo de todos los compresores para proteger la mercanc\xEDa."],respuesta_correcta:0,explicacion:"Los racks bien dise\xF1ados tienen presostatos mec\xE1nicos de respaldo (fail-safe) que operan los compresores por presi\xF3n de succi\xF3n cuando el controlador electr\xF3nico falla. Esto mantiene la refrigeraci\xF3n activa hasta que se repare el controlador."},{id:"ns_0310",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar la 'Eficiencia de Ruta'. \xBFQu\xE9 tecnolog\xEDa impacta m\xE1s directamente en el costo de combustible?",opciones:["Software de optimizaci\xF3n de rutas con GPS y despacho en tiempo real.","Camionetas con motores h\xEDbridos o de cuatro cilindros de alta eficiencia.","Tarjetas de cr\xE9dito corporativas que ofrecen reembolsos en gasolineras.","Capacitaci\xF3n de t\xE9cnicos en t\xE9cnicas de conducci\xF3n defensiva e inercia."],respuesta_correcta:0,explicacion:"El software de optimizaci\xF3n de rutas con GPS reduce las millas innecesarias entre llamadas, impactando directamente el costo de combustible y el tiempo no facturable."},{id:"ns_0311",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con evaporador inundado presenta burbujas en la mirilla de l\xEDquido, pero el subenfriamiento es de 12\xB0F. \xBFQu\xE9 indica?",opciones:["Restricci\xF3n en el filtro deshidratador o en la l\xEDnea de l\xEDquido previa.","Falta de refrigerante l\xEDquido para llenar el volumen total del sistema.","Gases incondensables que est\xE1n atrapados en la parte superior del visor.","Operaci\xF3n normal debido a la alta velocidad del flujo de refrigerante."],respuesta_correcta:0,explicacion:"Burbujas en el visor con subenfriamiento adecuado de 12\xB0F indican una restricci\xF3n (filtro deshidratador o l\xEDnea de l\xEDquido) que causa una ca\xEDda de presi\xF3n antes del visor, no falta de carga."},{id:"ns_0312",categoria:"NATE_SR_HVAC",pregunta:"Al analizar un gr\xE1fico psicrom\xE9trico, si aumentamos solo la temperatura de bulbo seco sin a\xF1adir humedad, \xBFqu\xE9 sucede?",opciones:["La humedad relativa disminuye mientras que la humedad absoluta permanece constante.","El punto de roc\xEDo sube proporcionalmente al incremento de la temperatura seca.","La entalp\xEDa del aire disminuye debido a la expansi\xF3n de las mol\xE9culas de vapor.","La capacidad de enfriamiento del serpent\xEDn aumenta al haber mayor diferencial."],respuesta_correcta:0,explicacion:"Al aumentar solo la temperatura de bulbo seco sin a\xF1adir humedad, la cantidad de agua en el aire (humedad absoluta) no cambia. Sin embargo, el aire m\xE1s caliente puede contener m\xE1s humedad, por lo que el porcentaje de saturaci\xF3n (humedad relativa) disminuye."},{id:"ns_0313",categoria:"NATE_SR_CEO",pregunta:"Un CEO debe responder ante una demanda por 'Mold Growth' en un edificio. \xBFQu\xE9 registro t\xE9cnico es su mejor defensa?",opciones:["Reportes de mantenimiento que prueben que la humedad relativa se mantuvo bajo el 60%.","Facturas de compra de los filtros de aire de alta eficiencia instalados en el sitio.","Certificaciones NATE vigentes de todos los t\xE9cnicos que visitaron la propiedad.","El contrato de instalaci\xF3n donde se especifica que el moho es riesgo del cliente."],respuesta_correcta:0,explicacion:"Los reportes de mantenimiento que documentan la humedad relativa bajo control (menos del 60%) son la mejor defensa legal, ya que prueban que la empresa mantuvo condiciones correctas."},{id:"ns_0314",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema Multi-split tiene todas las unidades interiores encendidas, pero solo una enfr\xEDa. \xBFCu\xE1l es el fallo l\xF3gico?",opciones:["Las v\xE1lvulas de expansi\xF3n electr\xF3nica (EEV) de las otras unidades est\xE1n cerradas.","El compresor inverter est\xE1 operando a su frecuencia m\xEDnima por un error de placa.","La carga de refrigerante es insuficiente para alimentar m\xE1s de un evaporador.","Hay una inversi\xF3n de cables de comunicaci\xF3n entre las unidades que no enfr\xEDan."],respuesta_correcta:0,explicacion:"Si solo una unidad enfr\xEDa y las dem\xE1s no, las v\xE1lvulas de expansi\xF3n electr\xF3nica (EEV) de las unidades que no enfr\xEDan est\xE1n cerradas, bloqueando el flujo de refrigerante a esos evaporadores."},{id:"ns_0315",categoria:"NATE_SR_RACK",pregunta:"En un sistema de rack, el separador de aceite est\xE1 fr\xEDo al tacto durante la operaci\xF3n. \xBFQu\xE9 significa?",opciones:["No hay flujo de gas de descarga a trav\xE9s del separador o est\xE1 puenteado.","El sistema de refrigeraci\xF3n del aceite est\xE1 funcionando con m\xE1xima eficiencia.","El refrigerante l\xEDquido est\xE1 inundando el separador por una falla en la TXV.","El nivel de aceite es tan alto que act\xFAa como un aislante t\xE9rmico interno."],respuesta_correcta:0,explicacion:"El separador de aceite est\xE1 en la l\xEDnea de descarga y deber\xEDa estar caliente durante la operaci\xF3n normal. Si est\xE1 fr\xEDo, no hay flujo de gas de descarga pasando a trav\xE9s de \xE9l, indicando que est\xE1 puenteado o la conexi\xF3n est\xE1 obstruida."},{id:"ns_0316",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de 15 toneladas presenta ciclos cortos por el interruptor de alta presi\xF3n. El condensador est\xE1 limpio. \xBFQu\xE9 sigue?",opciones:["Verificar la rotaci\xF3n de los ventiladores del condensador y el subenfriamiento.","Purgar refrigerante asumiendo que el sistema tiene una sobrecarga de f\xE1brica.","Puentear el switch de alta presi\xF3n para verificar si el compresor sigue operando.","Cambiar el filtro de aire interior para reducir la carga t\xE9rmica en el sistema."],respuesta_correcta:0,explicacion:"Con el condensador limpio pero alta presi\xF3n, se debe verificar la rotaci\xF3n correcta de los ventiladores (giro inverso mueve poco aire) y medir el subenfriamiento. Un subenfriamiento alto con alta presi\xF3n puede indicar sobrecarga de refrigerante; un subenfriamiento bajo indica falta de rechazo de calor."},{id:"ns_0317",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior detecta que el voltaje de control de 24V cae a 18V cuando el contactor cierra. \xBFDiagn\xF3stico?",opciones:["Transformador de control infradimensionado (VA insuficientes) o bobina en corto.","Ca\xEDda de voltaje en la l\xEDnea principal de 240V que afecta al transformador.","Uso de cables de control de calibre 22 en una distancia mayor a 100 pies.","El termostato digital est\xE1 consumiendo demasiada corriente para el circuito."],respuesta_correcta:0,explicacion:"Una ca\xEDda de 24V a 18V al cerrar el contactor indica que el transformador no tiene suficientes VA para la carga, o que la bobina del contactor tiene un cortocircuito parcial que consume excesiva corriente. Ambos causan ca\xEDda de voltaje de control."},{id:"ns_0318",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con R-123 (baja presi\xF3n) tiene una presi\xF3n de evaporador por encima de la atmosf\xE9rica en reposo. \xBFQu\xE9 indica?",opciones:["Que la temperatura de la sala de m\xE1quinas es superior al punto de ebullici\xF3n del gas.","Existe una fuga masiva que ha igualado las presiones con el aire exterior.","El calentador del evaporador est\xE1 fallando y no mantiene la presi\xF3n de seguridad.","Es una condici\xF3n normal ya que el R-123 siempre opera a presiones positivas."],respuesta_correcta:0,explicacion:"El R-123 tiene un punto de ebullici\xF3n de ~80\xB0F a presi\xF3n atmosf\xE9rica. Si la sala de m\xE1quinas est\xE1 por encima de esa temperatura, el refrigerante se vaporiza y la presi\xF3n del evaporador supera la atmosf\xE9rica."},{id:"ns_0319",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor tiene una succi\xF3n de 140 PSI y descarga de 350 PSI con R-410A. \xBFQu\xE9 concluye el Senior?",opciones:["La v\xE1lvula inversora est\xE1 fugando internamente (bypass de gas caliente).","El sistema est\xE1 operando perfectamente considerando un d\xEDa templado exterior.","Falta de refrigerante l\xEDquido que impide que la descarga suba a 500 PSI.","El compresor tiene las v\xE1lvulas de descarga da\xF1adas y no puede bombear."],respuesta_correcta:0,explicacion:"Succion alta (140 PSI) y descarga baja (350 PSI) con ratio de compresion reducido es sintoma clasico de fuga interna en la valvula inversora. El gas de descarga se recircula a la succion sin hacer trabajo util."},{id:"ns_0320",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere incentivar a los t\xE9cnicos a trav\xE9s de 'Revenue Sharing'. \xBFCu\xE1l es el mayor riesgo operativo?",opciones:["Priorizaci\xF3n de ventas sobre la calidad t\xE9cnica y reparaciones necesarias.","Aumento en el costo de la n\xF3mina que reduce el margen de utilidad neta.","Descontento entre los t\xE9cnicos que realizan instalaciones vs. los de servicio.","Necesidad de contratar m\xE1s contadores para calcular las comisiones exactas."],respuesta_correcta:0,explicacion:"El Revenue Sharing puede hacer que los t\xE9cnicos prioricen la venta de equipos nuevos sobre la reparaci\xF3n t\xE9cnicamente correcta, comprometiendo la calidad y la \xE9tica del servicio."},{id:"ns_0321",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, se observa que el nivel de aceite en todos los compresores baja simult\xE1neamente. \xBFCausa ra\xEDz?",opciones:["Baja velocidad del gas en las l\xEDneas de succi\xF3n que impide el retorno de aceite.","Falla en la v\xE1lvula diferencial de presi\xF3n que alimenta el dep\xF3sito de aceite.","El separador de aceite principal tiene el filtro de malla met\xE1lica roto.","Todos los compresores tienen desgaste en los anillos y consumen m\xE1s aceite."],respuesta_correcta:0,explicacion:"Cuando todos los compresores pierden aceite simult\xE1neamente, el aceite se est\xE1 acumulando en el sistema (evaporadores, condensador). La causa m\xE1s com\xFAn es baja velocidad del gas en las l\xEDneas de succi\xF3n que no puede arrastrar el aceite de vuelta."},{id:"ns_0322",categoria:"NATE_SR_HVAC",pregunta:"Un motor de soplador PSC tiene un capacitor de 5 MFD. Si el t\xE9cnico instala uno de 10 MFD, \xBFqu\xE9 sucede?",opciones:["El motor se sobrecalentar\xE1 debido al aumento excesivo del flujo de corriente.","El motor tendr\xE1 m\xE1s torque de arranque y consumir\xE1 menos energ\xEDa el\xE9ctrica.","Las RPM del motor aumentar\xE1n un 20% mejorando el flujo de aire del sistema.","El motor funcionar\xE1 de manera m\xE1s silenciosa al tener un campo magn\xE9tico fuerte."],respuesta_correcta:0,explicacion:"Instalar un capacitor del doble del valor especificado (10 MFD vs 5 MFD) genera un flujo de corriente excesivo en el devanado de arranque del motor. Esta sobrecorriente produce calor adicional que deteriora el aislamiento y causa sobrecalentamiento y falla prematura."},{id:"ns_0323",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una ca\xEDda de temperatura (Delta T) de agua helada de solo 4\xB0F (Dise\xF1o es 10\xB0F). \xBFQu\xE9 indica?",opciones:["Flujo de agua excesivo a trav\xE9s del evaporador o baja carga t\xE9rmica.","Falta de refrigerante en el chiller que impide el enfriamiento del agua.","Incrustaciones severas en los tubos que bloquean la transferencia t\xE9rmica.","La bomba de agua helada tiene el impulsor desgastado y mueve poco flujo."],respuesta_correcta:0,explicacion:"Un Delta T de 4\xB0F vs. dise\xF1o de 10\xB0F indica flujo de agua excesivo (el agua pasa demasiado r\xE1pido para enfriarse) o baja carga t\xE9rmica en el edificio que demanda menos enfriamiento."},{id:"ns_0324",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter muestra el error 'Outdoor Coil Sensor Open'. \xBFC\xF3mo afecta la operaci\xF3n?",opciones:["El sistema no entrar\xE1 en modo de deshielo o lo har\xE1 de forma err\xE1tica.","El compresor se bloquear\xE1 inmediatamente por protecci\xF3n de sobrecalentamiento.","La unidad solo funcionar\xE1 en modo de ventilaci\xF3n hasta que se repare el sensor.","El ventilador exterior girar\xE1 a la m\xE1xima velocidad sin importar la carga."],respuesta_correcta:0,explicacion:"El sensor del serpent\xEDn exterior es esencial para detectar la formaci\xF3n de escarcha y activar el ciclo de deshielo. Sin este sensor, el sistema no podr\xE1 iniciar el deshielo correctamente."},{id:"ns_0325",categoria:"NATE_SR_CEO",pregunta:"Un CEO decide expandir su empresa a 'Commercial Kitchen Refrigeration'. \xBFCu\xE1l es el desaf\xEDo principal?",opciones:["La necesidad de t\xE9cnicos disponibles 24/7 y stock de piezas multimarca.","El cumplimiento de normativas de salud relacionadas con el moho en paredes.","La baja rentabilidad de los equipos de cocina comparado con chillers industriales.","La dificultad para encontrar refrigerantes espec\xEDficos para m\xE1quinas de hielo."],respuesta_correcta:0,explicacion:"La refrigeraci\xF3n comercial de cocinas opera 24/7 y requiere t\xE9cnicos disponibles en todo momento con stock de piezas multimarca, ya que el tiempo de inactividad causa p\xE9rdidas de producto."},{id:"ns_0326",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calefacci\xF3n, una bomba de calor tiene un Delta T de 40\xB0F. \xBFQu\xE9 concluye el Senior?",opciones:["Flujo de aire interior insuficiente (filtros sucios o motor a baja velocidad).","Operaci\xF3n perfecta; un Delta T alto indica una gran transferencia de calor.","Exceso de refrigerante que est\xE1 inundando el serpent\xEDn de la unidad interior.","Las resistencias el\xE9ctricas est\xE1n encendidas simult\xE1neamente con el compresor."],respuesta_correcta:0,explicacion:"Un Delta T de 40F en modo calor es excesivamente alto. Indica flujo de aire insuficiente (filtros sucios o motor de soplador a baja velocidad), haciendo que el aire se caliente en exceso sobre el serpentin."},{id:"ns_0327",categoria:"NATE_SR_RACK",pregunta:"Se detecta presencia de aire en un sistema de rack con R-448A. \xBFQu\xE9 par\xE1metro se altera primero?",opciones:["La presi\xF3n de descarga ser\xE1 m\xE1s alta que la presi\xF3n de saturaci\xF3n del gas.","La temperatura de succi\xF3n bajar\xE1 debido a la expansi\xF3n del aire en el rack.","El aceite se volver\xE1 espumoso y el nivel en los compresores subir\xE1 de golpe.","El consumo el\xE9ctrico del rack bajar\xE1 al haber menos masa de refrigerante."],respuesta_correcta:0,explicacion:"El aire es un gas no condensable que se acumula en el condensador, sumando su presi\xF3n parcial a la del refrigerante. Esto eleva la presi\xF3n de descarga por encima de la presi\xF3n de saturaci\xF3n esperada para la temperatura del condensador."},{id:"ns_0328",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete con gas tiene una llama amarilla y ondulante. \xBFQu\xE9 peligro Senior existe?",opciones:["Producci\xF3n de mon\xF3xido de carbono (CO) por combusti\xF3n incompleta de gas.","Baja eficiencia t\xE9rmica que aumentar\xE1 la factura de gas del cliente final.","Desgaste prematuro de los quemadores por exceso de temperatura localizada.","Acumulaci\xF3n de holl\xEDn en el sensor de flama que bloquear\xE1 la ignici\xF3n."],respuesta_correcta:0,explicacion:"Una llama amarilla y ondulante indica combusti\xF3n incompleta por falta de aire primario o exceso de gas. La combusti\xF3n incompleta produce mon\xF3xido de carbono (CO), un gas letal inodoro. Este es el peligro m\xE1s grave y la prioridad absoluta para un Senior."},{id:"ns_0329",categoria:"NATE_SR_MANAGEMENT",pregunta:"Al realizar un retrofit de R-22 a R-407C, el Senior insiste en cambiar el aceite. \xBFPor qu\xE9?",opciones:["El aceite mineral no es miscible con HFC y causar\xE1 fallas de retorno de aceite.","El R-407C descompone qu\xEDmicamente el aceite mineral en pocos d\xEDas de uso.","El aceite POE es necesario para aumentar la presi\xF3n de descarga del sistema.","Las v\xE1lvulas de expansi\xF3n t\xE9rmicas solo funcionan con aceite de poliol\xE9ster."],respuesta_correcta:0,explicacion:"Los refrigerantes HFC como el R-407C no son miscibles con aceite mineral. Sin miscibilidad, el aceite no retorna al compresor y se acumula en el evaporador, causando falla de lubricaci\xF3n y eventual destrucci\xF3n del compresor. Se requiere aceite POE o AB."},{id:"ns_0330",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga autom\xE1tica que expulsa refrigerante l\xEDquido constantemente. \xBFCausa?",opciones:["Falla en la v\xE1lvula de flotador de la purga o sensor de nivel defectuoso.","La presi\xF3n del condensador es tan alta que vence la capacidad de la purga.","Infiltraci\xF3n masiva de aire que impide la separaci\xF3n correcta del gas.","El calentador de la unidad de purga est\xE1 quemado y no evapora el l\xEDquido."],respuesta_correcta:0,explicacion:"Una purga autom\xE1tica que expulsa refrigerante l\xEDquido constantemente indica falla en la v\xE1lvula de flotador que controla el nivel, o un sensor de nivel defectuoso que no separa correctamente l\xEDquido de gas."},{id:"ns_0331",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Callbacks Rate'. \xBFQu\xE9 inversi\xF3n t\xE9cnica es m\xE1s efectiva?",opciones:["Programas de capacitaci\xF3n t\xE9cnica continua y procesos de verificaci\xF3n en campo.","Comprar herramientas de diagn\xF3stico de marca premium para todos los t\xE9cnicos.","Aumentar el salario de los t\xE9cnicos para que trabajen con m\xE1s motivaci\xF3n.","Contratar a un supervisor que revise f\xEDsicamente cada trabajo terminado."],respuesta_correcta:0,explicacion:"La capacitaci\xF3n t\xE9cnica continua y los procesos de verificaci\xF3n en campo atacan la causa ra\xEDz de los callbacks: falta de conocimiento o de un procedimiento estandarizado."},{id:"ns_0332",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 105 PSI y descarga de 480 PSI con R-410A. El subenfriamiento es 25\xB0F. \xBFEstado?",opciones:["Restricci\xF3n en el dispositivo de expansi\xF3n o en el filtro deshidratador.","Exceso de carga de refrigerante que inunda el condensador del sistema.","Falta de refrigerante que impide que la succi\xF3n suba a niveles de dise\xF1o.","Falla del ventilador del condensador que eleva la presi\xF3n de descarga."],respuesta_correcta:0,explicacion:"Succi\xF3n baja (105 PSI) con descarga muy alta (480 PSI) y subenfriamiento elevado (25\xB0F) indica una restricci\xF3n que acumula l\xEDquido antes del dispositivo de expansi\xF3n. El filtro deshidratador tapado o la TXV restringida impiden el flujo, creando este patr\xF3n de presiones."},{id:"ns_0333",categoria:"NATE_SR_MINISPLIT",pregunta:"Un VRF tiene un error de 'Master/Slave Address Conflict'. \xBFC\xF3mo lo resuelve el Senior?",opciones:["Reiniciando los dip-switches de direccionamiento seg\xFAn el manual de f\xE1brica.","Cambiando el cable de comunicaci\xF3n por uno blindado en todas las unidades.","Puenteando los terminales de comunicaci\xF3n en la unidad exterior temporalmente.","Reemplazando la placa electr\xF3nica de la unidad que reporta el conflicto."],respuesta_correcta:0,explicacion:"El conflicto de direcciones Master/Slave se resuelve reiniciando los dip-switches de direccionamiento en cada unidad interior siguiendo el esquema del manual de f\xE1brica para asignar direcciones \xFAnicas."},{id:"ns_0334",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo refrigeraci\xF3n, una bomba de calor tiene un sobrecalentamiento de 30\xB0F. \xBFQu\xE9 indica?",opciones:["Baja carga de refrigerante o una TXV que est\xE1 fallando hacia cerrado.","Exceso de carga de refrigerante que inunda el serpent\xEDn del evaporador.","Operaci\xF3n normal para un d\xEDa con carga t\xE9rmica alta dentro del edificio.","Que la v\xE1lvula inversora est\xE1 permitiendo un bypass interno de gas fr\xEDo."],respuesta_correcta:0,explicacion:"Un sobrecalentamiento de 30F es muy alto (lo normal es 8-14F). Indica que el refrigerante se evapora demasiado pronto, tipicamente por falta de carga o una TXV que no abre lo suficiente."},{id:"ns_0335",categoria:"NATE_SR_RACK",pregunta:"Un rack de CO2 transcr\xEDtico tiene una presi\xF3n de salida del gas cooler de 1400 PSI. \xBFEs seguro?",opciones:["S\xED, es una presi\xF3n operativa est\xE1ndar para sistemas de CO2 transcr\xEDtico.","No, el switch de alta presi\xF3n deber\xEDa haber cortado el sistema a 1200 PSI.","Depende de si el refrigerante se encuentra por encima del punto cr\xEDtico.","Solo si la temperatura del gas a la salida es inferior a los 80 grados F."],respuesta_correcta:0,explicacion:"Los sistemas de CO2 transcr\xEDtico operan normalmente con presiones de descarga entre 1100-1450 PSI. Los componentes est\xE1n dise\xF1ados para estas presiones extremas, por lo que 1400 PSI est\xE1 dentro del rango operativo est\xE1ndar."},{id:"ns_0336",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un approach de evaporador de 8\xB0F (nominal es 2\xB0F). El Senior concluye:",opciones:["Tubos del evaporador sucios que requieren limpieza mec\xE1nica o qu\xEDmica.","El chiller tiene una sobrecarga de refrigerante que inunda el sistema.","El flujo de agua es demasiado bajo para permitir una transferencia eficiente.","Los sensores de temperatura est\xE1n descalibrados y marcan valores altos."],respuesta_correcta:0,explicacion:"Un approach de evaporador de 8\xB0F vs. nominal de 2\xB0F indica fouling en los tubos que act\xFAa como aislante t\xE9rmico, reduciendo la transferencia de calor entre el refrigerante y el agua."},{id:"ns_0337",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que no puede hacer vac\xEDo porque la bomba tira humo. \xBFQu\xE9 le dice el Senior?",opciones:["Es vapor de agua siendo evacuado; el aceite de la bomba debe cambiarse.","La bomba se est\xE1 quemando y debe ser apagada inmediatamente por seguridad.","El sistema tiene una fuga masiva que permite la entrada de aire atmosf\xE9rico.","El humo es normal cuando se evac\xFAan sistemas que usaron refrigerante R-22."],respuesta_correcta:0,explicacion:"El 'humo' de la bomba de vac\xEDo es vapor de agua que fue evacuado del sistema y contamina el aceite de la bomba. La soluci\xF3n es cambiar el aceite de la bomba (puede requerirse varias veces en sistemas muy h\xFAmedos) para restaurar su eficiencia."},{id:"ns_0338",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que el 'Account Receivable' es muy alto a m\xE1s de 90 d\xEDas. \xBFQu\xE9 riesgo hay?",opciones:["Problemas de liquidez para pagar n\xF3minas y falta de capital de trabajo.","Necesidad de aumentar los precios para compensar el dinero no cobrado.","Mejora en la relaci\xF3n con los clientes al darles plazos largos de pago.","Aumento en el valor de la empresa al tener m\xE1s facturaci\xF3n pendiente."],respuesta_correcta:0,explicacion:"Las cuentas por cobrar a m\xE1s de 90 d\xEDas representan un riesgo serio de liquidez; ese dinero no est\xE1 disponible para n\xF3minas ni capital de trabajo operativo."},{id:"ns_0339",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial tiene un Delta T de 12\xB0F y alta succi\xF3n. El compresor suena suave. \xBFCausa?",opciones:["Compresor con eficiencia volum\xE9trica baja (v\xE1lvulas internas da\xF1adas).","Falta de refrigerante l\xEDquido que no permite el enfriamiento del aire.","Exceso de flujo de aire a trav\xE9s del evaporador por un motor ECM.","V\xE1lvula de expansi\xF3n (TXV) bloqueada en la posici\xF3n de cerrado total."],respuesta_correcta:0,explicacion:"Un Delta T bajo de 12\xB0F con succi\xF3n alta y compresor silencioso indica que el compresor no puede crear suficiente diferencial de presi\xF3n. Las v\xE1lvulas internas da\xF1adas permiten que el gas recircule internamente, reduciendo la eficiencia volum\xE9trica sin ruidos mec\xE1nicos evidentes."},{id:"ns_0340",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de 20 toneladas tiene un Delta P de aceite bajo. \xBFQu\xE9 revisa el Senior?",opciones:["Presencia de refrigerante l\xEDquido en el c\xE1rter que diluye el lubricante.","Si el separador de aceite est\xE1 retornando aceite al compresor equivocado.","La presi\xF3n de descarga del rack paralelo que alimenta a la unidad paquete.","El ajuste de la v\xE1lvula EPR que podr\xEDa estar restringiendo el retorno de gas."],respuesta_correcta:0,explicacion:"La causa m\xE1s com\xFAn de Delta P de aceite bajo es la diluci\xF3n del aceite por refrigerante l\xEDquido migrado al c\xE1rter. El refrigerante l\xEDquido reduce la viscosidad del aceite, impidiendo que la bomba genere la presi\xF3n diferencial necesaria para lubricar los cojinetes del compresor."},{id:"ns_0341",categoria:"NATE_SR_CHILLERS",pregunta:"En un chiller centr\xEDfugo, \xBFcu\xE1l es la funci\xF3n de la v\xE1lvula de 'Economizador'?",opciones:["Mejorar la eficiencia mediante el enfriamiento del l\xEDquido por flash gas.","Reducir el consumo el\xE9ctrico al apagar los ventiladores del condensador.","Permitir que el compresor opere a velocidades m\xE1s bajas sin entrar en surge.","Controlar el flujo de agua helada que entra al intercambiador de calor."],respuesta_correcta:0,explicacion:"El economizador enfr\xEDa el refrigerante l\xEDquido mediante flash gas a una presi\xF3n intermedia, inyectando este gas al compresor en una etapa intermedia para mejorar la eficiencia del ciclo."},{id:"ns_0342",categoria:"NATE_SR_CEO",pregunta:"Un CEO busca implementar 'Dynamic Pricing' (Precios Din\xE1micos). \xBFCu\xE1l es la l\xF3gica?",opciones:["Ajustar los precios seg\xFAn la oferta, demanda y estacionalidad del mercado.","Cobrar lo mismo a todos los clientes para mantener la equidad del negocio.","Reducir los precios cada vez que un competidor lanza una oferta especial.","Establecer precios fijos por contrato para asegurar ingresos a largo plazo."],respuesta_correcta:0,explicacion:"El Dynamic Pricing ajusta los precios seg\xFAn la oferta, la demanda y la estacionalidad, permitiendo maximizar ingresos en temporada alta y mantener volumen en temporada baja."},{id:"ns_0343",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter se apaga por 'Communication Error'. Los voltajes son correctos. \xBFQu\xE9 revisa?",opciones:["Ruido electromagn\xE9tico (EMI) causado por falta de tierra o cables de fuerza.","La carga de refrigerante que podr\xEDa estar afectando la placa electr\xF3nica.","Si el control remoto tiene las bater\xEDas bajas y no env\xEDa la se\xF1al Wi-Fi.","El capacitor de marcha del compresor que est\xE1 interfiriendo con la se\xF1al."],respuesta_correcta:0,explicacion:"Si los voltajes de comunicaci\xF3n son correctos pero persiste el error, el ruido electromagn\xE9tico (EMI) por falta de tierra o proximidad a cables de fuerza es la causa m\xE1s probable de corrupci\xF3n de la se\xF1al."},{id:"ns_0344",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor presenta una descarga de 550 PSI con R-410A. \xBFQu\xE9 revisa?",opciones:["Filtro de aire interior sucio o flujo de aire de la manejadora muy bajo.","Condensador exterior bloqueado por hielo o falla del ciclo de deshielo.","Carga de refrigerante excesiva que est\xE1 inundando el serpent\xEDn exterior.","V\xE1lvula inversora que no logr\xF3 cambiar completamente a la posici\xF3n de calor."],respuesta_correcta:0,explicacion:"En modo calor, el serpentin interior es el condensador. Una descarga de 550 PSI indica que el condensador no puede rechazar el calor. Con filtro sucio o bajo flujo de aire interior, la presion de condensacion se eleva peligrosamente."},{id:"ns_0345",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 sucede si la v\xE1lvula de retenci\xF3n de la descarga de un compresor falla?",opciones:["El refrigerante migrar\xE1 al compresor parado, causando arranques inundados.","La presi\xF3n de succi\xF3n aumentar\xE1 en todo el sistema del rack de refrigeraci\xF3n.","El aceite se quedar\xE1 atrapado en el condensador y no regresar\xE1 al rack.","El compresor consumir\xE1 el doble de amperaje al intentar arrancar con carga."],respuesta_correcta:0,explicacion:"Sin la v\xE1lvula de retenci\xF3n, el gas de alta presi\xF3n del cabezal de descarga y el refrigerante del condensador migran hacia el compresor apagado. Al arrancar, el compresor intenta comprimir l\xEDquido, causando golpe de l\xEDquido (slugging)."},{id:"ns_0346",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Junior quiere usar sellador de fugas en un chiller de 500 toneladas. \xBFQu\xE9 dice el Senior?",opciones:["Prohibido; el sellador puede obstruir los canales de aceite y da\xF1ar cojinetes.","Adelante, siempre que sea una marca certificada por el fabricante del chiller.","Solo si la fuga es menor a 5 libras por a\xF1o seg\xFAn las normativas de la EPA.","Se debe usar el doble de la dosis recomendada debido al volumen del sistema."],respuesta_correcta:0,explicacion:"En equipos de gran tonelaje como chillers, el sellador puede obstruir los canales de lubricaci\xF3n internos, los intercambiadores de calor y da\xF1ar los cojinetes del compresor. La fuga debe localizarse y repararse mec\xE1nicamente de forma profesional."},{id:"ns_0347",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Low Oil Pressure'. El nivel de aceite es normal. \xBFQu\xE9 componente revisa?",opciones:["La bomba de aceite mec\xE1nica o el sensor diferencial de presi\xF3n de aceite.","El calentador de c\xE1rter que no est\xE1 evaporando el refrigerante del aceite.","El filtro de succi\xF3n de refrigerante que tiene una ca\xEDda de presi\xF3n alta.","La v\xE1lvula de expansi\xF3n que est\xE1 alimentando l\xEDquido al c\xE1rter del motor."],respuesta_correcta:0,explicacion:"Con nivel de aceite normal, una baja presi\xF3n de aceite apunta a la bomba de aceite mec\xE1nica que no genera presi\xF3n suficiente, o al sensor diferencial de presi\xF3n que est\xE1 enviando lecturas err\xF3neas."},{id:"ns_0348",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial tiene un 'Static Pressure' de 1.1 pulg. W.C. \xBFQu\xE9 le sucede al motor PSC?",opciones:["Bajar\xE1 sus RPM, reducir\xE1 el flujo de aire y el amperaje de consumo bajar\xE1.","Aumentar\xE1 la velocidad para compensar la presi\xF3n est\xE1tica del sistema.","Se quemar\xE1 instant\xE1neamente debido al esfuerzo mec\xE1nico de la turbina.","Consumir\xE1 m\xE1s energ\xEDa el\xE9ctrica para intentar mover el aire restringido."],respuesta_correcta:0,explicacion:"Los motores PSC son de velocidad fija determinada por la carga mec\xE1nica. Ante alta presi\xF3n est\xE1tica (restricci\xF3n), la carga sobre el motor disminuye, haciendo que las RPM bajen, el flujo de aire se reduzca y el amperaje disminuya, opuesto al comportamiento de un ECM."},{id:"ns_0349",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir el 'Customer Satisfaction'. \xBFQu\xE9 herramienta es la m\xE1s est\xE1ndar?",opciones:["Net Promoter Score (NPS) enviado tras finalizar cada orden de servicio.","Contar el n\xFAmero de me gusta en las publicaciones de Facebook de la empresa.","Verificar cu\xE1ntas veces el cliente llam\xF3 para quejarse durante el \xFAltimo a\xF1o.","El margen de utilidad de cada contrato de mantenimiento preventivo vendido."],respuesta_correcta:0,explicacion:"El Net Promoter Score (NPS) enviado despu\xE9s de cada servicio es el est\xE1ndar de la industria para medir satisfacci\xF3n del cliente de forma cuantificable y comparable."},{id:"ns_0350",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-404A y las mirillas de las vitrinas tienen burbujas. El subenfriamiento es de 15\xB0F. \xBFCausa?",opciones:["Restricci\xF3n en el filtro de la l\xEDnea de l\xEDquido o antes de la mirilla.","Falta de refrigerante l\xEDquido en el recibidor principal del sistema de rack.","El ventilador del condensador est\xE1 girando demasiado lento por un capacitor.","Operaci\xF3n normal para sistemas de rack que usan tuber\xEDas de gran longitud."],respuesta_correcta:0,explicacion:"Con 15\xB0F de subenfriamiento, hay suficiente l\xEDquido en el sistema. Las burbujas indican una ca\xEDda de presi\xF3n localizada antes de la mirilla, t\xEDpicamente causada por un filtro deshidratador saturado que genera flash gas en ese punto."},{id:"ns_0351",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una ca\xEDda de presi\xF3n de agua baja en el evaporador. \xBFC\xF3mo afecta la capacidad?",opciones:["La capacidad disminuye debido a la baja transferencia t\xE9rmica por falta de flujo.","La capacidad aumenta ya que el refrigerante tiene m\xE1s tiempo para enfriar.","No afecta la capacidad, pero el compresor consumir\xE1 m\xE1s energ\xEDa el\xE9ctrica.","El chiller entrar\xE1 en modo de ahorro de energ\xEDa autom\xE1ticamente por control."],respuesta_correcta:0,explicacion:"Una baja ca\xEDda de presi\xF3n de agua indica bajo flujo, lo que reduce la velocidad del agua y la transferencia t\xE9rmica. Con menos intercambio de calor, la capacidad de enfriamiento del chiller disminuye."},{id:"ns_0352",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no arranca y el LED parpadea 5 veces. \xBFQu\xE9 hace el Senior?",opciones:["Consultar el manual t\xE9cnico para descodificar el error espec\xEDfico del fabricante.","Resetear el breaker y esperar a que el sistema se repare solo con el tiempo.","Cambiar la placa exterior asumiendo que es una falla de comunicaci\xF3n com\xFAn.","Agregar 1 libra de refrigerante para ver si el error desaparece por presi\xF3n."],respuesta_correcta:0,explicacion:"Los patrones de parpadeo del LED son c\xF3digos de diagn\xF3stico espec\xEDficos de cada fabricante. El Senior debe consultar el manual t\xE9cnico para decodificar el error exacto antes de realizar cualquier reparaci\xF3n."},{id:"ns_0353",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene un Delta T de 25\xB0F. El Senior sospecha de bajo flujo de aire. \xBFQu\xE9 mide?",opciones:["La presi\xF3n est\xE1tica total externa (TESP) y el amperaje del motor del soplador.","La temperatura de la l\xEDnea de succi\xF3n y el sobrecalentamiento del sistema.","El subenfriamiento a la salida del condensador y la presi\xF3n de descarga.","La ca\xEDda de voltaje entre los terminales L1 y L2 del contactor del compresor."],respuesta_correcta:0,explicacion:"La TESP (presi\xF3n est\xE1tica total externa) confirma directamente si hay restricciones en el sistema de conductos, y el amperaje del motor indica si est\xE1 trabajando dentro de sus par\xE1metros. Juntas, estas dos mediciones diagnostican problemas de flujo de aire de manera precisa."},{id:"ns_0354",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir la rotaci\xF3n de t\xE9cnicos. \xBFCu\xE1l es el factor no econ\xF3mico m\xE1s valorado?",opciones:["Equilibrio entre vida laboral y personal (horarios predecibles y guardias justas).","Tener camionetas nuevas cada dos a\xF1os con logotipos de dise\xF1o profesional.","Organizar fiestas trimestrales para los empleados con asistencia obligatoria.","Recibir uniformes de marca premium con bordados personalizados cada temporada."],respuesta_correcta:0,explicacion:"El equilibrio entre vida laboral y personal (horarios predecibles y guardias justas) es el factor no econ\xF3mico m\xE1s valorado por los t\xE9cnicos, por encima de beneficios materiales."},{id:"ns_0355",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFpor qu\xE9 la TXV exterior tiene una v\xE1lvula de retenci\xF3n?",opciones:["Para permitir el flujo libre de refrigerante en modo refrigeraci\xF3n sin restricci\xF3n.","Para evitar que el aceite regrese al compresor cuando el sistema est\xE1 apagado.","Para proteger a la v\xE1lvula de expansi\xF3n de las presiones altas del modo calor.","Para asegurar que el refrigerante l\xEDquido solo fluya en una direcci\xF3n siempre."],respuesta_correcta:0,explicacion:"La check valve en paralelo con la TXV exterior permite que el refrigerante fluya libremente en modo refrigeracion (bypass a la TXV exterior), ya que en ese modo la expansion ocurre en la TXV interior."},{id:"ns_0356",categoria:"NATE_SR_RACK",pregunta:"Un rack tiene una presi\xF3n de succi\xF3n de 15 PSI con R-404A. Las vitrinas est\xE1n a 40\xB0F. \xBFProblema?",opciones:["Presi\xF3n de succi\xF3n demasiado baja para vitrinas de media temperatura (media etapa).","Funcionamiento correcto; la presi\xF3n corresponde a la temperatura del producto.","Falta de refrigerante l\xEDquido que impide que la presi\xF3n de succi\xF3n suba m\xE1s.","V\xE1lvulas de expansi\xF3n de las vitrinas que est\xE1n inyectando demasiado l\xEDquido."],respuesta_correcta:0,explicacion:"Con R-404A, 15 PSI corresponde a una temperatura de evaporaci\xF3n de aproximadamente -15\xB0F, demasiado baja para vitrinas de media temperatura a 40\xB0F. La presi\xF3n de succi\xF3n deber\xEDa estar alrededor de 45-55 PSI para esa aplicaci\xF3n."},{id:"ns_0357",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un equipo en una obra grande. Nota que no usan arneses a 10 pies. \xBFAcci\xF3n?",opciones:["Detener el trabajo inmediatamente, colocar los arneses y dar una pl\xE1tica de seguridad.","Anotar los nombres de los t\xE9cnicos y reportarlos a la oficina al final del d\xEDa.","Pedirles que tengan cuidado y que se aseguren de terminar el trabajo r\xE1pido.","Ignorar la situaci\xF3n si el cliente no est\xE1 presente en el sitio de la obra hoy."],respuesta_correcta:0,explicacion:"OSHA requiere protecci\xF3n contra ca\xEDdas a partir de 6 pies en construcci\xF3n. A 10 pies, el incumplimiento es una violaci\xF3n grave. El l\xEDder debe detener el trabajo inmediatamente (stop work authority), corregir la situaci\xF3n y reforzar la seguridad."},{id:"ns_0358",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con condensador de aire tiene un ventilador que vibra. \xBFQu\xE9 da\xF1o Senior previene?",opciones:["Falla por fatiga del serpent\xEDn de aluminio y p\xE9rdida de refrigerante masiva.","Aumento en el consumo el\xE9ctrico del motor del ventilador por desequilibrio.","Reducci\xF3n de la vida \xFAtil de los rodamientos del compresor de tornillo.","Falsas alarmas de alta presi\xF3n de condensaci\xF3n en el controlador central."],respuesta_correcta:0,explicacion:"La vibraci\xF3n de un ventilador del condensador enfriado por aire puede causar fatiga mec\xE1nica en las conexiones del serpent\xEDn de aluminio, resultando en grietas y p\xE9rdida masiva de refrigerante."},{id:"ns_0359",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial tiene una succi\xF3n de 115 PSI y descarga de 450 PSI con R-410A. \xBFC\xF3mo est\xE1?",opciones:["Restricci\xF3n en el lado de alta o condensador extremadamente sucio.","Funcionamiento normal para un d\xEDa caluroso con carga t\xE9rmica est\xE1ndar.","Falta de refrigerante l\xEDquido que impide que la descarga baje a 300.","Compresor con eficiencia reducida que no puede bombear correctamente."],respuesta_correcta:0,explicacion:"Con R-410A, succi\xF3n de 115 PSI (~36\xB0F sat.) con descarga de 450 PSI (~120\xB0F sat.) muestra una descarga anormalmente alta. Esto indica una restricci\xF3n en el lado de alta, como un condensador sucio que no disipa calor, elevando la presi\xF3n de descarga."},{id:"ns_0360",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere aumentar el 'Customer Lifetime Value'. \xBFQu\xE9 estrategia lanza?",opciones:["Contratos de mantenimiento preventivo con beneficios exclusivos y descuentos.","Aumentar los precios de instalaci\xF3n para maximizar la ganancia del primer d\xEDa.","Eliminar el departamento de servicio para enfocarse solo en ventas de equipos.","Reducir la garant\xEDa de mano de obra a 30 d\xEDas para evitar gastos futuros."],respuesta_correcta:0,explicacion:"Los contratos de mantenimiento preventivo con beneficios exclusivos retienen al cliente por a\xF1os, generando m\xFAltiples transacciones y maximizando el Customer Lifetime Value."},{id:"ns_0361",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se instalan v\xE1lvulas solenoide en la l\xEDnea de l\xEDquido de cada vitrina?",opciones:["Para controlar la temperatura de la vitrina mediante el corte del flujo de l\xEDquido.","Para evitar que el aceite se acumule en el evaporador durante el funcionamiento.","Para aumentar el subenfriamiento del refrigerante antes de entrar a la TXV.","Para proteger al compresor de un posible retorno de l\xEDquido en el arranque."],respuesta_correcta:0,explicacion:"La v\xE1lvula solenoide de l\xEDquido permite controlar la temperatura de cada vitrina individualmente. Cuando la vitrina alcanza la temperatura deseada, la solenoide corta el flujo de refrigerante, implementando un control por pump-down del circuito."},{id:"ns_0362",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Low Evaporator Temp' constante. \xBFQu\xE9 revisa el Senior?",opciones:["Flujo de agua helada insuficiente o sensor de temperatura mal ubicado.","Carga de refrigerante excesiva que est\xE1 inundando el intercambiador.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total.","Si la torre de enfriamiento est\xE1 enviando agua demasiado fr\xEDa al condensador."],respuesta_correcta:0,explicacion:"Una falla constante de baja temperatura del evaporador indica flujo de agua insuficiente (el agua se enfr\xEDa demasiado) o un sensor de temperatura mal ubicado que lee valores incorrectos."},{id:"ns_0363",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter muestra el error 'H6' (Indoor Fan Motor error). \xBFQu\xE9 prueba?",opciones:["Si el ventilador gira libremente y la se\xF1al de voltaje de la placa interior.","El capacitor de arranque del motor del ventilador de la unidad exterior.","La carga de refrigerante que podr\xEDa estar bloqueando el flujo de aire interior.","La continuidad de los cables de comunicaci\xF3n entre la unidad interior y exterior."],respuesta_correcta:0,explicacion:"El error H6 indica fallo del motor del ventilador interior. El Senior verifica que el ventilador gire libremente (sin obstrucci\xF3n) y mide el voltaje que la placa interior env\xEDa al motor DC."},{id:"ns_0364",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, el ciclo de deshielo dura el tiempo m\xE1ximo y no quita el hielo. \xBFCausa?",opciones:["El ventilador exterior no se detuvo o la v\xE1lvula inversora no cambi\xF3 a fr\xEDo.","La carga de refrigerante es demasiado alta y el serpent\xEDn no se calienta.","Las resistencias el\xE9ctricas no encendieron durante el proceso de descongelado.","El sensor de temperatura de deshielo est\xE1 ubicado en la l\xEDnea de succi\xF3n."],respuesta_correcta:0,explicacion:"Para un deshielo efectivo, el ventilador exterior debe detenerse y la valvula inversora debe cambiar a modo refrigeracion para enviar gas caliente al serpentin exterior. Si alguno falla, el hielo no se derrite."},{id:"ns_0365",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que el 'Direct Labor Cost' es el 40% de los ingresos. \xBFC\xF3mo lo interpreta?",opciones:["Es un costo alto que indica ineficiencia operativa o falta de facturaci\xF3n.","Es un porcentaje excelente que asegura una rentabilidad neta superior al 20%.","Indica que los t\xE9cnicos est\xE1n vendiendo muchos accesorios y planes de servicio.","Es un valor irrelevante si el margen bruto de los materiales es superior al 50%."],respuesta_correcta:0,explicacion:"Un Direct Labor Cost del 40% es alto para la industria HVAC (ideal: 25-30%); indica que los t\xE9cnicos est\xE1n poco ocupados o que los precios de venta son insuficientes."},{id:"ns_0366",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-404A. Se detecta una fuga \xE1cida. \xBFQu\xE9 acci\xF3n t\xE9cnica es mandatoria?",opciones:["Cambiar el aceite, instalar filtros de succi\xF3n de limpieza y neutralizadores.","Simplemente reparar la fuga y completar la carga con refrigerante virgen.","Drenar el refrigerante y cargarlo de nuevo tras hacer un vac\xEDo de 24 horas.","Agregar un aditivo sellador de fugas que tambi\xE9n neutralice la acidez del POE."],respuesta_correcta:0,explicacion:"La acidez en el sistema indica descomposici\xF3n del aceite o contaminaci\xF3n. Es mandatorio cambiar el aceite contaminado, instalar filtros de succi\xF3n de limpieza (burnout filters) y neutralizadores de \xE1cido para remover los contaminantes y proteger los compresores."},{id:"ns_0367",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que no tiene la herramienta para medir micrones. \xBFQu\xE9 hace el Senior?",opciones:["Prohibir que termine el vac\xEDo y enviarle un vacu\xF3metro digital de inmediato.","Decirle que deje la bomba encendida por 4 horas y asuma que est\xE1 a 500.","Pedirle que use el man\xF3metro anal\xF3gico y vea si la aguja baja del cero.","Sugiere que use un poco de refrigerante para barrer la humedad del sistema."],respuesta_correcta:0,explicacion:"Sin un vacu\xF3metro digital (micron gauge) es imposible verificar que el sistema alcanz\xF3 500 micrones o menos. Asumir el vac\xEDo sin medirlo es una pr\xE1ctica irresponsable que puede dejar humedad en el sistema y causar fallas prematuras."},{id:"ns_0368",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una aproximaci\xF3n de evaporador de 0\xB0F. \xBFQu\xE9 sospecha el Senior?",opciones:["Falla de calibraci\xF3n del transductor de presi\xF3n o del sensor de temperatura.","El chiller est\xE1 operando en el punto de dise\xF1o perfecto del fabricante.","El flujo de agua es tan alto que no permite que el refrigerante se evapore.","El compresor centr\xEDfugo est\xE1 operando a su m\xE1xima velocidad de rotaci\xF3n."],respuesta_correcta:0,explicacion:"Un approach de evaporador de 0\xB0F es termodin\xE1micamente improbable. Indica falla de calibraci\xF3n en el transductor de presi\xF3n o sensor de temperatura que genera lecturas inconsistentes."},{id:"ns_0369",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 125 PSI y descarga de 380 PSI con R-410A. El subenfriamiento es 5\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido en el sistema (undercharged).","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total.","Condensador exterior sucio que no permite el intercambio t\xE9rmico.","Evaporador interior congelado que restringe la absorci\xF3n de calor."],respuesta_correcta:0,explicacion:"Un subenfriamiento de solo 5\xB0F con R-410A indica que el condensador no tiene suficiente l\xEDquido para subenfriarlo adecuadamente. Esto es se\xF1al cl\xE1sica de falta de carga (undercharged), donde no hay suficiente refrigerante para llenar completamente el condensador."},{id:"ns_0370",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete, el serpent\xEDn del evaporador se congela. El ventilador funciona bien. \xBFSiguiente paso?",opciones:["Verificar la carga de refrigerante y si la TXV est\xE1 operando correctamente.","Instalar un termostato de descongelaci\xF3n para que pare el compresor.","Reemplazar el motor del soplador por uno de mayor caballaje total.","Agregar refrigerante hasta que la presi\xF3n de succi\xF3n suba a 140 PSI."],respuesta_correcta:0,explicacion:"Con el ventilador funcionando correctamente, la congelaci\xF3n se debe a una temperatura de evaporaci\xF3n demasiado baja. Esto ocurre por carga baja de refrigerante o una TXV que restringe el flujo. Verificar ambas condiciones permite identificar la causa ra\xEDz antes de actuar."},{id:"ns_0371",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la 'Productividad T\xE9cnica'. \xBFCu\xE1l es la f\xF3rmula correcta?",opciones:["Horas facturadas al cliente divididas entre las horas totales pagadas al t\xE9cnico.","Ingresos totales del mes divididos entre el n\xFAmero de t\xE9cnicos en la n\xF3mina.","Cantidad de reparaciones terminadas dividida entre el costo de los materiales.","N\xFAmero de millas recorridas divididas entre el n\xFAmero de llamadas de servicio."],respuesta_correcta:0,explicacion:"La Productividad T\xE9cnica se calcula dividiendo las horas facturadas al cliente entre las horas totales pagadas, mostrando qu\xE9 porcentaje del tiempo genera ingresos directos."},{id:"ns_0372",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si la v\xE1lvula de bypass de gas caliente falla abierta?",opciones:["La presi\xF3n de succi\xF3n subir\xE1 y los compresores se sobrecalentar\xE1n r\xE1pido.","El rack se bloquear\xE1 por baja presi\xF3n al no retornar gas a la succi\xF3n.","El nivel de aceite en el separador bajar\xE1 dr\xE1sticamente de forma continua.","Las vitrinas se congelar\xE1n debido al exceso de calor en el evaporador."],respuesta_correcta:0,explicacion:"Con la v\xE1lvula de bypass abierta permanentemente, gas caliente de descarga recircula directamente a la succi\xF3n, elevando la presi\xF3n y temperatura. Los compresores trabajan recirculando gas caliente sin enfriar, sobrecalent\xE1ndose r\xE1pidamente."},{id:"ns_0373",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un approach de condensador de 15\xB0F. \xBFQu\xE9 acci\xF3n toma el Senior?",opciones:["Limpieza de tubos del condensador y verificar el tratamiento de agua de torre.","Agregar m\xE1s refrigerante l\xEDquido para bajar la temperatura de aproximaci\xF3n.","Aumentar el set-point de la temperatura del agua de la torre a 90 grados.","Reducir la velocidad de la bomba de condensador para estabilizar el flujo."],respuesta_correcta:0,explicacion:"Un approach de condensador de 15\xB0F indica fouling severo en los tubos. La limpieza mec\xE1nica y la verificaci\xF3n del tratamiento qu\xEDmico del agua de torre son las acciones correctivas prioritarias."},{id:"ns_0374",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no enfr\xEDa. Al medir voltaje entre S1 y S2 hay 240VAC. \xBFConclusi\xF3n?",opciones:["La alimentaci\xF3n el\xE9ctrica de la unidad exterior es correcta.","Hay una falla de comunicaci\xF3n masiva entre las dos unidades.","El fusible de la placa electr\xF3nica exterior est\xE1 fundido.","El compresor inverter est\xE1 aterrizado y consume voltaje."],respuesta_correcta:0,explicacion:"Un voltaje de 240VAC entre S1 y S2 confirma que la alimentaci\xF3n el\xE9ctrica llega correctamente a la unidad exterior. El problema de enfriamiento debe buscarse en otra parte del sistema."},{id:"ns_0375",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFcu\xE1l es el prop\xF3sito del 'Accumulator'?",opciones:["Evitar que el refrigerante l\xEDquido entre al compresor y lo da\xF1e mec\xE1nicamente.","Almacenar el exceso de aceite del sistema durante el modo de calefacci\xF3n.","Aumentar la presi\xF3n de succi\xF3n mediante el recalentamiento del gas fr\xEDo.","Separar los incondensables del refrigerante antes de entrar a la descarga."],respuesta_correcta:0,explicacion:"El acumulador de succion es un tanque antes del compresor que atrapa refrigerante liquido, permitiendo que solo vapor entre al compresor. Protege contra slugging (golpe de liquido) que danaria las valvulas o scrolls."},{id:"ns_0376",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un cliente se queja de un olor a quemado tras un mantenimiento. \xBFQu\xE9 debe hacer el Senior?",opciones:["Regresar al sitio inmediatamente, inspeccionar cables y motores por seguridad.","Decirle al cliente que es normal que los aceites de limpieza huelan as\xED.","Pedirle al cliente que apague el sistema y que llame en 24 horas si sigue el olor.","Preguntar al t\xE9cnico que realiz\xF3 el trabajo si dej\xF3 algo mal conectado ayer."],respuesta_correcta:0,explicacion:"Un olor a quemado despu\xE9s de un mantenimiento puede indicar un cable suelto, un motor trabado o un componente el\xE9ctrico fallando. Es una emergencia potencial que requiere inspecci\xF3n inmediata para prevenir incendios o da\xF1os mayores."},{id:"ns_0377",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Pumping' o 'Surge'. \xBFC\xF3mo se ajusta operativamente?",opciones:["Bajando la presi\xF3n de descarga o aumentando el flujo de gas por el impulsor.","Incrementando la velocidad de la bomba de agua helada del edificio.","Cerrando la v\xE1lvula de expansi\xF3n para reducir la masa de refrigerante.","Aumentando la temperatura del agua de la torre para subir la descarga."],respuesta_correcta:0,explicacion:"El surge se corrige reduciendo la relaci\xF3n de presiones (lift). Bajar la presi\xF3n de descarga (limpiar condensador, mejorar agua de torre) o aumentar el flujo de gas por el impulsor estabiliza la operaci\xF3n."},{id:"ns_0378",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial tiene una succi\xF3n de 145 PSI y descarga de 380 PSI. El sobrecalentamiento es 0\xB0F. \xBFCausa?",opciones:["V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total.","Falta de refrigerante l\xEDquido que impide que la descarga suba m\xE1s.","Evaporador interior con flujo de aire extremadamente alto (motor ECM).","Compresor perdiendo eficiencia volum\xE9trica por desgaste de pistones."],respuesta_correcta:0,explicacion:"Succi\xF3n alta de 145 PSI con sobrecalentamiento de 0\xB0F significa que el evaporador est\xE1 completamente inundado de l\xEDquido y el refrigerante no se evapora totalmente. Una TXV fallida en posici\xF3n abierta permite el paso descontrolado de l\xEDquido, causando flood-back al compresor."},{id:"ns_0379",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere expandirse a 'Industrial Chillers'. \xBFQu\xE9 inversi\xF3n es la m\xE1s cr\xEDtica?",opciones:["Equipos de izaje pesados, herramientas l\xE1ser de alineaci\xF3n y t\xE9cnicos Senior.","Comprar una flota de camionetas peque\xF1as para facilitar el estacionamiento.","Invertir en publicidad en redes sociales enfocada en clientes residenciales.","Contratar a m\xE1s personal de ventas para vender planes de mantenimiento b\xE1sicos."],respuesta_correcta:0,explicacion:"Los chillers industriales requieren equipos de izaje pesado, herramientas de alineaci\xF3n l\xE1ser y t\xE9cnicos Senior con experiencia en sistemas de alta capacidad y complejidad."},{id:"ns_0380",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 sucede si la v\xE1lvula de retenci\xF3n del separador de aceite falla abierta?",opciones:["El aceite y gas de descarga regresar\xE1n a los compresores durante el paro.","La presi\xF3n de succi\xF3n bajar\xE1 tanto que el rack se bloquear\xE1 por seguridad.","El nivel de aceite en el dep\xF3sito subir\xE1 por encima de la mirilla superior.","Las vitrinas dejar\xE1n de enfriar debido a la falta de diferencial de presi\xF3n."],respuesta_correcta:0,explicacion:"La v\xE1lvula check del separador evita el flujo inverso durante el paro. Si falla abierta, el gas de alta presi\xF3n y el aceite del dep\xF3sito pueden regresar hacia los compresores, causando migraci\xF3n de refrigerante e inundaci\xF3n de los c\xE1rteres."},{id:"ns_0381",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Unbalance' del 4%. \xBFQu\xE9 riesgo t\xE9cnico existe?",opciones:["Sobrecalentamiento excesivo del motor del compresor y fallo prematuro.","El chiller funcionar\xE1 al 96% de su capacidad nominal sin riesgo alguno.","La unidad de purga empezar\xE1 a operar para compensar el desequilibrio.","La v\xE1lvula de expansi\xF3n se cerrar\xE1 para proteger el circuito el\xE9ctrico."],respuesta_correcta:0,explicacion:"Un desbalance de voltaje del 4% puede causar un aumento de corriente de hasta 25% en una fase del motor, generando sobrecalentamiento excesivo y reducci\xF3n dr\xE1stica de la vida \xFAtil del motor."},{id:"ns_0382",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua por la unidad interior. El drenaje est\xE1 libre. \xBFCausa?",opciones:["Carga de refrigerante baja que causa escarcha parcial y goteo fuera de bandeja.","La bomba de condensado integrada tiene el flotador pegado en posici\xF3n alta.","El ventilador interior est\xE1 girando tan r\xE1pido que succiona el agua del serpent\xEDn.","La humedad relativa de la habitaci\xF3n es superior al 95% y condensa en chasis."],respuesta_correcta:0,explicacion:"Con el drenaje libre, una carga baja de refrigerante causa escarcha parcial e irregular en el serpent\xEDn. Al derretirse, el agua cae fuera de la bandeja de condensado, goteando dentro de la habitaci\xF3n."},{id:"ns_0383",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de retorno de 0.6 pulg. W.C. El dise\xF1o es 0.2. \xBFConsecuencia?",opciones:["Ruido excesivo, bajo flujo de aire y posible falla del motor del soplador.","Aumento en la eficiencia del intercambio de calor por la velocidad del aire.","Menor consumo el\xE9ctrico del motor al tener una restricci\xF3n en la succi\xF3n.","Mejora en la deshumidificaci\xF3n del ambiente al pasar el aire m\xE1s lento."],respuesta_correcta:0,explicacion:'Una presi\xF3n est\xE1tica de retorno de 0.6" W.C. cuando el dise\xF1o es 0.2" representa el triple de la restricci\xF3n permitida. Esto causa ruido por turbulencia, reducci\xF3n severa del flujo de aire, y estr\xE9s mec\xE1nico y el\xE9ctrico sobre el motor del soplador que puede provocar su falla.'},{id:"ns_0384",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el 'Check Valve' de la unidad interior falla abierta?",opciones:["En modo refrigeraci\xF3n, el refrigerante har\xE1 bypass a la TXV y no enfriar\xE1.","En modo calefacci\xF3n, el sistema se bloquear\xE1 por alta presi\xF3n de descarga.","El aceite se quedar\xE1 atrapado en el evaporador y el compresor fallar\xE1.","La v\xE1lvula inversora no podr\xE1 cambiar de posici\xF3n por falta de diferencial."],respuesta_correcta:0,explicacion:"La check valve interior esta en paralelo con la TXV interior. Si falla abierta, en modo refrigeracion el refrigerante hace bypass a la TXV y fluye sin restriccion, eliminando la caida de presion necesaria para enfriar."},{id:"ns_0385",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior observa que un Junior no usa 'Brazing Shield' al soldar. \xBFRiesgo?",opciones:["Da\xF1o t\xE9rmico a componentes sensibles como v\xE1lvulas o aislamiento de cables.","Que la soldadura de plata no se adhiera correctamente por falta de calor.","Aumento del consumo de ox\xEDgeno y acetileno durante el proceso de soldadura.","La formaci\xF3n de \xF3xido en la superficie externa de la tuber\xEDa de cobre."],respuesta_correcta:0,explicacion:"El brazing shield protege componentes cercanos del calor radiante de la antorcha. Sin \xE9l, v\xE1lvulas, aislamiento de cables el\xE9ctricos y otros componentes sensibles al calor pueden da\xF1arse irreversiblemente durante la soldadura."},{id:"ns_0386",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de temperatura de 'Leaving Water' descalibrado (marca menos). \xBFRiesgo?",opciones:["Congelaci\xF3n de los tubos del evaporador debido a un set-point real bajo.","El compresor se apagar\xE1 por alta presi\xF3n antes de alcanzar la temperatura.","La unidad de purga operar\xE1 innecesariamente expulsando gas al ambiente.","Aumento en el consumo de energ\xEDa el\xE9ctrica por ciclos de carga excesivos."],respuesta_correcta:0,explicacion:"Si el sensor de leaving water marca menos de lo real, el controlador cree que el agua est\xE1 m\xE1s fr\xEDa y sigue enfriando. Esto baja la temperatura real por debajo del dise\xF1o, arriesgando congelaci\xF3n de tubos."},{id:"ns_0387",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 indica una temperatura de descarga de 250\xB0F constante?",opciones:["Problema grave de sobrecalentamiento de succi\xF3n o falla interna del compresor.","Operaci\xF3n normal para un rack que usa R-404A en condiciones de carga alta.","Que el enfriador de aceite del rack paralelo est\xE1 funcionando perfectamente.","Falta de refrigerante l\xEDquido en el recibidor que impide el enfriamiento."],respuesta_correcta:0,explicacion:"Para R-404A, la temperatura de descarga normal es de 150-200\xB0F. Una temperatura constante de 250\xB0F indica un sobrecalentamiento de succi\xF3n severo o v\xE1lvulas de plato da\xF1adas en el compresor, requiriendo atenci\xF3n inmediata."},{id:"ns_0388",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere aumentar el 'Referral Rate'. \xBFQu\xE9 acci\xF3n es la m\xE1s efectiva?",opciones:["Ofrecer una recompensa o descuento tanto al que refiere como al nuevo cliente.","Pagar por anuncios en el peri\xF3dico local para que la gente conozca la marca.","Reducir el precio de todos los servicios para que los clientes hablen bien.","Contratar a un vendedor de puerta en puerta para buscar clientes referidos."],respuesta_correcta:0,explicacion:"Un programa de referidos que recompensa tanto al cliente que refiere como al nuevo cliente crea un incentivo bilateral que multiplica las recomendaciones de forma org\xE1nica."},{id:"ns_0389",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta una vibraci\xF3n en la frecuencia de paso de \xE1labes. \xBFCausa?",opciones:["Alineaci\xF3n incorrecta del impulsor o flujo de gas turbulento en la entrada.","Desgaste natural de los cojinetes de rodillos del motor de alta velocidad.","Falta de aceite en el sistema de lubricaci\xF3n por inyecci\xF3n del compresor.","El variador de frecuencia est\xE1 generando arm\xF3nicos que afectan al motor."],respuesta_correcta:0,explicacion:"La vibraci\xF3n en la frecuencia de paso de \xE1labes (blade pass frequency) indica una alineaci\xF3n incorrecta del impulsor o flujo turbulento en la entrada que genera pulsaciones a la frecuencia de los \xE1labes."},{id:"ns_0390",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 420 PSI. El aire sale a 65\xB0F. \xBFProblema?",opciones:["Bajo flujo de aire o carga de refrigerante ligeramente baja.","Funcionamiento normal considerando la temperatura exterior de 100 grados.","Exceso de carga de refrigerante que inunda el serpent\xEDn del condensador.","Compresor con v\xE1lvulas da\xF1adas que no logran enfriar el aire de suministro."],respuesta_correcta:0,explicacion:"Temperatura de suministro de 65\xB0F es alta (deber\xEDa ser ~55\xB0F), y la descarga de 420 PSI es elevada con succi\xF3n de 110 PSI. Bajo flujo de aire o falta leve de carga explican por qu\xE9 el evaporador no enfr\xEDa el aire suficientemente mientras la descarga est\xE1 elevada."},{id:"ns_0391",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar el 'Profit Margin' de las reparaciones. \xBFQu\xE9 debe auditar?",opciones:["El 'Mark-up' aplicado a las piezas de repuesto y el tiempo de mano de obra.","El costo del alquiler de la oficina administrativa central de la empresa.","La cantidad de uniformes que se compran para los t\xE9cnicos nuevos cada a\xF1o.","El n\xFAmero de seguidores que interact\xFAan con la marca en redes sociales."],respuesta_correcta:0,explicacion:"Para mejorar el margen de reparaciones, el CEO debe auditar el mark-up aplicado a piezas y el tiempo de mano de obra cobrado, ya que son los dos componentes directos del precio."},{id:"ns_0392",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no enfr\xEDa. El compresor exterior no arranca pero el ventilador s\xED. \xBFPrueba?",opciones:["Medir resistencia de las bobinas del compresor y voltaje DC de la placa.","Cambiar el capacitor de arranque por uno de mayor capacidad inmediatamente.","Puentear el interruptor de alta presi\xF3n para ver si el compresor enciende.","Agregar 2 libras de refrigerante R-410A para descartar una fuga total."],respuesta_correcta:0,explicacion:"Cuando el ventilador exterior funciona pero el compresor no arranca, el Senior mide la resistencia de las bobinas U, V, W del compresor y el voltaje DC que la placa IPM env\xEDa al motor para aislar la falla."},{id:"ns_0393",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el sensor de temperatura exterior falla en corto?",opciones:["El sistema podr\xEDa bloquear la calefacci\xF3n auxiliar o el ciclo de deshielo.","El compresor se quemar\xE1 debido a la falta de control de sobrecalentamiento.","La unidad operar\xE1 solo en modo refrigeraci\xF3n permanentemente por seguridad.","El ventilador exterior girar\xE1 en sentido contrario para proteger el serpent\xEDn."],respuesta_correcta:0,explicacion:"Si el sensor de temperatura exterior falla en corto (lee como muy caliente), el sistema podria bloquear la calefaccion auxiliar y no iniciar el defrost, creyendo que no hay condiciones de congelamiento."},{id:"ns_0394",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFpor qu\xE9 se usa una v\xE1lvula 'Check' en la succi\xF3n de cada compresor?",opciones:["Para evitar que el aceite y refrigerante migren al compresor que est\xE1 apagado.","Para aumentar la presi\xF3n de succi\xF3n y mejorar la eficiencia del sistema total.","Para permitir que los compresores arranquen sin carga durante los deshielos.","Para proteger al separador de aceite de las pulsaciones de gas de la succi\xF3n."],respuesta_correcta:0,explicacion:"La v\xE1lvula check en la succi\xF3n previene la migraci\xF3n de aceite y refrigerante hacia un compresor apagado a trav\xE9s del cabezal de succi\xF3n com\xFAn. Sin ella, el refrigerante se condensa en el c\xE1rter fr\xEDo del compresor parado."},{id:"ns_0395",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un plano donde el retorno de aire est\xE1 en la cocina. \xBFQu\xE9 hace?",opciones:["Solicita el cambio de ubicaci\xF3n del retorno para evitar olores y grasa en el equipo.","Instala el retorno en la cocina pero a\xF1ade un filtro de carb\xF3n activado extra.","Sigue el plano del arquitecto para no tener problemas de dise\xF1o legal despu\xE9s.","No hace nada, ya que la cocina es el lugar donde m\xE1s calor se genera siempre."],respuesta_correcta:0,explicacion:"Un retorno de aire en la cocina absorbe grasa, olores y humedad que contaminar\xE1n el serpent\xEDn del evaporador y se distribuir\xE1n por toda la casa. Es un error de dise\xF1o grave que debe corregirse reubicando el retorno."},{id:"ns_0396",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Water Flow' intermitente. El filtro est\xE1 limpio. \xBFQu\xE9 revisa?",opciones:["El interruptor de flujo (Paddle switch) o el transductor diferencial de presi\xF3n.","La velocidad del motor del compresor centr\xEDfugo en el panel de control.","Si la v\xE1lvula de expansi\xF3n electr\xF3nica est\xE1 inyectando l\xEDquido al sistema.","La carga de refrigerante l\xEDquido bas\xE1ndose en la mirilla del evaporador."],respuesta_correcta:0,explicacion:"Una falla intermitente de flujo de agua con filtro limpio apunta al interruptor de flujo (paddle switch) desgastado o al transductor diferencial de presi\xF3n descalibrado que genera falsas alarmas."},{id:"ns_0397",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 120 PSI y descarga de 410 PSI. El subenfriamiento es 10\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y subenfriamiento son los correctos.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser de 15 grados.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno.","Compresor fallando; el diferencial de presi\xF3n es insuficiente para enfriar."],respuesta_correcta:0,explicacion:"Con R-410A, succi\xF3n de 120 PSI (~38\xB0F sat.), descarga de 410 PSI (~112\xB0F sat.) y subenfriamiento de 10\xB0F est\xE1n dentro de rangos aceptables para operaci\xF3n en un d\xEDa moderadamente caluroso. El sistema funciona correctamente con carga de refrigerante adecuada."},{id:"ns_0398",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete, el motor del soplador consume m\xE1s amperaje del de placa. \xBFCausa?",opciones:["Presi\xF3n est\xE1tica del sistema muy baja (conductos abiertos o filtros faltantes).","Filtros de aire extremadamente sucios que restringen el flujo de aire total.","El motor es del tipo ECM y est\xE1 compensando la suciedad del serpent\xEDn.","Las rejillas de suministro est\xE1n cerradas, aumentando la contrapresi\xF3n interna."],respuesta_correcta:0,explicacion:"Un motor PSC consume m\xE1s amperaje con menor restricci\xF3n (presi\xF3n est\xE1tica baja). Sin filtros o con conductos abiertos/desconectados, el motor mueve m\xE1s aire del dise\xF1ado, lo que aumenta la carga en el eje y el consumo el\xE9ctrico por encima del amperaje de placa."},{id:"ns_0399",categoria:"NATE_SR_CEO",pregunta:"Un CEO debe asegurar que su empresa cumpla con la ley OSHA 1910.1200. \xBFQu\xE9 regula?",opciones:["La comunicaci\xF3n de peligros y el manejo de hojas de datos de seguridad (SDS).","El pago de horas extras y beneficios sociales a los empleados de campo.","La certificaci\xF3n de los recipientes de recuperaci\xF3n de gas refrigerante.","El uso obligatorio de uniformes ign\xEDfugos en todas las instalaciones HVAC."],respuesta_correcta:0,explicacion:"OSHA 1910.1200 (HazCom) regula la comunicaci\xF3n de peligros qu\xEDmicos y exige que la empresa tenga hojas de datos de seguridad (SDS) accesibles para todos los empleados."},{id:"ns_0400",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-407A y tiene una fuga en la l\xEDnea de l\xEDquido. El t\xE9cnico quiere completar carga. \xBFRiesgo?",opciones:["Fraccionamiento de la mezcla; la eficiencia y presiones ser\xE1n incorrectas.","El refrigerante se volver\xE1 inflamable al perder uno de sus componentes gaseosos.","El aceite se separar\xE1 del refrigerante y los compresores se bloquear\xE1n pronto.","No hay riesgo; el R-407A es una mezcla azeotr\xF3pica que no se fracciona."],respuesta_correcta:0,explicacion:"El R-407A es una mezcla zeotr\xF3pica (no azeotr\xF3pica) con un glide significativo. Durante una fuga, los componentes m\xE1s vol\xE1tiles escapan primero, alterando la composici\xF3n. Completar la carga no restaura la proporci\xF3n original; se debe recuperar y recargar."},{id:"ns_0401",categoria:"NATE_SR_PACKAGE",pregunta:"En un sistema de enfriamiento para Data Center (CRAC), se observa que el calor sensible es muy alto pero la humedad relativa cae al 20%. \xBFQu\xE9 acci\xF3n debe tomar el Senior?",opciones:["Activar el sistema de humidificaci\xF3n y verificar el sellado del piso falso.","Aumentar el flujo de aire del soplador para reducir la temperatura de salida.","Reducir la carga de refrigerante para permitir que el serpent\xEDn deshumidifique menos.","Instalar un variador de frecuencia en el compresor para modular la capacidad t\xE9rmica."],respuesta_correcta:0,explicacion:"En Data Centers, la humedad relativa baja (20%) crea riesgo de descarga electrost\xE1tica que puede da\xF1ar servidores. Se debe activar la humidificaci\xF3n integrada del CRAC y verificar el sellado del piso falso, ya que fugas de aire permiten la p\xE9rdida de humedad controlada."},{id:"ns_0402",categoria:"NATE_SR_RACK",pregunta:"Se detecta que un rack paralelo tiene una presi\xF3n de succi\xF3n superior a la de saturaci\xF3n de todas las vitrinas conectadas. \xBFQu\xE9 indica este fen\xF3meno?",opciones:["Falla en el controlador del rack o compresores insuficientes para la carga actual.","Las v\xE1lvulas EPR est\xE1n todas cerradas bloqueando el retorno de gas al cabezal.","Existe una fuga masiva de refrigerante en el lado de alta presi\xF3n del sistema.","El separador de aceite est\xE1 inundado y devuelve l\xEDquido a la l\xEDnea de succi\xF3n."],respuesta_correcta:0,explicacion:"Si la presi\xF3n de succi\xF3n es m\xE1s alta que la saturaci\xF3n de las vitrinas, los compresores no est\xE1n removiendo suficiente gas. Esto indica que el controlador no est\xE1 activando suficientes compresores, o los compresores no tienen capacidad para manejar la carga t\xE9rmica."},{id:"ns_0403",categoria:"NATE_SR_CEO",pregunta:"Durante una ola de calor, el 30% de la flota de la empresa falla mec\xE1nicamente. Desde la posici\xF3n de CEO, \xBFcu\xE1l es la prioridad inmediata?",opciones:["Alquilar unidades temporales y priorizar llamadas de emergencia sobre mantenimientos.","Sancionar al jefe de taller por la falta de mantenimiento preventivo en los veh\xEDculos.","Cancelar todas las citas y esperar a que las camionetas sean reparadas por la agencia.","Aumentar los precios de emergencia para compensar el costo del alquiler de transporte."],respuesta_correcta:0,explicacion:"En una crisis de flota durante temporada alta, la prioridad es alquilar unidades temporales y priorizar emergencias sobre mantenimientos para no perder ingresos cr\xEDticos."},{id:"ns_0404",categoria:"NATE_SR_MINISPLIT",pregunta:"Al trabajar con refrigerantes A2L (como R-454B o R-32), \xBFqu\xE9 herramienta es t\xE9cnicamente obligatoria para el Senior?",opciones:["Bomba de vac\xEDo y recuperadora con motores a prueba de chispas (Spark-proof).","Man\xF3metros anal\xF3gicos de alta presi\xF3n con mangueras de 1/2 pulgada de di\xE1metro.","Detector de fugas ultras\xF3nico calibrado espec\xEDficamente para gases de efecto invernadero.","B\xE1scula digital con precisi\xF3n de miligramos para cargas cr\xEDticas de micro-gramos."],respuesta_correcta:0,explicacion:"Los refrigerantes A2L como R-32 y R-454B son levemente inflamables. Las herramientas con motores a prueba de chispas (spark-proof) son obligatorias para evitar la ignici\xF3n durante la manipulaci\xF3n."},{id:"ns_0405",categoria:"NATE_SR_HVAC",pregunta:"Un sistema comercial con VAV (Variable Air Volume) tiene cajas que no abren. El ventilador principal est\xE1 al 100%. \xBFQu\xE9 revisa el Senior?",opciones:["El sensor de presi\xF3n est\xE1tica del conducto principal y su punto de consigna (set-point).","El amperaje del motor del soplador para asegurar que no est\xE9 sobrecargado.","Si el termostato de la zona est\xE1 enviando una se\xF1al de 24V al actuador del damper.","La carga de refrigerante del chiller que alimenta el serpent\xEDn de agua helada."],respuesta_correcta:0,explicacion:"En un sistema VAV, el sensor de presi\xF3n est\xE1tica controla la velocidad del ventilador principal. Si el sensor est\xE1 descalibrado o su set-point es incorrecto, el ventilador opera al 100% intentando alcanzar una presi\xF3n que no corresponde, independientemente de que las cajas no abran."},{id:"ns_0406",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor tiene una succi\xF3n de 80 PSI y descarga de 550 PSI con R-410A. El aire interior es de 70\xB0F. \xBFCausa?",opciones:["Restricci\xF3n en la v\xE1lvula de expansi\xF3n de la unidad exterior o falta de carga.","Condensador interior extremadamente sucio que eleva la presi\xF3n de descarga.","V\xE1lvula inversora con fuga interna que permite el paso de gas a la succi\xF3n.","Falla del ventilador exterior que impide la absorci\xF3n de calor ambiental."],respuesta_correcta:0,explicacion:"Succion baja (80 PSI) indica poca absorcion de calor exterior, y descarga alta (550 PSI) indica problemas de condensacion interior. La causa es restriccion en la TXV exterior o falta de carga de refrigerante."},{id:"ns_0407",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un l\xEDder de cuadrilla nota que un t\xE9cnico usa un cilindro de nitr\xF3geno sin regulador de presi\xF3n. \xBFCu\xE1l es el riesgo t\xE9cnico inmediato?",opciones:["Explosi\xF3n del serpent\xEDn o componentes del sistema debido a la presi\xF3n extrema (2000+ PSI).","Contaminaci\xF3n del sistema con nitr\xF3geno impuro al no estar regulado el flujo.","Da\xF1o a las v\xE1lvulas de servicio por la velocidad del gas al entrar al sistema.","Congelaci\xF3n de las tuber\xEDas de cobre por la expansi\xF3n adiab\xE1tica del nitr\xF3geno seco."],respuesta_correcta:0,explicacion:"Un cilindro de nitr\xF3geno contiene presiones de 2000+ PSI. Sin regulador, esa presi\xF3n entra directamente al sistema dise\xF1ado para presiones mucho menores, lo que puede causar una explosi\xF3n catastr\xF3fica de serpentines, tuber\xEDas o componentes."},{id:"ns_0408",categoria:"NATE_SR_CHILLERS",pregunta:"En un chiller de absorci\xF3n de Bromuro de Litio, se pierde el vac\xEDo. \xBFCu\xE1l es el s\xEDntoma operativo primario?",opciones:["Cristalizaci\xF3n inmediata de la soluci\xF3n y paro total del sistema por seguridad.","Aumento en el consumo de vapor o agua caliente para mantener la capacidad.","Reducci\xF3n en el flujo de agua helada a trav\xE9s del intercambiador secundario.","El refrigerante (agua) empieza a hervir a una temperatura mucho m\xE1s alta."],respuesta_correcta:0,explicacion:"En chillers de absorci\xF3n con LiBr, la p\xE9rdida de vac\xEDo (entrada de aire) interfiere directamente con el proceso de absorci\xF3n, causando cristalizaci\xF3n inmediata de la soluci\xF3n y paro por seguridad."},{id:"ns_0409",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete industrial muestra un error de 'Phase Loss'. Al medir, las tres fases tienen 460V, pero el error persiste. \xBFQu\xE9 sigue?",opciones:["Verificar el desequilibrio de voltaje y el monitor de fases (Phase Monitor) defectuoso.","Reemplazar el contactor del compresor asumiendo que un polo est\xE1 carbonizado.","Cambiar los fusibles de potencia por unos de mayor capacidad de respuesta r\xE1pida.","Resetear la placa de control desconectando el transformador de 24V por un minuto."],respuesta_correcta:0,explicacion:"Aunque las tres fases muestran 460V, un desequilibrio de voltaje entre fases (>2%) puede activar el error de Phase Loss. Tambi\xE9n el monitor de fases (Phase Monitor) puede estar defectuoso y generar falsas alarmas. Se debe medir el desequilibrio porcentual y probar el monitor."},{id:"ns_0410",categoria:"NATE_SR_CEO",pregunta:"Un CEO eval\xFAa el 'LTV' (Lifetime Value) frente al 'CAC' (Customer Acquisition Cost). \xBFCu\xE1l es la proporci\xF3n ideal para un negocio HVAC saludable?",opciones:["LTV debe ser al menos 3 veces superior al CAC para asegurar rentabilidad y crecimiento.","LTV y CAC deben ser iguales para garantizar que la empresa no pierda dinero.","CAC debe ser superior al LTV en los primeros 5 a\xF1os para ganar cuota de mercado.","No existe relaci\xF3n entre ambos; el \xFAnico dato relevante es la facturaci\xF3n bruta anual."],respuesta_correcta:0,explicacion:"La proporci\xF3n ideal LTV:CAC es de al menos 3:1; esto significa que cada cliente debe generar al menos 3 veces lo que cost\xF3 adquirirlo para asegurar rentabilidad sostenible."},{id:"ns_0411",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Oil Foaming' excesivo en el c\xE1rter tras un periodo de paro. \xBFCu\xE1l es la causa ra\xEDz Senior?",opciones:["Falla del calentador de c\xE1rter que permiti\xF3 la saturaci\xF3n de refrigerante en el aceite.","Uso de un aceite con viscosidad incorrecta para la presi\xF3n operativa del sistema.","Arranque del compresor con una carga t\xE9rmica en el evaporador excesivamente alta.","La unidad de purga est\xE1 devolviendo refrigerante l\xEDquido directamente al dep\xF3sito de aceite."],respuesta_correcta:0,explicacion:"Si el calentador de c\xE1rter falla durante el paro, el refrigerante migra y se disuelve en el aceite. Al arrancar, la ca\xEDda de presi\xF3n causa evaporaci\xF3n s\xFAbita del refrigerante, generando espuma excesiva."},{id:"ns_0412",categoria:"NATE_SR_RACK",pregunta:"En un rack con condensaci\xF3n por aire, el subenfriamiento es de 25\xB0F pero la presi\xF3n de descarga es baja. \xBFQu\xE9 indica?",opciones:["Exceso de carga de refrigerante atrapado en el condensador durante clima fr\xEDo.","Funcionamiento eficiente del sistema gracias a la baja temperatura ambiente.","Restricci\xF3n en la l\xEDnea de descarga antes de entrar al separador de aceite.","Falla en las v\xE1lvulas de inundaci\xF3n (head pressure control) que est\xE1n abiertas."],respuesta_correcta:0,explicacion:"Alto subenfriamiento con presi\xF3n de descarga baja indica que hay exceso de refrigerante l\xEDquido acumulado en el condensador, t\xEDpicamente en clima fr\xEDo. El condensador sobredimensionado o falta de control de presi\xF3n de cabeza causa esta condici\xF3n."},{id:"ns_0413",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere implementar un programa de 'Safety Incentives'. \xBFCu\xE1l es el dise\xF1o m\xE1s efectivo para evitar el ocultamiento de accidentes?",opciones:["Bonos basados en la participaci\xF3n en entrenamientos y reportes de condiciones inseguras.","Premios en efectivo para las cuadrillas que reporten cero accidentes en todo el a\xF1o.","Sanciones econ\xF3micas directas para el t\xE9cnico que sufra una lesi\xF3n en el trabajo.","Publicar los nombres de los t\xE9cnicos que cometan errores de seguridad en la oficina."],respuesta_correcta:0,explicacion:"Los bonos basados en participaci\xF3n en entrenamientos y reportes de condiciones inseguras incentivan la prevenci\xF3n sin castigar accidentes, evitando que los empleados oculten incidentes."},{id:"ns_0414",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema inverter reporta un error de 'DC Fan Motor'. El t\xE9cnico mide el voltaje de control pero el motor no gira. \xBFQu\xE9 prueba el Senior?",opciones:["Si el motor gira libremente y la resistencia de los devanados del estator.","El capacitor de arranque del motor del ventilador aunque sea de tipo DC.","El voltaje de la red AC que alimenta a la unidad interior del mini-split.","La continuidad de los fusibles de la placa electr\xF3nica de la unidad exterior."],respuesta_correcta:0,explicacion:"Ante un error de motor DC del ventilador, el Senior verifica que el rotor gire libremente (sin trabas mec\xE1nicas) y mide la resistencia de los devanados del estator para descartar un bobinado abierto o cortocircuitado."},{id:"ns_0415",categoria:"NATE_SR_HVAC",pregunta:"Al medir la temperatura de bulbo h\xFAmedo y seco, un t\xE9cnico nota que son iguales. \xBFQu\xE9 significa esto psicrom\xE9tricamente?",opciones:["El aire est\xE1 al 100% de humedad relativa (saturaci\xF3n total).","El aire est\xE1 extremadamente seco y no hay evaporaci\xF3n en el term\xF3metro.","El sistema de ventilaci\xF3n est\xE1 moviendo aire a una velocidad excesiva.","La carga t\xE9rmica del edificio es exactamente igual a la capacidad del equipo."],respuesta_correcta:0,explicacion:"Cuando la temperatura de bulbo h\xFAmedo iguala la de bulbo seco, significa que no hay evaporaci\xF3n en la mecha del term\xF3metro h\xFAmedo. Esto solo ocurre cuando el aire est\xE1 al 100% de humedad relativa (saturado), ya que no puede absorber m\xE1s humedad para causar enfriamiento evaporativo."},{id:"ns_0416",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor geot\xE9rmica de lazo cerrado tiene una presi\xF3n de succi\xF3n alta y descarga baja. El compresor suena suave. \xBFDiagn\xF3stico?",opciones:["Compresor con eficiencia volum\xE9trica reducida (v\xE1lvulas o scrolls da\xF1ados).","Bajo flujo de agua en el lazo de tierra que reduce el intercambio de calor.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total.","Exceso de anticongelante en el agua que aumenta la densidad del fluido."],respuesta_correcta:0,explicacion:"Succion alta y descarga baja con un compresor que suena suave es sintoma clasico de un compresor con valvulas o scrolls danados. No puede generar la diferencia de presion necesaria entre descarga y succion."},{id:"ns_0417",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera una cuadrilla de mantenimiento en un hospital. \xBFCu\xE1l es la prioridad t\xE9cnica absoluta?",opciones:["Mantener los diferenciales de presi\xF3n de aire y la filtraci\xF3n HEPA operativos.","Asegurar que el consumo el\xE9ctrico de los chillers sea el m\xEDnimo posible.","Limpiar los condensadores exteriores para evitar paros por alta presi\xF3n.","Verificar que todos los t\xE9cnicos usen uniformes limpios y tarjetas de ID."],respuesta_correcta:0,explicacion:"En hospitales, los diferenciales de presi\xF3n de aire y la filtraci\xF3n HEPA protegen a pacientes inmunodeprimidos de infecciones. Quir\xF3fanos y salas de aislamiento dependen de presi\xF3n positiva/negativa controlada para prevenir contaminaci\xF3n cruzada."},{id:"ns_0418",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete con gas tiene el intercambiador de calor con holl\xEDn. \xBFQu\xE9 ajuste de combusti\xF3n es necesario?",opciones:["Aumentar el flujo de aire primario y verificar la presi\xF3n de gas en el manifold.","Reducir la velocidad del soplador de suministro para aumentar la temperatura.","Instalar quemadores de acero inoxidable para evitar la acumulaci\xF3n de carb\xF3n.","Aumentar el di\xE1metro de la chimenea para mejorar el tiro natural del horno."],respuesta_correcta:0,explicacion:"El holl\xEDn indica combusti\xF3n incompleta por falta de aire primario o exceso de gas. Se debe ajustar el shutter del quemador para aumentar el aire primario y verificar que la presi\xF3n del manifold est\xE9 dentro de especificaciones para lograr una mezcla estequiom\xE9trica correcta."},{id:"ns_0419",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, la v\xE1lvula EPR de una vitrina de l\xE1cteos falla cerrada. \xBFQu\xE9 sucede con el producto?",opciones:["La vitrina dejar\xE1 de enfriar y el producto se perder\xE1 por alta temperatura.","La vitrina se congelar\xE1 ya que la succi\xF3n del rack es mucho m\xE1s baja.","El sistema har\xE1 bypass autom\xE1tico y mantendr\xE1 la temperatura de dise\xF1o.","La v\xE1lvula de expansi\xF3n compensar\xE1 la falta de flujo abriendo al 100%."],respuesta_correcta:0,explicacion:"Si la EPR falla cerrada, bloquea completamente el retorno de gas del evaporador al cabezal de succi\xF3n. Sin flujo de refrigerante, el evaporador no puede absorber calor y la vitrina dejar\xE1 de enfriar, poniendo el producto en riesgo."},{id:"ns_0420",categoria:"NATE_SR_CEO",pregunta:"Un CEO analiza el 'Aging Report' de sus cuentas por cobrar. \xBFQu\xE9 indica una mayor\xEDa de facturas en el rango de 61-90 d\xEDas?",opciones:["Fallas graves en el proceso de cobro o clientes con problemas financieros.","Un aumento saludable en las ventas a cr\xE9dito para grandes constructoras.","Eficiencia en la facturaci\xF3n pero lentitud en la entrega de los servicios.","Que la empresa tiene suficiente liquidez para financiar a sus propios clientes."],respuesta_correcta:0,explicacion:"Una mayor\xEDa de facturas en el rango de 61-90 d\xEDas indica fallas serias en el proceso de cobro o que los clientes tienen problemas financieros que requieren acci\xF3n inmediata."},{id:"ns_0421",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un approach de condensador de 12\xB0F. Se realiza limpieza y baja a 2\xB0F. \xBFQu\xE9 ahorro estima el Senior?",opciones:["Reducci\xF3n significativa del consumo el\xE9ctrico (aprox 10-15%) por menor presi\xF3n de descarga.","Mejora en la vida \xFAtil del aceite pero sin impacto real en el costo de energ\xEDa.","Aumento en la capacidad de flujo de agua helada a trav\xE9s del sistema del edificio.","Reducci\xF3n del ruido audible del compresor centr\xEDfugo durante la carga m\xE1xima."],respuesta_correcta:0,explicacion:"Un condensador sucio (approach de 12\xB0F) eleva la presi\xF3n de descarga, forzando al compresor a trabajar m\xE1s. La limpieza (bajando a 2\xB0F) reduce la descarga y ahorra aproximadamente 10-15% de energ\xEDa."},{id:"ns_0422",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRF reporta 'Liquid Pipe Thermistor Error'. Al revisar, el sensor est\xE1 lleno de hielo. \xBFCausa?",opciones:["Fuga de refrigerante en esa secci\xF3n o aislamiento t\xE9rmico deficiente.","El sensor est\xE1 operando correctamente bajo condiciones de carga extrema.","La placa electr\xF3nica est\xE1 enviando una se\xF1al de escarcha para protegerse.","El ventilador de la unidad interior est\xE1 girando en sentido contrario."],respuesta_correcta:0,explicacion:"La presencia de hielo en el sensor de la l\xEDnea de l\xEDquido indica una fuga de refrigerante en esa secci\xF3n (el gas al expandirse enfr\xEDa la zona) o aislamiento t\xE9rmico deficiente que permite condensaci\xF3n y congelamiento."},{id:"ns_0423",categoria:"NATE_SR_HVAC",pregunta:"Se encuentra una 'Ground Loop' (corriente a tierra) en un sistema de control DDC. \xBFCu\xE1l es el efecto?",opciones:["Se\xF1ales err\xE1ticas de sensores y posibles da\xF1os a los microprocesadores.","Aumento en el consumo de energ\xEDa del transformador de control de 24V.","Falla de los actuadores de los dampers que se quedar\xE1n siempre abiertos.","Activaci\xF3n constante de las alarmas de incendio del edificio por ruido."],respuesta_correcta:0,explicacion:"Un 'ground loop' genera diferencias de potencial entre puntos de tierra que inducen corrientes par\xE1sitas en los cables de se\xF1al. Estas corrientes interfieren con las se\xF1ales anal\xF3gicas y digitales de los sensores, causando lecturas err\xE1ticas y posibles da\xF1os a los microprocesadores."},{id:"ns_0424",categoria:"NATE_SR_CHILLERS",pregunta:"En un chiller con R-1233zd (nuevo refrigerante de baja presi\xF3n), \xBFpor qu\xE9 el vac\xEDo es cr\xEDtico?",opciones:["Porque opera bajo la presi\xF3n atmosf\xE9rica y cualquier aire causa alta presi\xF3n de descarga.","Porque el refrigerante es altamente inflamable y el aire provoca ignici\xF3n.","Porque la humedad descompone el refrigerante en cloro puro da\xF1ando el cobre.","Porque el aceite POE usado es 10 veces m\xE1s higrosc\xF3pico que el aceite mineral."],respuesta_correcta:0,explicacion:"El R-1233zd opera bajo presi\xF3n atmosf\xE9rica como el R-123. Cualquier infiltraci\xF3n de aire causa presi\xF3n parcial adicional que eleva la presi\xF3n de descarga y reduce la eficiencia del sistema."},{id:"ns_0425",categoria:"NATE_SR_CEO",pregunta:"Un CEO busca diversificar hacia 'Solar HVAC'. \xBFCu\xE1l es el componente de mayor costo operativo?",opciones:["Capacitaci\xF3n t\xE9cnica en electr\xF3nica de potencia y almacenamiento en bater\xEDas.","La compra de paneles fotovoltaicos de silicio monocristalino por volumen.","El marketing digital enfocado en clientes con alta conciencia ambiental.","La instalaci\xF3n de estructuras de montaje de aluminio en techos residenciales."],respuesta_correcta:0,explicacion:"La diversificaci\xF3n a Solar HVAC requiere inversi\xF3n significativa en capacitaci\xF3n t\xE9cnica sobre electr\xF3nica de potencia y bater\xEDas, siendo el componente operativo de mayor costo."},{id:"ns_0426",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor activa el defrost cada 30 minutos sin hielo visible. \xBFQu\xE9 revisa el Senior?",opciones:["El sensor de temperatura del serpent\xEDn exterior y el timer de la placa.","La carga de refrigerante que podr\xEDa estar por debajo de los l\xEDmites nominales.","Si el ventilador exterior se detiene completamente durante el funcionamiento.","La configuraci\xF3n del termostato interior respecto a la calefacci\xF3n auxiliar."],respuesta_correcta:0,explicacion:"Si el defrost se activa frecuentemente sin hielo visible, el sensor de temperatura del serpentin puede dar lecturas falsas de frio, o el timer de la placa esta mal configurado con intervalos demasiado cortos."},{id:"ns_0427",categoria:"NATE_SR_RACK",pregunta:"Un rack paralelo de baja temperatura presenta 'Oil Slugging' en el arranque. \xBFC\xF3mo lo soluciona?",opciones:["Mejorando la gesti\xF3n del calentador de c\xE1rter y la l\xF3gica de secuencia de arranque.","Instalando un filtro de succi\xF3n de mayor micraje para permitir el paso del aceite.","Reduciendo la carga de aceite total del sistema para que no se acumule tanto.","Aumentando la temperatura de succi\xF3n del rack mediante el ajuste de las vitrinas."],respuesta_correcta:0,explicacion:"El oil slugging al arranque ocurre por refrigerante l\xEDquido disuelto en el aceite del c\xE1rter. Los calentadores de c\xE1rter evaporan el refrigerante antes del arranque, y una secuencia de arranque adecuada con tiempos de precalentamiento previene el golpe de l\xEDquido."},{id:"ns_0428",categoria:"NATE_SR_PACKAGE",pregunta:"Un Rooftop de 50 toneladas tiene un Delta P de aire muy bajo. El soplador gira bien. \xBFQu\xE9 revisa?",opciones:["Ductos desconectados o dampers de alivio barom\xE9trico trabados en abierto.","Filtros de aire extremadamente limpios que no ofrecen ninguna resistencia.","La rotaci\xF3n del motor del soplador que podr\xEDa estar girando en sentido inverso.","Si el serpent\xEDn del evaporador est\xE1 congelado bloqueando totalmente el flujo."],respuesta_correcta:0,explicacion:"Si el soplador gira correctamente pero la presi\xF3n est\xE1tica es muy baja, el aire est\xE1 escapando antes de llegar a las zonas. Las causas m\xE1s comunes son ductos desconectados o un damper de alivio barom\xE9trico trabado en posici\xF3n abierta, que act\xFAa como un bypass masivo del sistema."},{id:"ns_0429",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior detecta que un t\xE9cnico est\xE1 recuperando refrigerante R-22 en un cilindro de R-410A. \xBFQu\xE9 hace?",opciones:["Detener la operaci\xF3n, explicar el peligro de mezcla y usar el cilindro correcto.","Permitirlo solo si el cilindro tiene suficiente capacidad de presi\xF3n para el R-22.","Anotar en el cilindro que ahora contiene una mezcla para que el centro de reciclaje sepa.","Ignorarlo siempre que el cilindro sea de color gris con tapa amarilla (recuperaci\xF3n)."],respuesta_correcta:0,explicacion:"Mezclar refrigerantes diferentes contamina ambos gases, haci\xE9ndolos inutilizables y potencialmente peligrosos. Se deben usar cilindros de recuperaci\xF3n dedicados y correctamente etiquetados por tipo de refrigerante para cumplir con las normas EPA."},{id:"ns_0430",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga 'Smart'. El reporte indica 'Excessive Run Time'. \xBFQu\xE9 concluye el Senior?",opciones:["El sistema tiene una fuga en el lado de baja (vac\xEDo) que aspira aire constantemente.","La purga est\xE1 defectuosa y su sensor de presi\xF3n necesita una calibraci\xF3n nueva.","El chiller ha estado operando a carga parcial durante demasiado tiempo seguido.","La temperatura del agua de la torre es demasiado baja para que la purga sea eficiente."],respuesta_correcta:0,explicacion:"Un tiempo de operaci\xF3n excesivo de la purga indica que el sistema est\xE1 aspirando aire constantemente a trav\xE9s de una fuga en el lado de baja presi\xF3n (vac\xEDo), requiriendo localizaci\xF3n de la fuga."},{id:"ns_0431",categoria:"NATE_SR_CEO",pregunta:"Un CEO busca implementar 'Predictive Maintenance'. \xBFCu\xE1l es el requisito tecnol\xF3gico principal?",opciones:["Sensores de IoT para monitorear vibraci\xF3n, temperatura y corriente en tiempo real.","Software de facturaci\xF3n que env\xEDe recordatorios autom\xE1ticos a los clientes cada a\xF1o.","Contratar a t\xE9cnicos Senior que puedan 'predecir' fallas bas\xE1ndose en su experiencia.","Instalar c\xE1maras en todos los cuartos de m\xE1quinas para ver el estado de los equipos."],respuesta_correcta:0,explicacion:"El mantenimiento predictivo requiere sensores IoT que monitoreen vibraci\xF3n, temperatura y amperaje en tiempo real para detectar anomal\xEDas antes de que se conviertan en fallas."},{id:"ns_0432",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una succi\xF3n de 118 PSI y descarga de 350 PSI. El sobrecalentamiento es 22\xB0F. \xBFEstado?",opciones:["Falta de refrigerante leve o restricci\xF3n parcial en el dispositivo de expansi\xF3n.","Funcionamiento normal para un d\xEDa con carga t\xE9rmica moderada en el evaporador.","Exceso de carga que est\xE1 inundando el condensador del sistema exterior.","Compresor fallando que no logra succionar suficiente masa de refrigerante."],respuesta_correcta:0,explicacion:"Sobrecalentamiento de 22\xB0F es m\xE1s alto que el rango ideal de 10-15\xB0F, indicando que el evaporador no recibe suficiente refrigerante. Esto puede ser por falta leve de carga o una restricci\xF3n parcial en la TXV o filtro deshidratador que limita el flujo de l\xEDquido."},{id:"ns_0433",categoria:"NATE_SR_MINISPLIT",pregunta:"Un VRF tiene un error de 'Oil Return Cycle Fail'. \xBFQu\xE9 revisa el t\xE9cnico Senior?",opciones:["La velocidad del compresor, las v\xE1lvulas solenoide de retorno y el nivel de aceite.","Si el filtro de aire interior est\xE1 bloqueando el retorno de gas hacia la unidad.","La carga de refrigerante l\xEDquido que podr\xEDa estar atrapando el aceite abajo.","Si el variador de frecuencia (VFD) tiene un error de sobrecalentamiento de placa."],respuesta_correcta:0,explicacion:"El ciclo de retorno de aceite en VRF depende de la velocidad del compresor, las v\xE1lvulas solenoide de retorno de aceite y el nivel de aceite. Si alguno falla, el aceite no regresa al c\xE1rter adecuadamente."},{id:"ns_0434",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo refrigeraci\xF3n, una bomba de calor tiene un subenfriamiento de 5\xB0F y sobrecalentamiento de 25\xB0F. \xBFCausa?",opciones:["Falta de carga de refrigerante (Undercharged).","Exceso de carga de refrigerante (Overcharged).","V\xE1lvula de expansi\xF3n (TXV) fallida en posici\xF3n abierta.","Condensador exterior extremadamente sucio o bloqueado."],respuesta_correcta:0,explicacion:"Subenfriamiento bajo (5F) indica poco liquido en el condensador. Sobrecalentamiento alto (25F) confirma que el evaporador recibe poco refrigerante. Ambos sintomas juntos son diagnostico clasico de falta de carga."},{id:"ns_0435",categoria:"NATE_SR_RACK",pregunta:"Un rack de baja temperatura usa descongelaci\xF3n por gas caliente. El tubo de drenaje se congela. \xBFQu\xE9 falta?",opciones:["Un cable calefactor (heat tape) en el drenaje y la trampa de aire externa.","Aumentar el tiempo de deshielo para que el agua alcance a salir del edificio.","Instalar una bomba de condensado de alta temperatura para forzar el drenaje.","Cerrar la v\xE1lvula de succi\xF3n m\xE1s r\xE1pido para evitar que el vapor se condense."],respuesta_correcta:0,explicacion:"En vitrinas de baja temperatura, el agua del deshielo puede congelarse en las l\xEDneas de drenaje que pasan por zonas fr\xEDas. Se requiere cable calefactor (heat tape) en el tubo de drenaje y la trampa para mantener el agua fluyendo."},{id:"ns_0436",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'High Motor Amperage' constante. El voltaje es nominal. \xBFQu\xE9 revisa?",opciones:["Fricci\xF3n excesiva en cojinetes, alta presi\xF3n de descarga o sobrecarga de gas.","Si los ventiladores del condensador est\xE1n girando a la velocidad correcta hoy.","La configuraci\xF3n del variador de frecuencia que podr\xEDa estar limitando el torque.","Si la unidad de purga est\xE1 devolviendo aire al evaporador del sistema centr\xEDfugo."],respuesta_correcta:0,explicacion:"Alto amperaje con voltaje nominal indica carga mec\xE1nica excesiva: fricci\xF3n en cojinetes desgastados, alta presi\xF3n de condensaci\xF3n por condensador sucio, o sobrecarga de gas que aumenta el trabajo de compresi\xF3n."},{id:"ns_0437",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un reemplazo de serpent\xEDn de 100 toneladas. \xBFQu\xE9 prueba de fugas es la m\xE1s rigurosa?",opciones:["Prueba de nitr\xF3geno a presi\xF3n de dise\xF1o (e.g. 450 PSI) sostenida por 24 horas.","Uso de burbujas de jab\xF3n en cada soldadura mientras el sistema est\xE1 al vac\xEDo.","Cargar el sistema con 5 libras de refrigerante y usar un detector electr\xF3nico.","Observar si el vac\xEDo de 500 micrones se mantiene estable durante 10 minutos."],respuesta_correcta:0,explicacion:"La prueba de presi\xF3n con nitr\xF3geno a presi\xF3n de dise\xF1o sostenida por 24 horas es la m\xE1s rigurosa porque detecta incluso micro-fugas que solo se manifiestan bajo presi\xF3n prolongada. En sistemas de gran tonelaje, esta verificaci\xF3n es esencial antes de cargar."},{id:"ns_0438",categoria:"NATE_SR_CEO",pregunta:"Un CEO busca reducir el 'Inventory Carrying Cost'. \xBFCu\xE1l es la estrategia log\xEDstica?",opciones:["Implementar un sistema de inventario 'Just-In-Time' con proveedores locales.","Comprar piezas por volumen y almacenarlas en el almac\xE9n central de la empresa.","Permitir que los t\xE9cnicos compren lo que necesiten en cualquier tienda de suministros.","Eliminar el stock de las camionetas para que el t\xE9cnico no sea responsable de piezas."],respuesta_correcta:0,explicacion:"El sistema Just-In-Time con proveedores locales reduce el costo de almacenamiento de inventario al mantener solo lo necesario, evitando capital inmovilizado en piezas."},{id:"ns_0439",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una descarga de 500 PSI con R-410A. El condensador est\xE1 limpio. \xBFQu\xE9 sigue?",opciones:["Verificar la rotaci\xF3n del ventilador exterior y la presencia de incondensables.","Agregar m\xE1s refrigerante l\xEDquido para intentar bajar la temperatura de descarga.","Cambiar el compresor asumiendo que el bobinado interno est\xE1 recalentado.","Puentear el interruptor de alta presi\xF3n para que el sistema siga operando hoy."],respuesta_correcta:0,explicacion:"Con condensador limpio y descarga de 500 PSI (extremadamente alta para R-410A), las causas probables son ventilador exterior girando al rev\xE9s o no girando, o incondensables (aire/nitr\xF3geno) en el sistema. Verificar la rotaci\xF3n del ventilador es el paso diagn\xF3stico l\xF3gico."},{id:"ns_0440",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete, el contactor del compresor se funde cada 3 meses. \xBFQu\xE9 causa ra\xEDz busca?",opciones:["Bajo voltaje (chattering), cables flojos o sobredimensionamiento de la carga.","Humedad en el ambiente que oxida los contactos de plata del componente.","Uso de un termostato de baja calidad que cicla el sistema muy r\xE1pido.","Que el t\xE9cnico est\xE1 usando contactores de 30 amperios para motores de 40."],respuesta_correcta:0,explicacion:"Un contactor que se funde repetidamente indica chattering (vibraci\xF3n) por bajo voltaje en la bobina, conexiones flojas que generan arco el\xE9ctrico, o carga excesiva. El chattering impide el cierre completo de los contactos, generando arco continuo que quema los contactos prematuramente."},{id:"ns_0441",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo tiene una aproximaci\xF3n de condensador de 1\xB0F. \xBFQu\xE9 concluye el Senior?",opciones:["Transferencia t\xE9rmica \xF3ptima y tubos perfectamente limpios en el lado agua.","Falta de refrigerante l\xEDquido; no hay masa suficiente para el intercambio total.","El flujo de agua es tan alto que no permite una lectura estable del sensor.","Error de calibraci\xF3n en los sensores de temperatura de entrada y salida agua."],respuesta_correcta:0,explicacion:"Un approach de condensador de 1\xB0F confirma que los tubos est\xE1n perfectamente limpios y la transferencia t\xE9rmica es \xF3ptima, con m\xEDnima diferencia entre la temperatura de saturaci\xF3n y la salida del agua."},{id:"ns_0442",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no responde al mando a distancia. El voltaje en la placa es de 5VDC. \xBFQu\xE9 sigue?",opciones:["Verificar el receptor de infrarrojos y la continuidad del cable de se\xF1al.","Reemplazar la placa principal exterior asumiendo que bloquea el sistema.","Cambiar las bater\xEDas del control remoto aunque la pantalla sea visible.","Resetear el sistema cortando la energ\xEDa desde el interruptor principal."],respuesta_correcta:0,explicacion:"Con 5VDC presente en la placa (alimentaci\xF3n correcta), el siguiente paso es verificar el receptor de infrarrojos y la continuidad del cable de se\xF1al entre el receptor y la placa principal de la unidad interior."},{id:"ns_0443",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 410 PSI con R-410A. \xBFC\xF3mo est\xE1?",opciones:["Funcionamiento normal para un d\xEDa con carga t\xE9rmica est\xE1ndar y alta temperatura.","Falta de refrigerante l\xEDquido que impide que la descarga baje a niveles de 300.","Restricci\xF3n en el dispositivo de expansi\xF3n que eleva la presi\xF3n de alta.","Compresor con eficiencia volum\xE9trica reducida que no puede bombear gas."],respuesta_correcta:0,explicacion:"Con R-410A, succi\xF3n de 110 PSI (~34\xB0F sat.) y descarga de 410 PSI (~112\xB0F sat.) son presiones normales para un d\xEDa caluroso. El diferencial de presi\xF3n es adecuado y la temperatura de saturaci\xF3n de descarga corresponde a una temperatura exterior elevada."},{id:"ns_0444",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere incentivar a sus t\xE9cnicos Senior. \xBFCu\xE1l es el beneficio de un plan 'Tool Allowance'?",opciones:["Garantiza que el t\xE9cnico use herramientas modernas y reduzca el tiempo de servicio.","Reduce la responsabilidad de la empresa en caso de robo de herramientas propias.","Es una forma de evadir impuestos al pagar beneficios en lugar de salarios brutos.","Permite que la empresa compre herramientas baratas y las asigne a los t\xE9cnicos."],respuesta_correcta:0,explicacion:"Un Tool Allowance garantiza que el t\xE9cnico Senior use herramientas modernas y actualizadas, reduciendo el tiempo de servicio y mejorando la calidad del diagn\xF3stico."},{id:"ns_0445",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFpor qu\xE9 el compresor zumba y se apaga por 'Internal Overload'?",opciones:["Capacitor de marcha defectuoso o compresor mec\xE1nicamente bloqueado.","Falta de refrigerante l\xEDquido que no permite el arranque del motor.","La v\xE1lvula inversora se encuentra en una posici\xF3n media bloqueando el flujo.","El termostato de la zona est\xE1 enviando una se\xF1al de 24V con fase invertida."],respuesta_correcta:0,explicacion:"Un compresor que zumba sin arrancar y se apaga por overload indica que el motor no puede girar. Las causas mas comunes son un capacitor de marcha defectuoso o un bloqueo mecanico interno del compresor."},{id:"ns_0446",categoria:"NATE_SR_RACK",pregunta:"Un rack paralelo tiene un visor de aceite con espuma persistente. \xBFQu\xE9 indica?",opciones:["Migraci\xF3n de refrigerante l\xEDquido al c\xE1rter durante los ciclos de paro.","Que el aceite es virgen y est\xE1 liberando burbujas de aire atrapadas hoy.","Funcionamiento perfecto del separador de aceite centr\xEDfugo del sistema.","Que el calentador de c\xE1rter est\xE1 operando con una potencia excesiva."],respuesta_correcta:0,explicacion:"La espuma persistente en el visor de aceite confirma migraci\xF3n de refrigerante l\xEDquido al c\xE1rter durante los periodos de paro. Al arrancar, la ca\xEDda de presi\xF3n en el c\xE1rter hace hervir el refrigerante dentro del aceite, generando espuma."},{id:"ns_0447",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Junior reporta que un cliente no quiere pagar el diagn\xF3stico. \xBFQu\xE9 hace el Senior?",opciones:["Explicar al cliente el valor del conocimiento t\xE9cnico y la soluci\xF3n ofrecida.","Aceptar que no pague para evitar una mala rese\xF1a en las redes sociales.","Retirar la pieza instalada y dejar el sistema descompuesto como estaba.","Darle un descuento del 50% para que el Junior pueda irse a otra llamada."],respuesta_correcta:0,explicacion:"El diagn\xF3stico t\xE9cnico tiene valor profesional: requiere conocimiento, experiencia y herramientas especializadas. Comunicar este valor al cliente de forma respetuosa valida el trabajo del t\xE9cnico y establece est\xE1ndares profesionales para la empresa."},{id:"ns_0448",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga manual. \xBFC\xF3mo sabe el t\xE9cnico que hay aire dentro?",opciones:["La presi\xF3n de condensaci\xF3n es mayor que la presi\xF3n de saturaci\xF3n del gas.","El compresor centr\xEDfugo empieza a vibrar por falta de masa de refrigerante.","La temperatura del agua helada de salida sube por encima del set-point.","El visor de l\xEDquido en el condensador muestra burbujas constantes hoy."],respuesta_correcta:0,explicacion:"La diferencia entre la presi\xF3n real de condensaci\xF3n y la presi\xF3n de saturaci\xF3n a la temperatura medida indica gases no condensables. Si la presi\xF3n es mayor que la saturaci\xF3n, hay aire presente en el sistema."},{id:"ns_0449",categoria:"NATE_SR_HVAC",pregunta:"Un motor de soplador PSC tiene un capacitor de 5 MFD. Se mide y marca 3 MFD. \xBFEfecto?",opciones:["El motor perder\xE1 torque, bajar\xE1 sus RPM y se sobrecalentar\xE1 r\xE1pidamente.","El motor consumir\xE1 menos amperaje y funcionar\xE1 de manera m\xE1s eficiente.","El motor girar\xE1 a la misma velocidad pero har\xE1 un ruido el\xE9ctrico agudo.","No habr\xE1 efecto visible hasta que el capacitor llegue a 0 MFD (abierto)."],respuesta_correcta:0,explicacion:"Un capacitor de 5 MFD que mide solo 3 MFD ha perdido el 40% de su capacitancia. Esto reduce significativamente el desfase de fase del devanado de arranque, causando p\xE9rdida de torque, reducci\xF3n de RPM y sobrecalentamiento del motor por el esfuerzo extra."},{id:"ns_0450",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Overhead'. \xBFCu\xE1l es la medida m\xE1s directa y t\xE9cnica?",opciones:["Implementar software de despacho para optimizar rutas y reducir combustible.","Bajar el precio de los filtros de aire para ganar m\xE1s contratos de servicio.","Reducir el salario de los t\xE9cnicos Junior para ahorrar en la n\xF3mina semanal.","Eliminar el uso de nitr\xF3geno en las soldaduras para bajar costos de materiales."],respuesta_correcta:0,explicacion:"El software de despacho optimiza rutas y reduce el consumo de combustible y tiempo muerto, impactando directamente los costos indirectos (Overhead) de la operaci\xF3n."},{id:"ns_0451",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller de tornillo presenta una ca\xEDda de presi\xF3n de aceite de 10 PSI. El m\xEDnimo es 15 PSI. \xBFAcci\xF3n?",opciones:["Verificar saturaci\xF3n del filtro de aceite y funcionamiento de la bomba interna.","Agregar 1 gal\xF3n de aceite POE de inmediato para subir la presi\xF3n del c\xE1rter.","Reducir la velocidad del compresor para bajar la demanda de lubricaci\xF3n.","Ignorar el valor si la temperatura de los rodamientos se mantiene estable."],respuesta_correcta:0,explicacion:"Una presi\xF3n diferencial de aceite de 10 PSI (m\xEDnimo 15 PSI) indica un filtro de aceite saturado que restringe el flujo, o una bomba interna desgastada que no genera la presi\xF3n suficiente."},{id:"ns_0452",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFcu\xE1l es la funci\xF3n primordial del 'Head Pressure Control Valve'?",opciones:["Inundar el condensador en invierno para mantener una presi\xF3n de descarga m\xEDnima.","Reducir el consumo de los ventiladores del condensador durante el verano seco.","Evitar que el aceite se enfr\xEDe demasiado antes de entrar al separador principal.","Aumentar el flujo de refrigerante hacia las vitrinas de baja temperatura hoy."],respuesta_correcta:0,explicacion:"La v\xE1lvula de control de presi\xF3n de cabeza retiene refrigerante l\xEDquido en el condensador durante clima fr\xEDo, reduciendo el \xE1rea de condensaci\xF3n efectiva. Esto mantiene la presi\xF3n de descarga m\xEDnima necesaria para alimentar l\xEDquido a las v\xE1lvulas de expansi\xF3n."},{id:"ns_0453",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere comprar otra empresa HVAC. \xBFQu\xE9 es lo primero que audita t\xE9cnicamente?",opciones:["La calidad de las instalaciones pasadas y el \xEDndice de 'Callbacks' hist\xF3rico.","El dise\xF1o del logotipo y la uniformidad de la marca en las camionetas nuevas.","La cantidad de herramientas de marca premium que posee la empresa objetivo.","El n\xFAmero de seguidores que interact\xFAan con la marca en sus redes sociales."],respuesta_correcta:0,explicacion:"Al adquirir otra empresa HVAC, la calidad de las instalaciones pasadas y el \xEDndice de callbacks hist\xF3rico revelan la competencia t\xE9cnica real y los riesgos de garant\xEDa futuros."},{id:"ns_0454",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter muestra el error 'P4' (IPM Overheat). El condensador est\xE1 limpio. \xBFCausa?",opciones:["Pasta t\xE9rmica seca entre el m\xF3dulo IPM y el disipador o falla del ventilador.","Carga de refrigerante excesiva que obliga al compresor a trabajar forzado.","Voltaje de l\xEDnea el\xE9ctrica superior a 250VAC que sobrecalienta la placa.","El termostato interior est\xE1 configurado a una temperatura demasiado baja."],respuesta_correcta:0,explicacion:"Con el condensador limpio, el sobrecalentamiento del IPM se debe a la pasta t\xE9rmica seca (pierde conductividad t\xE9rmica) entre el m\xF3dulo y el disipador, o a un fallo del ventilador que no enfr\xEDa el gabinete."},{id:"ns_0455",categoria:"NATE_SR_HVAC",pregunta:"Un sistema con R-410A tiene una succi\xF3n de 150 PSI y sobrecalentamiento de 2\xB0F. \xBFDiagn\xF3stico?",opciones:["Sistema sobrecargado de refrigerante que est\xE1 inundando el evaporador.","Falta de refrigerante l\xEDquido que impide que la descarga suba a niveles 400.","Filtro de aire extremadamente sucio que reduce la carga t\xE9rmica del sistema.","V\xE1lvula de expansi\xF3n (TXV) bloqueada en la posici\xF3n de cerrado total hoy."],respuesta_correcta:0,explicacion:"Succi\xF3n de 150 PSI (~48\xB0F sat.) es elevada y un sobrecalentamiento de 2\xB0F significa que casi todo el evaporador est\xE1 lleno de l\xEDquido. Esto es resultado de una sobrecarga de refrigerante que env\xEDa m\xE1s l\xEDquido del que el evaporador puede evaporar, inund\xE1ndolo."},{id:"ns_0456",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calor, una bomba de calor presenta la l\xEDnea de succi\xF3n escarchada hasta el compresor. \xBFCausa?",opciones:["Operaci\xF3n normal; el acumulador de succi\xF3n est\xE1 protegiendo al motor hoy.","V\xE1lvula inversora da\xF1ada que est\xE1 fugando gas de descarga a la succi\xF3n.","Falla del ventilador exterior que impide que el refrigerante absorba calor.","El termostato de la zona ha activado las resistencias de apoyo innecesarias."],respuesta_correcta:2,explicacion:"Si el ventilador exterior falla, el serpentin exterior no absorbe calor del aire ambiente. El refrigerante permanece frio y liquido, regresando por la linea de succion y causando escarcha hasta el compresor."},{id:"ns_0457",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior observa que un ayudante est\xE1 soldando sin usar 'Nitrogen Purge'. \xBFConsecuencia?",opciones:["Escamas de \xF3xido (soot) dentro del tubo que tapar\xE1n la TXV y el filtro.","Que la soldadura de plata no se adhiera al cobre por falta de ox\xEDgeno.","El cobre se volver\xE1 quebradizo y fallar\xE1 mec\xE1nicamente por el calor hoy.","No hay consecuencia t\xE9cnica si la tuber\xEDa es de menos de 1/2 pulgada de di\xE1metro."],respuesta_correcta:0,explicacion:"Sin purga de nitr\xF3geno, el ox\xEDgeno atrapado reacciona con el cobre caliente generando escamas de \xF3xido c\xFAprico (soot). Estas part\xEDculas circulan con el refrigerante y obstruyen el orificio de la TXV y el filtro deshidratador, causando restricciones."},{id:"ns_0458",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Surge' a carga parcial. \xBFC\xF3mo responde el control Senior?",opciones:["Ajustando los \xE1labes de entrada (vanes) o modulando la velocidad v\xEDa VFD.","Aumentando el set-point de temperatura de salida del agua helada al edificio.","Cerrando la v\xE1lvula de expansi\xF3n para reducir la masa de refrigerante total.","Apagando el chiller durante 10 minutos para que las presiones se igualen solo."],respuesta_correcta:0,explicacion:"El surge a carga parcial se controla ajustando los \xE1labes de entrada (vanes) para regular el flujo de gas, o modulando la velocidad del compresor mediante VFD para mantener una operaci\xF3n estable."},{id:"ns_0459",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una descarga de 380 PSI y subenfriamiento de 12\xB0F con R-410A. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y subenfriamiento est\xE1n en rango de dise\xF1o.","Falta de refrigerante leve; el subenfriamiento deber\xEDa ser de 15 grados F.","Exceso de carga; el subenfriamiento indica un condensador parcialmente inundado.","Compresor perdiendo eficiencia volum\xE9trica al no alcanzar los 450 PSI ideales."],respuesta_correcta:0,explicacion:"Descarga de 380 PSI (~104\xB0F sat.) y subenfriamiento de 12\xB0F con R-410A est\xE1n dentro del rango normal de operaci\xF3n. Un subenfriamiento de 10-15\xB0F es t\xEDpico para sistemas con TXV, confirmando que la carga de refrigerante y el intercambio de calor son correctos."},{id:"ns_0460",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar el 'Profit Margin' de los mantenimientos. \xBFQu\xE9 acci\xF3n toma?",opciones:["Estandarizar procesos para reducir el tiempo en el sitio y el desperdicio.","Aumentar el precio de los contratos de mantenimiento un 50% anual hoy.","Contratar solo a t\xE9cnicos de nivel b\xE1sico (helpers) para realizar limpiezas.","Eliminar el uso de qu\xEDmicos de limpieza de serpentines para ahorrar dinero."],respuesta_correcta:0,explicacion:"Estandarizar los procesos de mantenimiento reduce el tiempo en el sitio y minimiza el desperdicio de materiales, mejorando el margen de ganancia por cada visita."},{id:"ns_0461",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con evaporador inundado presenta 'Liquid Carryover'. \xBFQu\xE9 da\xF1o Senior previene?",opciones:["Rotura de los \xE1labes del impulsor o da\xF1o mec\xE1nico severo al compresor.","Aumento en la presi\xF3n de condensaci\xF3n por falta de \xE1rea de intercambio agua.","Falla en el sensor de nivel de refrigerante que bloquear\xE1 el sistema pronto.","Sobrecalentamiento del motor por falta de gas de succi\xF3n fr\xEDo para el enfriamiento."],respuesta_correcta:0,explicacion:"El arrastre de l\xEDquido (liquid carryover) hacia el compresor centr\xEDfugo puede causar da\xF1o severo a los \xE1labes del impulsor por impacto hidr\xE1ulico, ya que los l\xEDquidos son incompresibles."},{id:"ns_0462",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no enfr\xEDa. El voltaje entre S2 y S3 es de 24VDC constantes. \xBFCausa?",opciones:["Falla de comunicaci\xF3n; el voltaje deber\xEDa ser pulsante (fluctuante) entre 0-24.","La placa exterior est\xE1 operando correctamente enviando la se\xF1al de control.","El compresor inverter est\xE1 aterrizado y consume el voltaje de comunicaci\xF3n.","Falta de alimentaci\xF3n de 240VAC en los terminales L1 y L2 de la exterior."],respuesta_correcta:0,explicacion:"La se\xF1al de comunicaci\xF3n entre unidades debe ser un voltaje DC pulsante (fluctuante entre 0-24V). Un voltaje constante de 24VDC indica que no hay modulaci\xF3n de datos: falla de comunicaci\xF3n."},{id:"ns_0463",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 120 PSI y descarga de 450 PSI. El aire sale a 65\xB0F. \xBFCausa?",opciones:["Bajo flujo de aire (filtros o conductos) o evaporador parcialmente sucio.","Funcionamiento normal para un sistema operando en condiciones de alta carga.","Falta de refrigerante l\xEDquido que impide que el aire se enfr\xEDe a 55 grados.","V\xE1lvula de expansi\xF3n (TXV) bloqueada en la posici\xF3n de abierta total hoy."],respuesta_correcta:0,explicacion:"Temperatura de salida de 65\xB0F es demasiado alta (deber\xEDa ser ~55\xB0F), lo que indica insuficiente transferencia de calor en el evaporador. Con descarga de 450 PSI, bajo flujo de aire por filtros sucios o conductos restringidos es la causa m\xE1s probable del pobre enfriamiento."},{id:"ns_0464",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete, el serpent\xEDn del evaporador se congela. El ventilador funciona bien. \xBFQu\xE9 revisa?",opciones:["Carga de refrigerante baja o una TXV que est\xE1 inyectando poco l\xEDquido.","Si el motor del ventilador del condensador est\xE1 girando a bajas RPM.","Instalar un termostato de descongelaci\xF3n para que pare el compresor solo.","Agregar refrigerante hasta que la presi\xF3n de succi\xF3n suba a 150 PSI hoy."],respuesta_correcta:0,explicacion:"Con ventilador operando normalmente, la congelaci\xF3n se debe a una presi\xF3n de succi\xF3n demasiado baja. La causa directa es carga baja de refrigerante (fuga) o una TXV que no inyecta suficiente l\xEDquido, resultando en temperaturas de evaporaci\xF3n por debajo del punto de congelaci\xF3n."},{id:"ns_0465",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir el 'Customer Satisfaction'. \xBFQu\xE9 m\xE9trica es la m\xE1s s\xF3lida?",opciones:["Tasa de renovaci\xF3n de contratos de mantenimiento e \xEDndice NPS (Net Promoter).","N\xFAmero total de llamadas de servicio recibidas durante la temporada alta.","La cantidad de me gusta y comentarios positivos en la p\xE1gina de Facebook.","El margen de utilidad neta de cada reparaci\xF3n realizada por los t\xE9cnicos."],respuesta_correcta:0,explicacion:"La tasa de renovaci\xF3n de contratos y el NPS son las m\xE9tricas m\xE1s s\xF3lidas de satisfacci\xF3n porque reflejan acciones reales del cliente (pagar de nuevo) y su disposici\xF3n a recomendar."},{id:"ns_0466",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si la v\xE1lvula diferencial de aceite est\xE1 mal ajustada (muy baja)?",opciones:["Los compresores se apagar\xE1n por 'Oil Failure' al no recibir lubricante a tiempo.","El aceite se inyectar\xE1 con demasiada presi\xF3n da\xF1ando los sellos del motor.","El separador de aceite se desbordar\xE1 hacia la l\xEDnea de succi\xF3n del sistema.","La temperatura de descarga de los compresores subir\xE1 por encima de 250\xB0F."],respuesta_correcta:0,explicacion:"Si la v\xE1lvula diferencial est\xE1 ajustada muy baja, no hay suficiente presi\xF3n para empujar el aceite desde el dep\xF3sito hasta los c\xE1rteres de los compresores. Los compresores se quedan sin lubricante y el control de seguridad dispara un Oil Failure."},{id:"ns_0467",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que no tiene la b\xE1scula para cargar un sistema VRF. \xBFQu\xE9 dice el Senior?",opciones:["Prohibido cargar sin b\xE1scula; los sistemas VRF requieren peso exacto de f\xE1brica.","Que use el m\xE9todo del sobrecalentamiento y subenfriamiento para cargar gas.","Que cargue hasta que las presiones se estabilicen en los 120/400 PSI nominales.","Que use un cilindro graduado (charging cylinder) para medir el volumen l\xEDquido."],respuesta_correcta:0,explicacion:"Los sistemas VRF tienen m\xFAltiples evaporadores y l\xEDneas largas con carga cr\xEDtica calculada por el fabricante. Las presiones var\xEDan seg\xFAn la demanda de cada zona, por lo que el m\xE9todo de presiones no funciona; se debe pesar la carga exacta."},{id:"ns_0468",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una ca\xEDda de presi\xF3n de agua excesiva en el condensador. \xBFCausa probable?",opciones:["Incrustaciones de minerales o lodo en los tubos del intercambiador de calor.","La bomba de agua de la torre est\xE1 girando a una velocidad insuficiente hoy.","El refrigerante est\xE1 congelando el agua dentro de los tubos por baja presi\xF3n.","Las v\xE1lvulas de aislamiento del condensador est\xE1n completamente abiertas hoy."],respuesta_correcta:0,explicacion:"Una ca\xEDda de presi\xF3n excesiva en el condensador con agua indica incrustaciones de minerales o lodo que restringen el paso del agua por los tubos del intercambiador de calor."},{id:"ns_0469",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 115 PSI y descarga de 480 PSI. El subenfriamiento es 28\xB0F. \xBFCausa?",opciones:["Condensador extremadamente sucio o incondensables atrapados en el sistema.","Falta de refrigerante l\xEDquido que impide que la succi\xF3n suba a niveles 130.","V\xE1lvula de expansi\xF3n (TXV) bloqueada en la posici\xF3n de abierta total hoy.","El compresor est\xE1 perdiendo eficiencia y no logra comprimir el gas ralo."],respuesta_correcta:0,explicacion:"Descarga de 480 PSI es excesivamente alta y subenfriamiento de 28\xB0F es muy elevado. Un condensador sucio atrapa calor elevando la descarga, y los incondensables (aire) ocupan espacio en el condensador, forzando al l\xEDquido a acumularse m\xE1s y aumentando el subenfriamiento."},{id:"ns_0470",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete, el contactor del compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["Voltaje bajo en la bobina (menos de 18V) o suciedad en el n\xFAcleo magn\xE9tico.","Si los contactos principales est\xE1n soldados debido a un cortocircuito previo.","Si el capacitor de arranque del compresor tiene el rel\xE9 potencial abierto.","La continuidad de los fusibles de potencia de la l\xEDnea de alta tensi\xF3n AC."],respuesta_correcta:0,explicacion:"Un contactor que zumba indica que la fuerza electromagn\xE9tica es insuficiente para cerrar la armadura. Esto ocurre cuando el voltaje de la bobina cae por debajo del m\xEDnimo (t\xEDpicamente 18V en una bobina de 24V) o cuando hay suciedad u \xF3xido en las caras del n\xFAcleo magn\xE9tico que impide el cierre."},{id:"ns_0471",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar el 'Cash Flow'. \xBFCu\xE1l es la medida administrativa m\xE1s eficiente?",opciones:["Cobrar en el momento del servicio y reducir los d\xEDas de cr\xE9dito a 30 m\xE1ximo.","Pedir un pr\xE9stamo bancario a 10 a\xF1os para cubrir los gastos de operaci\xF3n.","Aumentar el stock de materiales en las camionetas para evitar ir a la tienda.","Reducir el salario de los t\xE9cnicos Junior para ahorrar dinero en la n\xF3mina."],respuesta_correcta:0,explicacion:"Cobrar en el momento del servicio y limitar el cr\xE9dito a 30 d\xEDas acelera el ciclo de efectivo, evitando la dependencia de financiamiento externo para operar."},{id:"ns_0472",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFcu\xE1l es la funci\xF3n de la v\xE1lvula 'Liquid Header Solenoid'?",opciones:["Aislar la l\xEDnea de l\xEDquido principal durante periodos de deshielo o paro rack.","Regular la presi\xF3n de inyecci\xF3n de aceite hacia los c\xE1rteres de compresores.","Aumentar el subenfriamiento del l\xEDquido antes de que llegue a las vitrinas.","Evitar que el refrigerante l\xEDquido regrese al separador de aceite del rack."],respuesta_correcta:0,explicacion:"La solenoide del cabezal de l\xEDquido a\xEDsla la l\xEDnea principal de l\xEDquido durante deshielos o paros del rack. Esto evita que el refrigerante l\xEDquido contin\xFAe fluyendo hacia las vitrinas cuando no hay compresores operando para mantener la succi\xF3n."},{id:"ns_0473",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta una purga de aire excesiva. Opera con R-134a. \xBFQu\xE9 indica?",opciones:["La purga est\xE1 defectuosa; el R-134a opera a presi\xF3n positiva y no aspira aire.","El chiller tiene una fuga masiva en el evaporador que permite la entrada aire.","El sistema de sellado del eje del compresor ha fallado mec\xE1nicamente hoy.","La temperatura del agua de la torre es demasiado baja para el condensador."],respuesta_correcta:0,explicacion:"El R-134a opera siempre a presi\xF3n positiva. Si la purga indica expulsi\xF3n de aire, es porque el sistema de purga est\xE1 defectuoso ya que bajo presi\xF3n positiva el aire no puede infiltrarse al sistema."},{id:"ns_0474",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no arranca. No hay c\xF3digos de error. \xBFQu\xE9 revisa el Senior?",opciones:["El fusible de la placa interior y si el voltaje de llegada es de 240VAC.","La carga de refrigerante por peso para descartar una fuga total de gas gas.","Si el compresor est\xE1 aterrizado midiendo la resistencia contra la carcasa.","La placa electr\xF3nica de la unidad exterior por rastros de quemaduras hoy."],respuesta_correcta:0,explicacion:"Sin c\xF3digos de error, el sistema no est\xE1 recibiendo energ\xEDa o la placa no arranca. El Senior revisa primero el fusible de la placa interior y confirma 240VAC en la alimentaci\xF3n como diagn\xF3stico b\xE1sico."},{id:"ns_0475",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, la v\xE1lvula inversora hace un ruido de 'Chattering'. \xBFCausa?",opciones:["Bajo voltaje en la bobina de 24V o una se\xF1al de termostato inestable hoy.","Falta de presi\xF3n diferencial de refrigerante para mover el pist\xF3n interno.","El aceite del sistema es demasiado espeso y bloquea el movimiento v\xE1lvula.","Es un sonido normal cuando el sistema opera a temperaturas bajo cero hoy."],respuesta_correcta:0,explicacion:"El chattering ocurre cuando la bobina solenoide de 24V no recibe voltaje suficiente para mantener el piston piloto en posicion firme, causando que el piston principal vibre entre las dos posiciones de la valvula."},{id:"ns_0476",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior detecta un error de dise\xF1o en un plano de conductos. \xBFQu\xE9 hace?",opciones:["Notificar al ingeniero y proponer una soluci\xF3n t\xE9cnica basada en campo.","Instalar el sistema como dice el plano para evitar responsabilidad legal hoy.","Corregir el dise\xF1o por su cuenta sin avisar a nadie para terminar r\xE1pido.","Decirle al cliente que el ingeniero no sabe nada y que \xE9l lo har\xE1 mejor."],respuesta_correcta:0,explicacion:"La comunicaci\xF3n con el ingeniero de dise\xF1o es esencial para resolver errores de forma profesional. El t\xE9cnico Senior aporta experiencia pr\xE1ctica de campo, pero los cambios deben documentarse y aprobarse dentro de la cadena de responsabilidad del proyecto."},{id:"ns_0477",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Reversal'. \xBFQu\xE9 sucede si se ignora el error?",opciones:["El compresor girar\xE1 al rev\xE9s y no bombear\xE1 aceite ni refrigerante l\xEDquido hoy.","La unidad funcionar\xE1 al 50% de su capacidad nominal debido al desfase fase.","El motor se quemar\xE1 instant\xE1neamente al intentar vencer la inercia carga.","Las v\xE1lvulas de expansi\xF3n se cerrar\xE1n por seguridad al detectar el error hoy."],respuesta_correcta:0,explicacion:"La inversi\xF3n de fases causa rotaci\xF3n inversa del compresor. Sin flujo correcto de refrigerante ni bombeo de aceite, se producen da\xF1os mec\xE1nicos inmediatos por falta de lubricaci\xF3n en los cojinetes."},{id:"ns_0478",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. El subenfriamiento es 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido severa en el sistema (Undercharged).","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total hoy.","Condensador exterior extremadamente sucio que no permite el intercambio.","Evaporador interior congelado que bloquea el flujo de calor totalmente hoy."],respuesta_correcta:0,explicacion:"Subenfriamiento de 0\xB0F confirma que no hay l\xEDquido subenfriado en la salida del condensador. Con presiones moderadas, esto indica falta severa de refrigerante: no hay suficiente masa de refrigerante para llenar el condensador con l\xEDquido antes de llegar al dispositivo de expansi\xF3n."},{id:"ns_0479",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n hoy.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada hoy.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial hoy.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos."],respuesta_correcta:0,explicacion:"Smart Homes requiere t\xE9cnicos con conocimiento en redes, protocolos de comunicaci\xF3n (Wi-Fi, Zigbee, Z-Wave) e integraci\xF3n de sistemas inteligentes, m\xE1s all\xE1 del HVAC convencional."},{id:"ns_0480",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 indica una temperatura de succi\xF3n muy alta en el cabezal?",opciones:["Sobrecalentamiento excesivo que da\xF1ar\xE1 la lubricaci\xF3n de compresores pronto.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de evaporaci\xF3n hoy.","Falta de refrigerante l\xEDquido en el recibidor principal del rack paralelo.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n cerradas por temperatura."],respuesta_correcta:0,explicacion:"Una temperatura de succi\xF3n excesivamente alta significa que el gas llega demasiado caliente a los compresores. Esto degrada el aceite lubricante y reduce el enfriamiento del motor, acelerando el desgaste de los cojinetes y partes internas."},{id:"ns_0481",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. \xBFQu\xE9 revisa?",opciones:["Presencia de aire en la tuber\xEDa, paddle roto o transductor descalibrado.","La carga de refrigerante que podr\xEDa estar congelando el agua en tubos.","El sentido de rotaci\xF3n del motor del compresor centr\xEDfugo del sistema hoy.","La apertura de las v\xE1lvulas de expansi\xF3n del circuito de refrigeraci\xF3n hoy."],respuesta_correcta:0,explicacion:"Con bomba encendida, una alarma de flow switch indica problemas mec\xE1nicos del sensor: paddle roto, aire en la tuber\xEDa que afecta la lectura, o transductor de presi\xF3n diferencial descalibrado."},{id:"ns_0482",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. \xBFCausa?",opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.","La bomba de condensado integrada ha fallado y no puede evacuar el agua.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido.","La humedad en la habitaci\xF3n es superior al 95% y satura el serpent\xEDn hoy."],respuesta_correcta:0,explicacion:"El goteo al parar el compresor indica que el agua acumulada durante la operaci\xF3n no drena correctamente. Una contrapendiente o bloqueo parcial en la parte alta del drenaje retiene agua que se libera al cesar la operaci\xF3n."},{id:"ns_0483",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de 0.9 en suministro y 0.2 en retorno. \xBFProblema?",opciones:["Restricci\xF3n severa en conductos de suministro o difusores cerrados hoy.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo hoy.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o hoy."],respuesta_correcta:0,explicacion:'La distribuci\xF3n de presi\xF3n est\xE1tica de 0.9" en suministro vs 0.2" en retorno muestra que la restricci\xF3n principal est\xE1 en el lado de suministro. Conductos aplastados, demasiados codos, o difusores cerrados en el suministro causan esta asimetr\xEDa de presi\xF3n.'},{id:"ns_0484",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre los 20\xB0F y 30\xB0F.","S\xED, las bombas de calor siempre tienen un diferencial menor que hornos.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en modo calor esta por debajo del rango aceptable de 20-30F. Indica baja capacidad de calentamiento por falta de refrigerante, exceso de flujo de aire, o pobre absorcion de calor exterior."},{id:"ns_0485",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. \xBFQu\xE9 paso es vital post-quemadura?",opciones:["Realizar prueba de acidez del aceite y usar filtros succi\xF3n de limpieza.","A\xF1adir aditivo sellador de fugas para prevenir fallas futuras en l\xEDneas.","Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.","Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy."],respuesta_correcta:0,explicacion:"Despu\xE9s de una quemadura de compresor, los \xE1cidos y residuos carbonizados contaminan todo el sistema. La prueba de acidez determina el nivel de contaminaci\xF3n, y los filtros de succi\xF3n de limpieza (suction line filters) protegen el compresor nuevo."},{id:"ns_0486",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. \xBFEstado?",opciones:["Funcionamiento correcto; la purga est\xE1 separando los no condensables hoy.","Falla en el serpent\xEDn de condensaci\xF3n interno de la unidad de purga hoy.","El sistema tiene una fuga masiva de agua hacia el lado del refrigerante.","La temperatura del evaporador es demasiado alta para que la purga trabaje."],respuesta_correcta:0,explicacion:"Si la purga expulsa mucho aire y poco refrigerante, est\xE1 separando correctamente los gases no condensables del refrigerante. Esto indica operaci\xF3n normal y eficiente de la unidad de purga."},{id:"ns_0487",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si el 'Oil Separator' queda pegado en posici\xF3n abierta?",opciones:["Gas caliente de descarga pasar\xE1 directo al dep\xF3sito aceite y a la succi\xF3n.","El rack se quedar\xE1 sin aceite en pocos minutos al no poder separarlo gas.","Los compresores se apagar\xE1n por alta presi\xF3n al bloquearse el flujo gas.","El nivel de aceite en los c\xE1rteres subir\xE1 tanto que da\xF1ar\xE1 los pistones."],respuesta_correcta:0,explicacion:"Con el flotador abierto permanentemente, gas caliente de descarga pasa sin control al dep\xF3sito de aceite y puede alcanzar la succi\xF3n. Este bypass reduce la capacidad del sistema y crea un cortocircuito de gas caliente."},{id:"ns_0488",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. \xBFQu\xE9 KPI usa?",opciones:["N\xFAmero de llamadas de nuevos clientes que mencionan haber visto la unidad.","La cantidad de millas recorridas por cada veh\xEDculo en zonas residenciales.","El costo total del dise\xF1o e instalaci\xF3n del r\xF3tulo dividido entre 12 meses.","El aumento en la velocidad promedio de t\xE9cnicos al conducir camionetas nuevas."],respuesta_correcta:0,explicacion:"El KPI directo para camionetas rotuladas es contar cu\xE1ntos clientes nuevos mencionan haberla visto, ya que conecta la inversi\xF3n visual con la generaci\xF3n real de negocio."},{id:"ns_0489",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. \xBFQu\xE9 revisa?",opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy.","La carga de refrigerante l\xEDquido bas\xE1ndose en el visor del evaporador hoy.","Si la v\xE1lvula de expansi\xF3n est\xE1 inyectando demasiado l\xEDquido al sistema.","El estado de los filtros de aire de la manejadora de aire del edificio."],respuesta_correcta:0,explicacion:"La alta presi\xF3n de condensaci\xF3n en un chiller enfriado por agua se debe principalmente a la temperatura del agua de torre y al funcionamiento de la bomba de condensador, que son los primeros puntos a verificar."},{id:"ns_0490",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n de 125 PSI y descarga 400 PSI con R-410A. \xBFEstado aire?",opciones:["Funcionamiento normal bajo condiciones de carga t\xE9rmica est\xE1ndar hoy hoy.","Falta de refrigerante que impide que temperatura del aire baje a 55 grados.","Exceso de carga que est\xE1 elevando la presi\xF3n de descarga innecesariamente.","Compresor con eficiencia reducida que no logra enfriar el aire correctamente."],respuesta_correcta:0,explicacion:"Con R-410A, succi\xF3n de 125 PSI (~40\xB0F sat.) y descarga de 400 PSI (~109\xB0F sat.) son valores que caen dentro del rango normal de operaci\xF3n para condiciones est\xE1ndar de carga t\xE9rmica. El sistema est\xE1 funcionando correctamente."},{id:"ns_0491",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. \xBFQu\xE9 estrategia?",opciones:["Programa de membres\xEDas mantenimiento para convertir clientes en recurrentes.","Aumentar el precio de la primera visita para maximizar la ganancia hoy.","Gastar m\xE1s dinero en anuncios de Google para atraer siempre clientes nuevos.","Despedir a t\xE9cnicos que no logren vender un sistema nuevo en cada visita."],respuesta_correcta:0,explicacion:"Las membres\xEDas de mantenimiento transforman clientes ocasionales en recurrentes, creando un flujo de ingresos predecible y aumentando la retenci\xF3n a largo plazo."},{id:"ns_0492",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. \xBFQu\xE9 revisa?",opciones:["Carga de refrigerante baja o una restricci\xF3n en la v\xE1lvula de expansi\xF3n.","Si el ventilador interior est\xE1 sucio y no sopla suficiente aire fr\xEDo hoy.","El voltaje de la l\xEDnea el\xE9ctrica que podr\xEDa estar por debajo de 200V hoy.","Si el control remoto est\xE1 configurado en una temperatura demasiado baja."],respuesta_correcta:0,explicacion:"La protecci\xF3n de temperatura de descarga del compresor se activa por carga baja de refrigerante (el gas no enfr\xEDa el compresor) o por restricci\xF3n en la EEV que limita el flujo de refrigerante."},{id:"ns_0493",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba calor, \xBFqu\xE9 sucede si 'Check Valve' condensador falla abierta?",opciones:["En modo calor el refrigerante har\xE1 bypass a TXV impidiendo calentamiento.","El sistema funcionar\xE1 mejor al haber menos restricci\xF3n al flujo l\xEDquido.","La presi\xF3n de descarga subir\xE1 hasta que switch de alta apague el equipo.","El compresor se quemar\xE1 por el retorno de l\xEDquido masivo en el arranque."],respuesta_correcta:0,explicacion:"Si la check valve del condensador falla abierta, en modo calor el refrigerante hace bypass a la TXV. Sin la restriccion de la TXV, no hay caida de presion y el sistema no calienta correctamente."},{id:"ns_0494",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula 'Quench' o inyecci\xF3n de l\xEDquido?",opciones:["Para enfriar gas de succi\xF3n y evitar que descarga da\xF1e el aceite hoy hoy.","Para aumentar la presi\xF3n de succi\xF3n cuando carga en vitrinas es baja hoy.","Para limpiar el interior de compresores de acumulaciones de carbonilla hoy.","Para ayudar al retorno de aceite desde los evaporadores m\xE1s lejanos hoy hoy."],respuesta_correcta:0,explicacion:"La v\xE1lvula Quench inyecta refrigerante l\xEDquido para reducir la temperatura de descarga del compresor. Temperaturas de descarga excesivas degradan el aceite POE, formando \xE1cidos y carbonilla que da\xF1an v\xE1lvulas y cojinetes."},{id:"ns_0495",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. \xBFCriterio?",opciones:["El volumen de agua y la accesibilidad para eliminaci\xF3n segura del fluido.","Cu\xE1l de las dos herramientas es m\xE1s nueva y hace menos ruido al operar.","La preferencia del cliente sobre qu\xE9 herramienta quiere ver en su casa hoy.","Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy."],respuesta_correcta:0,explicacion:"La decisi\xF3n t\xE9cnica se basa en el volumen de agua acumulada y la accesibilidad del punto de drenaje. Grandes vol\xFAmenes requieren bomba de capacidad adecuada; espacios reducidos pueden requerir aspiradora. La eliminaci\xF3n segura del fluido es prioritaria."},{id:"ns_0496",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene purga que marca 'Water Detected'. \xBFQu\xE9 acci\xF3n es urgente?",opciones:["Realizar prueba presi\xF3n a tubos del evaporador para buscar rupturas hoy.","Cambiar el filtro deshidratador de la purga y seguir operando el sistema.","Aumentar la temperatura del agua helada para evitar que vapor condense hoy.","Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy."],respuesta_correcta:0,explicacion:"La detecci\xF3n de agua indica una posible ruptura en los tubos del evaporador donde el agua del lazo puede infiltrarse al lado del refrigerante. La prueba de presi\xF3n es urgente para localizar la fuga."},{id:"ns_0497",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n 130 PSI y descarga 380 PSI. Subenfriamiento 12\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y el subenfriamiento est\xE1n en rango.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser 15 grados hoy.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno.","Compresor fallando; la diferencia presi\xF3n entre succi\xF3n y descarga es baja."],respuesta_correcta:0,explicacion:"Succi\xF3n de 130 PSI y descarga de 380 PSI con subenfriamiento de 12\xB0F est\xE1n todos dentro de rangos aceptables para R-410A. El subenfriamiento de 10-15\xB0F confirma carga correcta, y el diferencial de presi\xF3n indica un compresor en buen estado."},{id:"ns_0498",categoria:"NATE_SR_PACKAGE",pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["El voltaje en la bobina (24V) y si hay suciedad u \xF3xido en el n\xFAcleo hoy.","Si los contactos principales est\xE1n quemados o soldados entre s\xED hoy hoy hoy.","El capacitor de arranque del compresor que podr\xEDa estar descargado hoy hoy.","La continuidad de los fusibles de potencia de la l\xEDnea de 240 voltios hoy."],respuesta_correcta:0,explicacion:"El zumbido de un contactor sin cerrar es causado por voltaje insuficiente en la bobina o impedimento mec\xE1nico en el n\xFAcleo. Medir el voltaje de la bobina y limpiar las superficies del n\xFAcleo magn\xE9tico es el diagn\xF3stico correcto antes de reemplazar el componente."},{id:"ns_0499",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico cobra 'por fuera' a clientes. \xBFQu\xE9 acci\xF3n toma?",opciones:["Despido inmediato y posible acci\xF3n legal seg\xFAn el contrato de trabajo hoy.","Hablar con el t\xE9cnico y pedirle una comisi\xF3n por esos trabajos extras hoy.","Ignorar la situaci\xF3n si el t\xE9cnico es el que m\xE1s dinero genera hoy hoy hoy.","Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."],respuesta_correcta:0,explicacion:"Cobrar por fuera es una violaci\xF3n grave del contrato laboral y de la confianza; el despido inmediato y la acci\xF3n legal son la respuesta apropiada para proteger el negocio."},{id:"ns_0500",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFPor qu\xE9 es fundamental cargar l\xEDquido en el recibidor?",opciones:["Para evitar fraccionamiento de la mezcla y asegurar composici\xF3n correcta hoy.","Para que el refrigerante se mezcle m\xE1s r\xE1pido con el aceite POE del rack.","Para prevenir que las v\xE1lvulas de descarga de compresores se calienten hoy.","Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal."],respuesta_correcta:0,explicacion:"Las mezclas zeotr\xF3picas como el R-448A deben cargarse en fase l\xEDquida para que todos los componentes entren al sistema en la proporci\xF3n correcta. La carga en gas causa fraccionamiento y altera las propiedades termodin\xE1micas de la mezcla."},{id:"ns_0501",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRV muestra una temperatura de descarga excesiva en el compresor maestro, pero los esclavos operan normal. \xBFQu\xE9 debe auditar el Senior?",opciones:["La v\xE1lvula de inyecci\xF3n de l\xEDquido del compresor maestro o el nivel de aceite.","La carga total de refrigerante bas\xE1ndose en la presi\xF3n de succi\xF3n del sistema.","El sensor de temperatura de ambiente exterior de la unidad maestra solamente.","La configuraci\xF3n de los dip-switches de capacidad en todas las unidades interiores."],respuesta_correcta:0,explicacion:"Si solo el compresor maestro tiene temperatura de descarga alta y los esclavos operan normal, el problema es espec\xEDfico de ese compresor: la v\xE1lvula de inyecci\xF3n de l\xEDquido o el nivel de aceite insuficiente."},{id:"ns_0502",categoria:"NATE_SR_PACKAGE",pregunta:"Un an\xE1lisis de laboratorio reporta presencia de cobre en el aceite de un chiller centr\xEDfugo. \xBFCu\xE1l es la implicaci\xF3n t\xE9cnica?",opciones:["Desgaste por fricci\xF3n en los cojinetes de empuje o corrosi\xF3n \xE1cida en los tubos.","Es un residuo normal del proceso de asentamiento del compresor tras el arranque.","El refrigerante est\xE1 reaccionando con el barniz del motor debido a la humedad.","La bomba de aceite mec\xE1nica est\xE1 cavitando y desprendiendo virutas met\xE1licas."],respuesta_correcta:0,explicacion:"La presencia de cobre en el an\xE1lisis de aceite indica copper plating, causado por desgaste de cojinetes de empuje o corrosi\xF3n \xE1cida que disuelve el cobre de los tubos del condensador/evaporador. Es una se\xF1al de alerta grave que requiere investigar la fuente y el nivel de acidez del aceite."},{id:"ns_0503",categoria:"NATE_SR_CEO",pregunta:"Un CEO eval\xFAa la compra de un local propio versus seguir rentando. \xBFQu\xE9 factor fiscal es clave para la decisi\xF3n de CAPEX?",opciones:["La depreciaci\xF3n del activo y la creaci\xF3n de capital en el balance general.","El ahorro inmediato en el flujo de caja mensual al no pagar renta externa.","La posibilidad de contratar a m\xE1s personal administrativo en el nuevo espacio.","El aumento en la visibilidad de la marca para los clientes locales de la zona."],respuesta_correcta:0,explicacion:"La compra de un local propio permite deducir la depreciaci\xF3n del activo fiscalmente y crea patrimonio (equity) en el balance general, siendo el factor fiscal clave en la decisi\xF3n de CAPEX."},{id:"ns_0504",categoria:"NATE_SR_HVAC",pregunta:"En un ambiente con una humedad relativa del 90%, el diferencial entre bulbo seco y h\xFAmedo (wet bulb depression) ser\xE1:",opciones:["M\xEDnimo, indicando que el aire est\xE1 muy cerca de su punto de saturaci\xF3n total.","M\xE1ximo, debido a la gran cantidad de vapor de agua presente en el aire.","Constante, independientemente de los cambios en la temperatura de bulbo seco.","Inexistente, ya que ambos bulbos marcar\xE1n exactamente la misma temperatura."],respuesta_correcta:0,explicacion:"Con 90% de humedad relativa, el aire est\xE1 muy cerca de la saturaci\xF3n (100%). La diferencia entre bulbo seco y h\xFAmedo (wet bulb depression) ser\xE1 m\xEDnima porque hay muy poca evaporaci\xF3n posible en el term\xF3metro h\xFAmedo cuando el aire ya contiene casi toda la humedad que puede sostener."},{id:"ns_0505",categoria:"NATE_SR_RACK",pregunta:"Un sistema de refrigeraci\xF3n industrial usa R-717 (Amon\xEDaco). \xBFPor qu\xE9 no se debe usar cobre en las tuber\xEDas?",opciones:["El amon\xEDaco corroe agresivamente el cobre en presencia de cualquier humedad.","La presi\xF3n de operaci\xF3n del amon\xEDaco excede la resistencia del cobre Tipo L.","El cobre reacciona con el amon\xEDaco creando un gas explosivo e inestable.","Las vibraciones del compresor de amon\xEDaco causar\xEDan fatiga t\xE9rmica en el cobre."],respuesta_correcta:0,explicacion:"El amon\xEDaco (NH3) ataca qu\xEDmicamente al cobre y sus aleaciones en presencia de humedad, formando compuestos de cobre-amon\xEDaco que corroen y debilitan las tuber\xEDas. Por eso los sistemas de amon\xEDaco usan exclusivamente tuber\xEDa de acero."},{id:"ns_0506",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo refrigeraci\xF3n tiene un subenfriamiento de 18\xB0F y sobrecalentamiento de 3\xB0F. \xBFQu\xE9 indica?",opciones:["Sistema con exceso de carga de refrigerante que inunda el condensador.","Restricci\xF3n en el filtro deshidratador de la l\xEDnea de l\xEDquido del sistema.","Bajo flujo de aire a trav\xE9s del serpent\xEDn exterior (condensador) en verano.","V\xE1lvula inversora que no est\xE1 sellando correctamente en la posici\xF3n de fr\xEDo."],respuesta_correcta:0,explicacion:"Subenfriamiento alto (18F) indica exceso de liquido en el condensador, y sobrecalentamiento bajo (3F) indica que el evaporador recibe demasiado refrigerante. Ambos sintomas confirman sobrecarga de refrigerante."},{id:"ns_0507",categoria:"NATE_SR_CEO",pregunta:"Un CEO detecta que sus t\xE9cnicos no realizan el reporte de recuperaci\xF3n de gas. \xBFCu\xE1l es el riesgo legal ante la EPA?",opciones:["Multas severas por cada infracci\xF3n y p\xE9rdida de la certificaci\xF3n de la empresa.","Suspensi\xF3n de la licencia de conducir comercial para todos los t\xE9cnicos del equipo.","Aumento en el costo de los permisos de construcci\xF3n para nuevos proyectos HVAC.","La imposibilidad de comprar refrigerante virgen en los centros de distribuci\xF3n."],respuesta_correcta:0,explicacion:"La EPA impone multas severas por cada infracci\xF3n de registro de recuperaci\xF3n de refrigerante y puede revocar la certificaci\xF3n de la empresa, afectando su capacidad de operar."},{id:"ns_0508",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'low evaporator pressure' pero el agua helada sale a la temperatura de set-point. \xBFQu\xE9 revisa el Senior?",opciones:["Falta de refrigerante o una v\xE1lvula de expansi\xF3n mal calibrada o fallida.","El sensor de presi\xF3n de succi\xF3n que podr\xEDa estar enviando una se\xF1al falsa.","La limpieza de los tubos del condensador que afecta la presi\xF3n de alta.","El flujo de agua de la torre de enfriamiento que es demasiado bajo hoy."],respuesta_correcta:0,explicacion:"Si el agua sale a set-point pero la presi\xF3n de succi\xF3n es baja, hay falta de refrigerante o la v\xE1lvula de expansi\xF3n est\xE1 restringida. El sistema compensa temporalmente pero opera de forma ineficiente."},{id:"ns_0509",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete con VAV tiene una presi\xF3n est\xE1tica de conductos que fluct\xFAa violentamente. \xBFCausa ra\xEDz?",opciones:["El lazo de control PID del variador de frecuencia (VFD) est\xE1 mal sintonizado.","El sensor de presi\xF3n est\xE1tica est\xE1 ubicado demasiado cerca del soplador principal.","Hay demasiadas cajas VAV cerrando simult\xE1neamente durante la carga parcial.","El motor del soplador tiene un rodamiento desgastado que var\xEDa las RPM totales."],respuesta_correcta:0,explicacion:"Fluctuaciones violentas de presi\xF3n est\xE1tica en un sistema VAV con VFD indican un lazo PID mal sintonizado. Si la ganancia proporcional es demasiado alta o el tiempo integral es demasiado corto, el VFD sobrecompensa cada cambio, creando oscilaciones que nunca se estabilizan."},{id:"ns_0510",categoria:"NATE_SR_CEO",pregunta:"Como CEO, usted decide invertir en una flota el\xE9ctrica. \xBFCu\xE1l es el principal desaf\xEDo operativo para sus t\xE9cnicos?",opciones:["La gesti\xF3n del tiempo de carga y la planeaci\xF3n de rutas seg\xFAn la autonom\xEDa.","La falta de espacio en el veh\xEDculo para herramientas pesadas y refrigerantes.","El ruido excesivo del motor el\xE9ctrico que distrae al t\xE9cnico durante el manejo.","La dificultad para encontrar estaciones de carga en zonas residenciales nuevas."],respuesta_correcta:0,explicacion:"El principal desaf\xEDo de flota el\xE9ctrica es gestionar los tiempos de carga y planear rutas seg\xFAn la autonom\xEDa del veh\xEDculo para no dejar t\xE9cnicos varados sin completar sus llamadas."},{id:"ns_0511",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, se observa que la presi\xF3n del recibidor fluct\xFAa con la temperatura ambiente. \xBFQu\xE9 componente fall\xF3?",opciones:["La v\xE1lvula reguladora de presi\xF3n del recibidor (ORI/ORD o equivalente).","El ventilador del condensador remoto que no modula su velocidad por presi\xF3n.","La v\xE1lvula diferencial de aceite que est\xE1 permitiendo el paso de gas caliente.","El transductor de presi\xF3n de descarga que controla la l\xF3gica de los compresores."],respuesta_correcta:0,explicacion:"La v\xE1lvula reguladora del recibidor (ORI/ORD) mantiene una presi\xF3n estable independiente de las condiciones ambientales. Si falla, la presi\xF3n del recibidor fluct\xFAa directamente con la temperatura ambiente, afectando la alimentaci\xF3n de l\xEDquido a las vitrinas."},{id:"ns_0512",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRF tiene un error de 'Suction Pressure Sensor'. \xBFCu\xE1l es el riesgo de seguir operando en modo manual?",opciones:["Falla del compresor por retorno de l\xEDquido o sobrecalentamiento extremo.","P\xE9rdida total de la comunicaci\xF3n entre la unidad exterior y los evaporadores.","Aumento en el consumo de energ\xEDa pero sin riesgo para la integridad mec\xE1nica.","Que el sistema solo funcione en modo de calefacci\xF3n independientemente del mando."],respuesta_correcta:0,explicacion:"Sin el sensor de presi\xF3n de succi\xF3n, el sistema no puede proteger al compresor contra retorno de l\xEDquido (presi\xF3n alta) ni sobrecalentamiento extremo (presi\xF3n muy baja), arriesgando una falla mec\xE1nica."},{id:"ns_0513",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo usa R-123. Se detecta una fuga \xE1cida. \xBFQu\xE9 acci\xF3n de remediaci\xF3n es obligatoria post-reparaci\xF3n?",opciones:["Cambios sucesivos de aceite y filtros deshidratadores de alta capacidad \xE1cida.","A\xF1adir un neutralizador l\xEDquido y no cambiar el aceite hasta el pr\xF3ximo a\xF1o.","Realizar un vac\xEDo de 50 micrones para asegurar que el \xE1cido se evapore solo.","Pintar el interior de la carcasa del evaporador para evitar que el \xE1cido la da\xF1e."],respuesta_correcta:0,explicacion:"Tras una fuga \xE1cida en un sistema con R-123, se requieren cambios sucesivos de aceite y filtros deshidratadores de alta capacidad \xE1cida para neutralizar y remover los contaminantes \xE1cidos del sistema."},{id:"ns_0514",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa una instalaci\xF3n donde el drenaje de condensado no tiene trampa (P-Trap). \xBFEfecto?",opciones:["El agua no drenar\xE1 si el serpent\xEDn est\xE1 en el lado de succi\xF3n del soplador.","La humedad en el edificio aumentar\xE1 un 20% debido al aire que entra al tubo.","El compresor se apagar\xE1 por alta presi\xF3n debido al calor que sube por el drenaje.","No hay efecto t\xE9cnico; las trampas solo se usan para evitar olores del drenaje."],respuesta_correcta:0,explicacion:"Cuando el serpent\xEDn est\xE1 en el lado de succi\xF3n (presi\xF3n negativa), sin trampa P el aire es succionado por el tubo de drenaje impidiendo que el agua drene por gravedad. La trampa crea un sello de agua que bloquea el flujo de aire y permite el drenaje."},{id:"ns_0515",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC quiere reducir el 'Customer Acquisition Cost' (CAC). \xBFQu\xE9 canal es m\xE1s rentable a largo plazo?",opciones:["El SEO org\xE1nico y la generaci\xF3n de contenido t\xE9cnico \xFAtil para el cliente.","Anuncios pagados en motores de b\xFAsqueda (PPC) durante la temporada de verano.","Patrocinio de eventos deportivos locales para aumentar el reconocimiento visual.","Env\xEDo masivo de correos postales con cupones de descuento para instalaciones."],respuesta_correcta:0,explicacion:"El SEO org\xE1nico y el contenido t\xE9cnico \xFAtil generan leads a costo marginal decreciente a largo plazo, siendo el canal m\xE1s rentable comparado con la publicidad pagada continua."},{id:"ns_0516",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter presenta un ruido de expansi\xF3n (hissing) fuerte en la unidad interior. \xBFCausa Senior?",opciones:["Falta de refrigerante que genera burbujas de vapor en la l\xEDnea de l\xEDquido.","La v\xE1lvula de expansi\xF3n electr\xF3nica (EEV) est\xE1 mal lubricada por el aceite.","El ventilador interior est\xE1 desbalanceado y genera una resonancia ac\xFAstica.","Es un sonido normal cuando el compresor modula a su frecuencia m\xE1s alta."],respuesta_correcta:0,explicacion:"El ruido de expansi\xF3n (hissing) fuerte en la unidad interior indica falta de refrigerante que genera burbujas de vapor (flash gas) en la l\xEDnea de l\xEDquido antes de llegar a la v\xE1lvula de expansi\xF3n."},{id:"ns_0517",categoria:"NATE_SR_HVAC",pregunta:"Al enfriar aire por debajo de su punto de roc\xEDo (Dew Point), \xBFqu\xE9 cambio f\xEDsico ocurre?",opciones:["Se produce condensaci\xF3n de agua y tanto la entalp\xEDa como la humedad bajan.","La temperatura de bulbo seco baja pero la humedad absoluta se mantiene igual.","El aire gana energ\xEDa latente mientras pierde energ\xEDa sensible proporcionalmente.","La humedad relativa baja al 50% debido a la contracci\xF3n de las mol\xE9culas de aire."],respuesta_correcta:0,explicacion:"Cuando el aire se enfr\xEDa por debajo de su punto de roc\xEDo, el vapor de agua condensa sobre la superficie del serpent\xEDn. Esto remueve tanto calor sensible (temperatura) como calor latente (humedad), reduciendo la entalp\xEDa total y la humedad absoluta del aire."},{id:"ns_0518",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de 40 toneladas presenta vibraciones en el compresor Scroll. El subenfriamiento es 0\xB0F. \xBFCausa?",opciones:["Slugging de l\xEDquido refrigerante debido a una falta de carga o falla de TXV.","Desgaste natural de las espirales del scroll por operar a altas presiones.","Falta de aceite en el sistema que no permite la lubricaci\xF3n de los cojinetes.","El compresor est\xE1 operando en sentido inverso por una falla de fase el\xE9ctrica."],respuesta_correcta:0,explicacion:"Un subenfriamiento de 0\xB0F significa que el refrigerante llega al dispositivo de expansi\xF3n como mezcla l\xEDquido-vapor en lugar de l\xEDquido subenfriado. Esto indica baja carga o falla de TXV, y el l\xEDquido sin evaporar puede llegar al compresor scroll causando slugging (golpe de l\xEDquido) y vibraciones severas."},{id:"ns_0519",categoria:"NATE_SR_CEO",pregunta:"Un CEO analiza su 'Net Profit Margin'. Si este es del 5%, \xBFqu\xE9 acci\xF3n es prioritaria para mejorarlo?",opciones:["Controlar gastos operativos (Overhead) y optimizar la facturaci\xF3n por hora.","Aumentar el salario de los t\xE9cnicos para que vendan m\xE1s sistemas nuevos.","Reducir el costo de los materiales comprando piezas de marcas gen\xE9ricas.","Eliminar el departamento de mantenimiento para reducir los gastos de flota."],respuesta_correcta:0,explicacion:"Un Net Profit Margin del 5% es bajo; la acci\xF3n prioritaria es controlar el Overhead y optimizar la facturaci\xF3n por hora para que m\xE1s ingresos lleguen a la l\xEDnea final."},{id:"ns_0520",categoria:"NATE_SR_RACK",pregunta:"En un rack, se instala un sistema de 'Heat Reclaim'. \xBFC\xF3mo afecta esto al condensador principal?",opciones:["Reduce la carga t\xE9rmica que el condensador debe rechazar a la atm\xF3sfera.","Aumenta la presi\xF3n de descarga de los compresores de forma permanente.","Requiere ventiladores de mayor caballaje para compensar la ca\xEDda de presi\xF3n.","Elimina la necesidad de usar un recibidor de l\xEDquido en el sistema de rack."],respuesta_correcta:0,explicacion:"El Heat Reclaim aprovecha parte del calor de descarga para calentar agua o aire del edificio. Al extraer calor antes del condensador, se reduce la carga t\xE9rmica que el condensador debe disipar, mejorando la eficiencia general del sistema."},{id:"ns_0521",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con R-134a tiene un approach de evaporador de 10\xB0F y baja succi\xF3n. El agua fluye bien. \xBFDiagn\xF3stico?",opciones:["Tubos del evaporador sucios en el lado del agua (biofilm o incrustaci\xF3n).","Sobrecarga de refrigerante que inunda el intercambiador de calor de placas.","Falla en el sensor de temperatura de entrada del agua helada al edificio.","La bomba de aceite no est\xE1 suministrando la presi\xF3n necesaria al compresor."],respuesta_correcta:0,explicacion:"Un approach alto de evaporador (10\xB0F) con flujo de agua correcto indica fouling en los tubos del lado del agua (biofilm o incrustaci\xF3n mineral) que act\xFAa como aislante y reduce la transferencia t\xE9rmica."},{id:"ns_0522",categoria:"NATE_SR_HVAC",pregunta:"Se encuentra un compresor residencial 'quemado' con olor \xE1cido. \xBFQu\xE9 debe hacer el Senior antes de instalar el nuevo?",opciones:["Lavado del sistema con agente de limpieza (flushing) y cambio de filtros.","Simplemente realizar un vac\xEDo de 24 horas para extraer los vapores \xE1cidos.","A\xF1adir el doble de la carga de aceite para diluir cualquier residuo \xE1cido.","Instalar un capacitor de arranque para ayudar al compresor nuevo a vencer la presi\xF3n."],respuesta_correcta:0,explicacion:"Un compresor quemado con olor \xE1cido indica descomposici\xF3n del aceite y formaci\xF3n de \xE1cidos que contaminaron todo el circuito frigor\xEDfico. Un lavado (flushing) con agente de limpieza elimina los residuos \xE1cidos y las part\xEDculas, y los filtros nuevos atrapan contaminantes restantes."},{id:"ns_0523",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la 'Retenci\xF3n de Clientes'. \xBFQu\xE9 m\xE9trica es la m\xE1s representativa?",opciones:["Porcentaje de clientes con contrato de mantenimiento que renuevan anualmente.","El n\xFAmero de nuevos clientes que llegan por recomendaciones de boca en boca.","La cantidad total de facturas emitidas a clientes residenciales cada trimestre.","El margen de utilidad neta de las instalaciones de equipos nuevos este a\xF1o."],respuesta_correcta:0,explicacion:"El porcentaje de renovaci\xF3n anual de contratos de mantenimiento mide directamente la retenci\xF3n real: clientes que deciden seguir pagando por el servicio a\xF1o tras a\xF1o."},{id:"ns_0524",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, la v\xE1lvula inversora queda trabada en la posici\xF3n media. \xBFQu\xE9 s\xEDntoma se observa?",opciones:["Presiones de succi\xF3n y descarga casi iguales y falta total de capacidad.","Aumento dr\xE1stico de la presi\xF3n de descarga hasta que el switch corta.","Congelaci\xF3n inmediata del serpent\xEDn exterior independientemente del modo.","El compresor arranca pero se apaga por protecci\xF3n interna en 30 segundos."],respuesta_correcta:0,explicacion:"Con la valvula inversora en posicion media, las presiones de alta y baja se igualan porque el gas circula libremente entre ambos lados. El compresor opera pero no puede establecer el diferencial necesario."},{id:"ns_0525",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split muestra el error 'Communication Fault'. Al medir, el cable de se\xF1al tiene 120VAC contra tierra. \xBFEstado?",opciones:["Hay una fuga de voltaje AC al cable de se\xF1al; la placa est\xE1 da\xF1ada o hay un corto.","Es el voltaje normal de operaci\xF3n para sistemas inverter de alta eficiencia.","El compresor est\xE1 aterrizado y env\xEDa voltaje por el chasis a la placa de control.","Falta la conexi\xF3n de tierra f\xEDsica en la unidad exterior del sistema inverter."],respuesta_correcta:0,explicacion:"El cable de se\xF1al (comunicaci\xF3n) nunca debe tener 120VAC contra tierra. Esa presencia de voltaje AC indica una fuga de voltaje desde la placa de potencia al circuito de se\xF1al, se\xF1al de placa da\xF1ada o cortocircuito."},{id:"ns_0526",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se utiliza una v\xE1lvula 'Static' de bypass de gas caliente?",opciones:["Para mantener una presi\xF3n m\xEDnima de succi\xF3n durante periodos de carga baja.","Para deshelar los evaporadores de las vitrinas de l\xE1cteos de forma r\xE1pida.","Para reducir la presi\xF3n de descarga cuando el condensador remoto falla hoy.","Para asegurar que el aceite regrese al rack paralelo desde las l\xEDneas largas."],respuesta_correcta:0,explicacion:"La v\xE1lvula de bypass est\xE1tica de gas caliente inyecta gas de descarga a la succi\xF3n cuando la presi\xF3n de succi\xF3n baja demasiado por baja carga. Esto previene que los compresores operen en vac\xEDo y protege contra congelamiento de evaporadores."},{id:"ns_0527",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere implementar 'Performance Pay'. \xBFCu\xE1l es el peligro t\xE9cnico de pagar por velocidad?",opciones:["Aumento de callbacks y omisi\xF3n de pasos cr\xEDticos como el vac\xEDo o pruebas de nitr\xF3geno.","Que los t\xE9cnicos ganen m\xE1s dinero que los gerentes de servicio de la empresa.","Dificultad para calcular el pago exacto si el trabajo se complica mec\xE1nicamente.","Descontento de los clientes por ver a los t\xE9cnicos trabajando demasiado r\xE1pido."],respuesta_correcta:0,explicacion:"Pagar por velocidad incentiva a los t\xE9cnicos a omitir pasos cr\xEDticos como el vac\xEDo profundo, pruebas de nitr\xF3geno o verificaciones finales, aumentando los callbacks."},{id:"ns_0528",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una ca\xEDda de presi\xF3n de 8 PSI en el evaporador. El dise\xF1o pide 5 PSI. \xBFAcci\xF3n Senior?",opciones:["Reducir el flujo de agua helada cerrando parcialmente la v\xE1lvula de balanceo.","Aumentar la velocidad de la bomba de agua para limpiar los tubos internamente.","Agregar refrigerante l\xEDquido hasta que la ca\xEDda de presi\xF3n se estabilice en 5.","Ignorar el valor si el Delta T de temperatura del agua es de exactamente 10\xB0F."],respuesta_correcta:0,explicacion:"Una ca\xEDda de presi\xF3n de 8 PSI vs. dise\xF1o de 5 PSI indica flujo de agua excesivo. Se debe reducir cerrando parcialmente la v\xE1lvula de balanceo para ajustar el flujo al caudal de dise\xF1o."},{id:"ns_0529",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior observa que el visor de l\xEDquido est\xE1 lleno pero el subenfriamiento es de 0\xB0F. \xBFDiagn\xF3stico?",opciones:["El visor est\xE1 lleno de vapor (gas) o hay aire atrapado en el condensador.","El sistema tiene una carga de refrigerante perfecta seg\xFAn los est\xE1ndares NATE.","La v\xE1lvula de expansi\xF3n est\xE1 inyectando demasiado l\xEDquido al evaporador.","Falta de flujo de aire en el condensador exterior que eleva la descarga."],respuesta_correcta:0,explicacion:"Un subenfriamiento de 0\xB0F significa que el refrigerante est\xE1 en el punto exacto de saturaci\xF3n sin enfriarse por debajo. Si el visor aparenta estar lleno, podr\xEDa estar lleno de vapor (gas flash) o tener incondensables (aire) que dan una apariencia enga\xF1osa."},{id:"ns_0530",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado de 'Smart Maintenance'. \xBFQu\xE9 sensor es el m\xE1s valioso para la predicci\xF3n?",opciones:["Transductor de presi\xF3n y amper\xEDmetro de compresor con conexi\xF3n a la nube.","Sensor de temperatura ambiente en el termostato de la sala de estar principal.","Detector de humedad en la bandeja de condensados para evitar desbordes.","Contador de horas de operaci\xF3n mec\xE1nica para programar visitas anuales."],respuesta_correcta:0,explicacion:"Los transductores de presi\xF3n y amper\xEDmetros de compresor conectados a la nube permiten detectar anomal\xEDas en el rendimiento del compresor antes de que ocurra una falla catastr\xF3fica."},{id:"ns_0531",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Vibration Fault' en el eje de alta velocidad. \xBFQu\xE9 debe revisar el Senior?",opciones:["Alineaci\xF3n del acoplamiento y estado de los cojinetes de rodillos o metal.","Si el refrigerante tiene incondensables que causan turbulencia en el gas.","La carga de aceite en el c\xE1rter que podr\xEDa estar lubricando en exceso el eje.","El voltaje de las tres fases de alimentaci\xF3n que podr\xEDa estar desequilibrado."],respuesta_correcta:0,explicacion:"La vibraci\xF3n en el eje de alta velocidad de un chiller centr\xEDfugo indica problemas de alineaci\xF3n del acoplamiento o desgaste en los cojinetes, que son los componentes cr\xEDticos del tren de transmisi\xF3n."},{id:"ns_0532",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial con R-410A tiene succi\xF3n de 110 PSI y descarga de 450 PSI. Subenfriamiento 20\xB0F. \xBFEstado?",opciones:["Restricci\xF3n en la l\xEDnea de l\xEDquido o v\xE1lvula de expansi\xF3n (TXV) fallida.","Falta de refrigerante l\xEDquido en el sistema que impide que la succi\xF3n suba.","Exceso de carga de refrigerante que inunda el condensador exterior hoy.","Compresor perdiendo eficiencia volum\xE9trica al no poder bombear el gas."],respuesta_correcta:0,explicacion:"Succi\xF3n baja (110 PSI) con descarga alta (450 PSI) y subenfriamiento alto (20\xB0F) indican que el refrigerante se acumula en el lado de alta sin fluir correctamente al evaporador. Una restricci\xF3n en la l\xEDnea de l\xEDquido o TXV fallida impide el paso del refrigerante."},{id:"ns_0533",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que el 'Average Ticket' de mantenimiento es menor al costo operativo. \xBFAcci\xF3n?",opciones:["Reestructurar el precio del plan y capacitar en ventas de accesorios cr\xEDticos.","Reducir el tiempo que el t\xE9cnico pasa en la casa del cliente a 20 minutos.","Eliminar el uso de qu\xEDmicos de limpieza para reducir el costo de materiales.","Pedir a los t\xE9cnicos que usen sus propios veh\xEDculos para ahorrar en flota."],respuesta_correcta:0,explicacion:"Si el Average Ticket de mantenimiento no cubre el costo operativo, se debe reestructurar el precio del plan y capacitar al t\xE9cnico en identificar y vender accesorios de valor real."},{id:"ns_0534",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no modula y opera siempre al 100%. El cliente se queja de fr\xEDo. \xBFCausa?",opciones:["Termistor de aire de retorno descalibrado o mal ubicado fuera del flujo.","El compresor inverter ha perdido su capacidad de variar frecuencia interna.","Placa de control exterior con un rel\xE9 de bypass pegado mec\xE1nicamente.","El control remoto est\xE1 configurado en modo 'Turbo' o 'Jet Cool' fijo."],respuesta_correcta:0,explicacion:"Si el inverter opera siempre al 100% sin modular, el termistor de aire de retorno descalibrado o mal ubicado env\xEDa lecturas err\xF3neas, haciendo que el sistema crea que nunca alcanza la temperatura deseada."},{id:"ns_0535",categoria:"NATE_SR_HVAC",pregunta:"Un motor de soplador PSC zumba y no arranca. El capacitor mide bien. \xBFQu\xE9 prueba sigue?",opciones:["Resistencia de los devanados del motor y verificar si el eje est\xE1 trabado.","Cambiar el capacitor de todas formas por uno de mayor microfaradios hoy.","Verificar si el termostato est\xE1 enviando la se\xF1al de 24V al rel\xE9 del motor.","Limpiar la turbina del soplador para reducir la inercia de arranque mec\xE1nica."],respuesta_correcta:0,explicacion:"Si el capacitor mide bien pero el motor no arranca, el siguiente paso es verificar la resistencia de los devanados para descartar un devanado abierto o en corto, y comprobar si el eje est\xE1 trabado mec\xE1nicamente. Estos son los dos fallos restantes m\xE1s comunes en motores PSC."},{id:"ns_0536",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor tiene la descarga fr\xEDa y la succi\xF3n caliente. \xBFQu\xE9 fall\xF3?",opciones:["La v\xE1lvula inversora se qued\xF3 en modo refrigeraci\xF3n o est\xE1 fugando bypass.","Falta de refrigerante total que impide que el ciclo de calor se establezca.","El ventilador interior est\xE1 apagado y no hay intercambio de calor en casa.","El sensor de temperatura exterior est\xE1 bloqueando el arranque del compresor."],respuesta_correcta:0,explicacion:"Si en modo calor la descarga esta fria y la succion caliente, el refrigerante no sigue el ciclo de calefaccion. La valvula inversora se quedo en modo refrigeracion o tiene bypass interno, invirtiendo el flujo esperado."},{id:"ns_0537",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera una instalaci\xF3n de un rack comercial. \xBFPor qu\xE9 insiste en soldar con nitr\xF3geno?",opciones:["Prevenir la formaci\xF3n de escamas de \xF3xido que da\xF1an v\xE1lvulas solenoide.","Aumentar la resistencia mec\xE1nica de la soldadura de plata en las uniones.","Evitar que el cobre se enfr\xEDe demasiado r\xE1pido y se fracture la uni\xF3n hoy.","Es un requisito est\xE9tico para que la tuber\xEDa no se vea negra por fuera."],respuesta_correcta:0,explicacion:"En racks comerciales con m\xFAltiples v\xE1lvulas solenoide, TXVs y filtros, las escamas de \xF3xido generadas al soldar sin nitr\xF3geno pueden obstruir estos componentes cr\xEDticos. La purga de nitr\xF3geno desplaza el ox\xEDgeno y previene la oxidaci\xF3n interna."},{id:"ns_0538",categoria:"NATE_SR_PACKAGE",pregunta:"Un Rooftop de 20 toneladas presenta un Delta T de 10\xB0F. El flujo de aire es correcto. \xBFCausa?",opciones:["Falta de refrigerante o compresores con baja eficiencia volum\xE9trica hoy.","Filtros de aire extremadamente limpios que no permiten el enfriamiento aire.","La configuraci\xF3n del variador de frecuencia que limita las RPM del motor.","Uso de un refrigerante con Glide que no ha sido cargado en fase l\xEDquida."],respuesta_correcta:0,explicacion:"Con flujo de aire correcto, un Delta T bajo (10\xB0F vs. 18-22\xB0F normal) significa que el sistema no tiene suficiente capacidad de enfriamiento. Las causas son falta de refrigerante que reduce la capacidad del evaporador, o compresores con baja eficiencia volum\xE9trica que no bombean suficiente gas."},{id:"ns_0539",categoria:"NATE_SR_RACK",pregunta:"En un rack, el visor de aceite del compresor est\xE1 lleno de refrigerante l\xEDquido. \xBFPeligro?",opciones:["Lavado de cojinetes y posible golpe de l\xEDquido (slugging) al arrancar hoy.","Mejora en la viscosidad del aceite que permite un arranque m\xE1s suave hoy.","Aumento en la presi\xF3n de succi\xF3n del sistema que ayuda a enfriar vitrinas.","No hay peligro; el calentador de c\xE1rter lo evaporar\xE1 en pocos minutos hoy."],respuesta_correcta:0,explicacion:"El refrigerante l\xEDquido en el c\xE1rter diluye y lava el aceite de los cojinetes, eliminando la pel\xEDcula lubricante. Al arrancar, la ca\xEDda de presi\xF3n causa ebullici\xF3n s\xFAbita del refrigerante que arrastra aceite, causando golpe de l\xEDquido y da\xF1o mec\xE1nico severo."},{id:"ns_0540",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar el 'Cash Cycle'. \xBFCu\xE1l es la medida m\xE1s efectiva hoy?",opciones:["Implementar pagos digitales inmediatos y facturaci\xF3n electr\xF3nica en sitio.","Aumentar los d\xEDas de cr\xE9dito a los proveedores de materiales industriales.","Reducir el stock de piezas en el almac\xE9n para no tener capital parado hoy.","Contratar a un gestor de cobranza externo para las facturas de 30 d\xEDas."],respuesta_correcta:0,explicacion:"Los pagos digitales inmediatos y la facturaci\xF3n electr\xF3nica en sitio eliminan los retrasos de cobro, acortando dr\xE1sticamente el ciclo de efectivo (Cash Cycle) de la empresa."},{id:"ns_0541",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Monitor'. Se miden 480V en las 3 fases. \xBFQu\xE9 revisa?",opciones:["Desequilibrio de voltaje (unbalance) superior al 2% o monitor defectuoso.","La rotaci\xF3n de las fases que fue invertida en la alimentaci\xF3n principal.","El fusible de control de 24V que alimenta la bobina del contactor hoy.","La carga de refrigerante que podr\xEDa estar afectando la l\xF3gica de arranque."],respuesta_correcta:0,explicacion:"Con 480V estables en las tres fases, una falla del monitor de fase indica un desequilibrio de voltaje (unbalance) superior al 2% entre fases, o el propio monitor de fase est\xE1 defectuoso."},{id:"ns_0542",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta ruidos de martilleo al apagar. \xBFQu\xE9 revisa el Senior?",opciones:["V\xE1lvula de retenci\xF3n de descarga o falta de soportes en tuber\xEDa de cobre.","El capacitor de marcha que est\xE1 descargando energ\xEDa de forma err\xE1tica hoy.","Si el motor del ventilador del condensador tiene el aspa desequilibrada.","La carga de refrigerante que es tan alta que causa una sobrepresi\xF3n hoy."],respuesta_correcta:0,explicacion:"Los ruidos de martilleo al apagar ocurren cuando la presi\xF3n de descarga empuja refrigerante de vuelta a trav\xE9s del compresor por falta de una v\xE1lvula de retenci\xF3n. Tambi\xE9n pueden ser causados por tuber\xEDa sin soportes que vibra cuando el flujo de refrigerante se detiene abruptamente."},{id:"ns_0543",categoria:"NATE_SR_CEO",pregunta:"Usted es CEO. Un t\xE9cnico sufre una descarga el\xE9ctrica por no usar LOTO. \xBFResponsabilidad?",opciones:["La empresa es responsable por no asegurar el cumplimiento del protocolo OSHA.","Solo el t\xE9cnico es responsable por negligencia personal en el sitio de obra.","El cliente es responsable por no apagar el interruptor principal del edificio.","Nadie es responsable si el t\xE9cnico tiene su certificaci\xF3n NATE vigente hoy."],respuesta_correcta:0,explicacion:"Bajo OSHA, la empresa es responsable de implementar y hacer cumplir los protocolos de seguridad como LOTO; un accidente por incumplimiento es responsabilidad directa del empleador."},{id:"ns_0544",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split reporta error de 'Outdoor Coil Temp Sensor'. \xBFC\xF3mo afecta esto?",opciones:["El sistema no entrar\xE1 en modo de deshielo o lo har\xE1 de forma ineficiente.","El compresor inverter se bloquear\xE1 permanentemente por alta temperatura.","La unidad interior solo funcionar\xE1 en modo de ventilador hasta repararlo.","El ventilador exterior girar\xE1 a m\xE1xima velocidad sin importar la carga hoy."],respuesta_correcta:0,explicacion:"El sensor del serpent\xEDn exterior es necesario para detectar la formaci\xF3n de escarcha e iniciar el ciclo de deshielo. Sin este sensor, el deshielo no se activar\xE1 o funcionar\xE1 de forma ineficiente."},{id:"ns_0545",categoria:"NATE_SR_HVAC",pregunta:"Al aumentar la velocidad del aire a trav\xE9s de un serpent\xEDn fr\xEDo, el Delta T bajar\xE1. \xBFPor qu\xE9?",opciones:["Menor tiempo de contacto entre el aire y la superficie fr\xEDa del serpent\xEDn.","Aumento en la energ\xEDa latente del aire que compensa la p\xE9rdida de calor.","El refrigerante se evapora m\xE1s r\xE1pido y enfr\xEDa menos la masa de aire hoy.","La humedad relativa sube tanto que impide la transferencia de calor seco."],respuesta_correcta:0,explicacion:"Al aumentar la velocidad del aire, cada part\xEDcula de aire pasa menos tiempo en contacto con la superficie fr\xEDa del serpent\xEDn, absorbiendo menos calor. Aunque se mueve m\xE1s masa de aire (m\xE1s CFM), la diferencia de temperatura entre entrada y salida (Delta T) disminuye."},{id:"ns_0546",categoria:"NATE_SR_RACK",pregunta:"Se observa 'Short Cycling' en el compresor de lead de un rack. \xBFQu\xE9 ajuste realiza?",opciones:["Aumentar la banda muerta (deadband) o diferencial en el controlador rack.","Cambiar el sensor de presi\xF3n de succi\xF3n asumiendo que est\xE1 descalibrado.","A\xF1adir m\xE1s aceite al c\xE1rter para amortiguar el arranque del compresor hoy.","Reducir la velocidad del ventilador del condensador para subir la presi\xF3n."],respuesta_correcta:0,explicacion:"El ciclo corto (short cycling) ocurre cuando el diferencial entre el punto de encendido y apagado del compresor es insuficiente. Aumentar la banda muerta (deadband) en el controlador proporciona m\xE1s separaci\xF3n entre los setpoints de corte y arranque."},{id:"ns_0547",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que termin\xF3 el vac\xEDo en 5 minutos en un sistema de 5 toneladas. \xBFAcci\xF3n?",opciones:["Repetir el vac\xEDo; es f\xEDsicamente imposible eliminar humedad en ese tiempo.","Felicitar al t\xE9cnico por tener una bomba de vac\xEDo de gran capacidad (CFM).","Verificar el visor de l\xEDquido para confirmar si el sistema est\xE1 seco hoy.","Permitir la carga de gas si el vacu\xF3metro digital marca 499 micrones hoy."],respuesta_correcta:0,explicacion:"La evacuaci\xF3n de humedad es un proceso que requiere tiempo para que el agua atrapada en superficies y aceite se evapore a baja presi\xF3n. Cinco minutos son insuficientes para un sistema de 5 toneladas; el vac\xEDo r\xE1pido solo indica baja presi\xF3n, no ausencia de humedad."},{id:"ns_0548",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga manual. El t\xE9cnico observa que sale gas pero la presi\xF3n no baja. \xBFCausa?",opciones:["Hay aire atrapado y el gas que sale es una mezcla de aire y refrigerante.","La purga est\xE1 ubicada en el punto m\xE1s bajo del condensador por error hoy.","El refrigerante es de tipo azeotr\xF3pico y no se separa de los incondensables.","La temperatura del agua de la torre es demasiado alta para purgar aire hoy."],respuesta_correcta:0,explicacion:"Si al purgar sale gas pero la presi\xF3n no baja, es porque el gas expulsado es una mezcla de aire y refrigerante. El aire atrapado mantiene la presi\xF3n parcial elevada hasta que se extraiga completamente."},{id:"ns_0549",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n de 125 PSI y descarga de 450 PSI. El subenfriamiento es 20\xB0F. \xBFEstado?",opciones:["Sistema con exceso de carga de refrigerante (Overcharged) hoy hoy hoy.","Falta de refrigerante l\xEDquido que impide que la descarga suba a 500 PSI.","Restricci\xF3n en el dispositivo de expansi\xF3n que eleva la presi\xF3n de alta.","Compresor perdiendo eficiencia volum\xE9trica por desgaste de los pistones."],respuesta_correcta:0,explicacion:"Succi\xF3n de 125 PSI con descarga elevada de 450 PSI y subenfriamiento alto de 20\xB0F indica exceso de refrigerante. El condensador est\xE1 parcialmente inundado de l\xEDquido, lo que reduce su \xE1rea efectiva de condensaci\xF3n y eleva tanto la presi\xF3n de descarga como el subenfriamiento."},{id:"ns_0550",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir el 'Technician Efficiency'. \xBFQu\xE9 KPI es el m\xE1s preciso?",opciones:["Horas facturadas vs horas pagadas (Billable vs Non-Billable efficiency).","N\xFAmero total de llamadas de servicio terminadas por semana por t\xE9cnico.","Cantidad de ingresos generados en ventas de equipos nuevos mensualmente.","Reducci\xF3n en el costo de combustible de la camioneta asignada al t\xE9cnico."],respuesta_correcta:0,explicacion:"La eficiencia t\xE9cnica se mide con precisi\xF3n comparando las horas facturadas (Billable) vs. las horas pagadas (Non-Billable), revelando cu\xE1nto tiempo productivo genera ingresos."},{id:"ns_0551",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller de tornillo tiene una falla de 'Slide Valve Failure'. \xBFC\xF3mo afecta esto?",opciones:["El compresor no podr\xE1 modular su capacidad y operar\xE1 a carga fija hoy.","El compresor se bloquear\xE1 mec\xE1nicamente y no podr\xE1 arrancar del todo hoy.","La presi\xF3n de aceite bajar\xE1 dr\xE1sticamente causando un paro por seguridad.","El motor consumir\xE1 el doble de amperaje al intentar mover la v\xE1lvula hoy."],respuesta_correcta:0,explicacion:"La v\xE1lvula de corredera (slide valve) controla la capacidad del compresor de tornillo. Si falla, el compresor no puede modular y opera a carga fija, sin poder adaptarse a la demanda del edificio."},{id:"ns_0552",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, se observa que una vitrina descongela pero las otras no. \xBFQu\xE9 revisa?",opciones:["La l\xF3gica de grupos de deshielo en el controlador principal del rack hoy.","Si la v\xE1lvula solenoide de gas caliente de esa vitrina est\xE1 abierta hoy.","La presi\xF3n del recibidor que podr\xEDa estar demasiado baja para el empuje.","El sensor de temperatura de ambiente que bloquea el deshielo por calor."],respuesta_correcta:0,explicacion:"Si solo una vitrina descongela y las dem\xE1s no, la programaci\xF3n de grupos de deshielo en el controlador puede estar incorrecta. Los grupos definen qu\xE9 vitrinas entran en deshielo simult\xE1neamente y si alguna fue excluida por error de configuraci\xF3n."},{id:"ns_0553",categoria:"NATE_SR_CEO",pregunta:"Un CEO eval\xFAa el 'Current Ratio'. Si el valor es de 0.8, \xBFqu\xE9 significa hoy?",opciones:["La empresa tiene dificultades de liquidez para pagar deudas a corto plazo.","La empresa es extremadamente rentable y tiene un flujo de caja excelente.","Los activos fijos superan a los pasivos circulantes en un margen del 20%.","La empresa califica para los mejores pr\xE9stamos bancarios de la industria."],respuesta_correcta:0,explicacion:"Un Current Ratio de 0.8 significa que los activos corrientes no cubren los pasivos corrientes; la empresa tiene dificultades de liquidez para pagar deudas a corto plazo."},{id:"ns_0554",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter muestra el error 'Outdoor Unit AC Leakage'. \xBFQu\xE9 revisa?",opciones:["Fuga de corriente a tierra en el compresor o motor del ventilador hoy.","Fuga de refrigerante en las conexiones flare de la unidad exterior hoy.","Voltaje de l\xEDnea el\xE9ctrica superior a los 260VAC que satura la placa.","Si hay humedad condensada dentro de la caja de control electr\xF3nica hoy."],respuesta_correcta:0,explicacion:"El error 'AC Leakage' indica fuga de corriente a tierra. En la unidad exterior, las causas principales son el aislamiento deteriorado del compresor o del motor del ventilador que permite corriente a tierra."},{id:"ns_0555",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene un Delta T de 15\xB0F. El Senior mide el amperaje del motor soplador y es bajo. \xBFCausa?",opciones:["Filtros de aire sucios o serpent\xEDn del evaporador obstruido por polvo hoy.","Falta de refrigerante l\xEDquido que reduce la carga t\xE9rmica del sistema hoy.","El motor del soplador est\xE1 girando a una velocidad excesiva para el ducto.","Las rejillas de suministro est\xE1n completamente abiertas permitiendo flujo."],respuesta_correcta:0,explicacion:"Un Delta T alto con amperaje bajo del soplador indica flujo de aire reducido. Un motor PSC consume menos amperaje cuando tiene restricci\xF3n (filtros sucios o evaporador obstruido), ya que la carga mec\xE1nica disminuye con menos flujo."},{id:"ns_0556",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calor, una bomba de calor presenta alta descarga y alta succi\xF3n. \xBFQu\xE9 fall\xF3?",opciones:["La v\xE1lvula inversora est\xE1 fugando bypass o el compresor perdi\xF3 eficiencia.","Falta de refrigerante l\xEDquido que impide que el sistema alcance presi\xF3n.","El ventilador exterior est\xE1 apagado bloqueando la absorci\xF3n de calor hoy.","Exceso de carga de refrigerante que inunda el serpent\xEDn de la interior hoy."],respuesta_correcta:0,explicacion:"Succion alta y descarga alta con perdida de capacidad es sintoma de fuga interna en la valvula inversora. El gas de descarga se recircula a la succion, elevando ambas presiones sin transferir calor util."},{id:"ns_0557",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior observa que un ayudante carga refrigerante en estado gaseoso a una mezcla zeotr\xF3pica. \xBFRiesgo?",opciones:["Fraccionamiento de la mezcla y p\xE9rdida de las propiedades de dise\xF1o hoy.","Da\xF1o mec\xE1nico a las v\xE1lvulas del compresor por la velocidad del gas hoy.","Que el aceite POE se separe del refrigerante y tape el filtro hoy hoy hoy.","No hay riesgo si el sistema est\xE1 operando a plena carga t\xE9rmica hoy hoy."],respuesta_correcta:0,explicacion:"Las mezclas zeotr\xF3picas (como R-407C, R-410A) deben cargarse en estado l\xEDquido porque sus componentes tienen diferentes presiones de vapor. Cargar en gas causa fraccionamiento: los componentes m\xE1s vol\xE1tiles entran primero, alterando la composici\xF3n de dise\xF1o."},{id:"ns_0558",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Low Approach' de condensador (0.5\xB0F). \xBFC\xF3mo lo interpreta?",opciones:["Sensores descalibrados o transferencia t\xE9rmica perfecta por limpieza hoy.","Falta de refrigerante l\xEDquido que no cubre los tubos del intercambiador.","Flujo de agua de torre excesivo que falsea la lectura del termistor hoy.","El compresor est\xE1 operando a su m\xE1xima frecuencia de rotaci\xF3n mec\xE1nica."],respuesta_correcta:0,explicacion:"Un approach de condensador de 0.5\xB0F es extremadamente bajo y puede indicar sensores descalibrados, o una transferencia t\xE9rmica excepcionalmente buena por tubos reci\xE9n limpiados."},{id:"ns_0559",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 135 PSI y descarga de 400 PSI con R-410A. \xBFC\xF3mo est\xE1?",opciones:["Funcionamiento normal para un d\xEDa con carga t\xE9rmica alta y calor hoy hoy.","Falta de refrigerante leve que impide que la descarga suba a 500 PSI.","Exceso de carga que est\xE1 elevando la succi\xF3n por encima de los 120 PSI.","Compresor defectuoso que no logra crear el diferencial de presi\xF3n hoy."],respuesta_correcta:0,explicacion:"Con R-410A, succi\xF3n de 135 PSI (~44\xB0F sat.) y descarga de 400 PSI (~109\xB0F sat.) son valores normales para un d\xEDa con carga t\xE9rmica alta. Las presiones est\xE1n dentro de los rangos de dise\xF1o y el sistema opera correctamente."},{id:"ns_0560",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar el 'Billable Ratio' de su equipo. \xBFQu\xE9 acci\xF3n toma?",opciones:["Optimizar el despacho para reducir el tiempo de viaje entre llamadas hoy.","Obligar a los t\xE9cnicos a cobrar un m\xEDnimo de 2 horas por cada visita hoy.","Reducir el salario base y aumentar las comisiones por ventas de equipos.","Eliminar el uso de software de gesti\xF3n para ahorrar en licencias hoy hoy."],respuesta_correcta:0,explicacion:"Optimizar el despacho para reducir el tiempo de viaje entre llamadas aumenta las horas facturables por d\xEDa, mejorando directamente el Billable Ratio del equipo."},{id:"ns_0561",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Motor Temperature' con amperaje normal. \xBFQu\xE9 revisa?",opciones:["La l\xEDnea de enfriamiento del motor (refrigerante l\xEDquido) y su filtro hoy.","La viscosidad del aceite que podr\xEDa estar causando fricci\xF3n en motor hoy.","El flujo de agua en el condensador que es insuficiente para enfriar hoy.","Si el compresor opera con un voltaje excesivamente alto o bajo hoy hoy."],respuesta_correcta:0,explicacion:"Con amperaje normal, la falla de temperatura del motor apunta a un problema en el sistema de enfriamiento del motor por refrigerante l\xEDquido. La l\xEDnea de enfriamiento o su filtro pueden estar bloqueados."},{id:"ns_0562",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no arranca y el LED parpadea 3 veces. \xBFQu\xE9 hace el Senior?",opciones:["Consultar el manual t\xE9cnico para descodificar el c\xF3digo de error hoy hoy.","Resetear el breaker y esperar a que el sistema se repare solo hoy hoy.","Cambiar la placa exterior asumiendo que es una falla com\xFAn de marca hoy.","Agregar 1 libra de refrigerante para ver si el error desaparece hoy hoy."],respuesta_correcta:0,explicacion:"Los patrones de parpadeo del LED son c\xF3digos de diagn\xF3stico propios de cada fabricante. El Senior siempre consulta el manual t\xE9cnico para decodificar el error espec\xEDfico antes de actuar."},{id:"ns_0563",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene un sobrecalentamiento de 35\xB0F y subenfriamiento de 12\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido (Undercharged) o restricci\xF3n en la TXV hoy.","Exceso de carga de refrigerante que inunda el evaporador interior hoy.","Filtro de aire extremadamente sucio que reduce la carga t\xE9rmica hoy hoy.","El compresor est\xE1 perdiendo eficiencia y no succiona refrigerante hoy."],respuesta_correcta:0,explicacion:"Un sobrecalentamiento alto de 35\xB0F indica que el evaporador no recibe suficiente refrigerante l\xEDquido. Con subenfriamiento de 12\xB0F (aceptable), la causa m\xE1s probable es falta de carga o una restricci\xF3n en la TXV que limita el flujo de refrigerante al evaporador."},{id:"ns_0564",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calor, una bomba de calor presenta ruidos de martilleo hidr\xE1ulico. \xBFCausa?",opciones:["Retorno de l\xEDquido al compresor debido a una TXV exterior abierta hoy.","La v\xE1lvula inversora est\xE1 cambiando de posici\xF3n de forma aleatoria hoy.","El aceite del sistema est\xE1 demasiado fr\xEDo y golpea los pistones hoy hoy.","Es un sonido normal cuando las resistencias el\xE9ctricas se expanden hoy."],respuesta_correcta:0,explicacion:"Los ruidos de martilleo hidraulico ocurren cuando refrigerante liquido entra al compresor. Una TXV exterior abierta en modo calor permite paso excesivo de liquido que no se evapora completamente antes del compresor."},{id:"ns_0565",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que el 'DSO' (Days Sales Outstanding) es de 60 d\xEDas. \xBFQu\xE9 significa?",opciones:["La empresa tarda 60 d\xEDas en promedio en cobrar sus facturas emitidas hoy.","La empresa tiene suficiente capital para operar durante los pr\xF3ximos 60 d\xEDas.","Los t\xE9cnicos tardan 60 d\xEDas en promedio en terminar una instalaci\xF3n hoy.","El inventario en el almac\xE9n se renueva cada 60 d\xEDas de forma constante hoy."],respuesta_correcta:0,explicacion:"Un DSO de 60 d\xEDas significa que la empresa tarda en promedio 60 d\xEDas en cobrar sus facturas emitidas, lo cual es alto y puede crear problemas de flujo de caja."},{id:"ns_0566",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 indica una temperatura de succi\xF3n muy fr\xEDa (escarcha en el cabezal)?",opciones:["Retorno de refrigerante l\xEDquido que pone en riesgo a los compresores hoy.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de enfriamiento hoy.","Falta de refrigerante en el recibidor que causa una expansi\xF3n prematura.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n abiertas al 100% hoy hoy."],respuesta_correcta:0,explicacion:"La escarcha en el cabezal de succi\xF3n indica que refrigerante l\xEDquido est\xE1 llegando sin evaporarse completamente. El l\xEDquido enfr\xEDa la tuber\xEDa por debajo del punto de roc\xEDo del aire, formando escarcha. Esto es un riesgo directo de golpe de l\xEDquido."},{id:"ns_0567",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior debe explicar el 'GWP' a un aprendiz. \xBFQu\xE9 significa hoy?",opciones:["Potencial de calentamiento global del refrigerante usado en el equipo hoy.","Garant\xEDa de piezas y mano de obra que ofrece el fabricante del sistema.","Eficiencia energ\xE9tica total del equipo en condiciones extremas de calor.","Presi\xF3n m\xE1xima de trabajo que puede soportar el serpent\xEDn de cobre hoy hoy."],respuesta_correcta:0,explicacion:"GWP (Global Warming Potential) indica el impacto ambiental de un refrigerante en comparaci\xF3n con el CO2 (GWP=1). Refrigerantes como R-410A tienen GWP de 2088, mientras que los nuevos R-32 y R-454B tienen GWP mucho menor."},{id:"ns_0568",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'High Approach' de evaporador (15\xB0F). El agua fluye bien. \xBFAcci\xF3n?",opciones:["Limpieza mec\xE1nica de tubos del evaporador y an\xE1lisis de agua helada hoy.","Agregar refrigerante l\xEDquido hasta que el approach baje a 2 grados hoy.","Aumentar la velocidad de la bomba de agua mediante el variador de frecuencia.","Ignorar el valor si la temperatura de salida del agua es la correcta hoy hoy."],respuesta_correcta:0,explicacion:"Un approach alto de evaporador (15\xB0F) con flujo correcto indica fouling severo en los tubos. La limpieza mec\xE1nica y el an\xE1lisis del agua helada son necesarios para restaurar la transferencia t\xE9rmica."},{id:"ns_0569",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 420 PSI con R-410A. \xBFC\xF3mo est\xE1?",opciones:["Falta de refrigerante leve o condensador exterior parcialmente sucio hoy.","Funcionamiento normal para un d\xEDa caluroso con carga t\xE9rmica est\xE1ndar hoy.","Exceso de carga de refrigerante que inunda el condensador del sistema hoy.","Compresor con eficiencia reducida que no puede bombear gas correctamente."],respuesta_correcta:0,explicacion:"Succi\xF3n de 110 PSI (ligeramente baja) con descarga de 420 PSI (ligeramente alta) sugiere falta de refrigerante leve o un condensador parcialmente sucio. La succi\xF3n baja indica menos refrigerante en el evaporador, mientras la descarga elevada puede indicar pobre disipaci\xF3n de calor."},{id:"ns_0570",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Customer Churn'. \xBFQu\xE9 estrategia es la m\xE1s efectiva?",opciones:["Plan de membres\xEDas de mantenimiento con visitas programadas y beneficios.","Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy.","Gastar m\xE1s dinero en anuncios de Google para atraer siempre clientes nuevos.","Despedir a los t\xE9cnicos que no logren vender un sistema nuevo cada semana."],respuesta_correcta:0,explicacion:"Un plan de membres\xEDas de mantenimiento con visitas programadas y beneficios exclusivos reduce el churn al crear un v\xEDnculo continuo y valor percibido por el cliente."},{id:"ns_0571",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula solenoide en la l\xEDnea de l\xEDquido de cada vitrina?",opciones:["Controlar la temperatura de la vitrina mediante el corte del flujo l\xEDquido.","Evitar que el aceite se acumule en el evaporador durante el funcionamiento.","Aumentar el subenfriamiento del refrigerante antes de entrar a la TXV hoy.","Proteger al compresor de un posible retorno de l\xEDquido en el arranque hoy."],respuesta_correcta:0,explicacion:"La solenoide de l\xEDquido corta el suministro de refrigerante a la vitrina cuando se satisface la temperatura. Al cerrar, inicia un pump-down del evaporador que evita la acumulaci\xF3n de l\xEDquido y permite un control preciso de temperatura."},{id:"ns_0572",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Loss'. \xBFQu\xE9 componente protege al motor?",opciones:["Monitor de fase o rel\xE9 de sobrecarga de estado s\xF3lido del sistema hoy hoy.","Fusibles de retardo de tiempo instalados en la desconexi\xF3n principal hoy.","Interruptor termomagn\xE9tico de la placa de control de 120 voltios hoy hoy.","Contactor magn\xE9tico que se abrir\xE1 por falta de voltaje en la bobina hoy."],respuesta_correcta:0,explicacion:"El monitor de fase y el rel\xE9 de sobrecarga de estado s\xF3lido son los dispositivos dise\xF1ados espec\xEDficamente para detectar p\xE9rdida de fase y proteger el motor del compresor contra da\xF1os."},{id:"ns_0573",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. \xBFCausa?",opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.","La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido.","La humedad en la habitaci\xF3n es superior al 95% y satura el serpent\xEDn hoy."],respuesta_correcta:0,explicacion:"Cuando el goteo ocurre solo al parar el compresor, el agua retenida por contrapendiente o bloqueo parcial en el drenaje se libera cuando cesan la vibraci\xF3n y el flujo de aire de la unidad."},{id:"ns_0574",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de 0.9 en suministro y 0.2 en retorno. \xBFProblema?",opciones:["Restricci\xF3n severa en conductos de suministro o difusores cerrados hoy hoy.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire hoy.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo hoy hoy.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o hoy hoy."],respuesta_correcta:0,explicacion:'Con presi\xF3n est\xE1tica de 0.9" en suministro y solo 0.2" en retorno, la mayor parte de la restricci\xF3n del sistema est\xE1 en el lado de suministro. Conductos restringidos, aplastados o difusores cerrados causan esta distribuci\xF3n de presi\xF3n desproporcionada.'},{id:"ns_0575",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre 20\xB0F y 30\xB0F hoy.","S\xED, las bombas de calor siempre tienen un diferencial menor que hornos hoy.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en modo calor es bajo. El rango normal es 20-30F. Un diferencial insuficiente indica problemas como baja carga de refrigerante, flujo de aire excesivo, o fallas en el serpentin exterior."},{id:"ns_0576",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. \xBFQu\xE9 paso es vital post-quemadura?",opciones:["Realizar prueba de acidez del aceite y usar filtros succi\xF3n de limpieza hoy.","A\xF1adir aditivo sellador de fugas para prevenir fallas futuras en l\xEDneas hoy.","Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.","Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy hoy."],respuesta_correcta:0,explicacion:"Una quemadura de compresor genera \xE1cidos y part\xEDculas carbonizadas que contaminan todo el circuito frigor\xEDfico. La prueba de acidez del aceite cuantifica la contaminaci\xF3n, y los filtros de succi\xF3n de limpieza capturan residuos antes de que lleguen al compresor nuevo."},{id:"ns_0577",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. \xBFEstado?",opciones:["Funcionamiento correcto; la purga est\xE1 separando los no condensables hoy hoy.","Falla en el serpent\xEDn de condensaci\xF3n interno de la unidad de purga hoy hoy.","El sistema tiene una fuga masiva de agua hacia el lado del refrigerante hoy.","La temperatura del evaporador es demasiado alta para que la purga trabaje."],respuesta_correcta:0,explicacion:"La purga que expulsa mucho aire pero poco refrigerante est\xE1 cumpliendo su funci\xF3n correctamente: separar y expulsar los gases no condensables mientras retiene el refrigerante en el sistema."},{id:"ns_0578",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si el 'Oil Separator' queda pegado en posici\xF3n abierta?",opciones:["Gas caliente de descarga pasar\xE1 directo al dep\xF3sito aceite y succi\xF3n hoy hoy.","El rack se quedar\xE1 sin aceite en pocos minutos al no poder separarlo gas.","Los compresores se apagar\xE1n por alta presi\xF3n al bloquearse el flujo gas.","El nivel de aceite en los c\xE1rteres subir\xE1 tanto que da\xF1ar\xE1 los pistones hoy."],respuesta_correcta:0,explicacion:"El flotador del separador abierto permanentemente crea un camino directo para el gas caliente de descarga hacia el dep\xF3sito de aceite. Este gas a alta presi\xF3n puede empujar aceite y gas hacia la succi\xF3n, reduciendo la eficiencia del sistema."},{id:"ns_0579",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. \xBFQu\xE9 KPI usa?",opciones:["N\xFAmero de llamadas de nuevos clientes que mencionan haber visto la unidad hoy.","La cantidad de millas recorridas por cada veh\xEDculo en zonas residenciales.","El costo total del dise\xF1o e instalaci\xF3n del r\xF3tulo dividido entre 12 meses.","El aumento en la velocidad promedio de t\xE9cnicos al conducir camionetas nuevas."],respuesta_correcta:0,explicacion:"La m\xE9trica clave para camionetas rotuladas es rastrear las llamadas de nuevos clientes que espec\xEDficamente mencionan haber visto el veh\xEDculo, conectando visibilidad con conversi\xF3n."},{id:"ns_0580",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. \xBFQu\xE9 revisa?",opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy hoy.","La carga de refrigerante l\xEDquido bas\xE1ndose en el visor del evaporador hoy hoy.","Si la v\xE1lvula de expansi\xF3n est\xE1 inyectando demasiado l\xEDquido al sistema.","El estado de los filtros de aire de la manejadora de aire del edificio hoy."],respuesta_correcta:0,explicacion:"La alta presi\xF3n de condensaci\xF3n en un chiller con condensador de agua se diagnostica verificando primero la temperatura del agua de torre y el funcionamiento de la bomba de condensador."},{id:"ns_0581",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n de 125 PSI y descarga 400 PSI con R-410A. \xBFEstado aire?",opciones:["Funcionamiento normal bajo condiciones de carga t\xE9rmica est\xE1ndar hoy hoy hoy.","Falta de refrigerante que impide que temperatura del aire baje a 55 grados.","Exceso de carga que est\xE1 elevando la presi\xF3n de descarga innecesariamente.","Compresor con eficiencia reducida que no logra enfriar el aire correctamente."],respuesta_correcta:0,explicacion:"Succi\xF3n de 125 PSI y descarga de 400 PSI con R-410A representan valores dentro del rango normal de operaci\xF3n. El diferencial de presi\xF3n es adecuado para una carga t\xE9rmica est\xE1ndar, indicando que el sistema funciona correctamente."},{id:"ns_0582",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. \xBFQu\xE9 estrategia?",opciones:["Programa de membres\xEDas mantenimiento para convertir clientes en recurrentes hoy.","Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy.","Gastar m\xE1s dinero en anuncios de Google para atraer siempre clientes nuevos.","Despedir a t\xE9cnicos que no logren vender un sistema nuevo en cada visita."],respuesta_correcta:0,explicacion:"Las membres\xEDas de mantenimiento son la estrategia m\xE1s efectiva para convertir clientes de una sola visita en clientes recurrentes con ingresos predecibles."},{id:"ns_0583",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. \xBFQu\xE9 revisa?",opciones:["Carga de refrigerante baja o una restricci\xF3n en la v\xE1lvula de expansi\xF3n hoy.","Si el ventilador interior est\xE1 sucio y no sopla suficiente aire fr\xEDo hoy hoy.","El voltaje de la l\xEDnea el\xE9ctrica que podr\xEDa estar por debajo de 200V hoy hoy.","Si el control remoto est\xE1 configurado en una temperatura demasiado baja hoy."],respuesta_correcta:0,explicacion:"La temperatura de descarga excesiva del compresor se debe a falta de refrigerante (el gas no enfr\xEDa suficientemente el compresor) o una restricci\xF3n en la EEV que limita el flujo."},{id:"ns_0584",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba calor, \xBFqu\xE9 sucede si 'Check Valve' condensador falla abierta?",opciones:["En modo calor el refrigerante har\xE1 bypass a TXV impidiendo calentamiento hoy.","El sistema funcionar\xE1 mejor al haber menos restricci\xF3n al flujo l\xEDquido.","La presi\xF3n de descarga subir\xE1 hasta que switch de alta apague el equipo.","El compresor se quemar\xE1 por el retorno de l\xEDquido masivo en el arranque hoy."],respuesta_correcta:0,explicacion:"Si la check valve del condensador falla abierta, el refrigerante hace bypass a la TXV en modo calor. Sin la restriccion del dispositivo de expansion, no hay cambio de estado adecuado y el calentamiento se pierde."},{id:"ns_0585",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula 'Quench' o inyecci\xF3n de l\xEDquido?",opciones:["Para enfriar gas de succi\xF3n y evitar que descarga da\xF1e el aceite hoy hoy hoy.","Para aumentar la presi\xF3n de succi\xF3n cuando carga en vitrinas es baja hoy hoy.","Para limpiar el interior de compresores de acumulaciones de carbonilla hoy hoy.","Para ayudar al retorno de aceite desde los evaporadores m\xE1s lejanos hoy hoy hoy."],respuesta_correcta:0,explicacion:"La inyecci\xF3n de l\xEDquido (Quench) enfr\xEDa el gas para mantener la temperatura de descarga dentro de l\xEDmites seguros. Las temperaturas excesivas descomponen el aceite lubricante, formando \xE1cidos y dep\xF3sitos que da\xF1an el compresor."},{id:"ns_0586",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. \xBFCriterio?",opciones:["El volumen de agua y la accesibilidad para eliminaci\xF3n segura del fluido hoy.","Cu\xE1l de las dos herramientas es m\xE1s nueva y hace menos ruido al operar hoy.","La preferencia del cliente sobre qu\xE9 herramienta quiere ver en su casa hoy hoy.","Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy hoy."],respuesta_correcta:0,explicacion:"La elecci\xF3n entre aspiradora y bomba depende de factores t\xE9cnicos: volumen total del agua acumulada y accesibilidad del espacio. Estas condiciones determinan cu\xE1l herramienta es m\xE1s eficiente y segura para la situaci\xF3n espec\xEDfica."},{id:"ns_0587",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene purga que marca 'Water Detected'. \xBFQu\xE9 acci\xF3n es urgente?",opciones:["Realizar prueba presi\xF3n a tubos del evaporador para buscar rupturas hoy hoy.","Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.","Aumentar la temperatura del agua helada para evitar que vapor condense hoy hoy.","Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy hoy."],respuesta_correcta:0,explicacion:"Agua detectada por la purga requiere una prueba de presi\xF3n urgente en los tubos del evaporador, ya que la fuente m\xE1s probable de contaminaci\xF3n por agua es una ruptura en el intercambiador."},{id:"ns_0588",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n 130 PSI y descarga 380 PSI. Subenfriamiento 12\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y el subenfriamiento est\xE1n en rango hoy.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser 15 grados hoy hoy.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno hoy.","Compresor fallando; la diferencia presi\xF3n entre succi\xF3n y descarga es baja hoy."],respuesta_correcta:0,explicacion:"Presiones de succi\xF3n de 130 PSI y descarga de 380 PSI con subenfriamiento de 12\xB0F son valores que caen dentro del rango \xF3ptimo de operaci\xF3n para R-410A. El subenfriamiento entre 10-15\xB0F es ideal para confirmar carga correcta y operaci\xF3n eficiente del condensador."},{id:"ns_0589",categoria:"NATE_SR_PACKAGE",pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["El voltaje en la bobina (24V) y si hay suciedad u \xF3xido en el n\xFAcleo hoy hoy.","Si los contactos principales est\xE1n quemados o soldados entre s\xED hoy hoy hoy hoy.","El capacitor de arranque del compresor que podr\xEDa estar descargado hoy hoy hoy.","La continuidad de los fusibles de potencia de la l\xEDnea de 240 voltios hoy hoy."],respuesta_correcta:0,explicacion:"Un contactor que zumba sin completar el cierre tiene un problema electromagn\xE9tico o mec\xE1nico. El voltaje bajo en la bobina no genera suficiente fuerza de atracci\xF3n, y la suciedad u \xF3xido en el n\xFAcleo crea un entrehierro que impide el cierre completo de la armadura."},{id:"ns_0590",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico cobra 'por fuera' a clientes. \xBFQu\xE9 acci\xF3n toma?",opciones:["Despido inmediato y posible acci\xF3n legal seg\xFAn el contrato de trabajo hoy hoy.","Hablar con el t\xE9cnico y pedirle una comisi\xF3n por esos trabajos extras hoy hoy.","Ignorar la situaci\xF3n si el t\xE9cnico es el que m\xE1s dinero genera hoy hoy hoy hoy.","Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy hoy."],respuesta_correcta:0,explicacion:"El cobro por fuera es fraude laboral; el despido inmediato con posible acci\xF3n legal es la \xFAnica respuesta que protege la integridad y los ingresos de la empresa."},{id:"ns_0591",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFPor qu\xE9 es fundamental cargar l\xEDquido en el recibidor?",opciones:["Para evitar fraccionamiento de la mezcla y asegurar composici\xF3n correcta hoy hoy.","Para que el refrigerante se mezcle m\xE1s r\xE1pido con el aceite POE del rack hoy.","Para prevenir que las v\xE1lvulas de descarga de compresores se calienten hoy hoy.","Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal hoy."],respuesta_correcta:0,explicacion:"El R-448A contiene m\xFAltiples componentes con diferentes volatilidades. Cargar en l\xEDquido asegura que la proporci\xF3n de cada componente se mantiene exacta, evitando el fraccionamiento que alterar\xEDa las propiedades de la mezcla."},{id:"ns_0592",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. \xBFEfecto?",opciones:["El controlador no podr\xE1 calcular la carga t\xE9rmica real del edificio hoy hoy.","El compresor se apagar\xE1 inmediatamente por seguridad de flujo de agua hoy hoy.","La unidad operar\xE1 siempre al 100% de su capacidad nominal sin modular hoy hoy.","No hay efecto si el sensor de 'Leaving Water' est\xE1 operando correctamente hoy hoy."],respuesta_correcta:0,explicacion:"Sin el sensor de entering water, el controlador no puede calcular el Delta T ni la carga t\xE9rmica real del edificio, impidiendo la modulaci\xF3n correcta de la capacidad del chiller."},{id:"ns_0593",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de descarga de 550 PSI con R-410A. \xBFCausa?",opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy hoy hoy.","Falta de refrigerante l\xEDquido que impide que el sistema enfr\xEDe el aire hoy hoy.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total hoy.","El compresor est\xE1 perdiendo eficiencia y no logra comprimir el gas ralo hoy hoy."],respuesta_correcta:0,explicacion:"Una descarga de 550 PSI con R-410A es extremadamente peligrosa (l\xEDmite de operaci\xF3n ~600 PSI). Un condensador sucio impide la disipaci\xF3n de calor, y un ventilador exterior fallando elimina la convecci\xF3n forzada, ambos causando acumulaci\xF3n extrema de presi\xF3n en el lado de alta."},{id:"ns_0594",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Average Response Time'. \xBFQu\xE9 medida toma hoy?",opciones:["Implementar software de despacho inteligente y zonificaci\xF3n de t\xE9cnicos hoy hoy.","Aumentar el n\xFAmero de t\xE9cnicos en la n\xF3mina aunque no haya llamadas suficientes.","Reducir el tiempo de almuerzo de los t\xE9cnicos para que est\xE9n m\xE1s disponibles hoy.","Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy."],respuesta_correcta:0,explicacion:"El software de despacho inteligente con zonificaci\xF3n geogr\xE1fica asigna al t\xE9cnico m\xE1s cercano y disponible, reduciendo dr\xE1sticamente el tiempo de respuesta a emergencias."},{id:"ns_0595",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. \xBFCausa?",opciones:["Falla de comunicaci\xF3n; el voltaje deber\xEDa fluctuar entre 0 y 24VDC hoy hoy hoy.","La placa exterior est\xE1 operando correctamente enviando la se\xF1al de control hoy.","El compresor inverter est\xE1 aterrizado y consume el voltaje de comunicaci\xF3n hoy.","Falta de alimentaci\xF3n de 240VAC en los terminales L1 y L2 de la exterior hoy hoy."],respuesta_correcta:0,explicacion:"En sistemas inverter, la se\xF1al de comunicaci\xF3n entre S2 y S3 debe ser un voltaje DC pulsante (0-24V). Un voltaje fijo de 24VDC indica ausencia de modulaci\xF3n de datos: falla de comunicaci\xF3n."},{id:"ns_0596",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el 'Defrost Sensor' falla en circuito abierto?",opciones:["El sistema nunca entrar\xE1 en modo de deshielo y el serpent\xEDn se congelar\xE1 hoy.","El sistema entrar\xE1 en modo de deshielo cada 30 minutos sin importar el hielo hoy.","El compresor se quemar\xE1 debido a la falta de control de sobrecalentamiento hoy.","La unidad operar\xE1 solo en modo refrigeraci\xF3n permanentemente por seguridad hoy."],respuesta_correcta:0,explicacion:"Si el sensor de defrost falla en circuito abierto, la placa no recibe la senal de temperatura baja del serpentin. Sin esta senal, el sistema nunca cumple la condicion para iniciar el deshielo y el hielo se acumula."},{id:"ns_0597",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un sistema VRF. \xBFPor qu\xE9 es vital pesar la carga?",opciones:["Los sistemas VRF son de carga cr\xEDtica y las presiones no son indicadores hoy hoy.","Es un requisito legal de la EPA para sistemas con m\xE1s de 50 libras de gas hoy.","Para asegurar que el aceite POE regrese correctamente a los compresores hoy hoy.","Para evitar que la garant\xEDa del fabricante se anule tras la instalaci\xF3n hoy hoy."],respuesta_correcta:0,explicacion:"Los sistemas VRF operan con m\xFAltiples evaporadores a diferentes cargas, haciendo que las presiones var\xEDen constantemente. La \xFAnica forma confiable de asegurar la carga correcta es pesar el refrigerante seg\xFAn la f\xF3rmula del fabricante."},{id:"ns_0598",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Reversal'. \xBFQu\xE9 sucede si se ignora el error?",opciones:["El compresor girar\xE1 al rev\xE9s y no bombear\xE1 aceite ni refrigerante l\xEDquido hoy hoy.","La unidad funcionar\xE1 al 50% de su capacidad nominal debido al desfase fase hoy.","El motor se quemar\xE1 instant\xE1neamente al intentar vencer la inercia carga hoy hoy.","Las v\xE1lvulas de expansi\xF3n se cerrar\xE1n por seguridad al detectar el error hoy hoy."],respuesta_correcta:0,explicacion:"La inversi\xF3n de fases provoca rotaci\xF3n inversa del compresor centr\xEDfugo. Sin bombeo de aceite ni circulaci\xF3n de refrigerante correcta, el equipo sufre da\xF1os mec\xE1nicos por falta de lubricaci\xF3n."},{id:"ns_0599",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. Subenfriamiento 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido severa en el sistema (Undercharged) hoy hoy hoy.","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total hoy hoy hoy.","Condensador exterior extremadamente sucio que no permite el intercambio t\xE9rmico.","Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."],respuesta_correcta:0,explicacion:"Subenfriamiento de 0\xB0F significa que sale vapor o mezcla bif\xE1sica del condensador en lugar de l\xEDquido puro. Con presiones no extremas, esto confirma una falta severa de refrigerante que no alcanza para llenar el condensador con l\xEDquido subenfriado."},{id:"ns_0600",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n hoy hoy.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada hoy hoy hoy.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial hoy hoy hoy.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos hoy hoy."],respuesta_correcta:0,explicacion:"El mercado de Smart Homes demanda t\xE9cnicos con habilidades en redes y protocolos de comunicaci\xF3n IoT para integrar termostatos, sensores y sistemas HVAC inteligentes."},{id:"ns_0601",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta una falla de 'Low Differential Pressure' en el evaporador. La bomba est\xE1 encendida y el variador marca 60Hz. \xBFQu\xE9 revisa el Senior?",opciones:["V\xE1lvulas de aislamiento parcialmente cerradas o cedazo (strainer) de agua obstruido.","Carga de refrigerante insuficiente que impide la ebullici\xF3n dentro de los tubos.","Sentido de rotaci\xF3n del compresor centr\xEDfugo tras un mantenimiento el\xE9ctrico.","Ajuste del set-point de temperatura de salida del agua helada al edificio."],respuesta_correcta:0,explicacion:"Con la bomba a 60Hz y baja presi\xF3n diferencial en el evaporador, las v\xE1lvulas de aislamiento parcialmente cerradas o un cedazo obstruido son las causas m\xE1s probables de restricci\xF3n de flujo de agua."},{id:"ns_0602",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo con CO2 (R-744), se produce un disparo de la v\xE1lvula de seguridad del recibidor durante un apag\xF3n. \xBFPor qu\xE9 ocurre esto?",opciones:["La presi\xF3n cr\xEDtica del CO2 se alcanza r\xE1pidamente al subir la temperatura ambiente.","El aceite se separa del refrigerante y genera una reacci\xF3n qu\xEDmica de alta presi\xF3n.","La v\xE1lvula de bypass de gas flash se bloque\xF3 en la posici\xF3n de abierta total.","El condensador evaporativo se vaci\xF3 y no hay forma de rechazar el calor latente."],respuesta_correcta:0,explicacion:"El CO2 tiene una presi\xF3n cr\xEDtica de 1070 PSI a 87.8\xB0F. Sin compresores ni condensador funcionando durante un apag\xF3n, la temperatura del CO2 sube con el ambiente, la presi\xF3n aumenta r\xE1pidamente hacia el punto cr\xEDtico y las v\xE1lvulas de seguridad se abren."},{id:"ns_0603",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que el 15% del inventario en las camionetas est\xE1 'obsoleto' o da\xF1ado. \xBFQu\xE9 sistema de control implementa?",opciones:["Inventario rotativo (Cycle Counting) y estandarizaci\xF3n de stock cr\xEDtico por unidad.","Prohibir que los t\xE9cnicos lleven piezas y obligarlos a ir al almac\xE9n central cada vez.","Descontar el valor de las piezas da\xF1adas directamente del bono de productividad t\xE9cnico.","Aumentar el tama\xF1o de las camionetas para que las piezas no se golpeen entre s\xED."],respuesta_correcta:0,explicacion:"El inventario rotativo (Cycle Counting) y la estandarizaci\xF3n del stock cr\xEDtico por unidad permiten detectar y corregir p\xE9rdidas, da\xF1os y obsolescencia de forma continua."},{id:"ns_0604",categoria:"NATE_SR_HVAC",pregunta:"Un controlador DDC pierde la comunicaci\xF3n con los sensores (COM Loss). \xBFCu\xE1l es la posici\xF3n de seguridad (Fail-Safe) para un damper de aire exterior?",opciones:["Cerrado completamente para evitar la entrada de aire no acondicionado o congelaci\xF3n.","Abierto al 100% para asegurar la ventilaci\xF3n m\xEDnima requerida por normativas ASHRAE.","En la \xFAltima posici\xF3n conocida antes de la p\xE9rdida de se\xF1al del bus de datos.","Modulando aleatoriamente bas\xE1ndose en el temporizador interno del controlador."],respuesta_correcta:0,explicacion:"En caso de p\xE9rdida de comunicaci\xF3n (COM Loss), la posici\xF3n fail-safe para el damper de aire exterior es cerrado. Esto previene la entrada de aire exterior no acondicionado que podr\xEDa causar congelamiento del serpent\xEDn en invierno o exceso de carga en verano."},{id:"ns_0605",categoria:"NATE_SR_HVAC",pregunta:"Al medir el sobrecalentamiento total en el compresor, el Senior obtiene 35\xB0F. El sobrecalentamiento en el evaporador es de 10\xB0F. \xBFDiagn\xF3stico?",opciones:["Ganancia de calor excesiva en la l\xEDnea de succi\xF3n debido a falta de aislamiento.","V\xE1lvula de expansi\xF3n (TXV) ajustada con una apertura excesivamente grande.","Falta de refrigerante en el sistema que genera gas ralo en la l\xEDnea de succi\xF3n.","Compresor con eficiencia volum\xE9trica baja que no logra succionar la masa de gas."],respuesta_correcta:0,explicacion:"Si el sobrecalentamiento en el evaporador es 10\xB0F (normal) pero el total en el compresor es 35\xB0F, hay 25\xB0F de ganancia de calor en la l\xEDnea de succi\xF3n. Esto indica falta de aislamiento t\xE9rmico en la tuber\xEDa de succi\xF3n que absorbe calor del ambiente."},{id:"ns_0606",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor presenta escarcha densa solo en las vueltas superiores del serpent\xEDn exterior. \xBFQu\xE9 indica?",opciones:["Restricci\xF3n parcial en el distribuidor de refrigerante del serpent\xEDn exterior.","Funcionamiento normal del ciclo de expansi\xF3n antes de activar el deshielo.","Falla del ventilador exterior que no logra mover aire a trav\xE9s de todo el panel.","Exceso de aceite atrapado en la parte inferior del intercambiador de calor."],respuesta_correcta:0,explicacion:"Escarcha densa solo en ciertas secciones indica restriccion parcial en el distribuidor de refrigerante. Los circuitos bloqueados no reciben refrigerante, mientras que los libres se sobrecargan y la escarcha es desigual."},{id:"ns_0607",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior detecta que su equipo no utiliza un vacu\xF3metro digital, sino los man\xF3metros de servicio. \xBFCu\xE1l es la cr\xEDtica t\xE9cnica?",opciones:["Los man\xF3metros no tienen la resoluci\xF3n necesaria para medir niveles de micrones reales.","El aceite de los man\xF3metros contaminar\xE1 el sistema durante el proceso de vac\xEDo profundo.","La EPA proh\xEDbe el uso de mangueras est\xE1ndar para procesos de evacuaci\xF3n de sistemas.","El vac\xEDo destruye el sello de caucho interno de los man\xF3metros anal\xF3gicos convencionales."],respuesta_correcta:0,explicacion:"Los man\xF3metros anal\xF3gicos de servicio miden presiones en PSI y solo muestran si la aguja est\xE1 'bajo cero', sin resoluci\xF3n en micrones. Se necesita un vacu\xF3metro digital para verificar con precisi\xF3n que el sistema alcanz\xF3 500 micrones o menos."},{id:"ns_0608",categoria:"NATE_SR_CHILLERS",pregunta:"En un chiller centr\xEDfugo, \xBFcu\xE1l es el prop\xF3sito de la 'Purge Unit' cuando se usa R-123?",opciones:["Remover aire y humedad, ya que el evaporador opera a presiones bajo la atmosf\xE9rica.","Extraer el exceso de refrigerante l\xEDquido que se acumula en el condensador de placas.","Filtrar las part\xEDculas met\xE1licas que se desprenden de los cojinetes de alta velocidad.","Mantener la viscosidad del aceite constante mediante la eliminaci\xF3n de gas diluido."],respuesta_correcta:0,explicacion:"El R-123 opera bajo presi\xF3n atmosf\xE9rica en el evaporador, creando vac\xEDo. La unidad de purga remueve el aire y la humedad que se infiltran a trav\xE9s de sellos y juntas hacia el sistema."},{id:"ns_0609",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete industrial muestra un error de 'VFD Over-torque' en el motor del soplador. \xBFQu\xE9 inspecci\xF3n f\xEDsica es prioritaria?",opciones:["Verificar si los dampers de suministro est\xE1n cerrados o hay una obstrucci\xF3n mec\xE1nica.","Cambiar el variador de frecuencia por uno de mayor caballaje de forma inmediata.","Medir el voltaje de fase a fase en la entrada del variador bajo carga m\xE1xima.","Lubricar los rodamientos del motor aunque sean del tipo sellado de por vida."],respuesta_correcta:0,explicacion:"Un error de Over-torque indica que el VFD detecta una demanda de torque excesiva en el motor. La causa f\xEDsica m\xE1s com\xFAn son dampers cerrados, obstrucciones mec\xE1nicas en el soplador o algo trabando la rueda, lo que aumenta la resistencia al giro y dispara la protecci\xF3n del variador."},{id:"ns_0610",categoria:"NATE_SR_CEO",pregunta:"Un CEO eval\xFAa el 'Labor Efficiency Variance'. Si el tiempo real es mayor al presupuestado, \xBFcu\xE1l es la acci\xF3n correctiva?",opciones:["Identificar brechas de capacitaci\xF3n o problemas en la precisi\xF3n de los estimados.","Reducir el salario de los t\xE9cnicos que no cumplan con los tiempos de la tabla.","Eliminar los trabajos complejos y centrarse solo en mantenimientos residenciales.","Aumentar el precio de la mano de obra para cubrir el exceso de tiempo trabajado."],respuesta_correcta:0,explicacion:"Si el tiempo real supera al presupuestado, la causa puede ser falta de capacitaci\xF3n o estimados imprecisos; identificar la brecha es clave antes de tomar medidas correctivas."},{id:"ns_0611",categoria:"NATE_SR_HVAC",pregunta:"En un gr\xE1fico psicrom\xE9trico, el movimiento horizontal hacia la izquierda representa un proceso de:",opciones:["Enfriamiento sensible (reducci\xF3n de temperatura sin cambio en la humedad absoluta).","Deshumidificaci\xF3n qu\xEDmica mediante el uso de desecantes s\xF3lidos o l\xEDquidos.","Enfriamiento y deshumidificaci\xF3n simult\xE1nea al tocar el punto de roc\xEDo.","Calentamiento sensible debido a la fricci\xF3n del aire en los conductos de metal."],respuesta_correcta:0,explicacion:"En el gr\xE1fico psicrom\xE9trico, un movimiento horizontal hacia la izquierda representa disminuci\xF3n de temperatura de bulbo seco sin cambio en la humedad absoluta (granos/lb). Este es un proceso de enfriamiento puramente sensible, donde no se remueve humedad del aire."},{id:"ns_0612",categoria:"NATE_SR_RACK",pregunta:"Un rack paralelo presenta una temperatura de descarga de 260\xB0F en el compresor Lead. El Senior nota que el sobrecalentamiento de succi\xF3n es de 40\xB0F. \xBFAcci\xF3n?",opciones:["Aislar la vitrina que est\xE1 inundando el rack o ajustar la v\xE1lvula de expansi\xF3n principal.","Instalar un ventilador adicional sobre la cabeza del compresor para enfriarlo hoy.","Agregar refrigerante l\xEDquido para bajar la temperatura de succi\xF3n por masa total.","Verificar si la inyecci\xF3n de l\xEDquido (Quench valve) est\xE1 operando correctamente."],respuesta_correcta:3,explicacion:"Con 40\xB0F de sobrecalentamiento y 260\xB0F de descarga, el gas llega demasiado caliente al compresor. La v\xE1lvula Quench deber\xEDa inyectar l\xEDquido para enfriar el gas. Si no est\xE1 operando, la temperatura de descarga se eleva peligrosamente."},{id:"ns_0613",categoria:"NATE_SR_CEO",pregunta:"Para mejorar la 'Lealtad del Empleado', un CEO HVAC decide implementar un 'Profit Sharing'. \xBFC\xF3mo se calcula usualmente?",opciones:["Un porcentaje de la utilidad neta distribuido seg\xFAn la antig\xFCedad y desempe\xF1o t\xE9cnico.","Dividir el total de las ventas brutas del mes entre todos los empleados de la n\xF3mina.","Dar un bono fijo a los t\xE9cnicos que no tengan accidentes vehiculares en el semestre.","Permitir que los t\xE9cnicos compren acciones de la empresa a valor de mercado actual."],respuesta_correcta:0,explicacion:"El Profit Sharing se calcula como un porcentaje de la utilidad neta distribuido seg\xFAn antig\xFCedad y desempe\xF1o, alineando los intereses del t\xE9cnico con la rentabilidad de la empresa."},{id:"ns_0614",categoria:"NATE_SR_MINISPLIT",pregunta:"En un sistema VRF, \xBFcu\xE1l es la consecuencia t\xE9cnica de no instalar las juntas de derivaci\xF3n (Refnets) de forma perfectamente horizontal?",opciones:["Distribuci\xF3n desigual de aceite y refrigerante l\xEDquido hacia las unidades interiores.","Aumento de la ca\xEDda de presi\xF3n que reduce la eficiencia SEER total del sistema.","Ruidos de expansi\xF3n excesivos debido a la turbulencia del gas en la derivaci\xF3n.","Activaci\xF3n err\xF3nea del sensor de flujo de la caja controladora de rama (BC box)."],respuesta_correcta:0,explicacion:"Las juntas de derivaci\xF3n (Refnets) deben instalarse horizontalmente para garantizar distribuci\xF3n uniforme de aceite y refrigerante l\xEDquido. Si est\xE1n inclinadas, el l\xEDquido y aceite fluyen desigualmente hacia las unidades."},{id:"ns_0615",categoria:"NATE_SR_CHILLERS",pregunta:"Se observa una 'aproximaci\xF3n negativa' en el condensador de un chiller enfriado por agua. \xBFQu\xE9 concluye el Senior?",opciones:["Error de calibraci\xF3n en los termistores o en el transductor de presi\xF3n de alta.","El condensador est\xE1 operando en un estado de eficiencia t\xE9rmica absoluta ideal.","La torre de enfriamiento est\xE1 entregando agua m\xE1s fr\xEDa que la temperatura ambiente.","Existe una fuga interna de refrigerante hacia el lazo de agua de condensaci\xF3n."],respuesta_correcta:0,explicacion:"Un approach negativo de condensador es f\xEDsicamente imposible en condiciones normales. Siempre indica un error de calibraci\xF3n en los termistores o en el transductor de presi\xF3n de descarga."},{id:"ns_0616",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de 25 toneladas quema el contactor del compresor cada 4 meses. \xBFQu\xE9 factor Senior investiga?",opciones:["Bajo voltaje en el circuito de control o cicleo excesivo (Short Cycling).","Uso de contactores de 2 polos en un sistema que requiere 3 polos reales hoy.","La calidad de la plata en los contactos del componente de repuesto gen\xE9rico.","Si el motor del compresor est\xE1 operando con un factor de potencia muy bajo hoy."],respuesta_correcta:0,explicacion:"Un contactor que falla repetidamente cada pocos meses indica chattering por bajo voltaje (la bobina no cierra completamente los contactos, generando arco) o short cycling excesivo que multiplica los ciclos de arranque y desgasta los contactos prematuramente."},{id:"ns_0617",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que la presi\xF3n de succi\xF3n es 'normal' pero no hay enfriamiento. El Senior nota que el compresor no consume amperaje. \xBFDiagn\xF3stico?",opciones:["Compresor con falla mec\xE1nica interna (biela rota o scrolls separados).","El contactor est\xE1 cerrado pero los fusibles de potencia est\xE1n quemados hoy.","Falta total de carga de refrigerante que impide la compresi\xF3n del gas hoy.","El protector t\xE9rmico interno del compresor est\xE1 abierto por alta temperatura."],respuesta_correcta:0,explicacion:"Si la presi\xF3n de succi\xF3n parece normal pero el compresor no consume amperaje significativo, indica que el compresor gira pero no comprime (biela rota, scrolls separados o v\xE1lvulas da\xF1adas). El gas pasa sin compresi\xF3n, igualando las presiones."},{id:"ns_0618",categoria:"NATE_SR_CEO",pregunta:"Al analizar el 'Customer Lifetime Value', un CEO decide enfocarse en el mercado de 'Property Management'. \xBFPor qu\xE9?",opciones:["Provee un flujo constante de \xF3rdenes de trabajo y contratos de volumen masivo.","Los administradores de propiedades siempre pagan por adelantado todas las facturas.","Permite cobrar tarifas premium por reparaciones sencillas en edificios de lujo.","No requiere que los t\xE9cnicos tengan certificaciones especiales para entrar a trabajar."],respuesta_correcta:0,explicacion:"Property Management provee un flujo constante de \xF3rdenes de trabajo y contratos de volumen porque administran m\xFAltiples propiedades con necesidades HVAC continuas."},{id:"ns_0619",categoria:"NATE_SR_CHILLERS",pregunta:"Un sistema de agua helada presenta aire atrapado constantemente. \xBFQu\xE9 componente debe revisar el Senior?",opciones:["El tanque de expansi\xF3n y los purgadores de aire autom\xE1ticos en los puntos altos.","La velocidad de la bomba que podr\xEDa estar cavitando por falta de presi\xF3n hoy.","El sello mec\xE1nico de la bomba de circulaci\xF3n que aspira aire durante el paro.","Si el chiller est\xE1 operando a una temperatura por debajo del punto de roc\xEDo hoy."],respuesta_correcta:0,explicacion:"El tanque de expansi\xF3n mantiene la presi\xF3n del sistema y los purgadores de aire en los puntos altos eliminan el aire atrapado. Si fallan estos componentes, el aire se acumula constantemente."},{id:"ns_0620",categoria:"NATE_SR_RACK",pregunta:"En un rack de refrigeraci\xF3n, \xBFcu\xE1l es la funci\xF3n de la v\xE1lvula de retenci\xF3n (check valve) en la l\xEDnea de aceite?",opciones:["Evitar que el refrigerante l\xEDquido migre al separador de aceite durante el paro.","Mantener la presi\xF3n del dep\xF3sito de aceite por encima de la presi\xF3n de succi\xF3n.","Reducir las pulsaciones de la bomba de aceite que podr\xEDan da\xF1ar los sensores.","Prevenir el retorno de gas de descarga hacia el c\xE1rter de los compresores hoy."],respuesta_correcta:0,explicacion:"La v\xE1lvula check en la l\xEDnea de aceite previene que el refrigerante l\xEDquido del sistema migre hacia el separador de aceite durante los periodos de paro. Esto mantiene la integridad del aceite y evita diluci\xF3n por refrigerante."},{id:"ns_0621",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con R-134a tiene una presi\xF3n de descarga de 210 PSI y temperatura de salida de agua de torre de 85\xB0F. \xBFApproach?",opciones:["Aproximadamente 50\xB0F; indicando una transferencia de calor ineficiente hoy.","Aproximadamente 10\xB0F; indicando un condensador operando en rango normal.","Aproximadamente 2\xB0F; indicando que el condensador est\xE1 perfectamente limpio.","No se puede calcular sin conocer la temperatura de entrada del agua de torre."],respuesta_correcta:0,explicacion:"A 210 PSI, la temperatura de saturaci\xF3n del R-134a es ~135\xB0F. Con agua de torre saliendo a 85\xB0F, el approach es ~50\xB0F, indicando una transferencia de calor muy ineficiente en el condensador."},{id:"ns_0622",categoria:"NATE_SR_HVAC",pregunta:"Se instala un motor ECM de repuesto y el flujo de aire es insuficiente. El motor es de la misma potencia. \xBFCausa Senior?",opciones:["La placa de control no est\xE1 programada con los taps de flujo correctos para el ducto.","El motor ECM requiere un capacitor de arranque especial para vencer la inercia hoy.","Los conductos de suministro tienen fugas masivas que no exist\xEDan anteriormente hoy.","El motor est\xE1 girando en sentido contrario debido a la polaridad de los 24V hoy."],respuesta_correcta:0,explicacion:"Los motores ECM de repuesto requieren programaci\xF3n espec\xEDfica de la placa de control para definir los taps de flujo de aire (CFM) seg\xFAn el sistema de conductos. Sin la configuraci\xF3n correcta, el motor no entregar\xE1 el flujo de aire dise\xF1ado aunque tenga la misma potencia nominal."},{id:"ns_0623",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC busca mejorar el 'Quick Ratio'. \xBFCu\xE1l de estas acciones lo logra directamente?",opciones:["Cobrar facturas pendientes y mantener el efectivo en la cuenta corriente hoy.","Comprar m\xE1s inventario de equipos nuevos para aprovechar descuentos por volumen.","Pagar todas las deudas a largo plazo usando las ganancias retenidas del a\xF1o hoy.","Invertir en la compra de un nuevo edificio administrativo para la empresa hoy hoy."],respuesta_correcta:0,explicacion:"Cobrar facturas pendientes y mantener efectivo en la cuenta mejora directamente el Quick Ratio, ya que aumenta los activos l\xEDquidos disponibles frente a los pasivos corrientes."},{id:"ns_0624",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calefacci\xF3n, una bomba de calor se apaga por alta presi\xF3n de descarga. El soplador interior funciona. \xBFCausa?",opciones:["Filtro de aire interior extremadamente sucio o serpent\xEDn interior bloqueado hoy.","Falla del ventilador exterior que impide que el refrigerante absorba calor hoy.","La v\xE1lvula inversora no logr\xF3 cambiar a la posici\xF3n de calor completamente hoy.","Falta de refrigerante l\xEDquido que causa que el compresor se sobrecaliente hoy hoy."],respuesta_correcta:0,explicacion:"En modo calor, el serpentin interior actua como condensador. Si el filtro de aire esta extremadamente sucio, el flujo de aire se reduce, impidiendo que el refrigerante rechace calor y elevando la presion de descarga."},{id:"ns_0625",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no arranca y marca error de 'DC Bus Low Voltage'. Al medir hay 240VAC entrada. \xBFQu\xE9 revisa?",opciones:["El puente rectificador y los capacitores de potencia en la placa exterior hoy.","La comunicaci\xF3n entre la unidad interior y exterior mediante el cable S3 hoy.","Si el compresor est\xE1 aterrizado midiendo resistencia contra la carcasa hoy hoy.","El transformador de control que alimenta a la placa electr\xF3nica de la interior."],respuesta_correcta:0,explicacion:"Con 240VAC de entrada correctos pero error de 'DC Bus Low Voltage', el puente rectificador no est\xE1 convirtiendo AC a DC o los capacitores de potencia est\xE1n descargados/da\xF1ados en la placa exterior."},{id:"ns_0626",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 s\xEDntoma indica que el separador de aceite est\xE1 'pasando' aceite al condensador?",opciones:["Nivel bajo constante en el dep\xF3sito y p\xE9rdida de capacidad en los evaporadores.","Alta temperatura de descarga y ciclos cortos de todos los compresores del rack.","Espuma en la mirilla de la l\xEDnea de l\xEDquido justo antes de las vitrinas hoy.","Aumento en la presi\xF3n de succi\xF3n debido a la viscosidad del aceite en gas hoy."],respuesta_correcta:0,explicacion:"Si el separador deja pasar aceite al condensador, el dep\xF3sito de aceite tendr\xE1 un nivel bajo constante. Adem\xE1s, el aceite acumulado en evaporadores forma una pel\xEDcula aislante en las paredes que reduce la transferencia de calor y la capacidad frigor\xEDfica."},{id:"ns_0627",categoria:"NATE_SR_CEO",pregunta:"Un CEO decide implementar 'In-House Training'. \xBFCu\xE1l es el KPI para justificar el gasto?",opciones:["Reducci\xF3n en el porcentaje de 'Callbacks' y aumento en la eficiencia por hora.","La cantidad de t\xE9cnicos que logran obtener su certificaci\xF3n EPA 608 este a\xF1o.","El ahorro en el costo de contratar empresas externas de capacitaci\xF3n t\xE9cnica hoy.","La satisfacci\xF3n de los empleados medida a trav\xE9s de encuestas an\xF3nimas hoy hoy."],respuesta_correcta:0,explicacion:"La reducci\xF3n en callbacks y el aumento en eficiencia por hora son KPIs medibles que justifican directamente la inversi\xF3n en capacitaci\xF3n interna con resultados financieros concretos."},{id:"ns_0628",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una ca\xEDda de temperatura de 15\xB0F en el evaporador. El dise\xF1o es de 10\xB0F. \xBFCausa?",opciones:["Bajo flujo de agua a trav\xE9s del evaporador debido a bomba o v\xE1lvulas hoy.","Flujo de agua excesivo que permite una transferencia de calor m\xE1s r\xE1pida hoy.","Carga t\xE9rmica del edificio superior a la capacidad nominal del chiller hoy hoy.","Incrustaciones en los tubos que obligan al agua a enfriarse m\xE1s lentamente hoy."],respuesta_correcta:0,explicacion:"Un Delta T de 15\xB0F vs. dise\xF1o de 10\xB0F indica bajo flujo de agua. El agua permanece m\xE1s tiempo en el evaporador, enfri\xE1ndose m\xE1s de lo normal debido a bomba deficiente o v\xE1lvulas restringidas."},{id:"ns_0629",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que no puede soldar una tuber\xEDa de 2 pulgadas porque hay agua dentro. \xBFConsejo Senior?",opciones:["Usar una bomba de vac\xEDo o nitr\xF3geno para desplazar el agua antes de soldar hoy.","Aumentar la potencia de la antorcha para evaporar el agua mientras se suelda.","Usar soldadura de esta\xF1o/plomo que requiere menos temperatura para fundir hoy.","Poner un tap\xF3n de pan dentro del tubo para bloquear el agua temporalmente hoy."],respuesta_correcta:0,explicacion:"El agua dentro de la tuber\xEDa absorbe el calor de la antorcha e impide que el cobre alcance la temperatura necesaria para la soldadura. Desplazar el agua con nitr\xF3geno o extraerla con bomba de vac\xEDo es necesario para lograr una uni\xF3n de calidad."},{id:"ns_0630",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Vehicle Downtime'. \xBFQu\xE9 acci\xF3n es la m\xE1s efectiva hoy?",opciones:["Programa de mantenimiento preventivo riguroso y flota de reserva m\xEDnima hoy.","Obligar a los t\xE9cnicos a reparar sus propias camionetas durante el fin de semana.","Comprar solo veh\xEDculos usados para reducir el impacto financiero de las fallas.","Eliminar el uso de GPS para evitar que los t\xE9cnicos conduzcan distancias largas."],respuesta_correcta:0,explicacion:"Un programa de mantenimiento preventivo riguroso para la flota y una reserva m\xEDnima de veh\xEDculos aseguran que siempre haya camionetas disponibles para las llamadas de servicio."},{id:"ns_0631",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Oil Loss' sin fugas visibles. \xBFQu\xE9 revisa el Senior?",opciones:["El sistema de recuperaci\xF3n de aceite (eductor) y la temperatura del evaporador.","Si el compresor est\xE1 operando a una velocidad excesiva para la carga hoy.","La viscosidad del aceite que podr\xEDa ser demasiado baja para el refrigerante hoy.","Si la unidad de purga est\xE1 extrayendo aceite junto con los incondensables hoy."],respuesta_correcta:0,explicacion:"Sin fugas visibles, la p\xE9rdida de aceite en un chiller centr\xEDfugo se debe a fallas en el sistema de recuperaci\xF3n de aceite (eductor) o acumulaci\xF3n de aceite en el evaporador por baja temperatura."},{id:"ns_0632",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de descarga de 450 PSI y succi\xF3n de 120 PSI con R-410A. \xBFC\xF3mo est\xE1?",opciones:["Funcionamiento normal para un d\xEDa con alta temperatura exterior y carga hoy.","Falta de refrigerante leve que impide que la descarga baje a los 300 PSI.","Restricci\xF3n en la v\xE1lvula de expansi\xF3n que eleva la presi\xF3n de alta hoy hoy.","Compresor con eficiencia reducida que no puede bombear gas correctamente hoy."],respuesta_correcta:0,explicacion:"Con R-410A, descarga de 450 PSI (~120\xB0F sat.) puede ser normal en un d\xEDa muy caluroso con temperatura exterior alta. Con succi\xF3n de 120 PSI (~38\xB0F sat.), el sistema est\xE1 operando dentro de par\xE1metros aceptables para condiciones de alta carga t\xE9rmica."},{id:"ns_0633",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir el 'ROI' de su publicidad en Google. \xBFQu\xE9 dato es vital hoy?",opciones:["Conversi\xF3n de clics en llamadas de servicio que resultaron en ventas reales.","El n\xFAmero total de impresiones del anuncio en las b\xFAsquedas locales hoy hoy.","El costo por clic (CPC) comparado con el promedio de la industria nacional.","La posici\xF3n del anuncio en la primera p\xE1gina de resultados de b\xFAsqueda hoy hoy."],respuesta_correcta:0,explicacion:"El dato vital para medir ROI de Google Ads es cu\xE1ntos clics se convirtieron en llamadas de servicio que resultaron en ventas reales con margen de utilidad."},{id:"ns_0634",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no enfr\xEDa. El compresor exterior arranca pero se apaga en 10 seg. \xBFCausa?",opciones:["Falla de IPM (m\xF3dulo de potencia) o compresor mec\xE1nicamente trabado hoy hoy.","Falta de refrigerante l\xEDquido que activa el sensor de baja presi\xF3n hoy hoy.","El ventilador interior est\xE1 apagado y la unidad se bloquea por seguridad hoy.","El control remoto est\xE1 configurado en una temperatura demasiado alta hoy hoy."],respuesta_correcta:0,explicacion:"Si el compresor arranca y se apaga en 10 segundos, el IPM detecta sobrecorriente (compresor mec\xE1nicamente trabado) o el m\xF3dulo de potencia mismo est\xE1 da\xF1ado y no puede mantener la operaci\xF3n."},{id:"ns_0635",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calor, una bomba de calor tiene un ruido de soplido fuerte en la inversora. \xBFCausa?",opciones:["Fuga interna de gas de descarga hacia la succi\xF3n a trav\xE9s de la v\xE1lvula hoy.","El refrigerante l\xEDquido est\xE1 pasando por la v\xE1lvula a alta velocidad hoy hoy.","La bobina solenoide est\xE1 vibrando contra el cuerpo de la v\xE1lvula hoy hoy hoy.","Es un sonido normal del flujo de refrigerante en sistemas de gran capacidad."],respuesta_correcta:0,explicacion:"Un soplido constante en la valvula inversora indica fuga interna de gas de descarga (alta presion) hacia la succion (baja presion). Esta fuga reduce la capacidad del sistema y produce un ruido audible."},{id:"ns_0636",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 sucede si la v\xE1lvula diferencial de aceite est\xE1 mal ajustada (muy alta)?",opciones:["Se inyecta demasiado aceite al c\xE1rter y puede causar da\xF1os mec\xE1nicos hoy hoy.","No habr\xE1 suficiente presi\xF3n para que el aceite regrese a los compresores hoy.","El separador de aceite se desbordar\xE1 hacia la l\xEDnea de descarga del rack hoy.","La temperatura del aceite bajar\xE1 por debajo del punto de lubricaci\xF3n hoy hoy."],respuesta_correcta:0,explicacion:"Un ajuste excesivamente alto de la v\xE1lvula diferencial permite un flujo desmedido de aceite hacia los c\xE1rteres. El exceso de aceite puede causar golpe hidr\xE1ulico, da\xF1ar los platos de v\xE1lvulas, y provocar arrastre de aceite hacia los evaporadores."},{id:"ns_0637",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Junior instala una unidad y no conecta la tierra f\xEDsica. El Senior advierte que:",opciones:["Es un riesgo mortal de descarga el\xE9ctrica y puede da\xF1ar placas electr\xF3nicas.","El compresor consumir\xE1 m\xE1s amperaje al no tener una referencia de neutro hoy.","La garant\xEDa del fabricante se anula si no hay conexi\xF3n a tierra certificada.","El equipo har\xE1 m\xE1s ruido debido a la falta de masa para las vibraciones hoy."],respuesta_correcta:0,explicacion:"Sin conexi\xF3n a tierra, cualquier fuga de corriente electrifica el chasis del equipo, creando un riesgo de electrocuci\xF3n mortal. Las placas electr\xF3nicas de control tambi\xE9n son vulnerables a da\xF1os por sobretensiones sin una referencia de tierra adecuada."},{id:"ns_0638",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una ca\xEDda de presi\xF3n de agua de 15 PSI en el evaporador. \xBFC\xF3mo verifica flujo?",opciones:["Consultando la curva de la bomba y la tabla de dise\xF1o del fabricante hoy hoy.","Midiendo la temperatura de salida del agua con un term\xF3metro l\xE1ser hoy hoy.","Observando el movimiento del agua en el tanque de expansi\xF3n abierto hoy hoy.","Contando las revoluciones por minuto del motor de la bomba de agua helada."],respuesta_correcta:0,explicacion:"La ca\xEDda de presi\xF3n de agua se correlaciona con el flujo seg\xFAn las curvas del fabricante. Consultando estos datos, se puede determinar si el flujo real corresponde al diferencial de presi\xF3n medido."},{id:"ns_0639",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta ruidos de 'Water Hammering' en l\xEDneas de refrigerante. \xBFCausa?",opciones:["L\xEDquido refrigerante regresando al compresor o falta de soportes tuber\xEDa hoy.","Aire atrapado en el sistema que no fue evacuado durante el proceso de vac\xEDo.","Una v\xE1lvula de expansi\xF3n que abre y cierra violentamente por falta de carga.","El uso de tuber\xEDa de succi\xF3n con di\xE1metro mayor al especificado por dise\xF1o."],respuesta_correcta:0,explicacion:"El 'water hammering' ocurre cuando refrigerante l\xEDquido golpea contra cambios de direcci\xF3n en la tuber\xEDa o regresa violentamente al compresor. Tuber\xEDas sin soportes adecuados amplifican estas vibraciones hidr\xE1ulicas, creando ruidos de martilleo audibles."},{id:"ns_0640",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar la retenci\xF3n de clientes. \xBFCu\xE1l es el impacto de un programa mantenimiento?",opciones:["Aumenta lealtad, reduce emergencias y genera ingresos recurrentes hoy hoy hoy.","Permite cobrar m\xE1s caro por reparaciones de emergencia al cliente fiel hoy.","Reduce necesidad de t\xE9cnicos Senior ya que el equipo estar\xE1 siempre nuevo.","Elimina competencia al obligar al cliente a firmar contrato de exclusividad."],respuesta_correcta:0,explicacion:"Los programas de mantenimiento preventivo aumentan la lealtad del cliente, previenen emergencias costosas y crean un flujo de ingresos recurrente y predecible."},{id:"ns_0641",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta una purga de aire constante. Opera con R-134a. \xBFQu\xE9 indica?",opciones:["La purga est\xE1 defectuosa; el R-134a opera a presi\xF3n positiva y no aspira aire.","El chiller tiene una fuga masiva en el evaporador que permite la entrada aire.","El sistema de sellado del eje del compresor ha fallado mec\xE1nicamente hoy hoy.","La temperatura del agua de la torre es demasiado baja para el condensador hoy."],respuesta_correcta:0,explicacion:"El R-134a opera a presi\xF3n positiva en todo el sistema. Una purga constante de aire es imposible bajo estas condiciones, indicando que el dispositivo de purga est\xE1 defectuoso."},{id:"ns_0642",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no arranca. No hay c\xF3digos de error. \xBFQu\xE9 revisa el Senior?",opciones:["El fusible de la placa interior y si el voltaje de llegada es de 240VAC hoy.","La carga de refrigerante por peso para descartar una fuga total de gas gas.","Si el compresor est\xE1 aterrizado midiendo la resistencia contra la carcasa.","La placa electr\xF3nica de la unidad exterior por rastros de quemaduras hoy hoy."],respuesta_correcta:0,explicacion:"Sin c\xF3digos de error, el sistema no recibe alimentaci\xF3n. El Senior verifica el fusible de la placa interior y confirma que llegan 240VAC, ya que sin energ\xEDa no hay diagn\xF3stico electr\xF3nico posible."},{id:"ns_0643",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. Subenfriamiento 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido severa en el sistema (Undercharged) hoy hoy.","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total hoy hoy.","Condensador exterior extremadamente sucio que no permite el intercambio t\xE9rmico.","Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."],respuesta_correcta:0,explicacion:"Subenfriamiento de 0\xB0F indica ausencia de l\xEDquido subenfriado en la salida del condensador. Esto es la firma diagn\xF3stica m\xE1s clara de falta severa de refrigerante (undercharged), donde la masa de refrigerante es insuficiente para completar la condensaci\xF3n."},{id:"ns_0644",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n hoy.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada hoy hoy.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial hoy hoy.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos hoy."],respuesta_correcta:0,explicacion:"Para Smart Homes se necesitan t\xE9cnicos con capacitaci\xF3n en redes, protocolos de comunicaci\xF3n e integraci\xF3n de dispositivos inteligentes con los sistemas HVAC."},{id:"ns_0645",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 indica una temperatura de succi\xF3n muy alta en el cabezal?",opciones:["Sobrecalentamiento excesivo que da\xF1ar\xE1 la lubricaci\xF3n de compresores pronto.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de evaporaci\xF3n hoy hoy.","Falta de refrigerante l\xEDquido en el recibidor principal del rack paralelo hoy.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n cerradas por temperatura hoy."],respuesta_correcta:0,explicacion:"El sobrecalentamiento excesivo del gas de succi\xF3n aumenta la temperatura en la c\xE1mara de compresi\xF3n y en el aceite. Las propiedades lubricantes del aceite se degradan con el calor, acortando la vida \xFAtil de cojinetes y pistones."},{id:"ns_0646",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. \xBFQu\xE9 revisa?",opciones:["Presencia de aire en la tuber\xEDa, paddle roto o transductor descalibrado hoy.","La carga de refrigerante que podr\xEDa estar congelando el agua en tubos hoy.","El sentido de rotaci\xF3n del motor del compresor centr\xEDfugo del sistema hoy hoy.","La apertura de las v\xE1lvulas de expansi\xF3n del circuito de refrigeraci\xF3n hoy hoy."],respuesta_correcta:0,explicacion:"Con la bomba funcionando, una alarma de flow switch indica problemas con el sensor: paddle roto, aire atrapado en la tuber\xEDa, o transductor de presi\xF3n diferencial que necesita calibraci\xF3n."},{id:"ns_0647",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. \xBFCausa?",opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior hoy.","La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido.","La humedad en la habitaci\xF3n es superior al 95% y satura el serpent\xEDn hoy hoy."],respuesta_correcta:0,explicacion:"El goteo solo al parar el compresor indica un problema de drenaje: contrapendiente o bloqueo parcial en la parte superior retiene agua durante la operaci\xF3n que se libera cuando el sistema se detiene."},{id:"ns_0648",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de 0.9 en suministro y 0.2 en retorno. \xBFProblema?",opciones:["Restricci\xF3n severa en conductos de suministro o difusores cerrados hoy hoy hoy.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire hoy.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo hoy hoy.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o hoy hoy."],respuesta_correcta:0,explicacion:'Presi\xF3n est\xE1tica desproporcionada (0.9" suministro vs 0.2" retorno) confirma que la restricci\xF3n est\xE1 concentrada en el lado de suministro del sistema de conductos, ya sea por difusores cerrados, conductos aplastados o subdimensionados.'},{id:"ns_0649",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre 20\xB0F y 30\xB0F hoy hoy.","S\xED, las bombas de calor siempre tienen un diferencial menor que hornos hoy.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo hoy."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en modo calor es insuficiente. El rango saludable es 20-30F. Este diferencial bajo sugiere que el sistema no genera suficiente calor por baja carga, problemas de flujo de aire, o fallas mecanicas."},{id:"ns_0650",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. \xBFQu\xE9 paso es vital post-quemadura?",opciones:["Realizar prueba de acidez del aceite y usar filtros succi\xF3n de limpieza hoy.","A\xF1adir aditivo sellador de fugas para prevenir fallas futuras en l\xEDneas hoy.","Cambiar el contactor y el capacitor aunque parezcan estar en buen estado hoy.","Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy hoy."],respuesta_correcta:0,explicacion:"Tras un burnout del compresor, los \xE1cidos y part\xEDculas carbonizadas circulan por todo el sistema. La prueba de acidez eval\xFAa la severidad de la contaminaci\xF3n y los filtros de succi\xF3n atrapan los residuos para evitar la destrucci\xF3n del compresor de reemplazo."},{id:"ns_0651",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. \xBFEstado?",opciones:["Funcionamiento correcto; la purga est\xE1 separando los no condensables hoy hoy hoy.","Falla en el serpent\xEDn de condensaci\xF3n interno de la unidad de purga hoy hoy.","El sistema tiene una fuga masiva de agua hacia el lado del refrigerante hoy.","La temperatura del evaporador es demasiado alta para que la purga trabaje hoy."],respuesta_correcta:0,explicacion:"Si la purga expulsa principalmente aire con poco refrigerante, est\xE1 funcionando correctamente al separar los no condensables del refrigerante, cumpliendo su prop\xF3sito de dise\xF1o."},{id:"ns_0652",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si el 'Oil Separator' queda pegado en posici\xF3n abierta?",opciones:["Gas caliente de descarga pasar\xE1 directo al dep\xF3sito aceite y succi\xF3n hoy hoy.","El rack se quedar\xE1 sin aceite en pocos minutos al no poder separarlo gas hoy.","Los compresores se apagar\xE1n por alta presi\xF3n al bloquearse el flujo gas hoy.","El nivel de aceite en los c\xE1rteres subir\xE1 tanto que da\xF1ar\xE1 los pistones hoy."],respuesta_correcta:0,explicacion:"Con el flotador del separador permanentemente abierto, el gas de descarga caliente pasa directo al dep\xF3sito de aceite y puede alcanzar la l\xEDnea de succi\xF3n. Esto genera un bypass interno que reduce la capacidad de refrigeraci\xF3n del rack."},{id:"ns_0653",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. \xBFQu\xE9 KPI usa?",opciones:["N\xFAmero de llamadas de nuevos clientes que mencionan haber visto la unidad hoy hoy.","La cantidad de millas recorridas por cada veh\xEDculo en zonas residenciales hoy.","El costo total del dise\xF1o e instalaci\xF3n del r\xF3tulo dividido entre 12 meses.","El aumento en la velocidad promedio de t\xE9cnicos al conducir camionetas nuevas."],respuesta_correcta:0,explicacion:"Medir cu\xE1ntos clientes nuevos mencionan haber visto la camioneta rotulada es la forma m\xE1s directa de evaluar el retorno de inversi\xF3n de la publicidad vehicular."},{id:"ns_0654",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. \xBFQu\xE9 revisa?",opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy hoy hoy.","La carga de refrigerante l\xEDquido bas\xE1ndose en el visor del evaporador hoy hoy.","Si la v\xE1lvula de expansi\xF3n est\xE1 inyectando demasiado l\xEDquido al sistema hoy.","El estado de los filtros de aire de la manejadora de aire del edificio hoy."],respuesta_correcta:0,explicacion:"La alta presi\xF3n de condensaci\xF3n con condensador de agua requiere verificar primero la temperatura del agua de torre y el funcionamiento de la bomba de condensador como causas directas."},{id:"ns_0655",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n de 125 PSI y descarga 400 PSI con R-410A. \xBFEstado aire?",opciones:["Funcionamiento normal bajo condiciones de carga t\xE9rmica est\xE1ndar hoy hoy hoy hoy.","Falta de refrigerante que impide que temperatura del aire baje a 55 grados hoy.","Exceso de carga que est\xE1 elevando la presi\xF3n de descarga innecesariamente hoy.","Compresor con eficiencia reducida que no logra enfriar el aire correctamente."],respuesta_correcta:0,explicacion:"Las presiones de succi\xF3n de 125 PSI y descarga de 400 PSI con R-410A son normales para operaci\xF3n est\xE1ndar. El sistema est\xE1 funcionando dentro de sus par\xE1metros de dise\xF1o bajo condiciones de carga t\xE9rmica t\xEDpicas."},{id:"ns_0656",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. \xBFQu\xE9 estrategia?",opciones:["Programa de membres\xEDas mantenimiento para convertir clientes en recurrentes hoy hoy.","Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy hoy.","Gastar m\xE1s dinero en anuncios de Google para atraer siempre clientes nuevos hoy.","Despedir a t\xE9cnicos que no logren vender un sistema nuevo en cada visita hoy."],respuesta_correcta:0,explicacion:"Las membres\xEDas de mantenimiento convierten clientes \xFAnicos en recurrentes, generando ingresos estables y predecibles que fortalecen el modelo de negocio."},{id:"ns_0657",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. \xBFQu\xE9 revisa?",opciones:["Carga de refrigerante baja o una restricci\xF3n en la v\xE1lvula de expansi\xF3n hoy hoy.","Si el ventilador interior est\xE1 sucio y no sopla suficiente aire fr\xEDo hoy hoy.","El voltaje de la l\xEDnea el\xE9ctrica que podr\xEDa estar por debajo de 200V hoy hoy.","Si el control remoto est\xE1 configurado en una temperatura demasiado baja hoy."],respuesta_correcta:0,explicacion:"La protecci\xF3n de temperatura de descarga se activa por carga de refrigerante insuficiente o restricci\xF3n en la v\xE1lvula de expansi\xF3n, ambas condiciones causan que el gas de descarga se sobrecaliente."},{id:"ns_0658",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba calor, \xBFqu\xE9 sucede si 'Check Valve' condensador falla abierta?",opciones:["En modo calor el refrigerante har\xE1 bypass a TXV impidiendo calentamiento hoy hoy.","El sistema funcionar\xE1 mejor al haber menos restricci\xF3n al flujo l\xEDquido hoy.","La presi\xF3n de descarga subir\xE1 hasta que switch de alta apague el equipo hoy.","El compresor se quemar\xE1 por el retorno de l\xEDquido masivo en el arranque hoy."],respuesta_correcta:0,explicacion:"La check valve permite bypass en modo calor. Si falla abierta, el refrigerante no pasa por la TXV, eliminando la restriccion necesaria para la caida de presion y el calentamiento adecuado del sistema."},{id:"ns_0659",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula 'Quench' o inyecci\xF3n de l\xEDquido?",opciones:["Para enfriar gas de succi\xF3n y evitar que descarga da\xF1e el aceite hoy hoy hoy hoy.","Para aumentar la presi\xF3n de succi\xF3n cuando carga en vitrinas es baja hoy hoy.","Para limpiar el interior de compresores de acumulaciones de carbonilla hoy hoy.","Para ayudar al retorno de aceite desde los evaporadores m\xE1s lejanos hoy hoy."],respuesta_correcta:0,explicacion:"La v\xE1lvula Quench controla la temperatura de descarga inyectando refrigerante l\xEDquido. Esto es esencial en racks de baja temperatura donde el alto ratio de compresi\xF3n genera temperaturas de descarga que pueden descomponer el aceite lubricante."},{id:"ns_0660",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. \xBFCriterio?",opciones:["El volumen de agua y la accesibilidad para eliminaci\xF3n segura del fluido hoy hoy.","Cu\xE1l de las dos herramientas es m\xE1s nueva y hace menos ruido al operar hoy.","La preferencia del cliente sobre qu\xE9 herramienta quiere ver en su casa hoy.","Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy hoy."],respuesta_correcta:0,explicacion:"La selecci\xF3n correcta de herramienta se basa en criterios t\xE9cnicos: cu\xE1nta agua hay que remover y si el punto de acumulaci\xF3n es accesible. Estas condiciones dictan la herramienta \xF3ptima para una resoluci\xF3n eficiente y segura."},{id:"ns_0661",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene purga que marca 'Water Detected'. \xBFQu\xE9 acci\xF3n es urgente?",opciones:["Realizar prueba presi\xF3n a tubos del evaporador para buscar rupturas hoy hoy hoy.","Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.","Aumentar la temperatura del agua helada para evitar que vapor condense hoy hoy.","Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy."],respuesta_correcta:0,explicacion:"La detecci\xF3n de agua por la purga es una emergencia que requiere prueba de presi\xF3n inmediata en los tubos del evaporador para identificar posibles rupturas que contaminen el refrigerante."},{id:"ns_0662",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n 130 PSI y descarga 380 PSI. Subenfriamiento 12\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y el subenfriamiento est\xE1n en rango hoy hoy.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser 15 grados hoy.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno hoy.","Compresor fallando; la diferencia presi\xF3n entre succi\xF3n y descarga es baja hoy."],respuesta_correcta:0,explicacion:"Presiones de 130/380 PSI con subenfriamiento de 12\xB0F son valores que caen dentro del rango \xF3ptimo de operaci\xF3n para R-410A. El subenfriamiento entre 10-15\xB0F es ideal para confirmar carga correcta y condensaci\xF3n eficiente."},{id:"ns_0663",categoria:"NATE_SR_PACKAGE",pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["El voltaje en la bobina (24V) y si hay suciedad u \xF3xido en el n\xFAcleo hoy hoy hoy.","Si los contactos principales est\xE1n quemados o soldados entre s\xED hoy hoy hoy.","El capacitor de arranque del compresor que podr\xEDa estar descargado hoy hoy.","La continuidad de los fusibles de potencia de la l\xEDnea de 240 voltios hoy hoy."],respuesta_correcta:0,explicacion:"El zumbido del contactor sin cierre mec\xE1nico es diagn\xF3stico de fuerza electromagn\xE9tica insuficiente. Se verifica primero el voltaje de la bobina (debe ser m\xEDnimo 85% del nominal) y la limpieza del n\xFAcleo magn\xE9tico, ya que la suciedad impide el contacto total de las superficies polares."},{id:"ns_0664",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico cobra 'por fuera' a clientes. \xBFQu\xE9 acci\xF3n toma?",opciones:["Despido inmediato y posible acci\xF3n legal seg\xFAn el contrato de trabajo hoy hoy hoy.","Hablar con el t\xE9cnico y pedirle una comisi\xF3n por esos trabajos extras hoy hoy.","Ignorar la situaci\xF3n si el t\xE9cnico es el que m\xE1s dinero genera hoy hoy hoy.","Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."],respuesta_correcta:0,explicacion:"El cobro por fuera constituye fraude; la respuesta correcta es el despido inmediato y la evaluaci\xF3n de acciones legales seg\xFAn lo estipulado en el contrato laboral."},{id:"ns_0665",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFPor qu\xE9 es fundamental cargar l\xEDquido en el recibidor?",opciones:["Para evitar fraccionamiento de la mezcla y asegurar composici\xF3n correcta hoy hoy hoy.","Para que el refrigerante se mezcle m\xE1s r\xE1pido con el aceite POE del rack hoy.","Para prevenir que las v\xE1lvulas de descarga de compresores se calienten hoy hoy.","Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal hoy hoy."],respuesta_correcta:0,explicacion:"Al cargar R-448A en fase l\xEDquida, se garantiza que la mezcla de componentes (R-32, R-125, R-134a, R-1234yf, R-1234ze) entre al sistema con la composici\xF3n de dise\xF1o, evitando el fraccionamiento que ocurrir\xEDa si se carga en gas."},{id:"ns_0666",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. \xBFEfecto?",opciones:["El controlador no podr\xE1 calcular la carga t\xE9rmica real del edificio hoy hoy hoy.","El compresor se apagar\xE1 inmediatamente por seguridad de flujo de agua hoy hoy.","La unidad operar\xE1 siempre al 100% de su capacidad nominal sin modular hoy hoy.","No hay efecto si el sensor de 'Leaving Water' est\xE1 operando correctamente hoy hoy."],respuesta_correcta:0,explicacion:"Sin el sensor de entering water, el controlador pierde la referencia de carga t\xE9rmica del edificio y no puede calcular correctamente la modulaci\xF3n de capacidad necesaria."},{id:"ns_0667",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de descarga de 550 PSI con R-410A. \xBFCausa?",opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy hoy hoy.","Falta de refrigerante l\xEDquido que impide que el sistema enfr\xEDe el aire hoy hoy.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total hoy.","El compresor est\xE1 perdiendo eficiencia y no logra comprimir el gas ralo hoy hoy."],respuesta_correcta:0,explicacion:"Una descarga de 550 PSI con R-410A es cr\xEDticamente alta y requiere atenci\xF3n inmediata. Un condensador extremadamente sucio o un ventilador que no funciona elimina la capacidad de rechazar calor, causando una acumulaci\xF3n peligrosa de presi\xF3n."},{id:"ns_0668",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Average Response Time'. \xBFQu\xE9 medida toma hoy?",opciones:["Implementar software de despacho inteligente y zonificaci\xF3n de t\xE9cnicos hoy hoy hoy.","Aumentar el n\xFAmero de t\xE9cnicos en la n\xF3mina aunque no haya llamadas suficientes.","Reducir el tiempo de almuerzo de los t\xE9cnicos para que est\xE9n m\xE1s disponibles hoy.","Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy."],respuesta_correcta:0,explicacion:"El software de despacho inteligente con zonificaci\xF3n reduce el tiempo de respuesta al enviar autom\xE1ticamente al t\xE9cnico m\xE1s cercano y mejor calificado para cada emergencia."},{id:"ns_0669",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. \xBFCausa?",opciones:["Falla de comunicaci\xF3n; el voltaje deber\xEDa fluctuar entre 0 y 24VDC hoy hoy hoy hoy.","La placa exterior est\xE1 operando correctamente enviando la se\xF1al de control hoy.","El compresor inverter est\xE1 aterrizado y consume el voltaje de comunicaci\xF3n hoy.","Falta de alimentaci\xF3n de 240VAC en los terminales L1 y L2 de la exterior hoy hoy."],respuesta_correcta:0,explicacion:"La comunicaci\xF3n inverter entre S2 y S3 usa se\xF1ales DC pulsantes (0-24V). Un voltaje fijo de 24VDC constante significa que no hay transmisi\xF3n de datos: existe una falla de comunicaci\xF3n."},{id:"ns_0670",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el 'Defrost Sensor' falla en circuito abierto?",opciones:["El sistema nunca entrar\xE1 en modo de deshielo y el serpent\xEDn se congelar\xE1 hoy hoy.","El sistema entrar\xE1 en modo de deshielo cada 30 minutos sin importar el hielo hoy.","El compresor se quemar\xE1 debido a la falta de control de sobrecalentamiento hoy.","La unidad operar\xE1 solo en modo refrigeraci\xF3n permanentemente por seguridad hoy."],respuesta_correcta:0,explicacion:"Con el sensor de defrost en circuito abierto, la placa interpreta que la temperatura del serpentin nunca baja lo suficiente. El sistema no cumple las condiciones para iniciar el deshielo y el hielo se acumula."},{id:"ns_0671",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un sistema VRF. \xBFPor qu\xE9 es vital pesar la carga?",opciones:["Los sistemas VRF son de carga cr\xEDtica y las presiones no son indicadores hoy hoy hoy.","Es un requisito legal de la EPA para sistemas con m\xE1s de 50 libras de gas hoy.","Para asegurar que el aceite POE regrese correctamente a los compresores hoy hoy.","Para evitar que la garant\xEDa del fabricante se anule tras la instalaci\xF3n hoy hoy."],respuesta_correcta:0,explicacion:"En sistemas VRF con m\xFAltiples zonas y l\xEDneas extensas, las presiones fluct\xFAan seg\xFAn la demanda t\xE9rmica de cada evaporador. Por eso, el pesaje exacto de refrigerante seg\xFAn la f\xF3rmula del fabricante es el \xFAnico m\xE9todo confiable de carga."},{id:"ns_0672",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Reversal'. \xBFQu\xE9 sucede si se ignora el error?",opciones:["El compresor girar\xE1 al rev\xE9s y no bombear\xE1 aceite ni refrigerante l\xEDquido hoy hoy hoy.","La unidad funcionar\xE1 al 50% de su capacidad nominal debido al desfase fase hoy.","El motor se quemar\xE1 instant\xE1neamente al intentar vencer la inercia carga hoy hoy.","Las v\xE1lvulas de expansi\xF3n se cerrar\xE1n por seguridad al detectar el error hoy hoy."],respuesta_correcta:0,explicacion:"Phase Reversal causa rotaci\xF3n inversa del compresor, eliminando el bombeo de aceite y la circulaci\xF3n de refrigerante. Los cojinetes fallan r\xE1pidamente sin lubricaci\xF3n adecuada."},{id:"ns_0673",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. Subenfriamiento 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido severa en el sistema (Undercharged) hoy hoy hoy hoy.","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total hoy hoy hoy.","Condensador exterior extremadamente sucio que no permite el intercambio t\xE9rmico.","Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."],respuesta_correcta:0,explicacion:"Subenfriamiento de 0\xB0F con presiones moderadas es el indicador diagn\xF3stico definitivo de falta severa de refrigerante. No hay suficiente masa de refrigerante en el sistema para que el condensador produzca l\xEDquido subenfriado en su salida."},{id:"ns_0674",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n hoy hoy hoy.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada hoy hoy hoy.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial hoy hoy hoy.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos hoy hoy."],respuesta_correcta:0,explicacion:"Smart Homes exige t\xE9cnicos que dominen redes y protocolos de comunicaci\xF3n para integrar termostatos inteligentes, sensores IoT y sistemas de automatizaci\xF3n con el HVAC."},{id:"ns_0675",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 indica una temperatura de succi\xF3n muy alta en el cabezal?",opciones:["Sobrecalentamiento excesivo que da\xF1ar\xE1 la lubricaci\xF3n de compresores pronto hoy hoy.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de evaporaci\xF3n hoy hoy hoy.","Falta de refrigerante l\xEDquido en el recibidor principal del rack paralelo hoy hoy.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n cerradas por temperatura hoy hoy."],respuesta_correcta:0,explicacion:"El gas de succi\xF3n demasiado caliente significa que los compresores reciben vapor con poco contenido de refrigerante l\xEDquido para enfriar el motor. Esto causa degradaci\xF3n acelerada del aceite y posible da\xF1o en los devanados del motor el\xE9ctrico."},{id:"ns_0676",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. \xBFQu\xE9 revisa?",opciones:["Presencia de aire en la tuber\xEDa, paddle roto o transductor descalibrado hoy hoy hoy.","La carga de refrigerante que podr\xEDa estar congelando el agua en tubos hoy hoy.","El sentido de rotaci\xF3n del motor del compresor centr\xEDfugo del sistema hoy hoy hoy.","La apertura de las v\xE1lvulas de expansi\xF3n del circuito de refrigeraci\xF3n hoy hoy hoy."],respuesta_correcta:0,explicacion:"Una alarma de flow switch con bomba operando indica un problema del sensor (paddle, transductor) o aire en la tuber\xEDa, no del sistema de refrigeraci\xF3n del chiller."},{id:"ns_0677",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. \xBFCausa?",opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior hoy hoy hoy.","La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy hoy.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido hoy.","La humedad en la habitaci\xF3n es superior al 95% y satura el serpent\xEDn hoy hoy hoy."],respuesta_correcta:0,explicacion:"El goteo al detenerse el compresor es causado por agua acumulada que no drena durante la operaci\xF3n debido a contrapendiente o bloqueo parcial alto en la l\xEDnea de drenaje."},{id:"ns_0678",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de 0.9 en suministro y 0.2 en retorno. \xBFProblema?",opciones:["Restricci\xF3n severa en conductos de suministro o difusores cerrados hoy hoy hoy hoy.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire hoy hoy.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo hoy hoy hoy.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o hoy hoy hoy."],respuesta_correcta:0,explicacion:'La distribuci\xF3n 0.9"/0.2" de presi\xF3n est\xE1tica indica restricci\xF3n predominante en el suministro. Cuando la mayor\xEDa de la ca\xEDda de presi\xF3n est\xE1 en el suministro, hay que buscar conductos restringidos, da\xF1ados o difusores cerrados en ese lado.'},{id:"ns_0679",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre 20\xB0F y 30\xB0F hoy hoy hoy.","S\xED, las bombas de calor siempre tienen un diferencial menor que hornos hoy hoy.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube hoy.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo hoy hoy."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en calefaccion esta fuera del rango aceptable (20-30F). Indica capacidad insuficiente, que puede deberse a baja carga de refrigerante, exceso de flujo de aire, o absorcion deficiente de calor exterior."},{id:"ns_0680",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. \xBFQu\xE9 paso es vital post-quemadura?",opciones:["Realizar prueba de acidez del aceite y usar filtros succi\xF3n de limpieza hoy hoy.","A\xF1adir aditivo sellador de fugas para prevenir fallas futuras en l\xEDneas hoy hoy.","Cambiar el contactor y el capacitor aunque parezcan estar en buen estado hoy hoy.","Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy hoy hoy."],respuesta_correcta:0,explicacion:"El procedimiento post-burnout incluye obligatoriamente la prueba de acidez del aceite y la instalaci\xF3n de filtros de succi\xF3n de limpieza. Estos pasos eliminan contaminantes \xE1cidos y residuos s\xF3lidos que destruir\xEDan prematuramente el compresor nuevo."},{id:"ns_0681",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. \xBFEstado?",opciones:["Funcionamiento correcto; la purga est\xE1 separando los no condensables hoy hoy hoy hoy.","Falla en el serpent\xEDn de condensaci\xF3n interno de la unidad de purga hoy hoy hoy.","El sistema tiene una fuga masiva de agua hacia el lado del refrigerante hoy hoy.","La temperatura del evaporador es demasiado alta para que la purga trabaje hoy hoy."],respuesta_correcta:0,explicacion:"La purga que expulsa aire con m\xEDnimo refrigerante funciona correctamente. Su dise\xF1o separa gases no condensables y los expulsa mientras retorna el refrigerante al sistema."},{id:"ns_0682",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si el 'Oil Separator' queda pegado en posici\xF3n abierta?",opciones:["Gas caliente de descarga pasar\xE1 directo al dep\xF3sito aceite y succi\xF3n hoy hoy hoy.","El rack se quedar\xE1 sin aceite en pocos minutos al no poder separarlo gas hoy hoy.","Los compresores se apagar\xE1n por alta presi\xF3n al bloquearse el flujo gas hoy hoy.","El nivel de aceite en los c\xE1rteres subir\xE1 tanto que da\xF1ar\xE1 los pistones hoy hoy."],respuesta_correcta:0,explicacion:"Un flotador trabado abierto en el separador permite el paso directo de gas de descarga a alta presi\xF3n y temperatura hacia el dep\xF3sito de aceite. Este cortocircuito interno compromete tanto la separaci\xF3n de aceite como la eficiencia del sistema."},{id:"ns_0683",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. \xBFQu\xE9 KPI usa?",opciones:["N\xFAmero de llamadas de nuevos clientes que mencionan haber visto la unidad hoy hoy hoy.","La cantidad de millas recorridas por cada veh\xEDculo en zonas residenciales hoy hoy.","El costo total del dise\xF1o e instalaci\xF3n del r\xF3tulo dividido entre 12 meses hoy.","El aumento en la velocidad promedio de t\xE9cnicos al conducir camionetas nuevas hoy."],respuesta_correcta:0,explicacion:"El KPI para camionetas rotuladas es el n\xFAmero de llamadas de nuevos clientes que reportan haber visto el veh\xEDculo, vinculando directamente la inversi\xF3n con nuevos leads."},{id:"ns_0684",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. \xBFQu\xE9 revisa?",opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy hoy hoy hoy.","La carga de refrigerante l\xEDquido bas\xE1ndose en el visor del evaporador hoy hoy hoy.","Si la v\xE1lvula de expansi\xF3n est\xE1 inyectando demasiado l\xEDquido al sistema hoy hoy.","El estado de los filtros de aire de la manejadora de aire del edificio hoy hoy."],respuesta_correcta:0,explicacion:"Alta presi\xF3n de condensaci\xF3n con condensador de agua se diagnostica primero verificando la temperatura del agua de torre y la operaci\xF3n de la bomba de agua de condensador."},{id:"ns_0685",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n de 125 PSI y descarga 400 PSI con R-410A. \xBFEstado aire?",opciones:["Funcionamiento normal bajo condiciones de carga t\xE9rmica est\xE1ndar hoy hoy hoy hoy hoy.","Falta de refrigerante que impide que temperatura del aire baje a 55 grados hoy hoy.","Exceso de carga que est\xE1 elevando la presi\xF3n de descarga innecesariamente hoy hoy.","Compresor con eficiencia reducida que no logra enfriar el aire correctamente hoy."],respuesta_correcta:0,explicacion:"Succi\xF3n de 125 PSI y descarga de 400 PSI son valores est\xE1ndar para R-410A bajo condiciones normales de carga. El diferencial de presi\xF3n y las temperaturas de saturaci\xF3n corresponden a operaci\xF3n correcta del sistema."},{id:"ns_0686",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. \xBFQu\xE9 estrategia?",opciones:["Programa de membres\xEDas mantenimiento para convertir clientes en recurrentes hoy hoy hoy.","Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy hoy hoy.","Gastar m\xE1s dinero en anuncios de Google para atraer siempre clientes nuevos hoy hoy.","Despedir a t\xE9cnicos que no logren vender un sistema nuevo en cada visita hoy hoy."],respuesta_correcta:0,explicacion:"Un programa de membres\xEDas de mantenimiento es la estrategia clave para reducir el porcentaje de clientes que solo usan el servicio una vez."},{id:"ns_0687",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. \xBFQu\xE9 revisa?",opciones:["Carga de refrigerante baja o una restricci\xF3n en la v\xE1lvula de expansi\xF3n hoy hoy hoy.","Si el ventilador interior est\xE1 sucio y no sopla suficiente aire fr\xEDo hoy hoy hoy.","El voltaje de la l\xEDnea el\xE9ctrica que podr\xEDa estar por debajo de 200V hoy hoy hoy.","Si el control remoto est\xE1 configurado en una temperatura demasiado baja hoy hoy."],respuesta_correcta:0,explicacion:"La temperatura de descarga excesiva se produce por falta de refrigerante o restricci\xF3n en la EEV, ya que ambas condiciones reducen el enfriamiento del compresor por el gas de succi\xF3n."},{id:"ns_0688",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba calor, \xBFqu\xE9 sucede si 'Check Valve' condensador falla abierta?",opciones:["En modo calor el refrigerante har\xE1 bypass a TXV impidiendo calentamiento hoy hoy hoy.","El sistema funcionar\xE1 mejor al haber menos restricci\xF3n al flujo l\xEDquido hoy hoy.","La presi\xF3n de descarga subir\xE1 hasta que switch de alta apague el equipo hoy hoy.","El compresor se quemar\xE1 por el retorno de l\xEDquido masivo en el arranque hoy hoy."],respuesta_correcta:0,explicacion:"Si la check valve del condensador falla abierta, el refrigerante en modo calor hace bypass a la TXV sin restriccion. Sin caida de presion en el dispositivo de expansion, no hay transferencia de calor efectiva."},{id:"ns_0689",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula 'Quench' o inyecci\xF3n de l\xEDquido?",opciones:["Para enfriar gas de succi\xF3n y evitar que descarga da\xF1e el aceite hoy hoy hoy hoy hoy.","Para aumentar la presi\xF3n de succi\xF3n cuando carga en vitrinas es baja hoy hoy hoy.","Para limpiar el interior de compresores de acumulaciones de carbonilla hoy hoy hoy.","Para ayudar al retorno de aceite desde los evaporadores m\xE1s lejanos hoy hoy hoy."],respuesta_correcta:0,explicacion:"La inyecci\xF3n de l\xEDquido Quench protege los compresores manteniendo la temperatura de descarga en rangos seguros. El aceite POE se descompone a temperaturas superiores a 250\xB0F, generando \xE1cidos que corroen componentes internos del compresor."},{id:"ns_0690",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. \xBFCriterio?",opciones:["El volumen de agua y la accesibilidad para eliminaci\xF3n segura del fluido hoy hoy hoy.","Cu\xE1l de las dos herramientas es m\xE1s nueva y hace menos ruido al operar hoy hoy.","La preferencia del cliente sobre qu\xE9 herramienta quiere ver en su casa hoy hoy.","Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy hoy hoy."],respuesta_correcta:0,explicacion:"El criterio t\xE9cnico correcto eval\xFAa el volumen total de agua y las condiciones de acceso al punto de drenaje. Estos factores determinan si una aspiradora de agua o una bomba es la herramienta m\xE1s apropiada para la eliminaci\xF3n segura y eficiente."},{id:"ns_0691",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene purga que marca 'Water Detected'. \xBFQu\xE9 acci\xF3n es urgente?",opciones:["Realizar prueba presi\xF3n a tubos del evaporador para buscar rupturas hoy hoy hoy hoy.","Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy hoy.","Aumentar la temperatura del agua helada para evitar que vapor condense hoy hoy hoy.","Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy hoy."],respuesta_correcta:0,explicacion:"Water Detected por la purga requiere acci\xF3n urgente: prueba de presi\xF3n a los tubos del evaporador para identificar la fuente de contaminaci\xF3n por agua antes de que da\xF1e el sistema."},{id:"ns_0692",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n 130 PSI y descarga 380 PSI. Subenfriamiento 12\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y el subenfriamiento est\xE1n en rango hoy hoy hoy.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser 15 grados hoy hoy.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno hoy hoy.","Compresor fallando; la diferencia presi\xF3n entre succi\xF3n y descarga es baja hoy hoy."],respuesta_correcta:0,explicacion:"Las presiones de 130/380 PSI con 12\xB0F de subenfriamiento confirman operaci\xF3n \xF3ptima. Todos los valores est\xE1n en rangos aceptables para R-410A, indicando carga correcta y buen funcionamiento del compresor y componentes."},{id:"ns_0693",categoria:"NATE_SR_PACKAGE",pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["El voltaje en la bobina (24V) y si hay suciedad u \xF3xido en el n\xFAcleo hoy hoy hoy hoy.","Si los contactos principales est\xE1n quemados o soldados entre s\xED hoy hoy hoy hoy.","El capacitor de arranque del compresor que podr\xEDa estar descargado hoy hoy hoy.","La continuidad de los fusibles de potencia de la l\xEDnea de 240 voltios hoy hoy hoy."],respuesta_correcta:0,explicacion:"Cuando un contactor zumba sin cerrar, la bobina electromagn\xE9tica no puede vencer la fuerza del resorte de retorno. Las dos causas principales son voltaje bajo en la bobina (ca\xEDda por cableado o transformador d\xE9bil) y contaminaci\xF3n del n\xFAcleo que aumenta el entrehierro efectivo."},{id:"ns_0694",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico cobra 'por fuera' a clientes. \xBFQu\xE9 acci\xF3n toma?",opciones:["Despido inmediato y posible acci\xF3n legal seg\xFAn el contrato de trabajo hoy hoy hoy hoy.","Hablar con el t\xE9cnico y pedirle una comisi\xF3n por esos trabajos extras hoy hoy hoy.","Ignorar la situaci\xF3n si el t\xE9cnico es el que m\xE1s dinero genera hoy hoy hoy hoy.","Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy hoy."],respuesta_correcta:0,explicacion:"Cobrar por fuera viola la confianza y el contrato laboral; el despido inmediato con posible acci\xF3n legal es la medida necesaria para preservar la integridad del negocio."},{id:"ns_0695",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFPor qu\xE9 es fundamental cargar l\xEDquido en el recibidor?",opciones:["Para evitar fraccionamiento de la mezcla y asegurar composici\xF3n correcta hoy hoy hoy hoy.","Para que el refrigerante se mezcle m\xE1s r\xE1pido con el aceite POE del rack hoy hoy.","Para prevenir que las v\xE1lvulas de descarga de compresores se calienten hoy hoy hoy.","Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal hoy hoy hoy."],respuesta_correcta:0,explicacion:"El fraccionamiento de mezclas zeotr\xF3picas como el R-448A ocurre cuando los componentes se separan al evaporarse a diferentes temperaturas. Cargar siempre en l\xEDquido mantiene la proporci\xF3n exacta de cada componente en la mezcla refrigerante."},{id:"ns_0696",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. \xBFEfecto?",opciones:["El controlador no podr\xE1 calcular la carga t\xE9rmica real del edificio hoy hoy hoy hoy.","El compresor se apagar\xE1 inmediatamente por seguridad de flujo de agua hoy hoy hoy.","La unidad operar\xE1 siempre al 100% de su capacidad nominal sin modular hoy hoy hoy.","No hay efecto si el sensor de 'Leaving Water' est\xE1 operando correctamente hoy hoy hoy."],respuesta_correcta:0,explicacion:"Sin el sensor de entrada de agua, el controlador no puede determinar la carga t\xE9rmica real, afectando la capacidad de modular correctamente la operaci\xF3n del chiller."},{id:"ns_0697",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de descarga de 550 PSI con R-410A. \xBFCausa?",opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy hoy hoy hoy.","Falta de refrigerante l\xEDquido que impide que el sistema enfr\xEDe el aire hoy hoy hoy.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total hoy hoy.","El compresor est\xE1 perdiendo eficiencia y no logra comprimir el gas ralo hoy hoy hoy."],respuesta_correcta:0,explicacion:"Descarga de 550 PSI es extremadamente alta para R-410A y se acerca al l\xEDmite de seguridad del sistema. Sin disipaci\xF3n adecuada de calor por condensador sucio o ventilador fallando, la presi\xF3n se acumula hasta niveles peligrosos que activan la protecci\xF3n de alta presi\xF3n."},{id:"ns_0698",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Average Response Time'. \xBFQu\xE9 medida toma hoy?",opciones:["Implementar software de despacho inteligente y zonificaci\xF3n de t\xE9cnicos hoy hoy hoy hoy.","Aumentar el n\xFAmero de t\xE9cnicos en la n\xF3mina aunque no haya llamadas suficientes hoy.","Reducir el tiempo de almuerzo de los t\xE9cnicos para que est\xE9n m\xE1s disponibles hoy hoy.","Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy hoy."],respuesta_correcta:0,explicacion:"Implementar software de despacho inteligente con zonificaci\xF3n de t\xE9cnicos es la medida m\xE1s t\xE9cnica y efectiva para reducir el Average Response Time de la empresa."},{id:"ns_0699",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. \xBFCausa?",opciones:["Falla de comunicaci\xF3n; el voltaje deber\xEDa fluctuar entre 0 y 24VDC hoy hoy hoy hoy hoy.","La placa exterior est\xE1 operando correctamente enviando la se\xF1al de control hoy hoy.","El compresor inverter est\xE1 aterrizado y consume el voltaje de comunicaci\xF3n hoy hoy.","Falta de alimentaci\xF3n de 240VAC en los terminales L1 y L2 de la exterior hoy hoy hoy."],respuesta_correcta:0,explicacion:"La se\xF1al entre S2 y S3 debe fluctuar entre 0 y 24VDC para transmitir datos. Un voltaje fijo de 24VDC indica falla de comunicaci\xF3n porque no hay modulaci\xF3n de se\xF1al digital."},{id:"ns_0700",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el 'Defrost Sensor' falla en circuito abierto?",opciones:["El sistema nunca entrar\xE1 en modo de deshielo y el serpent\xEDn se congelar\xE1 hoy hoy hoy.","El sistema entrar\xE1 en modo de deshielo cada 30 minutos sin importar el hielo hoy hoy.","El compresor se quemar\xE1 debido a la falta de control de sobrecalentamiento hoy hoy.","La unidad operar\xE1 solo en modo refrigeraci\xF3n permanentemente por seguridad hoy hoy."],respuesta_correcta:0,explicacion:"Cuando el sensor de defrost falla en circuito abierto, la placa nunca recibe la lectura de temperatura fria del serpentin. Sin cumplir esta condicion, el ciclo de deshielo nunca se inicia y el serpentin se congela."},{id:"ns_0701",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Vibration Trip' a altas RPM. Al inspeccionar, se encuentra un ligero desgaste en los sellos de laberinto. \xBFQu\xE9 riesgo Senior existe?",opciones:["P\xE9rdida de eficiencia por bypass interno de gas y aumento del ruido ac\xFAstico.","Migraci\xF3n masiva de aceite hacia el condensador que bloquear\xE1 el intercambio.","Explosi\xF3n por sobrepresi\xF3n interna al mezclarse el aire con el refrigerante.","Reducci\xF3n inmediata de la temperatura de descarga por debajo de saturaci\xF3n."],respuesta_correcta:0,explicacion:"El desgaste de sellos de laberinto permite bypass interno de gas entre etapas de compresi\xF3n, reduciendo la eficiencia del compresor y aumentando el nivel de ruido ac\xFAstico durante la operaci\xF3n."},{id:"ns_0702",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo con NH3 (Amon\xEDaco), \xBFcu\xE1l es la funci\xF3n de la v\xE1lvula de purga de aire autom\xE1tica?",opciones:["Eliminar gases no condensables del condensador para reducir la presi\xF3n de alta.","Liberar presi\xF3n de succi\xF3n hacia la atm\xF3sfera en caso de un paro de emergencia.","Drenar el aceite acumulado en el fondo de los evaporadores de baja temperatura.","Inyectar nitr\xF3geno para mantener la presi\xF3n positiva cuando el rack est\xE1 parado."],respuesta_correcta:0,explicacion:"Los gases no condensables (aire) se acumulan en el condensador y aumentan la presi\xF3n de descarga innecesariamente. La v\xE1lvula de purga autom\xE1tica detecta y elimina estos gases, manteniendo la eficiencia del condensador y reduciendo el consumo energ\xE9tico."},{id:"ns_0703",categoria:"NATE_SR_CEO",pregunta:"Un CEO recibe una rese\xF1a negativa viral sobre un t\xE9cnico Senior. \xBFCu\xE1l es la estrategia de 'Damage Control' m\xE1s efectiva?",opciones:["Responder con empat\xEDa, ofrecer una soluci\xF3n p\xFAblica y realizar una auditor\xEDa interna.","Ignorar el comentario para evitar que el algoritmo de redes sociales lo difunda m\xE1s.","Demandar al cliente por difamaci\xF3n si no presenta pruebas t\xE9cnicas del mal servicio.","Despedir al t\xE9cnico Senior inmediatamente para demostrar firmeza ante el p\xFAblico."],respuesta_correcta:0,explicacion:"Responder con empat\xEDa, ofrecer una soluci\xF3n p\xFAblica y hacer una auditor\xEDa interna demuestra profesionalismo, convierte una crisis en oportunidad y protege la reputaci\xF3n a largo plazo."},{id:"ns_0704",categoria:"NATE_SR_PACKAGE",pregunta:"Un variador de frecuencia (VFD) genera interferencia (EMI) que afecta a los sensores DDC cercanos. \xBFQu\xE9 componente debe instalar el Senior?",opciones:["Un filtro de arm\xF3nicos en la entrada o cables de motor blindados con tierra.","Un transformador de aislamiento de mayor capacidad para alimentar al variador.","Capacitores de correcci\xF3n de factor de potencia en paralelo con el motor AC.","Un supresor de picos (TVSS) en el tablero de distribuci\xF3n el\xE9ctrica principal."],respuesta_correcta:0,explicacion:"Los VFD generan arm\xF3nicos y ruido EMI por la conmutaci\xF3n PWM de alta frecuencia. Un filtro de arm\xF3nicos en la entrada reduce las corrientes arm\xF3nicas, y los cables blindados con tierra adecuada contienen la radiaci\xF3n electromagn\xE9tica, protegiendo los sensores DDC cercanos de interferencias."},{id:"ns_0705",categoria:"NATE_SR_HVAC",pregunta:"Un sistema de 10 toneladas tiene un Delta P de 0.1 pulg. W.C. a trav\xE9s de un serpent\xEDn de enfriamiento. \xBFQu\xE9 indica este valor?",opciones:["Falta de flujo de aire cr\xEDtico o serpent\xEDn extremadamente sobredimensionado.","Serpent\xEDn saturado de suciedad que requiere una limpieza qu\xEDmica profunda hoy.","Operaci\xF3n nominal seg\xFAn las tablas de dise\xF1o para sistemas de alta velocidad.","Que el motor del soplador est\xE1 girando al doble de sus RPM de placa nominal."],respuesta_correcta:0,explicacion:'Un Delta P de solo 0.1" W.C. a trav\xE9s de un serpent\xEDn de 10 toneladas es extremadamente bajo e indica que casi no hay aire pasando. Esto significa falta de flujo de aire cr\xEDtico, ya sea por un soplador fallando, conductos desconectados o un serpent\xEDn enormemente sobredimensionado.'},{id:"ns_0706",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor presenta una succi\xF3n de 60 PSI con R-410A. El serpent\xEDn exterior est\xE1 limpio. \xBFQu\xE9 revisa el Senior?",opciones:["La v\xE1lvula de expansi\xF3n exterior o una posible falta de carga de refrigerante.","El ventilador interior que podr\xEDa estar moviendo aire a una velocidad excesiva.","La v\xE1lvula inversora que podr\xEDa estar parcialmente movida hacia refrigeraci\xF3n.","El sensor de temperatura de aire de retorno que activa el ciclo de deshielo."],respuesta_correcta:0,explicacion:"Una succion de 60 PSI con R-410A equivale a aproximadamente 17F de saturacion, lo cual es bajo para modo calor. Con el serpentin limpio, la causa mas probable es una TXV exterior defectuosa o falta de carga."},{id:"ns_0707",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un equipo que realiza una prueba de presi\xF3n con aire comprimido en lugar de nitr\xF3geno. \xBFPor qu\xE9 es una falla grave?",opciones:["El aire introduce humedad y ox\xEDgeno, lo que causar\xE1 acidez y oxidaci\xF3n interna.","El aire comprimido no alcanza las presiones necesarias para detectar micro-fugas.","La EPA proh\xEDbe el uso de aire atmosf\xE9rico en sistemas que usaron aceites POE.","El aire comprimido es explosivo cuando se mezcla con restos de aceite mineral."],respuesta_correcta:0,explicacion:"El aire comprimido contiene humedad y ox\xEDgeno. La humedad reacciona con el refrigerante y el aceite formando \xE1cidos corrosivos, y el ox\xEDgeno oxida las superficies internas de cobre. El nitr\xF3geno seco es inerte y libre de humedad, por eso es el est\xE1ndar."},{id:"ns_0708",categoria:"NATE_SR_CHILLERS",pregunta:"En un chiller centr\xEDfugo, \xBFqu\xE9 par\xE1metro define el 'Choke Point' o punto de saturaci\xF3n de flujo?",opciones:["La velocidad del sonido del refrigerante en la garganta del impulsor del motor.","La temperatura m\xE1xima que puede soportar el aceite antes de carbonizarse hoy.","La presi\xF3n diferencial m\xE1xima entre el condensador y el evaporador del sistema.","El amperaje m\xE1ximo de placa del motor dividido por el factor de servicio real."],respuesta_correcta:0,explicacion:"El choke point ocurre cuando el flujo de gas alcanza la velocidad del sonido (velocidad s\xF3nica) en la garganta del impulsor, limitando el flujo m\xE1ximo independientemente del diferencial de presi\xF3n."},{id:"ns_0709",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de 30 toneladas presenta una falla de 'Low Suction Pressure'. El filtro est\xE1 limpio. \xBFQu\xE9 revisa el Senior?",opciones:["La carga de refrigerante y el funcionamiento de la v\xE1lvula de expansi\xF3n t\xE9rmica.","La rotaci\xF3n del ventilador del condensador que podr\xEDa estar girando al rev\xE9s.","Si el economizador est\xE1 introduciendo demasiado aire exterior fr\xEDo al sistema.","El ajuste del interruptor de alta presi\xF3n que podr\xEDa estar disparando el paro."],respuesta_correcta:0,explicacion:"Una presi\xF3n de succi\xF3n baja con filtro limpio indica que no llega suficiente refrigerante al evaporador. Las causas principales son carga baja (fuga) o una TXV que no abre lo suficiente, restringiendo el flujo de refrigerante l\xEDquido y bajando la presi\xF3n de evaporaci\xF3n."},{id:"ns_0710",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC analiza el 'Customer Retention Rate'. Si este baja del 70%, \xBFcu\xE1l es el impacto financiero?",opciones:["Aumento dr\xE1stico en el CAC (Customer Acquisition Cost) para mantener el ingreso.","Reducci\xF3n inmediata en los costos de marketing al haber menos clientes activos.","Mejora en el margen de utilidad neta al enfocarse solo en clientes nuevos hoy.","Incremento en el valor de reventa de la empresa por la rotaci\xF3n de cartera."],respuesta_correcta:0,explicacion:"Cuando la retenci\xF3n cae del 70%, la empresa debe gastar mucho m\xE1s en adquirir nuevos clientes (CAC alto) para reemplazar a los que se van, afectando severamente la rentabilidad."},{id:"ns_0711",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que marca 'High Non-Condensable Concentration'. El sistema opera a presi\xF3n positiva. \xBFCausa?",opciones:["Infiltraci\xF3n de aire durante una carga de refrigerante o servicio mal realizado.","Falla en el serpent\xEDn de condensaci\xF3n de la purga que no lic\xFAa el refrigerante.","El refrigerante se est\xE1 descomponiendo qu\xEDmicamente por alta temperatura descarga.","Agua infiltrada desde el evaporador que se est\xE1 evaporando dentro del sistema."],respuesta_correcta:0,explicacion:"En un sistema a presi\xF3n positiva, la alta concentraci\xF3n de no condensables indica que el aire entr\xF3 durante un servicio o carga de refrigerante mal realizada, no por infiltraci\xF3n durante operaci\xF3n."},{id:"ns_0712",categoria:"NATE_SR_RACK",pregunta:"En un rack de refrigeraci\xF3n, \xBFcu\xE1l es el s\xEDntoma de un separador de aceite con el flotador perforado?",opciones:["Paso masivo de gas de descarga hacia el dep\xF3sito de aceite y la l\xEDnea de succi\xF3n.","Falla de lubricaci\xF3n inmediata al no retornar aceite hacia los compresores hoy.","Aumento en la presi\xF3n de descarga debido a la restricci\xF3n de flujo de gas hoy.","Nivel de aceite excesivamente alto en el c\xE1rter de todos los compresores rack."],respuesta_correcta:0,explicacion:"Un flotador perforado se hunde y queda permanentemente abierto, permitiendo el paso continuo de gas de descarga caliente hacia el dep\xF3sito de aceite y eventualmente hacia la succi\xF3n, creando un bypass que reduce la capacidad del sistema."},{id:"ns_0713",categoria:"NATE_SR_CEO",pregunta:"Un CEO eval\xFAa el 'Account Payable Turnover'. Si este valor es muy bajo, \xBFqu\xE9 indica?",opciones:["La empresa est\xE1 tardando demasiado en pagar a sus proveedores de materiales.","La empresa tiene un flujo de caja excelente y paga todas sus deudas pronto.","Los clientes est\xE1n pagando sus facturas de servicio de forma casi instant\xE1nea.","El inventario de piezas se est\xE1 moviendo m\xE1s r\xE1pido de lo presupuestado hoy."],respuesta_correcta:0,explicacion:"Un Account Payable Turnover bajo significa que la empresa tarda demasiado en pagar a sus proveedores, lo que puede da\xF1ar relaciones comerciales y limitar el cr\xE9dito futuro."},{id:"ns_0714",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRF tiene un error de 'Sub-cooling Thermistor'. \xBFC\xF3mo afecta esto la eficiencia?",opciones:["El sistema no puede optimizar la carga de l\xEDquido, aumentando el consumo el\xE9ctrico.","El compresor inverter se bloquear\xE1 para evitar que el l\xEDquido llegue a succi\xF3n.","La unidad exterior se apagar\xE1 por completo hasta que el sensor sea reemplazado.","No afecta si la temperatura de descarga se mantiene por debajo de 200 grados F."],respuesta_correcta:0,explicacion:"El termistor de subenfriamiento permite al sistema optimizar la cantidad de l\xEDquido en el condensador. Sin esta lectura, el sistema no ajusta eficientemente la carga de l\xEDquido, aumentando el consumo el\xE9ctrico."},{id:"ns_0715",categoria:"NATE_SR_HVAC",pregunta:"Se encuentra un 'Voltage Imbalance' del 4% en un motor trif\xE1sico. \xBFCu\xE1l es el aumento de temperatura estimado?",opciones:["Aproximadamente un 25% a 30% por encima de la temperatura de operaci\xF3n normal.","Menos del 5%, lo cual es despreciable para motores con factor de servicio 1.15.","El motor operar\xE1 m\xE1s fr\xEDo debido a la reducci\xF3n del par motor (torque) total.","Depende \xFAnicamente de si el motor es de alta eficiencia (NEMA Premium) o no."],respuesta_correcta:0,explicacion:"Un desbalance de voltaje del 4% causa un aumento desproporcionado de temperatura en los devanados de aproximadamente 25-30%. La regla general es que el aumento de temperatura es proporcional al cuadrado del porcentaje de desbalance multiplicado por un factor de ~2."},{id:"ns_0716",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor activa el defrost. El ventilador exterior no se detiene. \xBFCausa?",opciones:["Rel\xE9 de la placa de control pegado o l\xF3gica de control de defrost defectuosa.","Es un comportamiento normal en modelos nuevos que usan VFD en el ventilador.","La v\xE1lvula inversora no logr\xF3 cambiar de posici\xF3n y el sistema sigue en calor.","El sensor de temperatura de ambiente exterior est\xE1 marcando un valor falso hoy."],respuesta_correcta:0,explicacion:"Durante el defrost, el ventilador exterior debe detenerse para que el gas caliente derrita el hielo sin que el aire frio enfrie el serpentin. Si el rele de la placa esta pegado, el ventilador sigue y el deshielo es ineficaz."},{id:"ns_0717",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior observa que un Junior no realiza el 'Triple Vac\xEDo'. \xBFCu\xE1l es el beneficio que se pierde?",opciones:["La capacidad de remover humedad profunda mediante la diluci\xF3n con nitr\xF3geno seco.","El ahorro de tiempo en el proceso de evacuaci\xF3n de sistemas de gran tonelaje.","La verificaci\xF3n de la estanqueidad del sistema antes de cargar el refrigerante.","La eliminaci\xF3n de los incondensables que quedan atrapados en el aceite POE hoy."],respuesta_correcta:0,explicacion:"El triple vac\xEDo consiste en evacuar, romper el vac\xEDo con nitr\xF3geno seco, y repetir tres veces. Cada ciclo de nitr\xF3geno diluye y arrastra la humedad residual que el vac\xEDo solo no puede eliminar completamente, logrando un secado mucho m\xE1s profundo."},{id:"ns_0718",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con evaporador de placas presenta una fuga interna. \xBFCu\xE1l es el s\xEDntoma?",opciones:["Mezcla de agua en el refrigerante y refrigerante en el lazo de agua helada.","Aumento dr\xE1stico de la presi\xF3n de succi\xF3n debido a la densidad del agua.","El aceite se vuelve lechoso y el compresor se apaga por alta presi\xF3n aceite.","La temperatura del agua helada baja de golpe por debajo del punto congelaci\xF3n."],respuesta_correcta:0,explicacion:"Una fuga interna en un evaporador de placas permite que el agua y el refrigerante se mezclen en ambas direcciones, contaminando tanto el circuito de refrigerante como el lazo de agua helada."},{id:"ns_0719",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete industrial tiene un motor de soplador con polea ajustable. Para aumentar CFM, \xBFqu\xE9 hace?",opciones:["Cerrar la polea del motor para aumentar el di\xE1metro efectivo y las RPM.","Abrir la polea del motor para reducir la tensi\xF3n de la correa y el roce hoy.","Cambiar la polea del soplador por una de mayor di\xE1metro para ganar torque.","Ajustar los tornillos de la base del motor para estirar la correa al m\xE1ximo."],respuesta_correcta:0,explicacion:"En una polea ajustable del motor, cerrar las mitades aumenta el di\xE1metro efectivo donde corre la correa. Esto aumenta la relaci\xF3n de poleas, haciendo que la polea del soplador gire m\xE1s r\xE1pido (m\xE1s RPM), lo que incrementa los CFM entregados al sistema de ductos."},{id:"ns_0720",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere implementar 'Job Costing' en tiempo real. \xBFQu\xE9 dato es el m\xE1s dif\xEDcil de capturar?",opciones:["El costo exacto de los consumibles menores y el tiempo de viaje real hoy.","El precio de los equipos principales como condensadores o manejadoras aire.","El salario bruto de los t\xE9cnicos Senior que realizan la instalaci\xF3n hoy hoy.","La cantidad de refrigerante recuperado durante el proceso de desinstalaci\xF3n."],respuesta_correcta:0,explicacion:"Los consumibles menores (selladores, cinta, conectores) y el tiempo de viaje real son los datos m\xE1s dif\xEDciles de capturar en tiempo real para un Job Costing preciso."},{id:"ns_0721",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un 'Approach' de condensador de 15\xB0F. Se sospecha de aire. \xBFC\xF3mo lo confirma?",opciones:["Comparando la presi\xF3n de descarga con la temperatura de saturaci\xF3n del gas.","Midiendo la temperatura de la carcasa del condensador con un sensor l\xE1ser.","Drenando una muestra de refrigerante y oliendo si hay presencia de \xE1cido.","Observando si hay burbujas en la mirilla de la l\xEDnea de l\xEDquido del chiller."],respuesta_correcta:0,explicacion:"Comparando la presi\xF3n de descarga real con la presi\xF3n de saturaci\xF3n a la temperatura medida del refrigerante, se confirma la presencia de aire. Si la presi\xF3n real es mayor, hay no condensables."},{id:"ns_0722",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una succi\xF3n de 100 PSI y descarga de 400 PSI con R-410A. \xBFC\xF3mo est\xE1 el flujo?",opciones:["Bajo flujo de aire en el evaporador o falta de carga de refrigerante leve.","Funcionamiento normal considerando una temperatura exterior de 95 grados F.","Exceso de carga que est\xE1 inundando el serpent\xEDn del condensador exterior.","Compresor con v\xE1lvulas da\xF1adas que no logran bombear el gas correctamente."],respuesta_correcta:0,explicacion:"Succi\xF3n de 100 PSI (baja, ~30\xB0F sat.) con descarga de 400 PSI indica que el evaporador no absorbe suficiente calor. Bajo flujo de aire reduce la carga t\xE9rmica en el evaporador, y falta leve de carga tambi\xE9n explica la succi\xF3n baja con descarga relativamente normal."},{id:"ns_0723",categoria:"NATE_SR_CEO",pregunta:"Como CEO, usted es auditado por el manejo de cilindros de recuperaci\xF3n. \xBFQu\xE9 falta es grave?",opciones:["Cilindros con fecha de prueba hidrost\xE1tica vencida (m\xE1s de 5 a\xF1os).","Usar cilindros de color gris con tapa amarilla para refrigerante R-410A.","Transportar m\xE1s de 3 cilindros en una camioneta de servicio est\xE1ndar hoy.","No tener el logotipo de la empresa impreso en la etiqueta del cilindro."],respuesta_correcta:0,explicacion:"Los cilindros de recuperaci\xF3n con prueba hidrost\xE1tica vencida (m\xE1s de 5 a\xF1os) representan un riesgo de seguridad y una falta grave ante auditor\xEDas DOT y EPA."},{id:"ns_0724",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calefacci\xF3n, una bomba de calor tiene un Delta T de 10\xB0F. Las resistencias est\xE1n apagadas. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido o flujo de aire interior excesivamente alto.","Operaci\xF3n normal; el Delta T subir\xE1 cuando la temperatura exterior baje.","V\xE1lvula inversora que no cambi\xF3 de posici\xF3n y sigue en modo refrigeraci\xF3n.","Condensador exterior sucio que impide la absorci\xF3n de calor ambiental hoy."],respuesta_correcta:0,explicacion:"Un Delta T de 10F sin resistencias es muy bajo. Indica que el compresor no genera suficiente calor. Las causas principales son falta de refrigerante o flujo de aire interior excesivamente alto que diluye el calor."},{id:"ns_0725",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema inverter reporta error de 'Compressor Position Detection'. \xBFQu\xE9 pieza fall\xF3?",opciones:["La placa electr\xF3nica de potencia (IPM) o los imanes del rotor del compresor.","El sensor de presi\xF3n de succi\xF3n que no detecta el arranque del motor hoy.","El capacitor de marcha que est\xE1 desvalorizado y no provee el par inicial.","La comunicaci\xF3n entre el termostato de pared y la unidad interior del AC."],respuesta_correcta:0,explicacion:"El error de detecci\xF3n de posici\xF3n del compresor indica que la placa IPM no puede determinar la posici\xF3n del rotor. La falla est\xE1 en la placa de potencia (IPM) o en los imanes del rotor del compresor."},{id:"ns_0726",categoria:"NATE_SR_RACK",pregunta:"Un rack de baja temperatura usa R-404A. La succi\xF3n es de 0 PSI. Las vitrinas est\xE1n calientes. \xBFCausa?",opciones:["Fuga total de refrigerante o una restricci\xF3n masiva en la l\xEDnea de succi\xF3n.","Funcionamiento normal; la presi\xF3n baj\xF3 al alcanzarse la temperatura de set.","El separador de aceite se qued\xF3 pegado en la posici\xF3n de abierto total hoy.","Los ventiladores del condensador remoto est\xE1n girando a m\xE1xima velocidad."],respuesta_correcta:0,explicacion:"Una presi\xF3n de succi\xF3n de 0 PSI con vitrinas calientes indica que no hay refrigerante circulando. Las dos causas principales son una fuga total que vaci\xF3 el sistema, o una restricci\xF3n severa en la l\xEDnea de succi\xF3n que impide el flujo de gas."},{id:"ns_0727",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar el 'Upselling' en mantenimiento. \xBFQu\xE9 incentivo es m\xE1s \xE9tico?",opciones:["Bonos por identificar y reportar componentes con desgaste cr\xEDtico comprobado.","Comisiones directas por cada sistema nuevo vendido independientemente del estado.","Sanciones para los t\xE9cnicos que no vendan al menos un accesorio por visita.","Premios por rapidez en terminar la llamada de servicio de mantenimiento hoy."],respuesta_correcta:0,explicacion:"Bonificar por identificar componentes con desgaste cr\xEDtico comprobado es \xE9tico porque el t\xE9cnico reporta hallazgos reales que benefician al cliente y no inventa necesidades."},{id:"ns_0728",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Low Flow' intermitente. El tanque de expansi\xF3n est\xE1 lleno. \xBFQu\xE9 revisa?",opciones:["Presencia de aire en el lazo de agua o sensor de flujo (paddle) da\xF1ado.","La carga de refrigerante l\xEDquido bas\xE1ndose en el visor del evaporador hoy.","Si la v\xE1lvula de expansi\xF3n est\xE1 inyectando l\xEDquido al c\xE1rter del motor hoy.","El estado de los filtros de aire de la manejadora de aire del edificio hoy."],respuesta_correcta:0,explicacion:"Con tanque de expansi\xF3n lleno, un bajo flujo intermitente indica aire atrapado en el lazo de agua que causa bolsas de aire, o un sensor de flujo (paddle) da\xF1ado que genera lecturas inconsistentes."},{id:"ns_0729",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un sistema donde el cliente puente\xF3 el switch de alta presi\xF3n. \xBFAcci\xF3n?",opciones:["Retirar el puente, reparar la causa del disparo y advertir sobre el peligro.","Dejar el puente si el sistema est\xE1 enfriando bien y el cliente est\xE1 feliz.","Ajustar el switch de alta a un valor superior para que no dispare tanto hoy.","Cobrar el diagn\xF3stico y no tocar el sistema por riesgo de responsabilidad."],respuesta_correcta:0,explicacion:"El switch de alta presi\xF3n es un dispositivo de seguridad que protege contra sobrepresi\xF3n peligrosa. Puentearlo elimina esa protecci\xF3n y puede causar explosi\xF3n del serpent\xEDn o da\xF1o catastr\xF3fico. Se debe retirar el puente y resolver la causa ra\xEDz del disparo."},{id:"ns_0730",categoria:"NATE_SR_CEO",pregunta:"Un CEO decide usar 'Sub-contractors' para instalaciones. \xBFCu\xE1l es el mayor riesgo?",opciones:["Inconsistencia en la calidad del trabajo y falta de control sobre la garant\xEDa.","Aumento en los costos fijos mensuales al tener que pagar facturas externas.","Dificultad para programar las visitas de mantenimiento preventivo anual hoy.","Que el subcontratista use sus propias herramientas en lugar de las nuestras."],respuesta_correcta:0,explicacion:"Los subcontratistas crean inconsistencia en la calidad del trabajo y la empresa pierde control sobre las garant\xEDas, ya que el cliente responsabiliza al contratista principal."},{id:"ns_0731",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una aproximaci\xF3n de evaporador de 0\xB0F. El Senior sospecha de:",opciones:["Sensores de temperatura descalibrados o refrigerante l\xEDquido en la succi\xF3n.","El chiller est\xE1 operando en su punto m\xE1ximo de eficiencia termodin\xE1mica hoy.","Los tubos del evaporador han sido limpiados recientemente con \xE1cido fuerte.","El flujo de agua a trav\xE9s del evaporador es exactamente el doble del nominal."],respuesta_correcta:0,explicacion:"Un approach de evaporador de 0\xB0F es termodin\xE1micamente improbable y se\xF1ala sensores descalibrados o refrigerante l\xEDquido en la succi\xF3n que falsea las mediciones de temperatura y presi\xF3n."},{id:"ns_0732",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta ruidos de 'Water Hammering' en las l\xEDneas de refrigerante. \xBFCausa?",opciones:["L\xEDquido refrigerante regresando al compresor o falta de soportes en tuber\xEDa.","Aire atrapado en el sistema que no fue evacuado durante el proceso de vac\xEDo.","Una v\xE1lvula de expansi\xF3n que abre y cierra violentamente por falta de carga.","El uso de tuber\xEDa de succi\xF3n con un di\xE1metro mayor al especificado por dise\xF1o."],respuesta_correcta:0,explicacion:"El 'water hammering' se produce por el impacto hidr\xE1ulico del refrigerante l\xEDquido contra las paredes de la tuber\xEDa o los componentes del compresor. L\xEDquido regresando al compresor o tuber\xEDa sin soportes son las causas m\xE1s frecuentes de este fen\xF3meno destructivo."},{id:"ns_0733",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar el 'Gross Profit Margin'. \xBFCu\xE1l de estas acciones impacta m\xE1s r\xE1pido?",opciones:["Mejorar la precisi\xF3n de los presupuestos para reducir el desperdicio de materiales.","Contratar a m\xE1s personal administrativo para gestionar mejor las facturas de cobro.","Comprar uniformes m\xE1s econ\xF3micos para reducir el gasto general de la empresa.","Aumentar el l\xEDmite de cr\xE9dito de los clientes para fomentar compras m\xE1s grandes."],respuesta_correcta:0,explicacion:"Presupuestos m\xE1s precisos reducen el desperdicio de materiales y el tiempo no productivo, lo que mejora el Gross Profit Margin de forma r\xE1pida y directamente medible."},{id:"ns_0734",categoria:"NATE_SR_MINISPLIT",pregunta:"Un sistema VRF tiene un ruido de expansi\xF3n fuerte en las unidades interiores. \xBFCausa?",opciones:["Falta de carga de refrigerante que causa vapor en la l\xEDnea de l\xEDquido hoy.","La placa de control est\xE1 moviendo la EEV demasiado r\xE1pido entre pasos hoy.","El aceite del sistema es demasiado espeso y causa fricci\xF3n en la v\xE1lvula.","Es un comportamiento normal cuando el sistema opera a m\xE1xima frecuencia hoy."],respuesta_correcta:0,explicacion:"El ruido de expansi\xF3n en unidades interiores VRF indica falta de refrigerante que genera vapor (flash gas) en la l\xEDnea de l\xEDquido, creando turbulencia audible al pasar por la v\xE1lvula de expansi\xF3n."},{id:"ns_0735",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor geot\xE9rmica tiene una falla de 'High Pressure'. El lazo es abierto. \xBFCausa?",opciones:["Incrustaciones de minerales en el intercambiador de calor de agua/gas hoy.","La bomba del pozo se detuvo o el filtro de sedimentos est\xE1 obstruido hoy.","La temperatura del subsuelo ha subido por encima de los 80 grados F hoy.","Hay una fuga de refrigerante hacia el agua del pozo por una ruptura hoy."],respuesta_correcta:0,explicacion:"En geotermicas de lazo abierto, los minerales del agua del pozo forman incrustaciones en el intercambiador de calor. Esto reduce la transferencia termica y eleva la presion de descarga hasta activar el switch de alta."},{id:"ns_0736",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si la v\xE1lvula diferencial de aceite est\xE1 mal ajustada (muy alta)?",opciones:["Se inyecta demasiado aceite al c\xE1rter y puede causar da\xF1os mec\xE1nicos hoy.","No habr\xE1 suficiente presi\xF3n para que el aceite regrese a los compresores.","El separador de aceite se desbordar\xE1 hacia la l\xEDnea de descarga del rack.","La temperatura del aceite bajar\xE1 por debajo del punto de lubricaci\xF3n hoy."],respuesta_correcta:0,explicacion:"Un diferencial de aceite ajustado muy alto fuerza demasiado aceite hacia los c\xE1rteres de los compresores. El exceso de aceite l\xEDquido puede ser comprimido accidentalmente, causando da\xF1o mec\xE1nico en v\xE1lvulas, bielas y pistones."},{id:"ns_0737",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior detecta un error de dise\xF1o en un plano de conductos. \xBFQu\xE9 hace?",opciones:["Notificar al ingeniero de dise\xF1o y sugerir una correcci\xF3n basada en campo.","Instalar el sistema como dice el plano para no tener responsabilidad legal.","Corregir el dise\xF1o por su cuenta sin avisar a nadie para terminar r\xE1pido.","Decirle al cliente que el ingeniero no sabe nada y que \xE9l lo har\xE1 mejor."],respuesta_correcta:0,explicacion:"Un t\xE9cnico Senior experimentado puede identificar errores de dise\xF1o gracias a su experiencia de campo. La acci\xF3n correcta es notificar al ingeniero con una propuesta de correcci\xF3n, manteniendo la colaboraci\xF3n profesional y la documentaci\xF3n adecuada."},{id:"ns_0738",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que expulsa refrigerante l\xEDquido. \xBFQu\xE9 componente fall\xF3?",opciones:["La v\xE1lvula de flotador o el orificio de separaci\xF3n de la unidad de purga.","El compresor centr\xEDfugo que est\xE1 enviando l\xEDquido hacia el condensador.","El sensor de presi\xF3n de la purga que est\xE1 enviando una se\xF1al err\xF3nea.","El calentador de la purga que no est\xE1 evaporando el l\xEDquido recolectado."],respuesta_correcta:0,explicacion:"La v\xE1lvula de flotador de la purga separa el l\xEDquido del gas. Si falla o el orificio de separaci\xF3n se obstruye, refrigerante l\xEDquido pasa a la c\xE1mara de expulsi\xF3n en vez de solo gases."},{id:"ns_0739",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 115 PSI y descarga de 320 PSI con R-410A. \xBFC\xF3mo est\xE1?",opciones:["Funcionamiento normal para un d\xEDa con temperatura exterior moderada hoy.","Falta de refrigerante l\xEDquido que impide que la descarga suba m\xE1s hoy.","Evaporador sucio que reduce la presi\xF3n de succi\xF3n por debajo de 120 hoy.","Compresor con desgaste moderado que a\xFAn mantiene el diferencial \xFAtil hoy."],respuesta_correcta:0,explicacion:"Succi\xF3n de 115 PSI (~36\xB0F sat.) y descarga de 320 PSI (~90\xB0F sat.) con R-410A son presiones normales para un d\xEDa con temperatura exterior moderada de 75-80\xB0F. El sistema opera dentro de par\xE1metros aceptables de dise\xF1o."},{id:"ns_0740",categoria:"NATE_SR_PACKAGE",pregunta:"En una unidad paquete, el serpent\xEDn del evaporador se congela. El filtro est\xE1 limpio. \xBFQu\xE9 sigue?",opciones:["Verificar la velocidad del motor del soplador y la carga de refrigerante.","Reemplazar la v\xE1lvula de expansi\xF3n t\xE9rmica (TXV) por una nueva hoy.","Instalar un termostato de descongelaci\xF3n para que pare el compresor.","Agregar refrigerante hasta que la presi\xF3n de succi\xF3n suba a 130 PSI hoy."],respuesta_correcta:0,explicacion:"Descartado el filtro sucio, las siguientes causas de congelaci\xF3n son el soplador operando a velocidad reducida (correa floja, motor d\xE9bil) que reduce el flujo de aire, o carga baja de refrigerante que baja la temperatura de evaporaci\xF3n por debajo del punto de congelaci\xF3n del agua."},{id:"ns_0741",categoria:"NATE_SR_CEO",pregunta:"Un CEO debe cumplir con la ley FLSA (Fair Labor Standards Act). \xBFQu\xE9 regula?",opciones:["El pago de horas extras y el salario m\xEDnimo para los empleados t\xE9cnicos.","La seguridad de los t\xE9cnicos en el sitio de trabajo y el uso de EPP.","La certificaci\xF3n de los equipos HVAC seg\xFAn su eficiencia energ\xE9tica.","El manejo y disposici\xF3n final de los refrigerantes usados en el campo."],respuesta_correcta:0,explicacion:"La FLSA regula el salario m\xEDnimo federal y el pago obligatorio de horas extras (1.5x despu\xE9s de 40 horas semanales) para empleados no exentos, incluyendo t\xE9cnicos HVAC."},{id:"ns_0742",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-407A. El t\xE9cnico mezcla con R-404A por error. \xBFConsecuencia?",opciones:["La relaci\xF3n presi\xF3n/temperatura ser\xE1 impredecible y el sistema fallar\xE1.","El sistema funcionar\xE1 bien ya que ambos refrigerantes son del tipo HFC.","La eficiencia aumentar\xE1 un 5% pero el compresor har\xE1 un poco m\xE1s de ruido.","El aceite se separar\xE1 del refrigerante y los compresores se bloquear\xE1n."],respuesta_correcta:0,explicacion:"Mezclar R-407A con R-404A crea una combinaci\xF3n con propiedades termodin\xE1micas impredecibles. Las tablas de presi\xF3n/temperatura no aplican, los controles del sistema no pueden funcionar correctamente, y el rendimiento ser\xE1 err\xE1tico y eventualmente da\xF1ino."},{id:"ns_0743",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta una purga de aire constante. Opera con R-134a. \xBFQu\xE9 indica?",opciones:["La purga est\xE1 defectuosa; el R-134a opera a presi\xF3n positiva y no aspira aire.","El chiller tiene una fuga masiva en el evaporador que permite la entrada aire.","El sistema de sellado del eje del compresor ha fallado mec\xE1nicamente hoy.","La temperatura del agua de la torre es demasiado baja para el condensador hoy."],respuesta_correcta:0,explicacion:"Con R-134a (presi\xF3n positiva), el aire no se infiltra al sistema durante operaci\xF3n normal. Una purga constante de aire indica un defecto en el sistema de purga que genera falsas lecturas."},{id:"ns_0744",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no arranca. No hay c\xF3digos de error. \xBFQu\xE9 revisa el Senior?",opciones:["El fusible de la unidad interior y si el voltaje de llegada es de 240VAC.","La carga de refrigerante por peso para descartar una fuga total de gas gas.","Si el compresor est\xE1 aterrizado midiendo la resistencia contra la carcasa.","La placa electr\xF3nica de la unidad exterior por rastros de quemaduras hoy hoy."],respuesta_correcta:0,explicacion:"Sin c\xF3digos de error visibles, el problema es de alimentaci\xF3n b\xE1sica. El Senior revisa el fusible de la unidad interior y confirma 240VAC de llegada como primer paso de diagn\xF3stico."},{id:"ns_0745",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. Subenfriamiento 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido severa en el sistema (Undercharged) hoy hoy.","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total hoy hoy.","Condensador exterior extremadamente sucio que no permite el intercambio t\xE9rmico.","Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."],respuesta_correcta:0,explicacion:"Subenfriamiento de 0\xB0F con presiones de 110/350 PSI indica falta severa de refrigerante. El condensador no tiene suficiente l\xEDquido para producir subenfriamiento, lo cual es el s\xEDntoma m\xE1s confiable de un sistema undercharged."},{id:"ns_0746",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n hoy.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada hoy hoy.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial hoy hoy.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos hoy."],respuesta_correcta:0,explicacion:"El mercado Smart Homes necesita t\xE9cnicos con habilidades en redes y protocolos de comunicaci\xF3n para integrar dispositivos IoT con sistemas HVAC de forma eficiente."},{id:"ns_0747",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 indica una temperatura de succi\xF3n muy alta en el cabezal?",opciones:["Sobrecalentamiento excesivo que da\xF1ar\xE1 la lubricaci\xF3n de compresores pronto.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de evaporaci\xF3n hoy hoy.","Falta de refrigerante l\xEDquido en el recibidor principal del rack paralelo hoy.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n cerradas por temperatura hoy."],respuesta_correcta:0,explicacion:"Temperatura de succi\xF3n elevada en el cabezal confirma un sobrecalentamiento excesivo. El gas demasiado caliente no enfr\xEDa adecuadamente el motor del compresor y degrada el aceite lubricante, reduciendo la vida \xFAtil del equipo."},{id:"ns_0748",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. \xBFQu\xE9 revisa?",opciones:["Presencia de aire en la tuber\xEDa, paddle roto o transductor descalibrado hoy.","La carga de refrigerante que podr\xEDa estar congelando el agua en tubos hoy.","El sentido de rotaci\xF3n del motor del compresor centr\xEDfugo del sistema hoy hoy.","La apertura de las v\xE1lvulas de expansi\xF3n del circuito de refrigeraci\xF3n hoy hoy."],respuesta_correcta:0,explicacion:"Flow Switch Alarm con bomba operando apunta a un paddle da\xF1ado, aire en la tuber\xEDa que interfiere con la medici\xF3n, o un transductor descalibrado que genera la alarma incorrectamente."},{id:"ns_0749",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. \xBFCausa?",opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior hoy.","La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido.","La humedad en la habitaci\xF3n es superior al 95% y satura el serpent\xEDn hoy hoy."],respuesta_correcta:0,explicacion:"El goteo solo al parar el compresor indica contrapendiente o bloqueo parcial en el drenaje que retiene agua durante la operaci\xF3n y la libera cuando la unidad se detiene."},{id:"ns_0750",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de 0.9 en suministro y 0.2 en retorno. \xBFProblema?",opciones:["Restricci\xF3n severa en conductos de suministro o difusores cerrados hoy hoy hoy.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire hoy.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo hoy hoy.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o hoy hoy."],respuesta_correcta:0,explicacion:'Presi\xF3n est\xE1tica de 0.9" en suministro versus 0.2" en retorno muestra restricci\xF3n concentrada en el lado de suministro. Los conductos de suministro restringidos o difusores cerrados son la causa de esta distribuci\xF3n desbalanceada.'},{id:"ns_0751",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre 20\xB0F y 30\xB0F hoy hoy.","S\xED, las bombas de calor siempre tienen un diferencial menor que hornos hoy.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo hoy."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en modo calor es bajo. Lo normal es 20-30F. Significa que el sistema no transfiere suficiente calor al aire, por problemas de carga de refrigerante, flujo de aire o absorcion de calor exterior."},{id:"ns_0752",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. \xBFQu\xE9 paso es vital post-quemadura?",opciones:["Realizar prueba de acidez del aceite y usar filtros succi\xF3n de limpieza hoy hoy.","A\xF1adir aditivo sellador de fugas para prevenir fallas futuras en l\xEDneas hoy hoy.","Cambiar el contactor y el capacitor aunque parezcan estar en buen estado hoy.","Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy hoy hoy."],respuesta_correcta:0,explicacion:"El burnout del compresor libera \xE1cidos y carb\xF3n al circuito frigor\xEDfico. Verificar la acidez del aceite indica el grado de contaminaci\xF3n, y los filtros de succi\xF3n de limpieza son esenciales para capturar part\xEDculas y proteger el compresor de reemplazo."},{id:"ns_0753",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. \xBFEstado?",opciones:["Funcionamiento correcto; la purga est\xE1 separando los no condensables hoy hoy hoy.","Falla en el serpent\xEDn de condensaci\xF3n interno de la unidad de purga hoy hoy.","El sistema tiene una fuga masiva de agua hacia el lado del refrigerante hoy.","La temperatura del evaporador es demasiado alta para que la purga trabaje hoy."],respuesta_correcta:0,explicacion:"La purga que expulsa aire con poco refrigerante est\xE1 operando correctamente, separando eficientemente los gases no condensables mientras minimiza la p\xE9rdida de refrigerante."},{id:"ns_0754",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si el 'Oil Separator' queda pegado en posici\xF3n abierta?",opciones:["Gas caliente de descarga pasar\xE1 directo al dep\xF3sito aceite y succi\xF3n hoy hoy.","El rack se quedar\xE1 sin aceite en pocos minutos al no poder separarlo gas hoy.","Los compresores se apagar\xE1n por alta presi\xF3n al bloquearse el flujo gas hoy.","El nivel de aceite en los c\xE1rteres subir\xE1 tanto que da\xF1ar\xE1 los pistones hoy."],respuesta_correcta:0,explicacion:"El flotador abierto del separador crea un camino libre para el gas de descarga hacia el dep\xF3sito y la succi\xF3n. Este bypass interno hace que parte del gas recircule sin pasar por el condensador ni los evaporadores, perdiendo capacidad."},{id:"ns_0755",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. \xBFQu\xE9 KPI usa?",opciones:["N\xFAmero de llamadas de nuevos clientes que mencionan haber visto la unidad hoy hoy.","La cantidad de millas recorridas por cada veh\xEDculo en zonas residenciales hoy.","El costo total del dise\xF1o e instalaci\xF3n del r\xF3tulo dividido entre 12 meses hoy.","El aumento en la velocidad promedio de t\xE9cnicos al conducir camionetas nuevas."],respuesta_correcta:0,explicacion:"Rastrear las llamadas de nuevos clientes que vieron la camioneta rotulada es el KPI m\xE1s directo para medir el retorno de la inversi\xF3n en publicidad vehicular."},{id:"ns_0756",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. \xBFQu\xE9 revisa?",opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy hoy hoy.","La carga de refrigerante l\xEDquido bas\xE1ndose en el visor del evaporador hoy hoy.","Si la v\xE1lvula de expansi\xF3n est\xE1 inyectando demasiado l\xEDquido al sistema hoy.","El estado de los filtros de aire de la manejadora de aire del edificio hoy."],respuesta_correcta:0,explicacion:"Alta presi\xF3n de condensaci\xF3n en un sistema con condensador de agua se diagnostica verificando la temperatura del agua de torre y confirmando que la bomba de condensador funciona correctamente."},{id:"ns_0757",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n de 125 PSI y descarga 400 PSI con R-410A. \xBFEstado aire?",opciones:["Funcionamiento normal bajo condiciones de carga t\xE9rmica est\xE1ndar hoy hoy hoy hoy.","Falta de refrigerante que impide que temperatura del aire baje a 55 grados hoy.","Exceso de carga que est\xE1 elevando la presi\xF3n de descarga innecesariamente hoy.","Compresor con eficiencia reducida que no logra enfriar el aire correctamente."],respuesta_correcta:0,explicacion:"Las presiones de 125/400 PSI con R-410A est\xE1n dentro del rango normal de operaci\xF3n bajo condiciones de carga t\xE9rmica est\xE1ndar. El sistema opera correctamente con un diferencial de presi\xF3n adecuado."},{id:"ns_0758",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. \xBFQu\xE9 estrategia?",opciones:["Programa de membres\xEDas mantenimiento para convertir clientes en recurrentes hoy hoy.","Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy hoy.","Gastar m\xE1s dinero en anuncios de Google para atraer siempre clientes nuevos hoy.","Despedir a t\xE9cnicos que no logren vender un sistema nuevo en cada visita hoy."],respuesta_correcta:0,explicacion:"Las membres\xEDas de mantenimiento son la herramienta m\xE1s efectiva para convertir clientes de una sola transacci\xF3n en clientes recurrentes con valor a largo plazo."},{id:"ns_0759",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. \xBFQu\xE9 revisa?",opciones:["Carga de refrigerante baja o una restricci\xF3n en la v\xE1lvula de expansi\xF3n hoy hoy.","Si el ventilador interior est\xE1 sucio y no sopla suficiente aire fr\xEDo hoy hoy.","El voltaje de la l\xEDnea el\xE9ctrica que podr\xEDa estar por debajo de 200V hoy hoy.","Si el control remoto est\xE1 configurado en una temperatura demasiado baja hoy."],respuesta_correcta:0,explicacion:"La protecci\xF3n de temperatura de descarga del compresor se activa por carga baja de refrigerante o restricci\xF3n en la EEV, condiciones que causan sobrecalentamiento excesivo del gas de descarga."},{id:"ns_0760",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba calor, \xBFqu\xE9 sucede si 'Check Valve' condensador falla abierta?",opciones:["En modo calor el refrigerante har\xE1 bypass a TXV impidiendo calentamiento hoy hoy.","El sistema funcionar\xE1 mejor al haber menos restricci\xF3n al flujo l\xEDquido hoy.","La presi\xF3n de descarga subir\xE1 hasta que switch de alta apague el equipo hoy.","El compresor se quemar\xE1 por el retorno de l\xEDquido masivo en el arranque hoy."],respuesta_correcta:0,explicacion:"Si la check valve del condensador falla abierta, en modo calor el refrigerante pasa sin restriccion en vez de la TXV. Sin la restriccion de expansion, el refrigerante no cambia de estado y el calentamiento se pierde."},{id:"ns_0761",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula 'Quench' o inyecci\xF3n de l\xEDquido?",opciones:["Para enfriar gas de succi\xF3n y evitar que descarga da\xF1e el aceite hoy hoy hoy hoy.","Para aumentar la presi\xF3n de succi\xF3n cuando carga en vitrinas es baja hoy hoy.","Para limpiar el interior de compresores de acumulaciones de carbonilla hoy hoy.","Para ayudar al retorno de aceite desde los evaporadores m\xE1s lejanos hoy hoy."],respuesta_correcta:0,explicacion:"La v\xE1lvula Quench es fundamental en racks con altas relaciones de compresi\xF3n. Al inyectar l\xEDquido, absorbe calor del gas de descarga por evaporaci\xF3n, manteniendo la temperatura en rangos seguros para la integridad del aceite y el compresor."},{id:"ns_0762",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. \xBFCriterio?",opciones:["El volumen de agua y la accesibilidad para eliminaci\xF3n segura del fluido hoy hoy.","Cu\xE1l de las dos herramientas es m\xE1s nueva y hace menos ruido al operar hoy.","La preferencia del cliente sobre qu\xE9 herramienta quiere ver en su casa hoy.","Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy hoy."],respuesta_correcta:0,explicacion:"El profesional eval\xFAa el volumen de agua y las condiciones de acceso para elegir la herramienta correcta. Una bomba puede manejar grandes vol\xFAmenes; una aspiradora es m\xE1s pr\xE1ctica en espacios reducidos. La seguridad en la eliminaci\xF3n del fluido es primordial."},{id:"ns_0763",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene purga que marca 'Water Detected'. \xBFQu\xE9 acci\xF3n es urgente?",opciones:["Realizar prueba presi\xF3n a tubos del evaporador para buscar rupturas hoy hoy hoy.","Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.","Aumentar la temperatura del agua helada para evitar que vapor condense hoy hoy.","Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy."],respuesta_correcta:0,explicacion:"La detecci\xF3n de agua por la purga es cr\xEDtica y requiere prueba de presi\xF3n urgente en los tubos del evaporador para encontrar la ruptura antes de que el agua da\xF1e el compresor y el aceite."},{id:"ns_0764",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n 130 PSI y descarga 380 PSI. Subenfriamiento 12\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y el subenfriamiento est\xE1n en rango hoy hoy.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser 15 grados hoy.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno hoy.","Compresor fallando; la diferencia presi\xF3n entre succi\xF3n y descarga es baja hoy."],respuesta_correcta:0,explicacion:"Presiones de 130/380 PSI con subenfriamiento de 12\xB0F son indicadores de operaci\xF3n \xF3ptima con R-410A. El subenfriamiento en el rango de 10-15\xB0F confirma una carga de refrigerante correcta."},{id:"ns_0765",categoria:"NATE_SR_PACKAGE",pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["El voltaje en la bobina (24V) y si hay suciedad u \xF3xido en el n\xFAcleo hoy hoy hoy.","Si los contactos principales est\xE1n quemados o soldados entre s\xED hoy hoy hoy.","El capacitor de arranque del compresor que podr\xEDa estar descargado hoy hoy.","La continuidad de los fusibles de potencia de la l\xEDnea de 240 voltios hoy hoy."],respuesta_correcta:0,explicacion:"El zumbido del contactor indica energizaci\xF3n parcial de la bobina. La fuerza magn\xE9tica es proporcional al voltaje; si este es bajo, la armadura vibra sin cerrar. La suciedad en el n\xFAcleo tambi\xE9n impide el sellado magn\xE9tico completo, perpetuando el zumbido y eventual quema de la bobina."},{id:"ns_0766",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico cobra 'por fuera' a clientes. \xBFQu\xE9 acci\xF3n toma?",opciones:["Despido inmediato y posible acci\xF3n legal seg\xFAn el contrato de trabajo hoy hoy hoy.","Hablar con el t\xE9cnico y pedirle una comisi\xF3n por esos trabajos extras hoy hoy.","Ignorar la situaci\xF3n si el t\xE9cnico es el que m\xE1s dinero genera hoy hoy hoy.","Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."],respuesta_correcta:0,explicacion:"El cobro por fuera a clientes es una falta grave que amerita despido inmediato y posible acci\xF3n legal para proteger los ingresos y la reputaci\xF3n de la empresa."},{id:"ns_0767",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFPor qu\xE9 es fundamental cargar l\xEDquido en el recibidor?",opciones:["Para evitar fraccionamiento de la mezcla y asegurar composici\xF3n correcta hoy hoy.","Para que el refrigerante se mezcle m\xE1s r\xE1pido con el aceite POE del rack hoy.","Para prevenir que las v\xE1lvulas de descarga de compresores se calienten hoy hoy.","Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal hoy."],respuesta_correcta:0,explicacion:"El R-448A es zeotr\xF3pico y sus componentes tienen diferentes presiones de vapor. Si se carga en gas, los componentes m\xE1s ligeros salen primero del cilindro, alterando la composici\xF3n final del sistema. La carga en l\xEDquido previene esta separaci\xF3n."},{id:"ns_0768",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. \xBFEfecto?",opciones:["El controlador no podr\xE1 calcular la carga t\xE9rmica real del edificio hoy hoy hoy.","El compresor se apagar\xE1 inmediatamente por seguridad de flujo de agua hoy hoy.","La unidad operar\xE1 siempre al 100% de su capacidad nominal sin modular hoy hoy.","No hay efecto si el sensor de 'Leaving Water' est\xE1 operando correctamente hoy hoy."],respuesta_correcta:0,explicacion:"Sin sensor de entering water, el controlador pierde la capacidad de medir la carga t\xE9rmica real, impidiendo una modulaci\xF3n precisa de la capacidad de enfriamiento."},{id:"ns_0769",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de descarga de 550 PSI con R-410A. \xBFCausa?",opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy hoy hoy.","Falta de refrigerante l\xEDquido que impide que el sistema enfr\xEDe el aire hoy hoy.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total hoy.","El compresor est\xE1 perdiendo eficiencia y no logra comprimir el gas ralo hoy hoy."],respuesta_correcta:0,explicacion:"Descarga de 550 PSI con R-410A representa una condici\xF3n cr\xEDtica. Sin rechazo de calor adecuado por un condensador sucio o ventilador fallando, la presi\xF3n alcanza niveles peligrosamente altos que pueden da\xF1ar el compresor o activar protecciones de seguridad."},{id:"ns_0770",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Average Response Time'. \xBFQu\xE9 medida toma hoy?",opciones:["Implementar software de despacho inteligente y zonificaci\xF3n de t\xE9cnicos hoy hoy hoy.","Aumentar el n\xFAmero de t\xE9cnicos en la n\xF3mina aunque no haya llamadas suficientes hoy.","Reducir el tiempo de almuerzo de los t\xE9cnicos para que est\xE9n m\xE1s disponibles hoy.","Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy."],respuesta_correcta:0,explicacion:"El despacho inteligente con zonificaci\xF3n de t\xE9cnicos asigna el recurso m\xE1s cercano a cada llamada, reduciendo el tiempo de respuesta de forma sistem\xE1tica y medible."},{id:"ns_0771",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. \xBFCausa?",opciones:["Falla de comunicaci\xF3n; el voltaje deber\xEDa fluctuar entre 0 y 24VDC hoy hoy hoy.","La placa exterior est\xE1 operando correctamente enviando la se\xF1al de control hoy.","El compresor inverter est\xE1 aterrizado y consume el voltaje de comunicaci\xF3n hoy.","Falta de alimentaci\xF3n de 240VAC en los terminales L1 y L2 de la exterior hoy hoy."],respuesta_correcta:0,explicacion:"La comunicaci\xF3n entre unidades inverter usa voltaje DC pulsante (0-24V) en los terminales S2/S3. Un voltaje fijo de 24VDC indica que no hay modulaci\xF3n de datos: falla de comunicaci\xF3n."},{id:"ns_0772",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el 'Defrost Sensor' falla en circuito abierto?",opciones:["El sistema nunca entrar\xE1 en modo de deshielo y el serpent\xEDn se congelar\xE1 hoy hoy.","El sistema entrar\xE1 en modo de deshielo cada 30 minutos sin importar el hielo hoy.","El compresor se quemar\xE1 debido a la falta de control de sobrecalentamiento hoy.","La unidad operar\xE1 solo en modo refrigeraci\xF3n permanentemente por seguridad hoy."],respuesta_correcta:0,explicacion:"El sensor de defrost en circuito abierto impide que la placa detecte la temperatura baja del serpentin exterior. Sin esta senal, la condicion de inicio de deshielo nunca se cumple y el hielo se acumula hasta bloquear el serpentin."},{id:"ns_0773",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un sistema VRF. \xBFPor qu\xE9 es vital pesar la carga?",opciones:["Los sistemas VRF son de carga cr\xEDtica y las presiones no son indicadores hoy hoy.","Es un requisito legal de la EPA para sistemas con m\xE1s de 50 libras de gas hoy.","Para asegurar que el aceite POE regrese correctamente a los compresores hoy hoy.","Para evitar que la garant\xEDa del fabricante se anule tras la instalaci\xF3n hoy hoy."],respuesta_correcta:0,explicacion:"Los VRF modulan capacidad continuamente, haciendo que las presiones cambien seg\xFAn la demanda. El pesaje de refrigerante seg\xFAn la f\xF3rmula del fabricante (carga base + longitud de tuber\xEDas adicionales) es la \xFAnica forma precisa de cargar estos sistemas."},{id:"ns_0774",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Reversal'. \xBFQu\xE9 sucede si se ignora el error?",opciones:["El compresor girar\xE1 al rev\xE9s y no bombear\xE1 aceite ni refrigerante l\xEDquido hoy hoy.","La unidad funcionar\xE1 al 50% de su capacidad nominal debido al desfase fase hoy.","El motor se quemar\xE1 instant\xE1neamente al intentar vencer la inercia carga hoy hoy.","Las v\xE1lvulas de expansi\xF3n se cerrar\xE1n por seguridad al detectar el error hoy hoy."],respuesta_correcta:0,explicacion:"La inversi\xF3n de fases causa que el compresor gire al rev\xE9s, perdiendo el bombeo de aceite y refrigerante. Sin lubricaci\xF3n, los cojinetes y el impulsor sufren da\xF1os mec\xE1nicos severos."},{id:"ns_0775",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. Subenfriamiento 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido severa en el sistema (Undercharged) hoy hoy hoy.","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total hoy hoy hoy.","Condensador exterior extremadamente sucio que no permite el intercambio t\xE9rmico.","Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."],respuesta_correcta:0,explicacion:"Subenfriamiento de 0\xB0F es la se\xF1al m\xE1s definitiva de falta severa de refrigerante. Sin suficiente masa de refrigerante, el condensador no puede producir l\xEDquido subenfriado y solo entrega mezcla bif\xE1sica al dispositivo de expansi\xF3n."},{id:"ns_0776",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n hoy hoy.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada hoy hoy hoy.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial hoy hoy hoy.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos hoy hoy."],respuesta_correcta:0,explicacion:"Smart Homes requiere t\xE9cnicos entrenados en redes, protocolos de comunicaci\xF3n e integraci\xF3n de sistemas inteligentes, competencias que exceden la formaci\xF3n HVAC tradicional."},{id:"ns_0777",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 indica una temperatura de succi\xF3n muy alta en el cabezal?",opciones:["Sobrecalentamiento excesivo que da\xF1ar\xE1 la lubricaci\xF3n de compresores pronto.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de evaporaci\xF3n hoy hoy hoy.","Falta de refrigerante l\xEDquido en el recibidor principal del rack paralelo hoy hoy.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n cerradas por temperatura hoy hoy."],respuesta_correcta:0,explicacion:"La temperatura alta en el cabezal de succi\xF3n significa gas excesivamente sobrecalentado. Esto compromete la lubricaci\xF3n al reducir la viscosidad del aceite por calor, y puede causar da\xF1o t\xE9rmico en los devanados del motor del compresor."},{id:"ns_0778",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. \xBFQu\xE9 revisa?",opciones:["Presencia de aire en la tuber\xEDa, paddle roto o transductor descalibrado hoy hoy hoy.","La carga de refrigerante que podr\xEDa estar congelando el agua en tubos hoy hoy.","El sentido de rotaci\xF3n del motor del compresor centr\xEDfugo del sistema hoy hoy hoy.","La apertura de las v\xE1lvulas de expansi\xF3n del circuito de refrigeraci\xF3n hoy hoy hoy."],respuesta_correcta:0,explicacion:"Una alarma de flow switch con bomba encendida indica problemas en la detecci\xF3n de flujo: paddle roto, aire atrapado, o transductor diferencial fuera de calibraci\xF3n."},{id:"ns_0779",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. \xBFCausa?",opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior hoy hoy hoy.","La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy hoy.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido hoy.","La humedad en la habitaci\xF3n es superior al 95% y satura el serpent\xEDn hoy hoy hoy."],respuesta_correcta:0,explicacion:"El goteo al detenerse el compresor se debe a una contrapendiente o bloqueo parcial en la parte alta del drenaje que retiene el condensado y lo libera cuando cesa la operaci\xF3n."},{id:"ns_0780",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de 0.9 en suministro y 0.2 en retorno. \xBFProblema?",opciones:["Restricci\xF3n severa en conductos de suministro o difusores cerrados hoy hoy hoy hoy.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire hoy hoy.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo hoy hoy hoy.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o hoy hoy hoy."],respuesta_correcta:0,explicacion:'La asimetr\xEDa de presi\xF3n est\xE1tica (0.9" suministro vs 0.2" retorno) indica que la restricci\xF3n del sistema est\xE1 mayoritariamente en el lado de suministro, causada por conductos restringidos, aplastados o difusores parcial o totalmente cerrados.'},{id:"ns_0781",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre 20\xB0F y 30\xB0F hoy hoy hoy.","S\xED, las bombas de calor siempre tienen un diferencial menor que hornos hoy hoy.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube hoy.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo hoy hoy."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en calefaccion esta por debajo del rango aceptable de 20-30F. Senala capacidad deficiente, tipicamente causada por baja carga de refrigerante, alto flujo de aire, o mala absorcion de calor exterior."},{id:"ns_0782",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. \xBFQu\xE9 paso es vital post-quemadura?",opciones:["Realizar prueba de acidez del aceite y usar filtros succi\xF3n de limpieza hoy hoy.","A\xF1adir aditivo sellador de fugas para prevenir fallas futuras en l\xEDneas hoy hoy.","Cambiar el contactor y el capacitor aunque parezcan estar en buen estado hoy hoy.","Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy hoy hoy."],respuesta_correcta:0,explicacion:"Despu\xE9s de un burnout, el sistema completo est\xE1 contaminado con \xE1cidos y residuos de descomposici\xF3n. La prueba de acidez mide la contaminaci\xF3n y los filtros de succi\xF3n atrapan part\xEDculas s\xF3lidas, ambos esenciales para proteger la inversi\xF3n en el compresor nuevo."},{id:"ns_0783",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. \xBFEstado?",opciones:["Funcionamiento correcto; la purga est\xE1 separando los no condensables hoy hoy hoy hoy.","Falla en el serpent\xEDn de condensaci\xF3n interno de la unidad de purga hoy hoy hoy.","El sistema tiene una fuga masiva de agua hacia el lado del refrigerante hoy hoy.","La temperatura del evaporador es demasiado alta para que la purga trabaje hoy hoy."],respuesta_correcta:0,explicacion:"Purga que expulsa aire con poco refrigerante est\xE1 funcionando como fue dise\xF1ada, separando correctamente los no condensables del refrigerante antes de expulsarlos."},{id:"ns_0784",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si el 'Oil Separator' queda pegado en posici\xF3n abierta?",opciones:["Gas caliente de descarga pasar\xE1 directo al dep\xF3sito aceite y succi\xF3n hoy hoy hoy.","El rack se quedar\xE1 sin aceite en pocos minutos al no poder separarlo gas hoy hoy.","Los compresores se apagar\xE1n por alta presi\xF3n al bloquearse el flujo gas hoy hoy.","El nivel de aceite en los c\xE1rteres subir\xE1 tanto que da\xF1ar\xE1 los pistones hoy hoy."],respuesta_correcta:0,explicacion:"Cuando el separador queda abierto, gas de descarga a alta temperatura y presi\xF3n fluye directamente al dep\xF3sito de aceite, empujando aceite hacia la succi\xF3n y creando un cortocircuito que compromete la refrigeraci\xF3n del sistema."},{id:"ns_0785",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. \xBFQu\xE9 KPI usa?",opciones:["N\xFAmero de llamadas de nuevos clientes que mencionan haber visto la unidad hoy hoy hoy.","La cantidad de millas recorridas por cada veh\xEDculo en zonas residenciales hoy hoy.","El costo total del dise\xF1o e instalaci\xF3n del r\xF3tulo dividido entre 12 meses hoy.","El aumento en la velocidad promedio de t\xE9cnicos al conducir camionetas nuevas hoy."],respuesta_correcta:0,explicacion:"Contabilizar las llamadas de nuevos clientes que mencionan la camioneta rotulada mide directamente la conversi\xF3n de la publicidad vehicular en oportunidades de negocio."},{id:"ns_0786",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. \xBFQu\xE9 revisa?",opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy hoy hoy hoy.","La carga de refrigerante l\xEDquido bas\xE1ndose en el visor del evaporador hoy hoy hoy.","Si la v\xE1lvula de expansi\xF3n est\xE1 inyectando demasiado l\xEDquido al sistema hoy hoy.","El estado de los filtros de aire de la manejadora de aire del edificio hoy hoy."],respuesta_correcta:0,explicacion:"La alta presi\xF3n de condensaci\xF3n con condensador de agua se investiga verificando temperatura del agua de torre y funcionamiento de la bomba como factores principales."},{id:"ns_0787",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n de 125 PSI y descarga 400 PSI con R-410A. \xBFEstado aire?",opciones:["Funcionamiento normal bajo condiciones de carga t\xE9rmica est\xE1ndar hoy hoy hoy hoy hoy.","Falta de refrigerante que impide que temperatura del aire baje a 55 grados hoy hoy.","Exceso de carga que est\xE1 elevando la presi\xF3n de descarga innecesariamente hoy hoy.","Compresor con eficiencia reducida que no logra enfriar el aire correctamente hoy."],respuesta_correcta:0,explicacion:"Succi\xF3n de 125 PSI y descarga de 400 PSI con R-410A son valores normales que indican funcionamiento correcto del sistema bajo condiciones de carga t\xE9rmica est\xE1ndar."},{id:"ns_0788",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. \xBFQu\xE9 estrategia?",opciones:["Programa de membres\xEDas mantenimiento para convertir clientes en recurrentes hoy hoy hoy.","Aumentar el precio de la primera visita para maximizar la ganancia hoy hoy hoy hoy.","Gastar m\xE1s dinero en anuncios de Google para atraer siempre clientes nuevos hoy hoy.","Despedir a t\xE9cnicos que no logren vender un sistema nuevo en cada visita hoy hoy."],respuesta_correcta:0,explicacion:"La estrategia m\xE1s efectiva para reducir los clientes de una sola vez es crear un programa de membres\xEDas de mantenimiento que ofrezca valor continuo."},{id:"ns_0789",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. \xBFQu\xE9 revisa?",opciones:["Carga de refrigerante baja o una restricci\xF3n en la v\xE1lvula de expansi\xF3n hoy hoy hoy.","Si el ventilador interior est\xE1 sucio y no sopla suficiente aire fr\xEDo hoy hoy hoy.","El voltaje de la l\xEDnea el\xE9ctrica que podr\xEDa estar por debajo de 200V hoy hoy hoy.","Si el control remoto est\xE1 configurado en una temperatura demasiado baja hoy hoy."],respuesta_correcta:0,explicacion:"La protecci\xF3n de temperatura de descarga se dispara por carga insuficiente de refrigerante o restricci\xF3n en la v\xE1lvula de expansi\xF3n, ambas causas generan sobrecalentamiento del gas de descarga."},{id:"ns_0790",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba calor, \xBFqu\xE9 sucede si 'Check Valve' condensador falla abierta?",opciones:["En modo calor el refrigerante har\xE1 bypass a TXV impidiendo calentamiento hoy hoy hoy.","El sistema funcionar\xE1 mejor al haber menos restricci\xF3n al flujo l\xEDquido hoy hoy.","La presi\xF3n de descarga subir\xE1 hasta que switch de alta apague el equipo hoy hoy.","El compresor se quemar\xE1 por el retorno de l\xEDquido masivo en el arranque hoy hoy."],respuesta_correcta:0,explicacion:"Con la check valve del condensador fallida abierta, el refrigerante en modo calor hace bypass a la TXV sin restriccion. La falta de caida de presion impide la transferencia de calor y el sistema no calienta."},{id:"ns_0791",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula 'Quench' o inyecci\xF3n de l\xEDquido?",opciones:["Para enfriar gas de succi\xF3n y evitar que descarga da\xF1e el aceite hoy hoy hoy hoy hoy.","Para aumentar la presi\xF3n de succi\xF3n cuando carga en vitrinas es baja hoy hoy hoy.","Para limpiar el interior de compresores de acumulaciones de carbonilla hoy hoy hoy.","Para ayudar al retorno de aceite desde los evaporadores m\xE1s lejanos hoy hoy hoy."],respuesta_correcta:0,explicacion:"En sistemas de baja temperatura con alta relaci\xF3n de compresi\xF3n, la temperatura de descarga puede exceder los 275\xB0F. La v\xE1lvula Quench inyecta l\xEDquido controladamente para reducir esta temperatura y proteger el aceite y el compresor."},{id:"ns_0792",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. \xBFCriterio?",opciones:["El volumen de agua y la accesibilidad para eliminaci\xF3n segura del fluido hoy hoy hoy.","Cu\xE1l de las dos herramientas es m\xE1s nueva y hace menos ruido al operar hoy hoy.","La preferencia del cliente sobre qu\xE9 herramienta quiere ver en su casa hoy hoy.","Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy hoy hoy."],respuesta_correcta:0,explicacion:"La decisi\xF3n profesional se fundamenta en criterios t\xE9cnicos: la cantidad de agua presente y la accesibilidad del espacio donde se acumul\xF3. Estos factores determinan cu\xE1l herramienta logra la eliminaci\xF3n m\xE1s segura y eficiente del fluido."},{id:"ns_0793",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene purga que marca 'Water Detected'. \xBFQu\xE9 acci\xF3n es urgente?",opciones:["Realizar prueba presi\xF3n a tubos del evaporador para buscar rupturas hoy hoy hoy hoy.","Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy hoy.","Aumentar la temperatura del agua helada para evitar que vapor condense hoy hoy hoy.","Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy hoy hoy."],respuesta_correcta:0,explicacion:"Water Detected por la purga es una alarma urgente que demanda prueba de presi\xF3n a los tubos del evaporador para localizar y reparar la ruptura que permite entrada de agua al refrigerante."},{id:"ns_0794",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n 130 PSI y descarga 380 PSI. Subenfriamiento 12\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y el subenfriamiento est\xE1n en rango hoy hoy hoy.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser 15 grados hoy hoy.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno hoy hoy.","Compresor fallando; la diferencia presi\xF3n entre succi\xF3n y descarga es baja hoy hoy."],respuesta_correcta:0,explicacion:"Las presiones de 130/380 PSI con 12\xB0F de subenfriamiento est\xE1n en rango \xF3ptimo para R-410A. El subenfriamiento entre 10-15\xB0F es ideal para confirmar carga correcta y operaci\xF3n eficiente del condensador."},{id:"ns_0795",categoria:"NATE_SR_PACKAGE",pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["El voltaje en la bobina (24V) y si hay suciedad u \xF3xido en el n\xFAcleo hoy hoy hoy hoy.","Si los contactos principales est\xE1n quemados o soldados entre s\xED hoy hoy hoy hoy.","El capacitor de arranque del compresor que podr\xEDa estar descargado hoy hoy hoy.","La continuidad de los fusibles de potencia de la l\xEDnea de 240 voltios hoy hoy hoy."],respuesta_correcta:0,explicacion:"Un contactor que vibra y zumba repetidamente tiene un problema de fuerza de cierre. La medici\xF3n del voltaje en la bobina confirma si hay ca\xEDda de tensi\xF3n, y la inspecci\xF3n visual del n\xFAcleo revela si hay contaminantes que impiden el contacto metal-con-metal necesario para el cierre."},{id:"ns_0796",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico cobra 'por fuera' a clientes. \xBFQu\xE9 acci\xF3n toma?",opciones:["Despido inmediato y posible acci\xF3n legal seg\xFAn el contrato de trabajo hoy hoy hoy hoy.","Hablar con el t\xE9cnico y pedirle una comisi\xF3n por esos trabajos extras hoy hoy hoy.","Ignorar la situaci\xF3n si el t\xE9cnico es el que m\xE1s dinero genera hoy hoy hoy hoy.","Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy hoy."],respuesta_correcta:0,explicacion:"El cobro por fuera es una violaci\xF3n contractual seria; el despido inmediato y la posible acci\xF3n legal son las medidas proporcionales a la gravedad de la falta."},{id:"ns_0797",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFPor qu\xE9 es fundamental cargar l\xEDquido en el recibidor?",opciones:["Para evitar fraccionamiento de la mezcla y asegurar composici\xF3n correcta hoy hoy hoy hoy.","Para que el refrigerante se mezcle m\xE1s r\xE1pido con el aceite POE del rack hoy hoy.","Para prevenir que las v\xE1lvulas de descarga de compresores se calienten hoy hoy hoy.","Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal hoy hoy hoy."],respuesta_correcta:0,explicacion:"La integridad de la composici\xF3n del R-448A depende de que se cargue en estado l\xEDquido. Al cargar en gas, el cilindro libera primero los componentes m\xE1s vol\xE1tiles, dejando los m\xE1s pesados atr\xE1s y alterando la mezcla en el sistema."},{id:"ns_0798",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. \xBFEfecto?",opciones:["El controlador no podr\xE1 calcular la carga t\xE9rmica real del edificio hoy hoy hoy hoy.","El compresor se apagar\xE1 inmediatamente por seguridad de flujo de agua hoy hoy hoy.","La unidad operar\xE1 siempre al 100% de su capacidad nominal sin modular hoy hoy hoy.","No hay efecto si el sensor de 'Leaving Water' est\xE1 operando correctamente hoy hoy hoy."],respuesta_correcta:0,explicacion:"Sin el sensor de entering water operativo, el controlador no puede calcular la carga t\xE9rmica del edificio ni modular la capacidad del chiller de forma correcta."},{id:"ns_0799",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de descarga de 550 PSI con R-410A. \xBFCausa?",opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy hoy hoy hoy.","Falta de refrigerante l\xEDquido que impide que el sistema enfr\xEDe el aire hoy hoy hoy.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total hoy hoy.","El compresor est\xE1 perdiendo eficiencia y no logra comprimir el gas ralo hoy hoy hoy."],respuesta_correcta:0,explicacion:"Una descarga de 550 PSI es extremadamente alta para R-410A e indica falta de rechazo de calor. Un condensador muy sucio o ventilador exterior que no funciona son las causas m\xE1s directas de esta acumulaci\xF3n peligrosa de presi\xF3n."},{id:"ns_0800",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Average Response Time'. \xBFQu\xE9 medida toma hoy?",opciones:["Implementar software de despacho inteligente y zonificaci\xF3n de t\xE9cnicos hoy hoy hoy hoy.","Aumentar el n\xFAmero de t\xE9cnicos en la n\xF3mina aunque no haya llamadas suficientes hoy.","Reducir el tiempo de almuerzo de los t\xE9cnicos para que est\xE9n m\xE1s disponibles hoy hoy.","Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy hoy."],respuesta_correcta:0,explicacion:"Software de despacho inteligente con zonificaci\xF3n geogr\xE1fica es la soluci\xF3n t\xE9cnica m\xE1s efectiva para reducir sistem\xE1ticamente el tiempo de respuesta promedio."},{id:"ns_0801",categoria:"NATE_SR_HVAC",pregunta:"En un sistema VAV, el sensor de presi\xF3n est\xE1tica del conducto principal marca 2.5 pulg. W.C. (Set-point 1.5). \xBFCu\xE1l es la consecuencia Senior inmediata?",opciones:["Ruido excesivo en los difusores y posible da\xF1o a los sellos de las cajas VAV.","El soplador entrar\xE1 en modo de ahorro de energ\xEDa para compensar la presi\xF3n.","Las cajas VAV se abrir\xE1n al 100% para liberar el exceso de presi\xF3n est\xE1tica.","El chiller se apagar\xE1 por falta de carga t\xE9rmica debido al bajo flujo de aire."],respuesta_correcta:0,explicacion:'Con presi\xF3n est\xE1tica de 2.5" W.C. (67% sobre el set-point de 1.5"), los difusores y cajas VAV experimentan velocidades de aire excesivas que generan ruido. La alta presi\xF3n tambi\xE9n puede da\xF1ar los sellos y actuadores de las cajas VAV por el esfuerzo mec\xE1nico.'},{id:"ns_0802",categoria:"NATE_SR_RACK",pregunta:"Un rack paralelo presenta una 'alta presi\xF3n de succi\xF3n' generalizada. Todos los compresores est\xE1n encendidos al 100%. \xBFQu\xE9 sospecha el Senior?",opciones:["Carga t\xE9rmica excesiva en la tienda o compresores con v\xE1lvulas internas da\xF1adas.","Falta de refrigerante l\xEDquido en el recibidor que impide la evaporaci\xF3n correcta.","Las v\xE1lvulas EPR est\xE1n restringiendo demasiado el flujo de gas hacia el rack.","El condensador remoto est\xE1 inundado de l\xEDquido debido al clima fr\xEDo exterior."],respuesta_correcta:0,explicacion:"Con todos los compresores al 100% y presi\xF3n de succi\xF3n alta, hay m\xE1s carga t\xE9rmica de la que el rack puede manejar. Esto puede ser por condiciones extremas en la tienda, o compresores con v\xE1lvulas internas da\xF1adas que no bombean eficientemente."},{id:"ns_0803",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Non-Billable Travel Time'. \xBFQu\xE9 estrategia de despacho es la m\xE1s t\xE9cnica?",opciones:["Zonificaci\xF3n geogr\xE1fica de t\xE9cnicos y uso de almacenes m\xF3viles (camionetas stock).","Reducir la velocidad m\xE1xima permitida de los veh\xEDculos para ahorrar combustible.","Obligar a los t\xE9cnicos a terminar cada llamada en menos de 45 minutos reloj.","Eliminar el cobro por diagn\xF3stico para atraer m\xE1s clientes en una misma zona."],respuesta_correcta:0,explicacion:"La zonificaci\xF3n geogr\xE1fica y los almacenes m\xF3viles reducen el tiempo de viaje no facturable al mantener al t\xE9cnico cerca de sus pr\xF3ximas llamadas con las piezas necesarias."},{id:"ns_0804",categoria:"NATE_SR_MINISPLIT",pregunta:"Un VRF presenta un error de 'EEV Coil Failure'. Al medir la bobina, el Senior encuentra 0 Ohms. \xBFQu\xE9 indica esto?",opciones:["Un cortocircuito interno en la bobina de la v\xE1lvula de expansi\xF3n electr\xF3nica.","Que la bobina est\xE1 operando en su punto de m\xE1xima inducci\xF3n magn\xE9tica hoy.","Una falta de comunicaci\xF3n entre la placa interior y el actuador de la v\xE1lvula.","Que el cable de se\xF1al est\xE1 desconectado pero la bobina f\xEDsicamente est\xE1 bien."],respuesta_correcta:0,explicacion:"Una lectura de 0 Ohms en la bobina de la EEV indica un cortocircuito interno. Una bobina sana debe tener una resistencia medible (t\xEDpicamente decenas a cientos de Ohms) seg\xFAn el modelo."},{id:"ns_0805",categoria:"NATE_SR_HVAC",pregunta:"Se encuentra un 'Phase Imbalance' del 2% en un edificio comercial. \xBFPor qu\xE9 el Senior no recomienda actuar de inmediato?",opciones:["Porque el l\xEDmite aceptable por la mayor\xEDa de fabricantes es de hasta un 3%.","Porque el costo de corregir el desequilibrio es mayor al ahorro de energ\xEDa.","Porque el desequilibrio de voltaje no afecta la vida \xFAtil de los motores Scroll.","Porque el monitor de fases compensar\xE1 autom\xE1ticamente la diferencia de tensi\xF3n."],respuesta_correcta:0,explicacion:"La mayor\xEDa de fabricantes de motores y compresores especifican un l\xEDmite de desbalance de fase del 2-3%. Un 2% est\xE1 dentro del rango aceptable, por lo que no justifica una inversi\xF3n inmediata en correcci\xF3n, ya que el impacto en la vida del equipo es m\xEDnimo."},{id:"ns_0806",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo calor tiene un 'Frost Pattern' desigual (franjas de hielo). \xBFDiagn\xF3stico?",opciones:["Falta parcial de refrigerante o restricci\xF3n en un circuito del distribuidor.","Operaci\xF3n normal cuando la humedad relativa exterior es superior al 80%.","Falla del motor del ventilador exterior que no cubre todo el serpent\xEDn hoy.","La v\xE1lvula inversora no logr\xF3 cambiar totalmente a la posici\xF3n de calefacci\xF3n."],respuesta_correcta:0,explicacion:"Un patron de escarcha desigual (franjas) indica que algunos circuitos del distribuidor estan parcialmente bloqueados o hay falta de refrigerante. Los circuitos con flujo se escarchan; los restantes quedan secos."},{id:"ns_0807",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior nota que su equipo est\xE1 purgando las mangueras con refrigerante al conectar. \xBFQu\xE9 norma de la EPA se est\xE1 violando?",opciones:["La prohibici\xF3n de venteo intencional de refrigerantes (De minimis exception no aplica).","La obligaci\xF3n de usar cilindros de recuperaci\xF3n de color gris con tapa amarilla.","El requisito de llevar un registro de peso exacto de cada onza de gas utilizada.","La necesidad de tener un vacu\xF3metro digital conectado durante cada carga de gas."],respuesta_correcta:0,explicacion:"La Secci\xF3n 608 de la EPA proh\xEDbe el venteo intencional de refrigerantes a la atm\xF3sfera. Purgar mangueras liberando refrigerante es una violaci\xF3n directa de esta norma, con multas de hasta $44,539 por d\xEDa por incidente."},{id:"ns_0808",categoria:"NATE_SR_CHILLERS",pregunta:"En un chiller de tornillo, el sensor de 'Oil Level' dispara una alarma, pero la mirilla est\xE1 llena. \xBFQu\xE9 revisa el Senior?",opciones:["Presencia de espuma de refrigerante en el aceite que falsea el sensor \xF3ptico.","La viscosidad del aceite que es demasiado alta para el flujo del sensor hoy.","Si el calentador de c\xE1rter est\xE1 quemado y el aceite se encuentra muy fr\xEDo.","La calibraci\xF3n del sensor de presi\xF3n diferencial de la bomba de lubricaci\xF3n."],respuesta_correcta:0,explicacion:"La espuma de refrigerante en el aceite genera lecturas falsas en el sensor \xF3ptico de nivel. El refrigerante disuelto en el aceite se evapora y crea espuma que el sensor interpreta como bajo nivel."},{id:"ns_0809",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete de 50 toneladas tiene un Delta P de aceite bajo. El t\xE9cnico agrega aceite pero el problema persiste. \xBFCausa?",opciones:["Migraci\xF3n de refrigerante l\xEDquido al c\xE1rter que diluye el aceite constantemente.","El separador de aceite tiene la malla interna rota y no atrapa el lubricante.","La bomba de aceite mec\xE1nica tiene un desgaste en los engranajes internos hoy.","El filtro de succi\xF3n de aceite est\xE1 obstruido por part\xEDculas de carb\xF3n \xE1cido."],respuesta_correcta:0,explicacion:"Si agregar aceite no corrige el Delta P bajo, es porque algo sigue diluyendo el lubricante. La migraci\xF3n de refrigerante l\xEDquido al c\xE1rter durante los per\xEDodos de apagado disuelve el aceite continuamente, reduciendo su viscosidad y la capacidad de la bomba para mantener presi\xF3n diferencial."},{id:"ns_0810",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC quiere aumentar el 'EBITDA'. \xBFCu\xE1l es la palanca operativa m\xE1s potente?",opciones:["Mejorar el margen bruto mediante la eficiencia t\xE9cnica y reducci\xF3n de mermas.","Aumentar el gasto en marketing para saturar el mercado residencial local hoy.","Comprar una flota nueva de veh\xEDculos para reducir el gasto de mantenimiento.","Reducir el salario de los t\xE9cnicos Senior para bajar el costo de venta directo."],respuesta_correcta:0,explicacion:"Mejorar el margen bruto mediante eficiencia t\xE9cnica y reducci\xF3n de mermas impacta directamente el EBITDA porque aumenta la utilidad operativa sin necesidad de m\xE1s ingresos."},{id:"ns_0811",categoria:"NATE_SR_HVAC",pregunta:"Si el aire pasa por un serpent\xEDn de enfriamiento y la temperatura de bulbo seco baja pero el punto de roc\xEDo se mantiene igual:",opciones:["El enfriamiento fue puramente sensible (no hubo deshumidificaci\xF3n).","El serpent\xEDn est\xE1 operando por debajo del punto de roc\xEDo del aire hoy.","La humedad relativa del aire ha disminuido dr\xE1sticamente tras el proceso.","El sistema tiene una falta de carga de refrigerante que impide condensar."],respuesta_correcta:0,explicacion:"Si la temperatura de bulbo seco baja pero el punto de roc\xEDo se mantiene igual, significa que no se removi\xF3 humedad del aire. El enfriamiento fue puramente sensible, lo que ocurre cuando la superficie del serpent\xEDn opera por encima del punto de roc\xEDo del aire."},{id:"ns_0812",categoria:"NATE_SR_RACK",pregunta:"Un sistema de rack utiliza 'Subcooling' por intercambiador de placas. \xBFQu\xE9 beneficio Senior es el m\xE1s importante?",opciones:["Aumento de la capacidad frigor\xEDfica y prevenci\xF3n de gas flash en l\xEDneas largas.","Reducci\xF3n de la presi\xF3n de descarga de los compresores de la etapa de alta.","Eliminaci\xF3n de la necesidad de usar acumuladores de succi\xF3n en el rack hoy.","Mejora en el retorno de aceite desde las vitrinas de congelados m\xE1s lejanas."],respuesta_correcta:0,explicacion:"El subenfriamiento adicional mediante intercambiador de placas enfr\xEDa el l\xEDquido muy por debajo de su punto de saturaci\xF3n. Esto previene la formaci\xF3n de gas flash en l\xEDneas largas y aumenta la capacidad frigor\xEDfica al entregar m\xE1s l\xEDquido \xFAtil a los evaporadores."},{id:"ns_0813",categoria:"NATE_SR_CEO",pregunta:"Como CEO, usted nota que sus mejores t\xE9cnicos se van a la competencia. \xBFQu\xE9 factor debe auditar primero?",opciones:["La cultura organizacional, el balance vida-trabajo y la compensaci\xF3n total.","El estado de las herramientas y la modernidad de las camionetas de la flota.","La cantidad de llamadas de servicio que cada t\xE9cnico debe atender al d\xEDa.","El dise\xF1o de los uniformes y la calidad de los beneficios de salud ofrecidos."],respuesta_correcta:0,explicacion:"La cultura organizacional, el balance vida-trabajo y la compensaci\xF3n total son los factores principales que determinan si los mejores t\xE9cnicos se quedan o se van a la competencia."},{id:"ns_0814",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter muestra el error 'P0' (IPM Error). Al revisar, el ventilador exterior est\xE1 trabado. \xBFRelaci\xF3n?",opciones:["La falta de flujo de aire sobrecalent\xF3 el m\xF3dulo IPM por alta corriente.","El IPM controla tanto al compresor como al ventilador en este modelo hoy.","El error P0 es una falla de comunicaci\xF3n causada por el ruido del motor.","No hay relaci\xF3n; el t\xE9cnico debe buscar una falla en la placa electr\xF3nica."],respuesta_correcta:0,explicacion:"Sin flujo de aire del ventilador exterior, el condensador no disipa calor, la presi\xF3n de descarga sube y el compresor demanda m\xE1s corriente, sobrecalentando el m\xF3dulo IPM y disparando el error P0."},{id:"ns_0815",categoria:"NATE_SR_CHILLERS",pregunta:"En un lazo de agua helada, se observa 'Corrosi\xF3n Galv\xE1nica'. \xBFQu\xE9 caus\xF3 esto?",opciones:["Contacto directo entre metales dis\xEDmiles (ej. cobre y acero) sin aislamiento.","El uso de glicol etil\xE9nico en una concentraci\xF3n superior al 50% en el lazo.","Una velocidad de flujo de agua excesiva que erosiona las paredes del tubo.","La falta de purga de aire que permite que el ox\xEDgeno reaccione con el hierro."],respuesta_correcta:0,explicacion:"La corrosi\xF3n galv\xE1nica ocurre cuando dos metales dis\xEDmiles (como cobre y acero) est\xE1n en contacto directo en presencia de un electrolito (agua), creando una celda electroqu\xEDmica destructiva."},{id:"ns_0816",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un approach de condensador de 2\xB0F, pero la descarga es de 450 PSI con R-410A. \xBFDiagn\xF3stico?",opciones:["Incondensables (aire) en el sistema o sobrecarga de refrigerante l\xEDquida.","El condensador est\xE1 perfectamente limpio y operando en rango de dise\xF1o hoy.","Falta de refrigerante que impide que la transferencia de calor sea total.","La torre de enfriamiento est\xE1 entregando agua demasiado caliente al sistema."],respuesta_correcta:0,explicacion:"Con approach de 2\xB0F (condensador limpio), una descarga de 450 PSI con R-410A est\xE1 muy por encima de lo normal. Esto indica gases no condensables en el sistema o sobrecarga de refrigerante."},{id:"ns_0817",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa una soldadura que se ve 'fr\xEDa' y opaca. \xBFQu\xE9 instruye al Junior?",opciones:["Limpiar, aplicar m\xE1s calor uniformemente y asegurar la capilaridad del aporte.","Lijar la superficie y cubrirla con una capa de sellador ep\xF3xico para gas.","Pintar la uni\xF3n para evitar que el cliente note la mala calidad est\xE9tica hoy.","Dejarla as\xED si la prueba de nitr\xF3geno a 100 PSI no muestra burbujas hoy."],respuesta_correcta:0,explicacion:"Una soldadura fr\xEDa y opaca indica que no se alcanz\xF3 la temperatura adecuada y el material de aporte no fluy\xF3 por capilaridad. Se debe limpiar la uni\xF3n, recalentar uniformemente y permitir que la soldadura de plata fluya correctamente por acci\xF3n capilar."},{id:"ns_0818",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere mejorar el 'Current Ratio' (Liquidez). \xBFQu\xE9 acci\xF3n es contraproducente?",opciones:["Comprar una gran cantidad de inventario pagando en efectivo de inmediato.","Cobrar las cuentas pendientes de clientes comerciales a m\xE1s de 90 d\xEDas hoy.","Vender activos fijos que no se utilizan y mantener el dinero en el banco.","Renegociar deudas de corto plazo para convertirlas en cr\xE9ditos a largo plazo."],respuesta_correcta:0,explicacion:"Comprar inventario pagando en efectivo reduce los activos l\xEDquidos sin reducir los pasivos corrientes, empeorando el Current Ratio; es contraproducente para la liquidez."},{id:"ns_0819",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de succi\xF3n de 105 PSI y descarga de 480 PSI. \xBFEstado?",opciones:["Restricci\xF3n en el lado de alta o condensador extremadamente sucio hoy hoy.","Funcionamiento normal para un d\xEDa con 105 grados F de temperatura exterior.","Falta de refrigerante l\xEDquido que impide que la succi\xF3n suba a 120 PSI.","V\xE1lvula de expansi\xF3n (TXV) bloqueada en la posici\xF3n de abierta total hoy."],respuesta_correcta:0,explicacion:"Succi\xF3n de 105 PSI (baja) con descarga de 480 PSI (muy alta) indica restricci\xF3n en el lado de alta del sistema. Un condensador sucio o restricci\xF3n en la l\xEDnea de l\xEDquido impide el flujo normal, acumulando presi\xF3n en el lado de descarga."},{id:"ns_0820",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFcu\xE1l es el prop\xF3sito de la v\xE1lvula 'Check' en la descarga de cada compresor?",opciones:["Evitar la migraci\xF3n de refrigerante l\xEDquido desde el condensador al compresor parado.","Aumentar la presi\xF3n de descarga para mejorar la separaci\xF3n de aceite hoy.","Permitir que el aceite regrese al c\xE1rter solo cuando el compresor est\xE1 encendido.","Proteger al condensador de las pulsaciones de gas de los compresores Scroll."],respuesta_correcta:0,explicacion:"La v\xE1lvula check de descarga impide el flujo reverso de refrigerante hacia un compresor que est\xE1 apagado. Sin esta protecci\xF3n, el l\xEDquido del condensador migrar\xEDa al compresor fr\xEDo, causando golpe de l\xEDquido al siguiente arranque."},{id:"ns_0821",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Monitor'. El voltaje es estable a 460V. \xBFQu\xE9 revisa?",opciones:["Secuencia de fases incorrecta tras una reparaci\xF3n el\xE9ctrica en el edificio.","El fusible de control de 24V que alimenta la bobina del contactor hoy hoy.","Si los ventiladores del condensador est\xE1n girando en sentido inverso hoy.","La carga de refrigerante que podr\xEDa estar afectando la l\xF3gica de arranque."],respuesta_correcta:0,explicacion:"Con voltaje estable a 460V, una falla del monitor de fase indica que la secuencia de fases fue invertida, t\xEDpicamente despu\xE9s de una reparaci\xF3n el\xE9ctrica en el edificio que alter\xF3 las conexiones."},{id:"ns_0822",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere implementar 'Dynamic Pricing'. \xBFCu\xE1l es el riesgo de marca?",opciones:["Percepci\xF3n de falta de transparencia o 'precio abusivo' en momentos de crisis.","Aumento en el costo de los materiales al fluctuar los precios de venta hoy.","Que los t\xE9cnicos no sepan calcular el precio correcto en cada visita t\xE9cnica.","Reducci\xF3n en la cantidad de llamadas de mantenimiento preventivo anual hoy."],respuesta_correcta:0,explicacion:"El Dynamic Pricing crea riesgo de marca cuando los clientes perciben los precios altos durante emergencias como abuso o falta de transparencia, da\xF1ando la confianza."},{id:"ns_0823",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no enfr\xEDa. El voltaje entre S1 y S2 es 240VAC. \xBFConclusi\xF3n?",opciones:["La alimentaci\xF3n el\xE9ctrica llega correctamente a la unidad exterior hoy hoy.","Hay una falla de comunicaci\xF3n masiva entre la interior y la exterior hoy.","El fusible de la placa electr\xF3nica exterior est\xE1 fundido y debe cambiarse.","El compresor inverter est\xE1 aterrizado y consume el voltaje de la l\xEDnea."],respuesta_correcta:0,explicacion:"Un voltaje de 240VAC entre S1 y S2 confirma que la alimentaci\xF3n el\xE9ctrica llega correctamente a la unidad exterior. El problema de enfriamiento debe buscarse en otro componente del sistema."},{id:"ns_0824",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFpor qu\xE9 el compresor se calienta en modo calefacci\xF3n?",opciones:["Relaci\xF3n de compresi\xF3n m\xE1s alta y menor masa de gas para enfriar el motor.","El ventilador exterior gira m\xE1s lento para permitir que el serpent\xEDn caliente.","Las resistencias el\xE9ctricas est\xE1n demasiado cerca de la succi\xF3n del compresor.","El aceite POE pierde viscosidad al operar con temperaturas exteriores bajas."],respuesta_correcta:0,explicacion:"En modo calefaccion, la temperatura exterior baja reduce la presion de succion, aumentando la relacion de compresion. Ademas, menos masa de gas de succion enfria el motor del compresor, resultando en temperaturas mas altas."},{id:"ns_0825",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que la bomba de vac\xEDo no baja de 2000 micrones. \xBFQu\xE9 hace el Senior?",opciones:["Cambiar el aceite de la bomba y verificar si hay fugas en las mangueras.","Dejarla encendida por 12 horas m\xE1s asumiendo que el sistema est\xE1 muy h\xFAmedo.","Cargar un poco de nitr\xF3geno y luego intentar el vac\xEDo de nuevo hoy hoy.","Usar el man\xF3metro anal\xF3gico para ver si la aguja baja m\xE1s all\xE1 del cero."],respuesta_correcta:0,explicacion:"Si la bomba no baja de 2000 micrones, las causas m\xE1s comunes son aceite contaminado con humedad (pierde eficiencia) o fugas en las mangueras/conexiones. Cambiar el aceite y verificar la hermeticidad de las conexiones resuelve la mayor\xEDa de estos casos."},{id:"ns_0826",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFQu\xE9 precauci\xF3n toma el Senior al cargar gas?",opciones:["Cargar siempre en estado l\xEDquido para evitar el fraccionamiento de la mezcla.","Cargar en estado gaseoso para no da\xF1ar las v\xE1lvulas de los compresores hoy.","Utilizar aceite mineral para asegurar que el refrigerante sea miscible hoy.","No cargar m\xE1s de 50 libras a la vez para evitar picos de presi\xF3n alta hoy."],respuesta_correcta:0,explicacion:"El R-448A es una mezcla zeotr\xF3pica de cinco componentes. Cargar en estado l\xEDquido es obligatorio para que todos los componentes entren al sistema en las proporciones de dise\xF1o, ya que en fase gaseosa se fraccionar\xEDan por diferencias de volatilidad."},{id:"ns_0827",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de temperatura de 'Leaving Water' roto. \xBFEfecto?",opciones:["El controlador no podr\xE1 modular la capacidad para mantener el set-point.","El compresor se apagar\xE1 inmediatamente por seguridad de flujo de agua hoy.","La unidad operar\xE1 siempre al 100% de su capacidad nominal sin modular hoy.","No hay efecto si el sensor de 'Entering Water' est\xE1 operando correctamente."],respuesta_correcta:0,explicacion:"El sensor de leaving water es el que el controlador usa para modular la capacidad del chiller y mantener el set-point. Sin \xE9l, el sistema no puede ajustar su operaci\xF3n correctamente."},{id:"ns_0828",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de descarga de 550 PSI con R-410A. \xBFCausa?",opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy.","Falta de refrigerante l\xEDquido que impide que el sistema enfr\xEDe el aire hoy.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total.","El compresor est\xE1 perdiendo eficiencia y no logra comprimir el gas ralo."],respuesta_correcta:0,explicacion:"Descarga de 550 PSI con R-410A es una condici\xF3n cr\xEDtica que requiere atenci\xF3n inmediata. Sin disipaci\xF3n adecuada de calor, ya sea por condensador sucio o ventilador fallando, la presi\xF3n de descarga alcanza niveles peligrosamente altos."},{id:"ns_0829",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Average Response Time'. \xBFQu\xE9 medida toma?",opciones:["Implementar software de despacho inteligente y zonificaci\xF3n de t\xE9cnicos hoy.","Aumentar el n\xFAmero de t\xE9cnicos en la n\xF3mina aunque no haya llamadas hoy.","Reducir el tiempo de almuerzo de los t\xE9cnicos para que est\xE9n m\xE1s disponibles.","Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas."],respuesta_correcta:0,explicacion:"El despacho inteligente con zonificaci\xF3n de t\xE9cnicos optimiza la asignaci\xF3n de recursos y reduce el tiempo de respuesta promedio de forma eficiente y escalable."},{id:"ns_0830",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. \xBFCausa?",opciones:["Falla de comunicaci\xF3n; el voltaje deber\xEDa fluctuar entre 0 y 24VDC hoy hoy.","La placa exterior est\xE1 operando correctamente enviando la se\xF1al de control.","El compresor inverter est\xE1 aterrizado y consume el voltaje de comunicaci\xF3n.","Falta de alimentaci\xF3n de 240VAC en los terminales L1 y L2 de la exterior."],respuesta_correcta:0,explicacion:"La se\xF1al entre S2 y S3 en sistemas inverter debe ser DC pulsante (0-24V). Un voltaje fijo de 24VDC indica falla de comunicaci\xF3n porque no hay modulaci\xF3n de datos entre las unidades."},{id:"ns_0831",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el 'Defrost Sensor' falla en circuito abierto?",opciones:["El sistema nunca entrar\xE1 en modo de deshielo y el serpent\xEDn se congelar\xE1.","El sistema entrar\xE1 en modo de deshielo cada 30 minutos sin importar el hielo.","El compresor se quemar\xE1 debido a la falta de control de sobrecalentamiento.","La unidad operar\xE1 solo en modo refrigeraci\xF3n permanentemente por seguridad."],respuesta_correcta:0,explicacion:"Si el sensor de defrost falla en circuito abierto, la placa nunca recibe la senal de temperatura fria necesaria para iniciar el deshielo. El hielo se acumula progresivamente hasta bloquear el flujo de aire del serpentin."},{id:"ns_0832",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un sistema VRF. \xBFPor qu\xE9 es vital pesar la carga?",opciones:["Los sistemas VRF son de carga cr\xEDtica y las presiones no son indicadores.","Es un requisito legal de la EPA para sistemas con m\xE1s de 50 libras de gas.","Para asegurar que el aceite POE regrese correctamente a los compresores hoy.","Para evitar que la garant\xEDa del fabricante se anule tras la instalaci\xF3n."],respuesta_correcta:0,explicacion:"Los sistemas VRF tienen carga cr\xEDtica calculada por el fabricante basada en la longitud de tuber\xEDas y cantidad de evaporadores. Las presiones var\xEDan con la modulaci\xF3n de capacidad, haciendo que el pesaje sea el \xFAnico m\xE9todo confiable."},{id:"ns_0833",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Reversal'. \xBFQu\xE9 sucede si se ignora el error?",opciones:["El compresor girar\xE1 al rev\xE9s y no bombear\xE1 aceite ni refrigerante l\xEDquido.","La unidad funcionar\xE1 al 50% de su capacidad nominal debido al desfase fase.","El motor se quemar\xE1 instant\xE1neamente al intentar vencer la inercia carga.","Las v\xE1lvulas de expansi\xF3n se cerrar\xE1n por seguridad al detectar el error."],respuesta_correcta:0,explicacion:"Phase Reversal causa rotaci\xF3n inversa del compresor, impidiendo el bombeo de aceite lubricante y la circulaci\xF3n de refrigerante. Esto resulta en da\xF1o mec\xE1nico r\xE1pido de los componentes internos."},{id:"ns_0834",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. Subenfriamiento 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido severa en el sistema (Undercharged) hoy hoy.","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total hoy hoy.","Condensador exterior extremadamente sucio que no permite el intercambio t\xE9rmico.","Evaporador interior congelado que bloquea el flujo de calor totalmente hoy."],respuesta_correcta:0,explicacion:"Subenfriamiento de 0\xB0F indica que el sistema no tiene suficiente refrigerante para producir l\xEDquido subenfriado en la salida del condensador. Esta es la confirmaci\xF3n diagn\xF3stica m\xE1s clara de un sistema severamente undercharged."},{id:"ns_0835",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n hoy.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada hoy hoy.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial hoy hoy.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos."],respuesta_correcta:0,explicacion:"Para Smart Homes se requieren t\xE9cnicos con conocimiento en redes y protocolos de comunicaci\xF3n para la integraci\xF3n de termostatos, sensores y automatizaci\xF3n del hogar."},{id:"ns_0836",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 indica una temperatura de succi\xF3n muy alta en el cabezal?",opciones:["Sobrecalentamiento excesivo que da\xF1ar\xE1 la lubricaci\xF3n de compresores pronto.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de evaporaci\xF3n hoy hoy.","Falta de refrigerante l\xEDquido en el recibidor principal del rack paralelo hoy.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n cerradas por temperatura."],respuesta_correcta:0,explicacion:"Una temperatura de succi\xF3n muy elevada causa sobrecalentamiento del gas que entra al compresor. Esto aumenta la temperatura de descarga y reduce la capacidad lubricante del aceite, llevando a desgaste prematuro de los componentes internos."},{id:"ns_0837",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. \xBFQu\xE9 revisa?",opciones:["Presencia de aire en la tuber\xEDa, paddle roto o transductor descalibrado hoy.","La carga de refrigerante que podr\xEDa estar congelando el agua en tubos hoy.","El sentido de rotaci\xF3n del motor del compresor centr\xEDfugo del sistema hoy.","La apertura de las v\xE1lvulas de expansi\xF3n del circuito de refrigeraci\xF3n hoy."],respuesta_correcta:0,explicacion:"Con bomba funcionando, la alarma de flow switch se\xF1ala un problema en el sensor de detecci\xF3n: paddle roto, aire en la tuber\xEDa, o transductor descalibrado que genera la falsa alarma."},{id:"ns_0838",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. \xBFCausa?",opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.","La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido.","La humedad en la habitaci\xF3n es superior al 95% y satura el serpent\xEDn hoy."],respuesta_correcta:0,explicacion:"El goteo solo cuando el compresor para indica contrapendiente o bloqueo parcial en el drenaje que retiene agua acumulada durante la operaci\xF3n y la libera al detenerse el equipo."},{id:"ns_0839",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de 0.9 en suministro y 0.2 en retorno. \xBFProblema?",opciones:["Restricci\xF3n severa en conductos de suministro o difusores cerrados hoy hoy.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire hoy.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo hoy.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o hoy."],respuesta_correcta:0,explicacion:'La presi\xF3n est\xE1tica de 0.9" en suministro frente a 0.2" en retorno demuestra que la restricci\xF3n principal est\xE1 en los conductos de suministro. Difusores cerrados o conductos restringidos son la causa directa.'},{id:"ns_0840",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre 20\xB0F y 30\xB0F hoy.","S\xED, las bombas de calor siempre tienen un diferencial menor que hornos hoy.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en modo calor esta por debajo del rango normal de 20-30F, indicando capacidad de calefaccion insuficiente. La causa tipica es baja carga, exceso de CFM, o mala absorcion de calor exterior."},{id:"ns_0841",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. \xBFQu\xE9 paso es vital post-quemadura?",opciones:["Realizar prueba de acidez del aceite y usar filtros succi\xF3n de limpieza hoy.","A\xF1adir aditivo sellador de fugas para prevenir fallas futuras en l\xEDneas hoy.","Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.","Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy."],respuesta_correcta:0,explicacion:"El procedimiento correcto post-burnout requiere medir la acidez del aceite del sistema para evaluar la contaminaci\xF3n, e instalar filtros de succi\xF3n de limpieza que protejan al compresor nuevo de los residuos \xE1cidos y part\xEDculas carbonizadas."},{id:"ns_0842",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. \xBFEstado?",opciones:["Funcionamiento correcto; la purga est\xE1 separando los no condensables hoy.","Falla en el serpent\xEDn de condensaci\xF3n interno de la unidad de purga hoy.","El sistema tiene una fuga masiva de agua hacia el lado del refrigerante.","La temperatura del evaporador es demasiado alta para que la purga trabaje."],respuesta_correcta:0,explicacion:"Si la purga expulsa mucho aire pero retiene el refrigerante, funciona correctamente. Su dise\xF1o est\xE1 optimizado para separar no condensables y mantener la carga de refrigerante del sistema."},{id:"ns_0843",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si el 'Oil Separator' queda pegado en posici\xF3n abierta?",opciones:["Gas caliente de descarga pasar\xE1 directo al dep\xF3sito aceite y succi\xF3n hoy.","El rack se quedar\xE1 sin aceite en pocos minutos al no poder separarlo gas.","Los compresores se apagar\xE1n por alta presi\xF3n al bloquearse el flujo gas.","El nivel de aceite en los c\xE1rteres subir\xE1 tanto que da\xF1ar\xE1 los pistones hoy."],respuesta_correcta:0,explicacion:"Un separador con flotador abierto permite que el gas de descarga a alta presi\xF3n pase directo al dep\xF3sito de aceite. Esto genera un cortocircuito de gas caliente que reduce la eficiencia del rack y puede empujar aceite hacia la succi\xF3n."},{id:"ns_0844",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. \xBFQu\xE9 KPI usa?",opciones:["N\xFAmero de llamadas de nuevos clientes que mencionan haber visto la unidad hoy.","La cantidad de millas recorridas por cada veh\xEDculo en zonas residenciales.","El costo total del dise\xF1o e instalaci\xF3n del r\xF3tulo dividido entre 12 meses.","El aumento en la velocidad promedio de t\xE9cnicos al conducir camionetas nuevas."],respuesta_correcta:0,explicacion:"El n\xFAmero de llamadas de nuevos clientes que vieron la camioneta es el indicador m\xE1s directo del impacto de las unidades rotuladas como herramienta de marketing."},{id:"ns_0845",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. \xBFQu\xE9 revisa?",opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy.","La carga de refrigerante l\xEDquido bas\xE1ndose en el visor del evaporador hoy.","Si la v\xE1lvula de expansi\xF3n est\xE1 inyectando demasiado l\xEDquido al sistema.","El estado de los filtros de aire de la manejadora de aire del edificio hoy."],respuesta_correcta:0,explicacion:"La alta presi\xF3n de condensaci\xF3n en un chiller con condensador de agua requiere verificar primero la temperatura del agua de torre y la bomba de condensador como causas m\xE1s directas."},{id:"ns_0846",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n de 125 PSI y descarga 400 PSI con R-410A. \xBFEstado aire?",opciones:["Funcionamiento normal bajo condiciones de carga t\xE9rmica est\xE1ndar hoy hoy.","Falta de refrigerante que impide que temperatura del aire baje a 55 grados.","Exceso de carga que est\xE1 elevando la presi\xF3n de descarga innecesariamente.","Compresor con eficiencia reducida que no logra enfriar el aire correctamente."],respuesta_correcta:0,explicacion:"Presiones de succi\xF3n de 125 PSI y descarga de 400 PSI con R-410A representan operaci\xF3n normal. El diferencial de presi\xF3n es correcto para condiciones est\xE1ndar de carga t\xE9rmica."},{id:"ns_0847",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. \xBFQu\xE9 estrategia?",opciones:["Programa de membres\xEDas mantenimiento para convertir clientes en recurrentes.","Aumentar el precio de la primera visita para maximizar la ganancia hoy.","Gastar m\xE1s dinero en anuncios de Google para atraer siempre clientes nuevos.","Despedir a t\xE9cnicos que no logren vender un sistema nuevo en cada visita."],respuesta_correcta:0,explicacion:"Las membres\xEDas de mantenimiento transforman clientes ocasionales en recurrentes, siendo la estrategia m\xE1s efectiva para construir una base de ingresos estable."},{id:"ns_0848",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. \xBFQu\xE9 revisa?",opciones:["Carga de refrigerante baja o una restricci\xF3n en la v\xE1lvula de expansi\xF3n hoy.","Si el ventilador interior est\xE1 sucio y no sopla suficiente aire fr\xEDo hoy.","El voltaje de la l\xEDnea el\xE9ctrica que podr\xEDa estar por debajo de 200V hoy.","Si el control remoto est\xE1 configurado en una temperatura demasiado baja hoy."],respuesta_correcta:0,explicacion:"La protecci\xF3n de temperatura de descarga se activa por refrigerante insuficiente o restricci\xF3n en la EEV, ambas condiciones causan que el compresor descargue gas sobrecalentado."},{id:"ns_0849",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba calor, \xBFqu\xE9 sucede si 'Check Valve' condensador falla abierta?",opciones:["En modo calor el refrigerante har\xE1 bypass a TXV impidiendo calentamiento hoy.","El sistema funcionar\xE1 mejor al haber menos restricci\xF3n al flujo l\xEDquido hoy.","La presi\xF3n de descarga subir\xE1 hasta que switch de alta apague el equipo hoy.","El compresor se quemar\xE1 por el retorno de l\xEDquido masivo en el arranque hoy."],respuesta_correcta:0,explicacion:"La check valve del condensador al fallar abierta permite que el refrigerante haga bypass en modo calor. Sin pasar por la TXV no hay restriccion, no hay cambio de presion y no hay calentamiento efectivo."},{id:"ns_0850",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula 'Quench' o inyecci\xF3n de l\xEDquido?",opciones:["Para enfriar gas de succi\xF3n y evitar que descarga da\xF1e el aceite hoy hoy.","Para aumentar la presi\xF3n de succi\xF3n cuando carga en vitrinas es baja hoy.","Para limpiar el interior de compresores de acumulaciones de carbonilla hoy.","Para ayudar al retorno de aceite desde los evaporadores m\xE1s lejanos hoy."],respuesta_correcta:0,explicacion:"La inyecci\xF3n Quench absorbe calor del gas mediante evaporaci\xF3n del refrigerante l\xEDquido inyectado. Esto controla la temperatura de descarga del compresor, protegiendo el aceite lubricante de la carbonizaci\xF3n y degradaci\xF3n qu\xEDmica."},{id:"ns_0851",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. \xBFCriterio?",opciones:["El volumen de agua y la accesibilidad para eliminaci\xF3n segura del fluido hoy.","Cu\xE1l de las dos herramientas es m\xE1s nueva y hace menos ruido al operar hoy.","La preferencia del cliente sobre qu\xE9 herramienta quiere ver en su casa hoy.","Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy."],respuesta_correcta:0,explicacion:"Un t\xE9cnico Senior selecciona la herramienta bas\xE1ndose en factores t\xE9cnicos objetivos: la cantidad de agua a extraer y qu\xE9 tan accesible es el punto de acumulaci\xF3n. Esto garantiza una intervenci\xF3n eficiente y una eliminaci\xF3n segura del fluido."},{id:"ns_0852",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene purga que marca 'Water Detected'. \xBFQu\xE9 acci\xF3n es urgente?",opciones:["Realizar prueba presi\xF3n a tubos del evaporador para buscar rupturas hoy.","Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.","Aumentar la temperatura del agua helada para evitar que vapor condense hoy.","Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy."],respuesta_correcta:0,explicacion:"La alarma de agua detectada por la purga indica posible ruptura en tubos del evaporador. La prueba de presi\xF3n es la acci\xF3n urgente para localizar la fuga y prevenir da\xF1o mayor."},{id:"ns_0853",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n 130 PSI y descarga 380 PSI. Subenfriamiento 12\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y el subenfriamiento est\xE1n en rango.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser 15 grados hoy.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno hoy.","Compresor fallando; la diferencia presi\xF3n entre succi\xF3n y descarga es baja hoy."],respuesta_correcta:0,explicacion:"Las presiones de 130/380 PSI con subenfriamiento de 12\xB0F son valores \xF3ptimos para R-410A. Confirman carga de refrigerante correcta y funcionamiento adecuado de todos los componentes del ciclo de refrigeraci\xF3n."},{id:"ns_0854",categoria:"NATE_SR_PACKAGE",pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["El voltaje en la bobina (24V) y si hay suciedad u \xF3xido en el n\xFAcleo hoy.","Si los contactos principales est\xE1n quemados o soldados entre s\xED hoy.","El capacitor de arranque del compresor que podr\xEDa estar descargado hoy.","La continuidad de los fusibles de potencia de la l\xEDnea de 240 voltios hoy."],respuesta_correcta:0,explicacion:"La bobina del contactor necesita voltaje adecuado para crear el campo magn\xE9tico que cierra los contactos. Voltaje bajo o un n\xFAcleo con suciedad u \xF3xido son las causas m\xE1s directas de que el contactor zumbe sin completar el cierre mec\xE1nico."},{id:"ns_0855",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico cobra 'por fuera' a clientes. \xBFQu\xE9 acci\xF3n toma?",opciones:["Despido inmediato y posible acci\xF3n legal seg\xFAn el contrato de trabajo hoy.","Hablar con el t\xE9cnico y pedirle una comisi\xF3n por esos trabajos extras hoy.","Ignorar la situaci\xF3n si el t\xE9cnico es el que m\xE1s dinero genera hoy.","Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."],respuesta_correcta:0,explicacion:"Cobrar por fuera es una falta que justifica despido inmediato y acci\xF3n legal, ya que el t\xE9cnico desv\xEDa ingresos que pertenecen a la empresa y viola su contrato."},{id:"ns_0856",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFPor qu\xE9 es fundamental cargar l\xEDquido en el recibidor?",opciones:["Para evitar fraccionamiento de la mezcla y asegurar composici\xF3n correcta hoy.","Para que el refrigerante se mezcle m\xE1s r\xE1pido con el aceite POE del rack hoy.","Para prevenir que las v\xE1lvulas de descarga de compresores se calienten hoy.","Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal."],respuesta_correcta:0,explicacion:"El R-448A debe cargarse siempre en fase l\xEDquida para mantener la composici\xF3n correcta de sus cinco componentes. La carga en gas provocar\xEDa fraccionamiento, alterando las presiones de operaci\xF3n y reduciendo la eficiencia del sistema."},{id:"ns_0857",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. \xBFEfecto?",opciones:["El controlador no podr\xE1 calcular la carga t\xE9rmica real del edificio hoy.","El compresor se apagar\xE1 inmediatamente por seguridad de flujo de agua hoy.","La unidad operar\xE1 siempre al 100% de su capacidad nominal sin modular hoy.","No hay efecto si el sensor de 'Leaving Water' est\xE1 operando correctamente hoy."],respuesta_correcta:0,explicacion:"El sensor de entering water permite calcular la carga t\xE9rmica (Delta T x flujo). Sin \xE9l, el controlador no puede determinar cu\xE1nta capacidad necesita el sistema."},{id:"ns_0858",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de descarga de 550 PSI con R-410A. \xBFCausa?",opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy.","Falta de refrigerante l\xEDquido que impide que el sistema enfr\xEDe el aire hoy.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total.","El compresor est\xE1 perdiendo eficiencia y no logra comprimir el gas ralo."],respuesta_correcta:0,explicacion:"Una descarga de 550 PSI con R-410A es cr\xEDtica y apunta directamente a falta de rechazo de calor en el condensador. Ya sea por suciedad extrema o falla del ventilador, el condensador no puede disipar el calor del refrigerante comprimido."},{id:"ns_0859",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Average Response Time'. \xBFQu\xE9 medida toma?",opciones:["Implementar software de despacho inteligente y zonificaci\xF3n de t\xE9cnicos hoy.","Aumentar el n\xFAmero de t\xE9cnicos en la n\xF3mina aunque no haya llamadas hoy.","Reducir el tiempo de almuerzo de los t\xE9cnicos para que est\xE9n m\xE1s disponibles.","Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas."],respuesta_correcta:0,explicacion:"El software de despacho inteligente con zonificaci\xF3n es la medida t\xE9cnica m\xE1s directa para reducir el tiempo de respuesta al asignar al t\xE9cnico \xF3ptimo para cada llamada."},{id:"ns_0860",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. \xBFCausa?",opciones:["Falla de comunicaci\xF3n; el voltaje deber\xEDa fluctuar entre 0 y 24VDC hoy hoy.","La placa exterior est\xE1 operando correctamente enviando la se\xF1al de control.","El compresor inverter est\xE1 aterrizado y consume el voltaje de comunicaci\xF3n.","Falta de alimentaci\xF3n de 240VAC en los terminales L1 y L2 de la exterior."],respuesta_correcta:0,explicacion:"La comunicaci\xF3n inverter entre S2 y S3 utiliza voltaje DC pulsante. Un valor fijo de 24VDC indica ausencia de modulaci\xF3n de datos, lo que significa falla en la comunicaci\xF3n digital."},{id:"ns_0861",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el 'Defrost Sensor' falla en circuito abierto?",opciones:["El sistema nunca entrar\xE1 en modo de deshielo y el serpent\xEDn se congelar\xE1.","El sistema entrar\xE1 en modo de deshielo cada 30 minutos sin importar el hielo.","El compresor se quemar\xE1 debido a la falta de control de sobrecalentamiento.","La unidad operar\xE1 solo en modo refrigeraci\xF3n permanentemente por seguridad."],respuesta_correcta:0,explicacion:"Con el sensor de defrost en circuito abierto, la placa no detecta cuando el serpentin necesita deshielo. El sistema nunca entra en modo defrost y el hielo bloquea el serpentin exterior progresivamente."},{id:"ns_0862",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un sistema VRF. \xBFPor qu\xE9 es vital pesar la carga?",opciones:["Los sistemas VRF son de carga cr\xEDtica y las presiones no son indicadores.","Es un requisito legal de la EPA para sistemas con m\xE1s de 50 libras de gas.","Para asegurar que el aceite POE regrese correctamente a los compresores hoy.","Para evitar que la garant\xEDa del fabricante se anule tras la instalaci\xF3n."],respuesta_correcta:0,explicacion:"En VRF, la carga de refrigerante se calcula por f\xF3rmula del fabricante (carga de f\xE1brica + volumen de tuber\xEDas adicionales). Las presiones no son confiables como indicador de carga porque el sistema modula constantemente su capacidad."},{id:"ns_0863",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Reversal'. \xBFQu\xE9 sucede si se ignora el error?",opciones:["El compresor girar\xE1 al rev\xE9s y no bombear\xE1 aceite ni refrigerante l\xEDquido.","La unidad funcionar\xE1 al 50% de su capacidad nominal debido al desfase fase.","El motor se quemar\xE1 instant\xE1neamente al intentar vencer la inercia carga.","Las v\xE1lvulas de expansi\xF3n se cerrar\xE1n por seguridad al detectar el error."],respuesta_correcta:0,explicacion:"Ignorar Phase Reversal permite que el compresor gire al rev\xE9s sin bombear aceite ni refrigerante, causando falla mec\xE1nica inmediata por falta de lubricaci\xF3n en cojinetes."},{id:"ns_0864",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. Subenfriamiento 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido severa en el sistema (Undercharged) hoy hoy.","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total hoy hoy.","Condensador exterior extremadamente sucio que no permite el intercambio t\xE9rmico.","Evaporador interior congelado que bloquea el flujo de calor totalmente hoy."],respuesta_correcta:0,explicacion:"Subenfriamiento de 0\xB0F con presiones moderadas es el diagn\xF3stico definitivo de falta severa de refrigerante. No hay masa suficiente en el sistema para que el condensador complete la condensaci\xF3n y entregue l\xEDquido subenfriado."},{id:"ns_0865",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n hoy.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada hoy hoy.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial hoy hoy.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos."],respuesta_correcta:0,explicacion:"Smart Homes exige t\xE9cnicos capacitados en redes y protocolos de comunicaci\xF3n para conectar e integrar dispositivos IoT con los sistemas de climatizaci\xF3n."},{id:"ns_0866",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 indica una temperatura de succi\xF3n muy alta en el cabezal?",opciones:["Sobrecalentamiento excesivo que da\xF1ar\xE1 la lubricaci\xF3n de compresores pronto.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de evaporaci\xF3n hoy hoy.","Falta de refrigerante l\xEDquido en el recibidor principal del rack paralelo hoy.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n cerradas por temperatura."],respuesta_correcta:0,explicacion:"El sobrecalentamiento excesivo del gas en el cabezal de succi\xF3n indica que el refrigerante se ha evaporado completamente y se ha calentado mucho m\xE1s de lo necesario. Esto perjudica la lubricaci\xF3n y eleva peligrosamente la temperatura de descarga."},{id:"ns_0867",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. \xBFQu\xE9 revisa?",opciones:["Presencia de aire en la tuber\xEDa, paddle roto o transductor descalibrado hoy.","La carga de refrigerante que podr\xEDa estar congelando el agua en tubos hoy.","El sentido de rotaci\xF3n del motor del compresor centr\xEDfugo del sistema hoy.","La apertura de las v\xE1lvulas de expansi\xF3n del circuito de refrigeraci\xF3n hoy."],respuesta_correcta:0,explicacion:"Flow Switch Alarm con bomba operando indica problema del sensor de flujo: paddle da\xF1ado, presencia de aire, o transductor de presi\xF3n diferencial que necesita recalibraci\xF3n."},{id:"ns_0868",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. \xBFCausa?",opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.","La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido.","La humedad en la habitaci\xF3n es superior al 95% y satura el serpent\xEDn hoy."],respuesta_correcta:0,explicacion:"El goteo al parar el compresor indica contrapendiente o bloqueo parcial del drenaje en la parte superior, reteniendo agua durante la operaci\xF3n que se libera al detenerse la unidad."},{id:"ns_0869",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de 0.9 en suministro y 0.2 en retorno. \xBFProblema?",opciones:["Restricci\xF3n severa en conductos de suministro o difusores cerrados hoy hoy.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire hoy.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo hoy.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o hoy."],respuesta_correcta:0,explicacion:'La distribuci\xF3n de presi\xF3n est\xE1tica 0.9"/0.2" confirma restricci\xF3n en el lado de suministro. Los conductos de suministro restringidos, colapsados o difusores cerrados son la fuente del problema.'},{id:"ns_0870",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre 20\xB0F y 30\xB0F hoy.","S\xED, las bombas de calor siempre tienen un diferencial menor que hornos hoy.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en calefaccion es insuficiente (rango normal 20-30F). Indica baja capacidad de calefaccion, usualmente por falta de refrigerante, exceso de flujo de aire interior o absorcion deficiente de calor exterior."},{id:"ns_0871",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera un reemplazo de compresor de 10 HP. \xBFQu\xE9 paso es vital post-quemadura?",opciones:["Realizar prueba de acidez del aceite y usar filtros succi\xF3n de limpieza hoy.","A\xF1adir aditivo sellador de fugas para prevenir fallas futuras en l\xEDneas hoy.","Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.","Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy."],respuesta_correcta:0,explicacion:"Cuando un compresor se quema, produce \xE1cidos fluorh\xEDdrico y clorh\xEDdrico que corroen el sistema. La prueba de acidez verifica la contaminaci\xF3n y los filtros de succi\xF3n capturan part\xEDculas s\xF3lidas, ambos cr\xEDticos para la sobrevivencia del compresor nuevo."},{id:"ns_0872",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga que tira mucho aire pero poco refrigerante. \xBFEstado?",opciones:["Funcionamiento correcto; la purga est\xE1 separando los no condensables hoy.","Falla en el serpent\xEDn de condensaci\xF3n interno de la unidad de purga hoy.","El sistema tiene una fuga masiva de agua hacia el lado del refrigerante.","La temperatura del evaporador es demasiado alta para que la purga trabaje."],respuesta_correcta:0,explicacion:"Purga que expulsa mucho aire y poco refrigerante funciona correctamente, cumpliendo su funci\xF3n de separar y remover gases no condensables del sistema de refrigeraci\xF3n."},{id:"ns_0873",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 sucede si el 'Oil Separator' queda pegado en posici\xF3n abierta?",opciones:["Gas caliente de descarga pasar\xE1 directo al dep\xF3sito aceite y succi\xF3n hoy.","El rack se quedar\xE1 sin aceite en pocos minutos al no poder separarlo gas.","Los compresores se apagar\xE1n por alta presi\xF3n al bloquearse el flujo gas.","El nivel de aceite en los c\xE1rteres subir\xE1 tanto que da\xF1ar\xE1 los pistones hoy."],respuesta_correcta:0,explicacion:"Con el flotador del separador trabado abierto, no hay barrera entre la descarga de alta presi\xF3n y el dep\xF3sito de aceite. El gas caliente pasa directamente, pudiendo empujar el aceite fuera del dep\xF3sito y reducir la eficiencia del rack."},{id:"ns_0874",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la efectividad de sus camionetas rotuladas. \xBFQu\xE9 KPI usa?",opciones:["N\xFAmero de llamadas de nuevos clientes que mencionan haber visto la unidad hoy.","La cantidad de millas recorridas por cada veh\xEDculo en zonas residenciales.","El costo total del dise\xF1o e instalaci\xF3n del r\xF3tulo dividido entre 12 meses.","El aumento en la velocidad promedio de t\xE9cnicos al conducir camionetas nuevas."],respuesta_correcta:0,explicacion:"Medir las llamadas de nuevos clientes que mencionan la camioneta rotulada es el KPI m\xE1s preciso para evaluar el retorno de la inversi\xF3n en branding vehicular."},{id:"ns_0875",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con condensador agua tiene 'High Condensing Pressure'. \xBFQu\xE9 revisa?",opciones:["Temperatura del agua de torre y si la bomba de condensador funciona hoy.","La carga de refrigerante l\xEDquido bas\xE1ndose en el visor del evaporador hoy.","Si la v\xE1lvula de expansi\xF3n est\xE1 inyectando demasiado l\xEDquido al sistema.","El estado de los filtros de aire de la manejadora de aire del edificio hoy."],respuesta_correcta:0,explicacion:"Alta presi\xF3n de condensaci\xF3n en condensador de agua: lo primero es verificar la temperatura del agua de torre y que la bomba de condensador est\xE9 funcionando correctamente."},{id:"ns_0876",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n de 125 PSI y descarga 400 PSI con R-410A. \xBFEstado aire?",opciones:["Funcionamiento normal bajo condiciones de carga t\xE9rmica est\xE1ndar hoy hoy.","Falta de refrigerante que impide que temperatura del aire baje a 55 grados.","Exceso de carga que est\xE1 elevando la presi\xF3n de descarga innecesariamente.","Compresor con eficiencia reducida que no logra enfriar el aire correctamente."],respuesta_correcta:0,explicacion:"Succi\xF3n de 125 PSI y descarga de 400 PSI con R-410A son presiones normales de operaci\xF3n. El sistema est\xE1 funcionando dentro de los par\xE1metros de dise\xF1o para condiciones de carga t\xE9rmica est\xE1ndar."},{id:"ns_0877",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que su empresa tiene muchos 'One-time Customers'. \xBFQu\xE9 estrategia?",opciones:["Programa de membres\xEDas mantenimiento para convertir clientes en recurrentes.","Aumentar el precio de la primera visita para maximizar la ganancia hoy.","Gastar m\xE1s dinero en anuncios de Google para atraer siempre clientes nuevos.","Despedir a t\xE9cnicos que no logren vender un sistema nuevo en cada visita."],respuesta_correcta:0,explicacion:"La membres\xEDa de mantenimiento es la herramienta probada para convertir clientes de una sola visita en clientes recurrentes con relaci\xF3n a largo plazo."},{id:"ns_0878",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter se apaga por 'Compressor Discharge Temp'. \xBFQu\xE9 revisa?",opciones:["Carga de refrigerante baja o una restricci\xF3n en la v\xE1lvula de expansi\xF3n hoy.","Si el ventilador interior est\xE1 sucio y no sopla suficiente aire fr\xEDo hoy.","El voltaje de la l\xEDnea el\xE9ctrica que podr\xEDa estar por debajo de 200V hoy.","Si el control remoto est\xE1 configurado en una temperatura demasiado baja hoy."],respuesta_correcta:0,explicacion:"La temperatura de descarga excesiva del compresor es causada por carga baja de refrigerante o restricci\xF3n en la v\xE1lvula de expansi\xF3n que reduce el efecto de enfriamiento del gas de succi\xF3n."},{id:"ns_0879",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba calor, \xBFqu\xE9 sucede si 'Check Valve' condensador falla abierta?",opciones:["En modo calor el refrigerante har\xE1 bypass a TXV impidiendo calentamiento hoy.","El sistema funcionar\xE1 mejor al haber menos restricci\xF3n al flujo l\xEDquido hoy.","La presi\xF3n de descarga subir\xE1 hasta que switch de alta apague el equipo hoy.","El compresor se quemar\xE1 por el retorno de l\xEDquido masivo en el arranque hoy."],respuesta_correcta:0,explicacion:"Si la check valve del condensador falla abierta, el refrigerante en modo calor circula sin pasar por la TXV. Sin la restriccion del dispositivo de expansion, no se produce el cambio de presion necesario para calentar."},{id:"ns_0880",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula 'Quench' o inyecci\xF3n de l\xEDquido?",opciones:["Para enfriar gas de succi\xF3n y evitar que descarga da\xF1e el aceite hoy hoy.","Para aumentar la presi\xF3n de succi\xF3n cuando carga en vitrinas es baja hoy.","Para limpiar el interior de compresores de acumulaciones de carbonilla hoy.","Para ayudar al retorno de aceite desde los evaporadores m\xE1s lejanos hoy."],respuesta_correcta:0,explicacion:"La v\xE1lvula Quench protege el sistema inyectando una cantidad controlada de l\xEDquido que se evapora y absorbe calor excesivo. Sin esta protecci\xF3n, temperaturas de descarga elevadas carbonizar\xEDan el aceite y da\xF1ar\xEDan las v\xE1lvulas del compresor."},{id:"ns_0881",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior debe decidir entre aspiradora agua o bomba para un drenaje. \xBFCriterio?",opciones:["El volumen de agua y la accesibilidad para eliminaci\xF3n segura del fluido hoy.","Cu\xE1l de las dos herramientas es m\xE1s nueva y hace menos ruido al operar hoy.","La preferencia del cliente sobre qu\xE9 herramienta quiere ver en su casa hoy.","Ninguno, ya que ambas herramientas hacen exactamente el mismo trabajo hoy."],respuesta_correcta:0,explicacion:"La decisi\xF3n entre aspiradora y bomba se toma evaluando la cantidad de agua y las condiciones de acceso. Un profesional elige la herramienta que resuelve el problema de forma segura y eficiente seg\xFAn las condiciones espec\xEDficas del sitio."},{id:"ns_0882",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene purga que marca 'Water Detected'. \xBFQu\xE9 acci\xF3n es urgente?",opciones:["Realizar prueba presi\xF3n a tubos del evaporador para buscar rupturas hoy.","Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.","Aumentar la temperatura del agua helada para evitar que vapor condense hoy.","Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy."],respuesta_correcta:0,explicacion:"Water Detected es una alarma cr\xEDtica que requiere prueba de presi\xF3n inmediata a los tubos del evaporador para identificar rupturas que permiten la entrada de agua al lado del refrigerante."},{id:"ns_0883",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n 130 PSI y descarga 380 PSI. Subenfriamiento 12\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y el subenfriamiento est\xE1n en rango.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser 15 grados hoy.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno hoy.","Compresor fallando; la diferencia presi\xF3n entre succi\xF3n y descarga es baja hoy."],respuesta_correcta:0,explicacion:"Presiones de 130/380 PSI con 12\xB0F de subenfriamiento confirman operaci\xF3n \xF3ptima. Todos los par\xE1metros est\xE1n dentro del rango normal para R-410A, indicando carga correcta y buen funcionamiento."},{id:"ns_0884",categoria:"NATE_SR_PACKAGE",pregunta:"En unidad paquete, el contactor compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["El voltaje en la bobina (24V) y si hay suciedad u \xF3xido en el n\xFAcleo hoy.","Si los contactos principales est\xE1n quemados o soldados entre s\xED hoy.","El capacitor de arranque del compresor que podr\xEDa estar descargado hoy.","La continuidad de los fusibles de potencia de la l\xEDnea de 240 voltios hoy."],respuesta_correcta:0,explicacion:"Revisar el voltaje de la bobina y el estado del n\xFAcleo es el procedimiento est\xE1ndar cuando un contactor zumba. Un voltaje de bobina inferior al 85% del nominal o residuos en las caras polares impiden que la armadura cierre completamente contra el resorte de retorno."},{id:"ns_0885",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico cobra 'por fuera' a clientes. \xBFQu\xE9 acci\xF3n toma?",opciones:["Despido inmediato y posible acci\xF3n legal seg\xFAn el contrato de trabajo hoy.","Hablar con el t\xE9cnico y pedirle una comisi\xF3n por esos trabajos extras hoy.","Ignorar la situaci\xF3n si el t\xE9cnico es el que m\xE1s dinero genera hoy.","Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."],respuesta_correcta:0,explicacion:"El cobro por fuera a clientes es una violaci\xF3n grave; la acci\xF3n correcta es el despido inmediato y la evaluaci\xF3n de acciones legales conforme al contrato laboral."},{id:"ns_0886",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFPor qu\xE9 es fundamental cargar l\xEDquido en el recibidor?",opciones:["Para evitar fraccionamiento de la mezcla y asegurar composici\xF3n correcta hoy.","Para que el refrigerante se mezcle m\xE1s r\xE1pido con el aceite POE del rack hoy.","Para prevenir que las v\xE1lvulas de descarga de compresores se calienten hoy.","Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal."],respuesta_correcta:0,explicacion:"Como mezcla zeotr\xF3pica, el R-448A se fracciona si se carga en vapor. Cada componente tiene una presi\xF3n de vapor distinta, por lo que cargar en l\xEDquido es la \xFAnica forma de garantizar que la composici\xF3n en el sistema sea la especificada por el fabricante."},{id:"ns_0887",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de temperatura de 'Entering Water' roto. \xBFEfecto?",opciones:["El controlador no podr\xE1 calcular la carga t\xE9rmica real del edificio hoy.","El compresor se apagar\xE1 inmediatamente por seguridad de flujo de agua hoy.","La unidad operar\xE1 siempre al 100% de su capacidad nominal sin modular hoy.","No hay efecto si el sensor de 'Leaving Water' est\xE1 operando correctamente hoy."],respuesta_correcta:0,explicacion:"Sin sensor de entering water, el controlador pierde la referencia para calcular la carga t\xE9rmica del edificio y no puede modular adecuadamente la capacidad del chiller."},{id:"ns_0888",categoria:"NATE_SR_HVAC",pregunta:"Un sistema residencial presenta una presi\xF3n de descarga de 550 PSI con R-410A. \xBFCausa?",opciones:["Condensador extremadamente sucio o ventilador exterior fallando hoy hoy.","Falta de refrigerante l\xEDquido que impide que el sistema enfr\xEDe el aire hoy.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en la posici\xF3n de abierta total.","El compresor est\xE1 perdiendo eficiencia y no logra comprimir el gas ralo."],respuesta_correcta:0,explicacion:"Descarga de 550 PSI es peligrosamente alta para R-410A. Un condensador sucio o ventilador fallando impide el rechazo de calor, causando acumulaci\xF3n de presi\xF3n que puede activar el switch de alta presi\xF3n o da\xF1ar el compresor."},{id:"ns_0889",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Average Response Time'. \xBFQu\xE9 medida toma?",opciones:["Implementar software de despacho inteligente y zonificaci\xF3n de t\xE9cnicos hoy.","Aumentar el n\xFAmero de t\xE9cnicos en la n\xF3mina aunque no haya llamadas hoy.","Reducir el tiempo de almuerzo de los t\xE9cnicos para que est\xE9n m\xE1s disponibles.","Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas."],respuesta_correcta:0,explicacion:"El despacho inteligente con zonificaci\xF3n geogr\xE1fica reduce el tiempo de respuesta al optimizar autom\xE1ticamente la asignaci\xF3n de t\xE9cnicos seg\xFAn ubicaci\xF3n y disponibilidad."},{id:"ns_0890",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC. \xBFCausa?",opciones:["Falla de comunicaci\xF3n; el voltaje deber\xEDa fluctuar entre 0 y 24VDC hoy hoy.","La placa exterior est\xE1 operando correctamente enviando la se\xF1al de control.","El compresor inverter est\xE1 aterrizado y consume el voltaje de comunicaci\xF3n.","Falta de alimentaci\xF3n de 240VAC en los terminales L1 y L2 de la exterior."],respuesta_correcta:0,explicacion:"En sistemas inverter, la se\xF1al de comunicaci\xF3n S2-S3 debe fluctuar entre 0 y 24VDC. Un voltaje constante indica que no hay transmisi\xF3n de datos: falla de comunicaci\xF3n entre unidades."},{id:"ns_0891",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el 'Defrost Sensor' falla en circuito abierto?",opciones:["El sistema nunca entrar\xE1 en modo de deshielo y el serpent\xEDn se congelar\xE1.","El sistema entrar\xE1 en modo de deshielo cada 30 minutos sin importar el hielo.","El compresor se quemar\xE1 debido a la falta de control de sobrecalentamiento.","La unidad operar\xE1 solo en modo refrigeraci\xF3n permanentemente por seguridad."],respuesta_correcta:0,explicacion:"El sensor de defrost en circuito abierto elimina la senal de temperatura al controlador. Sin verificar que el serpentin esta frio, el sistema nunca cumple la condicion de inicio de deshielo y el hielo se acumula."},{id:"ns_0892",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un sistema VRF. \xBFPor qu\xE9 es vital pesar la carga?",opciones:["Los sistemas VRF son de carga cr\xEDtica y las presiones no son indicadores.","Es un requisito legal de la EPA para sistemas con m\xE1s de 50 libras de gas.","Para asegurar que el aceite POE regrese correctamente a los compresores hoy.","Para evitar que la garant\xEDa del fabricante se anule tras la instalaci\xF3n."],respuesta_correcta:0,explicacion:"Los VRF requieren pesaje exacto porque la modulaci\xF3n variable de sus compresores inverter hace que las presiones fluct\xFAen constantemente. Solo el peso de refrigerante especificado por el fabricante garantiza el rendimiento correcto del sistema."},{id:"ns_0893",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Reversal'. \xBFQu\xE9 sucede si se ignora el error?",opciones:["El compresor girar\xE1 al rev\xE9s y no bombear\xE1 aceite ni refrigerante l\xEDquido.","La unidad funcionar\xE1 al 50% de su capacidad nominal debido al desfase fase.","El motor se quemar\xE1 instant\xE1neamente al intentar vencer la inercia carga.","Las v\xE1lvulas de expansi\xF3n se cerrar\xE1n por seguridad al detectar el error."],respuesta_correcta:0,explicacion:"Phase Reversal causa rotaci\xF3n inversa del compresor. Sin circulaci\xF3n de aceite ni refrigerante en la direcci\xF3n correcta, los componentes mec\xE1nicos fallan r\xE1pidamente."},{id:"ns_0894",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. Subenfriamiento 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido severa en el sistema (Undercharged) hoy hoy.","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total hoy hoy.","Condensador exterior extremadamente sucio que no permite el intercambio t\xE9rmico.","Evaporador interior congelado que bloquea el flujo de calor totalmente hoy."],respuesta_correcta:0,explicacion:"Subenfriamiento de 0\xB0F es la se\xF1al inequ\xEDvoca de falta severa de refrigerante. El sistema no tiene suficiente masa de refrigerante para completar la condensaci\xF3n y producir l\xEDquido subenfriado en la salida del condensador."},{id:"ns_0895",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado de 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n hoy.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada hoy hoy.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial hoy hoy.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos."],respuesta_correcta:0,explicacion:"Smart Homes demanda t\xE9cnicos con formaci\xF3n en redes y protocolos de comunicaci\xF3n para integrar sistemas inteligentes de climatizaci\xF3n con la infraestructura del hogar."},{id:"ns_0896",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 indica una temperatura de succi\xF3n muy alta en el cabezal?",opciones:["Sobrecalentamiento excesivo que da\xF1ar\xE1 la lubricaci\xF3n de compresores pronto.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de evaporaci\xF3n hoy hoy.","Falta de refrigerante l\xEDquido en el recibidor principal del rack paralelo hoy.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n cerradas por temperatura."],respuesta_correcta:0,explicacion:"Cuando la temperatura de succi\xF3n es muy alta, indica sobrecalentamiento severo. Los compresores semi-herm\xE9ticos dependen del gas de succi\xF3n para enfriar el motor; sin ese enfriamiento, el aceite pierde propiedades y los componentes se desgastan r\xE1pidamente."},{id:"ns_0897",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Flow Switch Alarm' con la bomba encendida. \xBFQu\xE9 revisa?",opciones:["Presencia de aire en la tuber\xEDa, paddle roto o transductor descalibrado hoy.","La carga de refrigerante que podr\xEDa estar congelando el agua en tubos hoy.","El sentido de rotaci\xF3n del motor del compresor centr\xEDfugo del sistema hoy.","La apertura de las v\xE1lvulas de expansi\xF3n del circuito de refrigeraci\xF3n hoy."],respuesta_correcta:0,explicacion:"Alarma de flow switch con bomba encendida apunta a problemas del sensor: paddle roto, aire en tuber\xEDa, o transductor descalibrado, no a problemas del sistema de refrigeraci\xF3n."},{id:"ns_0898",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando el compresor para. \xBFCausa?",opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.","La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido.","La humedad en la habitaci\xF3n es superior al 95% y satura el serpent\xEDn hoy."],respuesta_correcta:0,explicacion:"El goteo solo al parar el compresor indica un drenaje con contrapendiente o parcialmente obstruido que retiene condensado durante la operaci\xF3n y lo libera al cesar el funcionamiento."},{id:"ns_0899",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de 0.9 en suministro y 0.2 en retorno. \xBFProblema?",opciones:["Restricci\xF3n severa en conductos de suministro o difusores cerrados hoy hoy.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire hoy.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo hoy.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o hoy."],respuesta_correcta:0,explicacion:'Presi\xF3n est\xE1tica de 0.9" en suministro versus 0.2" en retorno indica restricci\xF3n predominante en el suministro. Conductos de suministro restringidos o difusores cerrados causan esta distribuci\xF3n asim\xE9trica.'},{id:"ns_0900",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre 20\xB0F y 30\xB0F hoy.","S\xED, las bombas de calor siempre tienen un diferencial menor que hornos hoy.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en modo calor no es aceptable (lo normal es 20-30F). Este diferencial bajo indica que la bomba de calor no transfiere suficiente calor, por falta de carga, flujo de aire excesivo o fallas en la absorcion exterior."},{id:"ns_0901",categoria:"NATE_SR_PACKAGE",pregunta:"Un ultra-congelador m\xE9dico (-80\xB0C) presenta una alarma de temperatura. El sistema es de cascada. \xBFCu\xE1l es la sospecha t\xE9cnica Senior?",opciones:["Falla en el compresor de la etapa de baja o p\xE9rdida de carga de refrigerante especial.","El ventilador del condensador de la etapa de alta est\xE1 girando demasiado r\xE1pido.","La junta de la puerta est\xE1 permitiendo una infiltraci\xF3n m\xEDnima de humedad ambiente.","El lubricante POE se ha solidificado debido a que el calentador de c\xE1rter fall\xF3."],respuesta_correcta:0,explicacion:"En un sistema de cascada, la etapa de baja temperatura es responsable de alcanzar los -80\xB0C. Si hay alarma de temperatura, la causa m\xE1s cr\xEDtica es falla del compresor de la etapa baja o p\xE9rdida del refrigerante especial de baja temperatura, ya que sin este circuito es imposible mantener -80\xB0C."},{id:"ns_0902",categoria:"NATE_SR_HVAC",pregunta:"Un sistema BMS reporta 'Token Loss' en una red MS/TP de BACnet. \xBFQu\xE9 problema f\xEDsico busca el Senior?",opciones:["Interferencia electromagn\xE9tica o una resistencia de terminaci\xF3n (EOL) faltante.","Falta de voltaje de 24V en el transformador que alimenta al controlador principal.","Direccionamiento MAC duplicado en dos dispositivos de la misma sub-red de control.","El cable de comunicaci\xF3n est\xE1 aterrizado en ambos extremos causando un bucle."],respuesta_correcta:0,explicacion:"El 'Token Loss' en una red BACnet MS/TP indica problemas en la capa f\xEDsica de comunicaci\xF3n. La interferencia electromagn\xE9tica corrompe las se\xF1ales y una resistencia de terminaci\xF3n (EOL) faltante causa reflexiones en el cable que impiden la comunicaci\xF3n correcta del token."},{id:"ns_0903",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC busca reducir costos mediante 'Econom\xEDa de Escala'. \xBFQu\xE9 acci\xF3n t\xE9cnica la representa?",opciones:["Estandarizar una sola marca de equipo para toda la empresa y negociar precios por volumen.","Contratar a m\xE1s t\xE9cnicos junior para reducir el costo promedio de la hora hombre.","Eliminar el uso de software de despacho para evitar el pago de licencias mensuales.","Diversificar los servicios ofreciendo plomer\xEDa y pintura adem\xE1s de aire acondicionado."],respuesta_correcta:0,explicacion:"La econom\xEDa de escala en HVAC se logra estandarizando una sola marca de equipo y negociando precios por volumen, reduciendo el costo unitario de materiales significativamente."},{id:"ns_0904",categoria:"NATE_SR_PACKAGE",pregunta:"Se encuentra 'Cera' (Waxing) en el dispositivo de expansi\xF3n de un sistema de baja temperatura con R-22. \xBFCausa?",opciones:["Uso de aceite mineral con un punto de fl\xF3culo demasiado alto para la aplicaci\xF3n.","Reacci\xF3n qu\xEDmica entre el refrigerante y la humedad residual en el sistema.","Descomposici\xF3n del barniz del motor del compresor debido a una quemadura previa.","El aceite POE absorbi\xF3 humedad y se convirti\xF3 en un pol\xEDmero s\xF3lido pegajoso."],respuesta_correcta:0,explicacion:"El waxing ocurre cuando el aceite mineral alcanza su punto de fl\xF3culo (cloud point) a bajas temperaturas, separ\xE1ndose y formando cera que obstruye el dispositivo de expansi\xF3n. En aplicaciones de baja temperatura con R-22, se necesita aceite mineral con punto de fl\xF3culo muy bajo o cambiar a aceite alquilbenceno."},{id:"ns_0905",categoria:"NATE_SR_HVAC",pregunta:"Al realizar una prueba de combusti\xF3n en un horno de alta eficiencia, se detecta un CO de 400 PPM. \xBFDecisi\xF3n Senior?",opciones:["Apagar el equipo inmediatamente; es una condici\xF3n peligrosa de combusti\xF3n incompleta.","Ajustar la presi\xF3n de gas en el manifold y volver a medir tras 10 minutos de operaci\xF3n.","Indicar al cliente que el valor es aceptable mientras no haya olor a gas en la casa.","Limpiar los quemadores con aire comprimido y asumir que el valor bajar\xE1 solo."],respuesta_correcta:0,explicacion:"Un nivel de CO de 400 PPM indica combusti\xF3n incompleta severa, lo cual es una condici\xF3n peligrosa que puede causar intoxicaci\xF3n por mon\xF3xido de carbono. El protocolo Senior es apagar el equipo inmediatamente para proteger la seguridad de los ocupantes."},{id:"ns_0906",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor en modo refrigeraci\xF3n tiene una descarga de 400 PSI y succi\xF3n de 150 PSI. El subenfriamiento es 2\xB0F. \xBFEstado?",opciones:["Sobrecarga de refrigerante que est\xE1 inundando el serpent\xEDn del evaporador.","Falta de refrigerante l\xEDquido o una v\xE1lvula de expansi\xF3n (TXV) fallida.","Falla del ventilador del condensador que eleva la presi\xF3n de alta innecesariamente.","Operaci\xF3n normal considerando una carga t\xE9rmica extremadamente alta en el interior."],respuesta_correcta:0,explicacion:"Descarga de 400 PSI, succion de 150 PSI y subenfriamiento de solo 2F indica exceso de refrigerante. El evaporador esta inundado de liquido, la succion esta alta por retorno de liquido, y el poco subenfriamiento confirma sobrecarga."},{id:"ns_0907",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior observa que su equipo usa 'Lijar' en lugar de un cortador de tubo para quitar rebabas. \xBFRiesgo?",opciones:["Introducci\xF3n de part\xEDculas met\xE1licas al sistema que da\xF1ar\xE1n las v\xE1lvulas y el compresor.","Que la tuber\xEDa no asiente correctamente en la conexi\xF3n flare causando una fuga.","P\xE9rdida de la certificaci\xF3n de la tuber\xEDa de cobre para uso en alta presi\xF3n.","Reducci\xF3n del di\xE1metro interno del tubo que afectar\xE1 el flujo de refrigerante."],respuesta_correcta:0,explicacion:"Lijar genera part\xEDculas met\xE1licas finas de cobre que pueden entrar al sistema refrigerante. Estas part\xEDculas da\xF1an las v\xE1lvulas de expansi\xF3n, obstruyen filtros y causan desgaste en las partes m\xF3viles del compresor. Se debe usar un desbarbador (reamer) adecuado."},{id:"ns_0908",categoria:"NATE_SR_CHILLERS",pregunta:"En un chiller enfriado por agua, el 'Approach' del condensador es de 0\xB0F. \xBFQu\xE9 sospecha el Senior?",opciones:["Sensores de temperatura descalibrados o un error en el transductor de presi\xF3n.","El sistema est\xE1 operando con una eficiencia de transferencia de calor perfecta.","El flujo de agua de la torre es tan alto que los sensores no logran estabilizarse.","Existe aire atrapado en la parte superior del condensador bloqueando el sensor."],respuesta_correcta:0,explicacion:"Un approach de condensador de 0\xB0F es f\xEDsicamente imposible bajo condiciones normales de operaci\xF3n. Indica un error de calibraci\xF3n en los sensores de temperatura o el transductor de presi\xF3n."},{id:"ns_0909",categoria:"NATE_SR_PACKAGE",pregunta:"Una unidad paquete industrial muestra un error de 'Internal Overload' en el compresor 1, pero el amperaje es normal. \xBFCausa?",opciones:["El protector t\xE9rmico est\xE1 fallando mec\xE1nicamente o hay un punto caliente en el borne.","La carga de refrigerante es ligeramente baja y no enfr\xEDa el motor lo suficiente.","El compresor est\xE1 operando con un voltaje de 208V en un sistema de 240V.","La viscosidad del aceite es demasiado baja causando fricci\xF3n interna invisible."],respuesta_correcta:0,explicacion:"Si el amperaje es normal pero el protector t\xE9rmico interno se dispara, el problema no es el\xE9ctrico sino del protector mismo. Un protector t\xE9rmico defectuoso puede disparar prematuramente, o puede haber un punto caliente en la conexi\xF3n del borne (resistencia alta localizada) que genera calor excesivo en ese punto sin afectar el amperaje total."},{id:"ns_0910",categoria:"NATE_SR_CEO",pregunta:"Un CEO debe asegurar que su empresa cumple con la 'Secci\xF3n 608' de la Clean Air Act. \xBFCu\xE1l es el registro m\xE1s cr\xEDtico?",opciones:["El registro de recuperaci\xF3n y disposici\xF3n de refrigerante por cada unidad de servicio.","La certificaci\xF3n NATE de cada t\xE9cnico que realiza instalaciones residenciales.","El historial de mantenimiento preventivo de la flota de veh\xEDculos de la empresa.","Las facturas de compra de nitr\xF3geno y otros gases no inflamables usados en obra."],respuesta_correcta:0,explicacion:"La Secci\xF3n 608 de la Clean Air Act exige registros detallados de recuperaci\xF3n y disposici\xF3n de refrigerante por cada unidad; su ausencia es la falta m\xE1s grave ante una auditor\xEDa."},{id:"ns_0911",categoria:"NATE_SR_HVAC",pregunta:"Al enfriar aire a carga parcial, la Humedad Relativa (RH) en la habitaci\xF3n tiende a subir. \xBFC\xF3mo lo corrige el Senior?",opciones:["Reduciendo la velocidad del soplador para aumentar el tiempo de contacto en el serpent\xEDn.","Aumentando la carga de refrigerante para bajar la presi\xF3n de succi\xF3n del sistema.","Instalando un termostato que controle \xFAnicamente la temperatura de bulbo seco.","Abriendo los dampers de aire exterior para introducir aire m\xE1s seco del ambiente."],respuesta_correcta:0,explicacion:"A carga parcial, el serpent\xEDn enfr\xEDa menos y su temperatura superficial sube por encima del punto de roc\xEDo, reduciendo la deshumidificaci\xF3n. Reducir la velocidad del soplador baja la temperatura del serpent\xEDn, aumentando el tiempo de contacto y mejorando la remoci\xF3n de humedad."},{id:"ns_0912",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, se observa que el separador de aceite est\xE1 muy caliente en la parte superior pero fr\xEDo en la inferior. \xBFDiagn\xF3stico?",opciones:["El separador est\xE1 inundado de refrigerante l\xEDquido o el flotador est\xE1 trabado.","El sistema de calefacci\xF3n interna del aceite est\xE1 operando a su m\xE1xima potencia.","Falta de flujo de gas de descarga a trav\xE9s del componente por una obstrucci\xF3n.","Es una condici\xF3n normal de estratificaci\xF3n t\xE9rmica dentro del separador de aceite."],respuesta_correcta:0,explicacion:"La parte superior caliente indica entrada de gas de descarga, pero la parte inferior fr\xEDa indica acumulaci\xF3n de refrigerante l\xEDquido o aceite fr\xEDo atrapado. El flotador trabado impide el drenaje normal, causando inundaci\xF3n en la parte baja del separador."},{id:"ns_0913",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC quiere mejorar su 'Conversion Rate' de presupuestos. \xBFQu\xE9 herramienta t\xE9cnica ayuda m\xE1s?",opciones:["Software de ventas con fotos del diagn\xF3stico, opciones de eficiencia y financiamiento.","Reducir el precio de los equipos un 10% por debajo del promedio del mercado local.","Aumentar el periodo de garant\xEDa de la mano de obra a 10 a\xF1os en todas las ventas.","Contratar a vendedores externos que no tengan conocimientos t\xE9cnicos de HVAC."],respuesta_correcta:0,explicacion:"Un software de ventas con fotos del diagn\xF3stico, opciones de eficiencia y financiamiento facilita la decisi\xF3n del cliente al hacer la propuesta visual, clara y financiable."},{id:"ns_0914",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter presenta el error 'Overcurrent Protection'. El compresor no arranca y solo zumba. \xBFQu\xE9 prueba?",opciones:["Resistencia de las bobinas (U, V, W) y si alguna fase est\xE1 aterrizada a tierra.","El capacitor de arranque del compresor aunque se trate de un sistema inverter.","El voltaje de la red AC de entrada que podr\xEDa estar por debajo de los 180V.","La comunicaci\xF3n entre la unidad interior y exterior mediante el cable de se\xF1al."],respuesta_correcta:0,explicacion:"Ante sobrecorriente con compresor que zumba sin arrancar, el Senior mide las bobinas U, V, W para detectar devanado abierto, cortocircuito entre fases o aterrizaje a tierra que impide el arranque."},{id:"ns_0915",categoria:"NATE_SR_CHILLERS",pregunta:"Un sistema de agua helada tiene un Delta T de 2\xB0F (Dise\xF1o es 10\xB0F). Las bombas est\xE1n al 100%. \xBFAcci\xF3n Senior?",opciones:["Cerrar las v\xE1lvulas de balanceo para reducir el flujo y aumentar el intercambio.","Agregar m\xE1s chillers al lazo para compensar la falta de enfriamiento del agua.","Aumentar la velocidad de las bombas para forzar una mayor transferencia t\xE9rmica.","Cambiar el set-point del chiller a una temperatura m\xE1s baja de forma inmediata."],respuesta_correcta:0,explicacion:"Un Delta T de 2\xB0F (dise\xF1o 10\xB0F) con bombas al 100% indica flujo excesivo. Cerrar v\xE1lvulas de balanceo reduce el flujo, aumenta el Delta T y mejora la eficiencia del intercambio t\xE9rmico."},{id:"ns_0916",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que 'ajust\xF3' una TXV cerr\xE1ndola 5 vueltas porque la succi\xF3n era alta. \xBFCr\xEDtica del Senior?",opciones:["La succi\xF3n alta se diagnostica primero por carga t\xE9rmica o eficiencia, no se ajusta la TXV.","Debi\xF3 cerrarla solo 2 vueltas y esperar 10 minutos para ver el cambio de presi\xF3n.","Las v\xE1lvulas de expansi\xF3n t\xE9rmicas modernas no se pueden ajustar mec\xE1nicamente.","Cerrar la v\xE1lvula causar\xE1 que el compresor se queme por falta de retorno de aceite."],respuesta_correcta:0,explicacion:"Una presi\xF3n de succi\xF3n alta puede tener m\xFAltiples causas: exceso de carga t\xE9rmica, filtro de aire sucio, exceso de refrigerante, etc. Ajustar la TXV sin diagnosticar la causa ra\xEDz enmascara el problema real y puede crear nuevos s\xEDntomas."},{id:"ns_0917",categoria:"NATE_SR_CEO",pregunta:"Un CEO analiza el 'Break-Even Point'. Si los costos variables (materiales) suben, \xBFqu\xE9 debe pasar con el precio?",opciones:["El precio debe subir o el volumen de ventas debe incrementarse para mantener margen.","El precio debe mantenerse igual para no perder competitividad en el mercado local.","Los costos fijos (renta, seguros) deben reducirse para compensar el alza de materiales.","Se debe eliminar el pago de horas extras para absorber el costo extra de las piezas."],respuesta_correcta:0,explicacion:"Si los costos variables suben, el precio de venta debe aumentar o el volumen de ventas debe crecer para mantener el margen de contribuci\xF3n y cubrir los costos fijos."},{id:"ns_0918",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Low Oil Temperature'. El calentador est\xE1 encendido. \xBFQu\xE9 revisa el Senior?",opciones:["El sensor de temperatura de aceite o una migraci\xF3n excesiva de refrigerante al c\xE1rter.","La viscosidad del aceite que es demasiado baja para la temperatura de consigna.","Si la bomba de aceite est\xE1 operando en sentido inverso tras un fallo el\xE9ctrico.","El flujo de agua helada que es demasiado alto y enfr\xEDa indirectamente al motor."],respuesta_correcta:0,explicacion:"Con calentador encendido y baja temperatura de aceite, el sensor puede estar defectuoso o hay migraci\xF3n excesiva de refrigerante al c\xE1rter que absorbe calor y enfr\xEDa el aceite por evaporaci\xF3n."},{id:"ns_0919",categoria:"NATE_SR_HVAC",pregunta:"Un motor de soplador PSC consume 8 amperios (Placa indica 6.5). El capacitor es nuevo. \xBFCausa?",opciones:["Presi\xF3n est\xE1tica muy baja (ductos abiertos) o motor con devanados parcialmente en corto.","Filtros de aire extremadamente sucios que obligan al motor a trabajar con m\xE1s carga.","Uso de un capacitor de menor capacidad (MFD) al especificado por el fabricante.","El voltaje de alimentaci\xF3n es de 240V cuando el motor es de dise\xF1o para 208V."],respuesta_correcta:0,explicacion:"Un motor PSC que consume m\xE1s amperaje del nominal con capacitor nuevo indica baja impedancia mec\xE1nica o el\xE9ctrica. Presi\xF3n est\xE1tica muy baja (sin restricci\xF3n) permite que el motor gire libremente a alta carga, o un devanado parcialmente en corto reduce la impedancia el\xE9ctrica."},{id:"ns_0920",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se utiliza una v\xE1lvula 'Bypass' de gas caliente hacia el recibidor?",opciones:["Para mantener la presi\xF3n del recibidor y asegurar el flujo de l\xEDquido hacia vitrinas en invierno.","Para deshelar los evaporadores de baja temperatura de forma r\xE1pida y eficiente.","Para enfriar el aceite antes de que entre al separador de aceite centr\xEDfugo hoy.","Para reducir el consumo el\xE9ctrico de los compresores de la etapa de alta presi\xF3n."],respuesta_correcta:0,explicacion:"En invierno, la presi\xF3n del recibidor puede bajar demasiado por la condensaci\xF3n eficiente en clima fr\xEDo. La v\xE1lvula bypass de gas caliente inyecta gas de descarga al recibidor para mantener la presi\xF3n necesaria y asegurar el flujo de l\xEDquido hacia las vitrinas."},{id:"ns_0921",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Surge' a carga completa. \xBFQu\xE9 factor Senior revisa?",opciones:["Incondensables en el sistema, condensador sucio o falta de carga de refrigerante.","Los \xE1labes de entrada (vanes) que est\xE1n demasiado abiertos para el flujo de gas.","El variador de frecuencia que est\xE1 operando a una frecuencia demasiado baja hoy.","La temperatura del agua helada de salida que es superior al set-point de dise\xF1o."],respuesta_correcta:0,explicacion:"Surge a carga completa indica que el compresor no puede mantener la elevaci\xF3n de presi\xF3n requerida. Causas: incondensables que elevan la descarga, condensador sucio, o falta de refrigerante."},{id:"ns_0922",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere implementar un programa de 'Referidos'. \xBFQu\xE9 m\xE9trica define el \xE9xito real?",opciones:["Costo de Adquisici\xF3n de Cliente (CAC) del referido comparado con el CAC de marketing pagado.","N\xFAmero total de clientes que mencionaron la promoci\xF3n en sus redes sociales personales.","El monto total de los descuentos otorgados a los clientes que refirieron a otros hoy.","La cantidad de t\xE9cnicos que lograron vender un sistema nuevo gracias a un referido."],respuesta_correcta:0,explicacion:"El \xE9xito real de un programa de referidos se mide comparando el CAC del cliente referido vs. el CAC de marketing pagado; los referidos deben ser significativamente m\xE1s baratos."},{id:"ns_0923",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no enfr\xEDa. Al medir voltaje entre S2 y S3 el mult\xEDmetro marca 0V fijos. \xBFCausa?",opciones:["Falla total en la placa electr\xF3nica (interior o exterior) que genera la se\xF1al.","Es el voltaje normal de operaci\xF3n cuando el sistema est\xE1 en modo de espera hoy.","El cable de comunicaci\xF3n S3 est\xE1 desconectado en alguno de los dos extremos.","El compresor est\xE1 operando a su frecuencia m\xEDnima y no requiere se\xF1al de control."],respuesta_correcta:0,explicacion:"Un voltaje de 0V fijos entre S2 y S3 indica que ninguna placa genera la se\xF1al de comunicaci\xF3n. Puede ser falla total de la placa electr\xF3nica (interior o exterior) que produce la se\xF1al pulsante."},{id:"ns_0924",categoria:"NATE_SR_HEATPUMP",pregunta:"En modo calefacci\xF3n, una bomba de calor tiene un sobrecalentamiento de 40\xB0F. \xBFQu\xE9 indica?",opciones:["Falta de refrigerante o una restricci\xF3n en el dispositivo de expansi\xF3n exterior.","Exceso de carga de refrigerante que est\xE1 inundando la unidad interior hoy.","Operaci\xF3n \xF3ptima para un sistema que trabaja con temperaturas exteriores bajo cero.","La v\xE1lvula inversora est\xE1 permitiendo un bypass de gas caliente hacia la succi\xF3n."],respuesta_correcta:0,explicacion:"Un sobrecalentamiento de 40F es excesivamente alto (lo normal es 8-15F). Indica que el refrigerante se evapora demasiado pronto en el serpentin exterior por falta de carga o restriccion en la TXV exterior."},{id:"ns_0925",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que 'complet\xF3' la carga de R-410A pesando el gas en estado gaseoso. \xBFQu\xE9 hace el Senior?",opciones:["Recuperar el gas y recargar en estado l\xEDquido para asegurar la composici\xF3n de la mezcla.","Aceptar el trabajo si las presiones de succi\xF3n y descarga se ven normales hoy.","Pedir al t\xE9cnico que a\xF1ada 1 libra extra de l\xEDquido para compensar el error previo.","Indicar que el R-410A es una mezcla azeotr\xF3pica y no importa el estado de carga."],respuesta_correcta:0,explicacion:"El R-410A es una mezcla casi-azeotr\xF3pica que debe cargarse en estado l\xEDquido para mantener la proporci\xF3n correcta de sus componentes (R-32 y R-125). Cargar en gas causa fraccionamiento que altera las presiones y el rendimiento del sistema."},{id:"ns_0926",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFcu\xE1l es el s\xEDntoma de una v\xE1lvula reguladora de presi\xF3n de c\xE1rter (CPR) ajustada muy baja?",opciones:["Baja capacidad de enfriamiento tras un deshielo al restringir demasiado el retorno de gas.","Sobrecalentamiento excesivo del motor del compresor durante la operaci\xF3n normal hoy.","Disparo frecuente del interruptor de alta presi\xF3n debido al exceso de masa gaseosa.","Paso de refrigerante l\xEDquido al c\xE1rter del compresor por falta de restricci\xF3n."],respuesta_correcta:0,explicacion:"Una CPR ajustada muy baja restringe excesivamente el flujo de gas hacia el compresor tras un deshielo, cuando la carga t\xE9rmica es alta. Esto limita la cantidad de gas que el compresor puede succionar, reduciendo la capacidad de enfriamiento del sistema."},{id:"ns_0927",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un approach de evaporador de 8\xB0F (Nominal 2\xB0F). El flujo de agua es correcto. \xBFAcci\xF3n?",opciones:["Limpieza mec\xE1nica de tubos del evaporador y verificar el tratamiento de agua helada.","Agregar refrigerante l\xEDquido hasta que el approach baje a los 2 grados ideales.","Reducir la velocidad de la bomba de agua helada para aumentar el tiempo de intercambio.","Cambiar los sensores de temperatura asumiendo que est\xE1n descalibrados por el tiempo."],respuesta_correcta:0,explicacion:"Approach de evaporador de 8\xB0F vs. nominal 2\xB0F con flujo correcto indica fouling en los tubos. La limpieza mec\xE1nica y verificar el tratamiento de agua restauran la eficiencia t\xE9rmica."},{id:"ns_0928",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 125 PSI y descarga de 450 PSI con R-410A. El subenfriamiento es 22\xB0F. \xBFEstado?",opciones:["Restricci\xF3n en el lado de alta (filtro o TXV) o condensador extremadamente sucio.","Sistema sobrecargado de refrigerante que est\xE1 inundando el serpent\xEDn exterior hoy.","Funcionamiento normal para un d\xEDa con carga t\xE9rmica alta y temperatura de 105\xB0F.","Compresor con eficiencia reducida que no logra crear el diferencial de presi\xF3n."],respuesta_correcta:0,explicacion:"Succi\xF3n de 125 PSI con descarga muy alta de 450 PSI y subenfriamiento elevado de 22\xB0F indica acumulaci\xF3n de l\xEDquido en el lado de alta. Una restricci\xF3n en el filtro deshidratador o TXV, o un condensador sucio, impide el flujo normal elevando la descarga y el subenfriamiento."},{id:"ns_0929",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que el 'Revenue per Employee' es bajo. \xBFQu\xE9 auditor\xEDa t\xE9cnica realiza?",opciones:["Uso de tiempo no facturable, retrabajos (callbacks) y precisi\xF3n en el despacho.","El costo promedio de las piezas de repuesto que se compran mensualmente hoy.","La cantidad de anuncios que se publican en las plataformas de redes sociales.","Si los t\xE9cnicos est\xE1n usando herramientas de marca premium o gen\xE9ricas hoy."],respuesta_correcta:0,explicacion:"El tiempo no facturable, los retrabajos (callbacks) y la precisi\xF3n del despacho son los factores operativos que m\xE1s impactan el Revenue per Employee en una empresa HVAC."},{id:"ns_0930",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua por la unidad interior. El drenaje est\xE1 libre. \xBFCausa Senior?",opciones:["Falta de refrigerante que causa escarcha parcial y goteo fuera de la bandeja de drenaje.","El ventilador interior est\xE1 girando tan r\xE1pido que succiona el agua del serpent\xEDn.","La bomba de condensados integrada ha fallado mec\xE1nicamente y no evac\xFAa nada.","Humedad relativa en la habitaci\xF3n superior al 95% que satura el serpent\xEDn hoy."],respuesta_correcta:0,explicacion:"Con drenaje libre, la escarcha parcial causada por falta de refrigerante crea goteo irregular fuera de la bandeja de condensado al derretirse, ya que la formaci\xF3n de hielo no es uniforme en el serpent\xEDn."},{id:"ns_0931",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFcu\xE1l es el prop\xF3sito de la 'Check Valve' en paralelo con la TXV interior?",opciones:["Permitir el flujo libre de refrigerante en modo calefacci\xF3n sin restricci\xF3n de la TXV.","Asegurar que el aceite regrese al compresor \xFAnicamente durante el modo fr\xEDo hoy.","Proteger a la v\xE1lvula de expansi\xF3n de las presiones altas del modo calefacci\xF3n.","Regular la presi\xF3n de succi\xF3n del sistema para evitar la congelaci\xF3n del serpent\xEDn."],respuesta_correcta:0,explicacion:"La check valve en paralelo con la TXV interior permite que el refrigerante fluya libremente en modo calefaccion sin restriccion de la TXV interior. En calefaccion, la expansion ocurre en la TXV exterior, no en la interior."},{id:"ns_0932",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Junior quiere usar sellador de fugas en un VRF. El Senior se lo proh\xEDbe por:",opciones:["Riesgo de obstrucci\xF3n de las micro-v\xE1lvulas EEV y da\xF1o al aceite POE.","El sellador es inflamable y pone en riesgo la seguridad de la instalaci\xF3n hoy.","La EPA proh\xEDbe el uso de selladores en sistemas con m\xE1s de 20 libras de gas.","El costo del sellador es superior al costo de encontrar y reparar la fuga hoy."],respuesta_correcta:0,explicacion:"Los sistemas VRF usan v\xE1lvulas de expansi\xF3n electr\xF3nicas (EEV) con orificios muy peque\xF1os que el sellador puede obstruir. Adem\xE1s, el sellador puede contaminar el aceite POE y afectar la lubricaci\xF3n del compresor, causando fallas costosas."},{id:"ns_0933",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una ca\xEDda de presi\xF3n de agua baja en el evaporador. \xBFC\xF3mo afecta la capacidad?",opciones:["La capacidad disminuye debido a la baja transferencia t\xE9rmica por falta de flujo.","La capacidad aumenta ya que el refrigerante tiene m\xE1s tiempo para enfriar el agua.","No afecta la capacidad, pero el compresor consumir\xE1 m\xE1s energ\xEDa el\xE9ctrica hoy.","El chiller entrar\xE1 en modo de ahorro de energ\xEDa autom\xE1ticamente por control hoy."],respuesta_correcta:0,explicacion:"Baja ca\xEDda de presi\xF3n de agua indica bajo flujo por el evaporador. Con menos flujo, la transferencia de calor se reduce y la capacidad de enfriamiento del chiller disminuye proporcionalmente."},{id:"ns_0934",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene un Delta T de 25\xB0F y succi\xF3n baja. El Senior sospecha de:",opciones:["Bajo flujo de aire (filtros sucios o motor soplador fallando).","Exceso de carga de refrigerante que est\xE1 inundando el serpent\xEDn interior hoy.","Falla de la v\xE1lvula de expansi\xF3n t\xE9rmica que est\xE1 abierta al 100% de flujo.","Presi\xF3n est\xE1tica del sistema extremadamente baja debido a conductos abiertos."],respuesta_correcta:0,explicacion:"Un Delta T alto de 25\xB0F con succi\xF3n baja indica que poco aire pasa por el evaporador. Filtros sucios o un motor de soplador fallando reducen el CFM, lo que enfr\xEDa m\xE1s el poco aire que pasa (Delta T alto) pero reduce la absorci\xF3n total de calor (succi\xF3n baja)."},{id:"ns_0935",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir la rotaci\xF3n de personal t\xE9cnico. \xBFQu\xE9 beneficio no monetario es m\xE1s valorado?",opciones:["Equilibrio vida-trabajo (horarios predecibles y guardias justas).","Tener camionetas nuevas con logotipos profesionales y GPS de \xFAltima generaci\xF3n.","Recibir uniformes de marca premium con bordados personalizados cada temporada.","Organizar eventos sociales mensuales con asistencia obligatoria para el equipo."],respuesta_correcta:0,explicacion:"El equilibrio vida-trabajo con horarios predecibles y guardias justas es el beneficio no monetario m\xE1s valorado por los t\xE9cnicos, superando a los beneficios materiales."},{id:"ns_0936",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 sucede si la v\xE1lvula de retenci\xF3n del condensador falla abierta?",opciones:["Migraci\xF3n masiva de refrigerante al condensador durante el paro en clima fr\xEDo.","Aumento en la presi\xF3n de succi\xF3n de todos los compresores conectados al rack.","El aceite se quedar\xE1 atrapado en el condensador y no regresar\xE1 al rack paralelo.","El sistema entrar\xE1 en modo de ahorro de energ\xEDa al reducir la carga del motor."],respuesta_correcta:0,explicacion:"Sin la v\xE1lvula check del condensador, el refrigerante l\xEDquido migra masivamente hacia el condensador fr\xEDo durante los periodos de paro en clima fr\xEDo. Esto vac\xEDa el recibidor y al arrancar no habr\xE1 suficiente l\xEDquido para alimentar las vitrinas."},{id:"ns_0937",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Surge' a carga parcial. \xBFC\xF3mo se ajusta operativamente?",opciones:["Bajando la presi\xF3n de descarga o aumentando el flujo de gas por el impulsor.","Cerrando la v\xE1lvula de expansi\xF3n para reducir la masa de refrigerante total.","Incrementando la velocidad de la bomba de agua helada del edificio central hoy.","Aumentando la temperatura del agua de la torre para subir la descarga hoy."],respuesta_correcta:0,explicacion:"El surge a carga parcial se corrige reduciendo la relaci\xF3n de presiones: bajando la presi\xF3n de descarga o aumentando el flujo de gas por el impulsor mediante vanes o VFD."},{id:"ns_0938",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 145 PSI y descarga de 380 PSI con R-410A. Sobrecalentamiento 0\xB0F. \xBFCausa?",opciones:["V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total.","Falta de refrigerante l\xEDquido que impide que la descarga suba a niveles 450.","Evaporador interior con flujo de aire extremadamente alto por un motor ECM.","Compresor perdiendo eficiencia volum\xE9trica por desgaste interno de pistones."],respuesta_correcta:0,explicacion:"Succi\xF3n alta de 145 PSI con sobrecalentamiento de 0\xB0F indica inundaci\xF3n del evaporador con l\xEDquido refrigerante. Una TXV abierta totalmente permite paso descontrolado de refrigerante, saturando el evaporador y enviando l\xEDquido de vuelta al compresor."},{id:"ns_0939",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere aumentar el 'Customer Lifetime Value'. \xBFQu\xE9 estrategia lanza?",opciones:["Contratos de mantenimiento preventivo con beneficios exclusivos y descuentos.","Aumentar los precios de instalaci\xF3n para maximizar la ganancia del primer d\xEDa.","Eliminar el departamento de servicio para enfocarse solo en ventas de equipos.","Reducir la garant\xEDa de mano de obra a 30 d\xEDas para evitar gastos futuros hoy."],respuesta_correcta:0,explicacion:"Los contratos de mantenimiento preventivo con beneficios exclusivos y descuentos retienen clientes por a\xF1os, maximizando el Customer Lifetime Value de forma sostenible."},{id:"ns_0940",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFqu\xE9 sucede si la v\xE1lvula de retenci\xF3n de un compresor falla abierta?",opciones:["El refrigerante migrar\xE1 al compresor parado, causando arranques inundados.","La presi\xF3n de succi\xF3n aumentar\xE1 en todo el sistema del rack de refrigeraci\xF3n.","El aceite se quedar\xE1 atrapado en el condensador y no regresar\xE1 al rack hoy.","El compresor consumir\xE1 el doble de amperaje al intentar arrancar con carga."],respuesta_correcta:0,explicacion:"Sin la v\xE1lvula check de descarga, el gas de alta presi\xF3n del cabezal y el refrigerante del condensador migran al compresor apagado. Al reiniciar, el compresor intenta comprimir el l\xEDquido acumulado, causando un golpe de l\xEDquido potencialmente destructivo."},{id:"ns_0941",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Unbalance' del 4%. \xBFQu\xE9 riesgo t\xE9cnico existe?",opciones:["Sobrecalentamiento excesivo del motor del compresor y fallo prematuro.","El chiller funcionar\xE1 al 96% de su capacidad nominal sin riesgo alguno hoy.","La unidad de purga empezar\xE1 a operar para compensar el desequilibrio el\xE9ctrico.","La v\xE1lvula de expansi\xF3n se cerrar\xE1 para proteger el circuito de refrigerante."],respuesta_correcta:0,explicacion:"Un desbalance de fase del 4% puede causar incrementos de corriente de hasta 25% en un devanado del motor, generando calor excesivo que acorta dr\xE1sticamente la vida del aislamiento."},{id:"ns_0942",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no enfr\xEDa. El compresor exterior no arranca pero el ventilador s\xED. \xBFPrueba?",opciones:["Medir resistencia de las bobinas del compresor y voltaje DC de la placa IPM.","Cambiar el capacitor de arranque por uno de mayor capacidad inmediatamente hoy.","Puentear el interruptor de alta presi\xF3n para ver si el compresor enciende hoy.","Agregar 2 libras de refrigerante R-410A para descartar una fuga total de gas."],respuesta_correcta:0,explicacion:"Con el ventilador exterior funcionando pero compresor sin arrancar, el Senior mide la resistencia de las bobinas del compresor y el voltaje DC del IPM para determinar si es falla mec\xE1nica o electr\xF3nica."},{id:"ns_0943",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una presi\xF3n est\xE1tica de retorno de 0.6 pulg. W.C. El dise\xF1o es 0.2. \xBFConsecuencia?",opciones:["Ruido excesivo, bajo flujo de aire y posible falla del motor del soplador.","Aumento en la eficiencia del intercambio de calor por la velocidad del aire.","Menor consumo el\xE9ctrico del motor al tener una restricci\xF3n en la succi\xF3n hoy.","Mejora en la deshumidificaci\xF3n del ambiente al pasar el aire m\xE1s lento hoy."],respuesta_correcta:0,explicacion:'Una presi\xF3n est\xE1tica de retorno de 0.6" W.C. (tres veces el dise\xF1o de 0.2") causa restricci\xF3n severa del flujo de aire, ruido excesivo por turbulencia, y sobrecarga del motor del soplador que puede resultar en falla prematura del motor.'},{id:"ns_0944",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el 'Check Valve' de la unidad interior falla abierta?",opciones:["En modo refrigeraci\xF3n, el refrigerante har\xE1 bypass a la TXV y no enfriar\xE1.","En modo calefacci\xF3n, el sistema se bloquear\xE1 por alta presi\xF3n de descarga.","El aceite se quedar\xE1 atrapado en el evaporador y el compresor fallar\xE1 hoy.","La v\xE1lvula inversora no podr\xE1 cambiar de posici\xF3n por falta de diferencial."],respuesta_correcta:0,explicacion:"La check valve interior permite bypass en modo calefaccion. Si falla abierta (stuck open), en modo refrigeracion el refrigerante hace bypass a la TXV interior, eliminando la restriccion necesaria para enfriar."},{id:"ns_0945",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior observa que un Junior no usa 'Brazing Shield' al soldar. \xBFRiesgo?",opciones:["Da\xF1o t\xE9rmico a componentes sensibles como v\xE1lvulas o aislamiento de cables.","Que la soldadura de plata no se adhiera correctamente por falta de calor hoy.","Aumento del consumo de ox\xEDgeno y acetileno durante el proceso de soldadura.","La formaci\xF3n de \xF3xido en la superficie externa de la tuber\xEDa de cobre hoy."],respuesta_correcta:0,explicacion:"El brazing shield (escudo t\xE9rmico) protege componentes adyacentes del calor intenso de la antorcha. Sin \xE9l, v\xE1lvulas con sellos internos, aislamiento de cables y otros materiales sensibles pueden sufrir da\xF1o t\xE9rmico irreversible."},{id:"ns_0946",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de 'Leaving Water' descalibrado (marca menos). \xBFRiesgo?",opciones:["Congelaci\xF3n de los tubos del evaporador debido a un set-point real bajo.","El compresor se apagar\xE1 por alta presi\xF3n antes de alcanzar la temperatura.","La unidad de purga operar\xE1 innecesariamente expulsando gas al ambiente hoy.","Aumento en el consumo de energ\xEDa el\xE9ctrica por ciclos de carga excesivos hoy."],respuesta_correcta:0,explicacion:"Un sensor de leaving water que marca menos de lo real hace que el controlador siga enfriando m\xE1s all\xE1 del set-point verdadero, arriesgando congelaci\xF3n de los tubos del evaporador."},{id:"ns_0947",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 indica una temperatura de descarga de 250\xB0F constante?",opciones:["Problema grave de sobrecalentamiento de succi\xF3n o falla interna del compresor.","Operaci\xF3n normal para un rack que usa R-404A en condiciones de carga alta.","Que el enfriador de aceite del rack paralelo est\xE1 funcionando perfectamente.","Falta de refrigerante l\xEDquido en el recibidor que impide el enfriamiento hoy."],respuesta_correcta:0,explicacion:"Una descarga de 250\xB0F constante con R-404A es anormalmente alta (normal: 150-200\xB0F). Esto indica sobrecalentamiento severo de succi\xF3n, posible falla de la v\xE1lvula Quench, o da\xF1o en las v\xE1lvulas internas del compresor que causan re-compresi\xF3n."},{id:"ns_0948",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere aumentar el 'Referral Rate'. \xBFQu\xE9 acci\xF3n es la m\xE1s efectiva?",opciones:["Ofrecer una recompensa o descuento tanto al que refiere como al nuevo cliente.","Pagar por anuncios en el peri\xF3dico local para que la gente conozca la marca.","Reducir el precio de todos los servicios para que los clientes hablen bien.","Contratar a un vendedor de puerta en puerta para buscar clientes referidos."],respuesta_correcta:0,explicacion:"Un programa de referidos que recompensa a ambas partes (quien refiere y el nuevo cliente) crea un ciclo virtuoso de recomendaciones que reduce el costo de adquisici\xF3n."},{id:"ns_0949",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta una vibraci\xF3n en la frecuencia de paso de \xE1labes. \xBFCausa?",opciones:["Alineaci\xF3n incorrecta del impulsor o flujo de gas turbulento en la entrada.","Desgaste natural de los cojinetes de rodillos del motor de alta velocidad.","Falta de aceite en el sistema de lubricaci\xF3n por inyecci\xF3n del compresor hoy.","El variador de frecuencia est\xE1 generando arm\xF3nicos que afectan al motor hoy."],respuesta_correcta:0,explicacion:"La vibraci\xF3n a la frecuencia de paso de \xE1labes (BPF) se relaciona con problemas de alineaci\xF3n del impulsor o flujo de gas turbulento en la entrada que genera pulsaciones r\xEDtmicas."},{id:"ns_0950",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 420 PSI. El aire sale a 65\xB0F. \xBFProblema?",opciones:["Bajo flujo de aire o carga de refrigerante ligeramente baja.","Funcionamiento normal considerando la temperatura exterior de 100 grados hoy.","Exceso de carga de refrigerante que inunda el serpent\xEDn del condensador hoy.","Compresor con v\xE1lvulas da\xF1adas que no logran enfriar el aire correctamente."],respuesta_correcta:0,explicacion:"Temperatura de suministro de 65\xB0F (deber\xEDa ser ~55\xB0F) con descarga elevada de 420 PSI indica que el evaporador no transfiere calor eficientemente. Bajo flujo de aire por filtros sucios o falta leve de refrigerante son las causas m\xE1s probables."},{id:"ns_0951",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir la 'Liquidez Inmediata'. \xBFQu\xE9 m\xE9trica utiliza?",opciones:["Cash Ratio (Efectivo y equivalentes dividido por pasivos corrientes).","Gross Profit Margin (Margen bruto sobre ventas totales del periodo actual).","Return on Investment (Retorno sobre la inversi\xF3n de las nuevas camionetas).","Debt-to-Equity Ratio (Relaci\xF3n entre deuda total y capital de los socios)."],respuesta_correcta:0,explicacion:"El Cash Ratio (efectivo y equivalentes / pasivos corrientes) mide la capacidad inmediata de pagar deudas solo con el efectivo disponible, siendo la m\xE9trica de liquidez m\xE1s estricta."},{id:"ns_0952",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un sensor de flujo tipo 'Diferencial de Presi\xF3n'. El valor es 0 PSI con bomba ON. \xBFCausa?",opciones:["L\xEDneas de impulsi\xF3n del sensor tapadas o bomba girando en sentido inverso.","Carga de refrigerante insuficiente que impide la presi\xF3n en el evaporador.","El variador de frecuencia de la bomba est\xE1 operando a su frecuencia m\xEDnima.","Existe aire atrapado en la carcasa del compresor centr\xEDfugo del sistema hoy."],respuesta_correcta:0,explicacion:"Con la bomba encendida y diferencial de 0 PSI, las l\xEDneas de impulsi\xF3n del sensor est\xE1n tapadas (no leen presi\xF3n) o la bomba gira en sentido inverso (no genera diferencial de presi\xF3n)."},{id:"ns_0953",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un equipo donde se instal\xF3 un compresor de 2 HP en lugar de 2.5 HP. \xBFEfecto?",opciones:["El compresor operar\xE1 con sobrecarga constante y fallar\xE1 prematuramente.","El sistema ser\xE1 m\xE1s eficiente al reducir el consumo el\xE9ctrico total hoy.","La v\xE1lvula de expansi\xF3n compensar\xE1 la diferencia de capacidad sin problemas.","El evaporador se congelar\xE1 debido a que el compresor succiona menos gas."],respuesta_correcta:0,explicacion:"Un compresor subdimensionado debe trabajar m\xE1s tiempo y m\xE1s duro para intentar satisfacer la demanda de enfriamiento, operando en sobrecarga constante. Esto eleva el amperaje, sobrecalienta el motor y reduce dr\xE1sticamente su vida \xFAtil."},{id:"ns_0954",categoria:"NATE_SR_RACK",pregunta:"En un rack paralelo, \xBFcu\xE1l es la funci\xF3n de la v\xE1lvula reguladora de presi\xF3n de evaporaci\xF3n (EPR)?",opciones:["Mantener una presi\xF3n m\xEDnima en el evaporador para controlar la temperatura de la vitrina.","Evitar que el refrigerante l\xEDquido regrese al cabezal de succi\xF3n del rack paralelo hoy.","Aumentar la presi\xF3n de descarga de los compresores de la etapa de baja presi\xF3n hoy.","Regular el flujo de aceite desde el separador hacia los c\xE1rteres de los motores hoy."],respuesta_correcta:0,explicacion:"La EPR se instala en la l\xEDnea de succi\xF3n de cada evaporador para mantener una presi\xF3n m\xEDnima constante, independientemente de la presi\xF3n de succi\xF3n del rack. Esto controla la temperatura del evaporador y evita que el producto se congele en vitrinas de media temperatura."},{id:"ns_0955",categoria:"NATE_SR_CEO",pregunta:"Un CEO HVAC quiere reducir el 'Average Response Time'. \xBFQu\xE9 medida toma?",opciones:["Implementar software de despacho inteligente y zonificaci\xF3n de t\xE9cnicos hoy.","Aumentar el n\xFAmero de t\xE9cnicos en la n\xF3mina aunque no haya llamadas hoy.","Reducir el tiempo de almuerzo de los t\xE9cnicos para que est\xE9n m\xE1s disponibles.","Cobrar una tarifa extra por emergencias para reducir la cantidad de llamadas hoy."],respuesta_correcta:0,explicacion:"El software de despacho inteligente con zonificaci\xF3n geogr\xE1fica es la soluci\xF3n m\xE1s efectiva para reducir el Average Response Time de manera sistem\xE1tica."},{id:"ns_0956",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no calienta bien. El voltaje entre S2 y S3 es 24VDC fijos. \xBFCausa?",opciones:["Falla de comunicaci\xF3n; el voltaje deber\xEDa fluctuar entre 0 y 24VDC hoy hoy.","La placa exterior est\xE1 operando correctamente enviando la se\xF1al de control hoy.","El compresor inverter est\xE1 aterrizado y consume el voltaje de comunicaci\xF3n.","Falta de alimentaci\xF3n de 240VAC en los terminales L1 y L2 de la exterior hoy."],respuesta_correcta:0,explicacion:"La se\xF1al de comunicaci\xF3n S2-S3 debe ser DC pulsante (0-24V). Un voltaje fijo de 24VDC indica que no hay modulaci\xF3n de datos entre las unidades, confirmando una falla de comunicaci\xF3n."},{id:"ns_0957",categoria:"NATE_SR_HEATPUMP",pregunta:"En una bomba de calor, \xBFqu\xE9 sucede si el 'Defrost Sensor' falla en circuito abierto?",opciones:["El sistema nunca entrar\xE1 en modo de deshielo y el serpent\xEDn se congelar\xE1.","El sistema entrar\xE1 en modo de deshielo cada 30 minutos sin importar el hielo.","El compresor se quemar\xE1 debido a la falta de control de sobrecalentamiento hoy.","La unidad operar\xE1 solo en modo refrigeraci\xF3n permanentemente por seguridad hoy."],respuesta_correcta:0,explicacion:"Con el defrost sensor en circuito abierto, la placa no recibe lectura de temperatura del serpentin exterior. Sin cumplir la condicion de temperatura baja, el ciclo de deshielo nunca se activa y el hielo se acumula."},{id:"ns_0958",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior revisa un sistema VRF. \xBFPor qu\xE9 es vital pesar la carga?",opciones:["Los sistemas VRF son de carga cr\xEDtica y las presiones no son indicadores.","Es un requisito legal de la EPA para sistemas con m\xE1s de 50 libras de gas.","Para asegurar que el aceite POE regrese correctamente a los compresores hoy.","Para evitar que la garant\xEDa del fabricante se anule tras la instalaci\xF3n hoy."],respuesta_correcta:0,explicacion:"Los sistemas VRF operan con compresores inverter que modulan velocidad continuamente, causando fluctuaciones normales de presi\xF3n. Por ello, el m\xE9todo de presiones es in\xFAtil y se debe pesar la carga seg\xFAn las especificaciones del fabricante."},{id:"ns_0959",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una falla de 'Phase Reversal'. \xBFQu\xE9 sucede si se ignora el error?",opciones:["El compresor girar\xE1 al rev\xE9s y no bombear\xE1 aceite ni refrigerante l\xEDquido.","La unidad funcionar\xE1 al 50% de su capacidad nominal debido al desfase fase.","El motor se quemar\xE1 instant\xE1neamente al intentar vencer la inercia carga hoy.","Las v\xE1lvulas de expansi\xF3n se cerrar\xE1n por seguridad al detectar el error hoy."],respuesta_correcta:0,explicacion:"La inversi\xF3n de fases causa rotaci\xF3n inversa del compresor centr\xEDfugo, impidiendo la circulaci\xF3n de aceite y refrigerante, lo que resulta en da\xF1o mec\xE1nico por falta de lubricaci\xF3n."},{id:"ns_0960",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 110 PSI y descarga de 350 PSI. Subenfriamiento 0\xB0F. \xBFCausa?",opciones:["Falta de refrigerante l\xEDquido severa en el sistema (Undercharged) hoy hoy.","V\xE1lvula de expansi\xF3n (TXV) fallida en la posici\xF3n de abierta total hoy hoy.","Condensador exterior extremadamente sucio que no permite el intercambio t\xE9rmico.","Evaporador interior congelado que bloquea el flujo de calor totalmente hoy hoy."],respuesta_correcta:0,explicacion:"Subenfriamiento de 0\xB0F confirma falta severa de refrigerante. Sin suficiente masa de refrigerante, el condensador entrega mezcla bif\xE1sica en lugar de l\xEDquido subenfriado, afectando todo el rendimiento del ciclo de refrigeraci\xF3n."},{id:"ns_0961",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico vende piezas usadas como nuevas. \xBFAcci\xF3n?",opciones:["Despido inmediato y pol\xEDtica de cero tolerancia para proteger la reputaci\xF3n.","Advertencia verbal indicando que debe informar al cliente si la pieza es usada.","Ignorar si el cliente no se queja y el equipo funciona correctamente hoy hoy.","Pedirle que compense la diferencia de precio al cliente en la pr\xF3xima visita."],respuesta_correcta:0,explicacion:"Vender piezas usadas como nuevas es fraude al cliente; la pol\xEDtica de cero tolerancia con despido inmediato protege la reputaci\xF3n y la integridad del negocio."},{id:"ns_0962",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Oil Loss' excesivo. El eductor est\xE1 limpio. \xBFQu\xE9 revisa?",opciones:["Operaci\xF3n constante a carga muy baja que impide el arrastre de aceite.","Si el compresor est\xE1 girando a m\xE1s RPM de las indicadas por el variador hoy.","La temperatura del evaporador que es demasiado alta para separar el aceite.","Si la unidad de purga est\xE1 extrayendo aceite junto con los incondensables hoy."],respuesta_correcta:0,explicacion:"La operaci\xF3n constante a carga muy baja reduce el arrastre de aceite por el gas de succi\xF3n. El aceite se acumula en el evaporador y no retorna al compresor, causando p\xE9rdida progresiva."},{id:"ns_0963",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera una auditor\xEDa de seguridad. \xBFQu\xE9 falta en una escalera es 'roja'?",opciones:["Fisuras visibles en los rieles laterales o pelda\xF1os con grasa/aceite.","Que la escalera sea de fibra de vidrio en lugar de aluminio ligero hoy.","La falta de la etiqueta con el nombre del t\xE9cnico due\xF1o de la herramienta.","Que el \xE1ngulo de inclinaci\xF3n sea de 70 grados en lugar de los 75 nominales."],respuesta_correcta:0,explicacion:"Fisuras en los rieles comprometen la integridad estructural de la escalera, y grasa o aceite en los pelda\xF1os causa resbalones. Ambas son condiciones de 'bandera roja' que requieren retirar la escalera del servicio inmediatamente por riesgo de ca\xEDda."},{id:"ns_0964",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 indica una presi\xF3n de aceite que fluct\xFAa con la presi\xF3n de succi\xF3n?",opciones:["Falla en la v\xE1lvula diferencial de aceite o bomba de aceite desgastada.","Operaci\xF3n normal ya que la bomba depende de la presi\xF3n de base del sistema.","Que el separador de aceite est\xE1 retornando gas caliente al c\xE1rter del motor.","Presencia de aire en las l\xEDneas de lubricaci\xF3n que causa cavitaci\xF3n hoy."],respuesta_correcta:0,explicacion:"La presi\xF3n neta de aceite debe ser independiente de la presi\xF3n de succi\xF3n (diferencial constante). Si fluct\xFAa con la succi\xF3n, la v\xE1lvula diferencial no est\xE1 regulando correctamente, o la bomba de aceite est\xE1 desgastada y no mantiene el diferencial."},{id:"ns_0965",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir el 'Technician ROI'. \xBFQu\xE9 datos combina?",opciones:["Ingresos generados y callbacks versus el costo total de compensaci\xF3n (Burden).","N\xFAmero de clientes nuevos atra\xEDdos versus el costo de marketing del mes hoy.","Horas trabajadas versus millas recorridas por la camioneta asignada hoy hoy.","La calificaci\xF3n de Google Reviews versus el n\xFAmero de uniformes comprados."],respuesta_correcta:0,explicacion:"El Technician ROI combina los ingresos generados y los callbacks (calidad) versus el costo total de compensaci\xF3n (Burden), dando una visi\xF3n completa del retorno por t\xE9cnico."},{id:"ns_0966",categoria:"NATE_SR_HVAC",pregunta:"Un sistema comercial con dampers multizona tiene una zona siempre caliente. \xBFQu\xE9 revisa?",opciones:["El actuador del damper de esa zona y la se\xF1al de 24V/0-10V del termostato.","La carga de refrigerante del chiller principal que alimenta a la manejadora.","Si el motor del soplador est\xE1 girando a la velocidad m\xE1xima permitida hoy.","La presi\xF3n est\xE1tica del conducto de retorno general del sistema de aire hoy."],respuesta_correcta:0,explicacion:"En un sistema multizona, si una zona siempre est\xE1 caliente, el problema m\xE1s probable es que el damper de esa zona no est\xE1 abriendo. Verificar el actuador del damper y la se\xF1al de control (24V o 0-10V) del termostato zonal es el paso diagn\xF3stico correcto."},{id:"ns_0967",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene un approach de evaporador negativo. \xBFC\xF3mo lo interpreta el Senior?",opciones:["Error en la calibraci\xF3n de sensores de temperatura o presi\xF3n de succi\xF3n.","Transferencia t\xE9rmica perfecta que excede los l\xEDmites te\xF3ricos de dise\xF1o.","El flujo de agua es tan alto que no permite la estabilizaci\xF3n t\xE9rmica hoy.","El sensor de temperatura de salida est\xE1 tocando una superficie caliente hoy."],respuesta_correcta:0,explicacion:"Un approach de evaporador negativo viola las leyes de la termodin\xE1mica en condiciones normales. Siempre indica error de calibraci\xF3n en sensores de temperatura o presi\xF3n del sistema."},{id:"ns_0968",categoria:"NATE_SR_MINISPLIT",pregunta:"Un VRF muestra error de 'Communication - Indoor Unit missing'. \xBFQu\xE9 es lo primero?",opciones:["Verificar alimentaci\xF3n el\xE9ctrica de esa unidad y fusibles de su placa hoy.","Cambiarlos cables de comunicaci\xF3n de todo el bus por cables blindados hoy.","Resetear el direccionamiento de todas las unidades desde la exterior hoy.","Reemplazar la placa electr\xF3nica de la unidad exterior asumiendo fallo hoy."],respuesta_correcta:0,explicacion:"Cuando una unidad interior 'desaparece' del bus de comunicaci\xF3n VRF, lo primero es verificar que tenga alimentaci\xF3n el\xE9ctrica y que los fusibles de su placa est\xE9n intactos antes de buscar problemas de comunicaci\xF3n."},{id:"ns_0969",categoria:"NATE_SR_MANAGEMENT",pregunta:"Al realizar un retrofit de R-22 a R-407C, el Senior exige cambiar el aceite. \xBFRaz\xF3n?",opciones:["El aceite mineral no retorna con HFC y causar\xE1 falla de lubricaci\xF3n pronto.","El R-407C descompone qu\xEDmicamente el aceite mineral en pocos d\xEDas de uso.","El aceite POE es necesario para aumentar la presi\xF3n de descarga del sistema.","Las v\xE1lvulas de expansi\xF3n t\xE9rmicas solo funcionan con aceite de poliol\xE9ster."],respuesta_correcta:0,explicacion:"Los refrigerantes HFC como el R-407C no son miscibles con aceite mineral. Sin miscibilidad, el aceite se queda atrapado en el evaporador y no retorna al compresor, causando falla de lubricaci\xF3n que destruye los cojinetes y las partes m\xF3viles."},{id:"ns_0970",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir el 'Callbacks Rate' al 1%. \xBFQu\xE9 inversi\xF3n es vital?",opciones:["Procesos de Control de Calidad (QC) post-instalaci\xF3n y entrenamiento t\xE9cnico.","Comprar herramientas de marca premium para todos los t\xE9cnicos del equipo hoy.","Aumentar el salario de los t\xE9cnicos para que trabajen con m\xE1s motivaci\xF3n hoy.","Contratar a un supervisor que revise f\xEDsicamente cada trabajo terminado hoy hoy."],respuesta_correcta:0,explicacion:"Reducir callbacks al 1% requiere procesos de Control de Calidad post-instalaci\xF3n y entrenamiento t\xE9cnico continuo que aseguren que cada trabajo se haga correctamente la primera vez."},{id:"ns_0971",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller centr\xEDfugo presenta 'Pumping' (Surge). El Senior nota agua de torre a 45\xB0F.",opciones:["El agua est\xE1 demasiado fr\xEDa; suba la temperatura para estabilizar presiones.","El agua est\xE1 perfecta; el problema es una falta severa de carga de gas hoy.","La torre est\xE1 enviando aire al condensador junto con el agua helada hoy.","Los ventiladores de la torre est\xE1n girando en sentido contrario al dise\xF1o hoy."],respuesta_correcta:0,explicacion:"Agua de torre a 45\xB0F reduce excesivamente la presi\xF3n de condensaci\xF3n. El bajo lift causa que el compresor centr\xEDfugo entre en surge. Se debe subir la temperatura del agua para estabilizar."},{id:"ns_0972",categoria:"NATE_SR_HVAC",pregunta:"Un motor de soplador ECM est\xE1 'haciendo hunting' (sube y baja RPM). \xBFCausa?",opciones:["Alta presi\xF3n est\xE1tica o restricciones severas en el sistema de conductos.","El termostato est\xE1 enviando se\xF1ales contradictorias de velocidad a la placa.","El capacitor de marcha est\xE1 fallando y no mantiene el torque del motor hoy.","La humedad en el aire est\xE1 afectando los sensores magn\xE9ticos internos hoy."],respuesta_correcta:0,explicacion:"Los motores ECM modulan la velocidad para mantener CFM constante. Ante alta presi\xF3n est\xE1tica, el motor sube RPM para compensar, pero al llegar a su l\xEDmite oscila entre velocidades intentando alcanzar el flujo programado, causando el efecto de hunting."},{id:"ns_0973",categoria:"NATE_SR_CEO",pregunta:"Un CEO nota que el 'Direct Labor Cost' es del 45% de los ingresos. \xBFInterpretaci\xF3n?",opciones:["Costo muy alto; indica ineficiencia operativa o precios de venta muy bajos.","Porcentaje excelente que asegura rentabilidad neta superior al 25% hoy hoy.","Indica que los t\xE9cnicos venden muchos accesorios y planes de mantenimiento.","Valor irrelevante si el margen bruto de materiales es superior al 60% hoy."],respuesta_correcta:0,explicacion:"Un Direct Labor Cost del 45% de los ingresos es excesivo para la industria HVAC; indica ineficiencia operativa, exceso de tiempo no facturable o precios de venta demasiado bajos."},{id:"ns_0974",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFqu\xE9 indica una temperatura de succi\xF3n muy fr\xEDa (escarcha en cabezal)?",opciones:["Retorno de l\xEDquido que pone en riesgo la integridad de los compresores.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de enfriamiento hoy hoy.","Falta de refrigerante en el recibidor que causa expansi\xF3n prematura hoy.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n abiertas al 100% hoy hoy."],respuesta_correcta:0,explicacion:"Escarcha en el cabezal de succi\xF3n es evidencia clara de retorno de refrigerante l\xEDquido. El l\xEDquido no evaporado enfr\xEDa la tuber\xEDa por debajo de 32\xB0F, formando hielo. Esta condici\xF3n puede causar golpe de l\xEDquido y da\xF1o catastr\xF3fico en los compresores."},{id:"ns_0975",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller con R-134a tiene succi\xF3n de 35 PSI. \xBFCu\xE1l es el riesgo Senior?",opciones:["Congelaci\xF3n de los tubos del evaporador (Saturaci\xF3n bajo 32\xB0F).","Sobrecalentamiento del motor por falta de masa de refrigerante hoy hoy.","Falla mec\xE1nica por falta de lubricaci\xF3n al no haber arrastre de aceite hoy.","Aumento excesivo del consumo el\xE9ctrico al intentar comprimir gas ralo hoy."],respuesta_correcta:0,explicacion:"A 35 PSI de succi\xF3n, el R-134a satura aproximadamente a 29\xB0F, por debajo del punto de congelaci\xF3n del agua. Esto crea riesgo directo de congelar los tubos del evaporador."},{id:"ns_0976",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico reporta que termin\xF3 vac\xEDo en 10 min en sistema de 10 ton. \xBFAcci\xF3n?",opciones:["Repetir vac\xEDo; es imposible eliminar humedad profunda en ese tiempo hoy hoy.","Felicitar al t\xE9cnico por tener una bomba de vac\xEDo de 12 CFM nueva hoy hoy.","Verificar el visor de l\xEDquido para confirmar si el sistema est\xE1 seco hoy hoy.","Permitir carga si el vacu\xF3metro digital marca 450 micrones estables hoy."],respuesta_correcta:0,explicacion:"Un sistema de 10 toneladas tiene un volumen interno grande donde la humedad se adhiere a superficies y se disuelve en el aceite. Diez minutos de vac\xEDo son f\xEDsicamente insuficientes para que toda esa humedad se evapore y sea evacuada."},{id:"ns_0977",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere medir 'Customer Churn'. \xBFQu\xE9 m\xE9trica monitorea m\xE1s hoy?",opciones:["Tasa de cancelaci\xF3n de contratos de mantenimiento vs renovaciones hoy hoy.","Cantidad de llamadas de emergencia recibidas durante la temporada alta hoy.","N\xFAmero de me gusta y comentarios positivos en la p\xE1gina de Facebook hoy.","El margen de utilidad de cada contrato de mantenimiento preventivo vendido."],respuesta_correcta:0,explicacion:"La tasa de cancelaci\xF3n de contratos de mantenimiento vs. renovaciones mide directamente el Customer Churn, mostrando cu\xE1ntos clientes recurrentes se pierden en cada periodo."},{id:"ns_0978",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se instalan solenoides en l\xEDnea de l\xEDquido de cada vitrina?",opciones:["Controlar temperatura mediante el corte del flujo de refrigerante hoy hoy.","Evitar que el aceite se acumule en el evaporador durante la operaci\xF3n hoy.","Aumentar el subenfriamiento del gas antes de entrar a la v\xE1lvula TXV hoy.","Proteger al compresor de un posible retorno de l\xEDquido en el arranque hoy."],respuesta_correcta:0,explicacion:"Las solenoides de l\xEDquido individuales permiten un control independiente de cada vitrina cortando el suministro de refrigerante cuando se alcanza la temperatura deseada. Esto implementa el control por pump-down y evita alimentaci\xF3n innecesaria."},{id:"ns_0979",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene una purga manual. El t\xE9cnico purga pero presi\xF3n no baja. \xBFCausa?",opciones:["Aire atrapado y el gas expulsado es mezcla de aire y refrigerante hoy hoy.","La purga est\xE1 en el punto m\xE1s bajo del condensador por error t\xE9cnico hoy.","El refrigerante es de tipo azeotr\xF3pico y no se separa de incondensables.","La temperatura del agua de torre es demasiado alta para purgar aire hoy hoy."],respuesta_correcta:0,explicacion:"Al purgar, el aire atrapado se mezcla con refrigerante y sale como mezcla gaseosa. La presi\xF3n no baja porque la presi\xF3n parcial del aire restante sigue siendo significativa en el sistema."},{id:"ns_0980",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene una succi\xF3n de 125 PSI y descarga de 450 PSI. \xBFEstado?",opciones:["Sistema con exceso de carga de refrigerante (Overcharged) hoy hoy hoy hoy.","Falta de refrigerante l\xEDquido que impide que descarga suba a 500 PSI hoy.","Restricci\xF3n en el dispositivo de expansi\xF3n que eleva la presi\xF3n de alta hoy.","Compresor perdiendo eficiencia volum\xE9trica por desgaste de los pistones hoy."],respuesta_correcta:0,explicacion:"Succi\xF3n de 125 PSI con descarga alta de 450 PSI y subenfriamiento elevado indica exceso de refrigerante. El condensador est\xE1 parcialmente inundado de l\xEDquido, reduciendo su \xE1rea de condensaci\xF3n efectiva y elevando la presi\xF3n de descarga."},{id:"ns_0981",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller de tornillo presenta 'Oil Foaming'. \xBFQu\xE9 da\xF1o Senior previene?",opciones:["Falla de lubricaci\xF3n en rodamientos y posible cavitaci\xF3n de la bomba hoy hoy.","Aumento en la presi\xF3n de condensaci\xF3n por exceso de aceite en el sistema.","Congelaci\xF3n de los tubos del evaporador al bajar la temperatura de ebullici\xF3n.","Desgaste prematuro de los \xE1labes del compresor centr\xEDfugo por impacto hoy."],respuesta_correcta:0,explicacion:"La espuma de aceite (oil foaming) impide que la bomba de aceite suministre lubricante a los rodamientos y puede causar cavitaci\xF3n de la bomba, resultando en falla de lubricaci\xF3n."},{id:"ns_0982",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un t\xE9cnico Senior observa que un ayudante sold\xF3 sin nitr\xF3geno. \xBFConsecuencia?",opciones:["Formaci\xF3n de holl\xEDn (soot) que tapar\xE1 filtros y orificios de expansi\xF3n hoy.","Que la soldadura de plata no se adhiera al cobre por falta de ox\xEDgeno hoy.","El cobre se volver\xE1 quebradizo y fallar\xE1 mec\xE1nicamente por el calor hoy hoy.","No hay consecuencia t\xE9cnica si la tuber\xEDa es de menos de 1/2 pulgada hoy hoy."],respuesta_correcta:0,explicacion:"Soldar sin purga de nitr\xF3geno permite que el ox\xEDgeno atrapado reaccione con el cobre caliente, formando holl\xEDn (soot/escamas de \xF3xido c\xFAprico). Estas part\xEDculas circulan y obstruyen filtros deshidratadores y orificios de v\xE1lvulas de expansi\xF3n."},{id:"ns_0983",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere reducir 'Vehicle Downtime'. \xBFQu\xE9 acci\xF3n es la m\xE1s efectiva hoy?",opciones:["Programa de mantenimiento preventivo riguroso y flota de reserva m\xEDnima.","Obligar a los t\xE9cnicos a reparar sus propias camionetas el fin de semana.","Comprar solo veh\xEDculos usados para reducir el impacto financiero inicial hoy.","Eliminar el uso de GPS para evitar que t\xE9cnicos conduzcan distancias largas."],respuesta_correcta:0,explicacion:"Un mantenimiento preventivo riguroso de la flota combinado con veh\xEDculos de reserva m\xEDnima asegura disponibilidad continua y minimiza el Vehicle Downtime."},{id:"ns_0984",categoria:"NATE_SR_RACK",pregunta:"En un rack, \xBFpor qu\xE9 se usa una v\xE1lvula 'Quench' o inyecci\xF3n de l\xEDquido?",opciones:["Para enfriar gas de succi\xF3n y evitar que descarga da\xF1e el aceite hoy hoy hoy.","Para aumentar la presi\xF3n de succi\xF3n cuando carga en vitrinas es baja hoy hoy.","Para limpiar el interior de compresores de acumulaciones de carbonilla hoy.","Para ayudar al retorno de aceite desde los evaporadores m\xE1s lejanos hoy hoy."],respuesta_correcta:0,explicacion:"La v\xE1lvula de inyecci\xF3n Quench es un control de seguridad que limita la temperatura de descarga. Al evaporar refrigerante l\xEDquido en la l\xEDnea de succi\xF3n o descarga, absorbe calor excesivo y mantiene el aceite dentro de su rango de estabilidad t\xE9rmica."},{id:"ns_0985",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller presenta 'Flow Switch Alarm' con bomba ON. \xBFQu\xE9 revisa el Senior?",opciones:["Paddle roto, aire en la tuber\xEDa o sensor diferencial descalibrado hoy hoy.","La carga de refrigerante que podr\xEDa estar congelando el agua en tubos hoy.","El sentido de rotaci\xF3n del motor del compresor centr\xEDfugo del sistema hoy.","La apertura de las v\xE1lvulas de expansi\xF3n del circuito de refrigeraci\xF3n hoy."],respuesta_correcta:0,explicacion:"Flow Switch Alarm con bomba encendida apunta al sensor de detecci\xF3n: paddle roto, aire atrapado en la tuber\xEDa, o sensor diferencial descalibrado que genera la alarma falsamente."},{id:"ns_0986",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter gotea agua dentro solo cuando compresor para. \xBFCausa?",opciones:["Drenaje con contrapendiente o parcialmente obstruido en la parte superior.","La bomba de condensado integrada ha fallado y no puede evacuar el agua hoy.","El serpent\xEDn est\xE1 tan fr\xEDo que el agua se congela y luego se derrite r\xE1pido.","La humedad en la habitaci\xF3n es superior al 95% y satura el serpent\xEDn hoy."],respuesta_correcta:0,explicacion:"El goteo solo al parar el compresor indica contrapendiente o bloqueo parcial en el drenaje que retiene agua durante la operaci\xF3n y la libera cuando la unidad se detiene."},{id:"ns_0987",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene presi\xF3n est\xE1tica de 0.9 en suministro y 0.2 en retorno. \xBFQu\xE9 es?",opciones:["Restricci\xF3n severa en conductos de suministro o difusores cerrados hoy hoy.","Los conductos de retorno son demasiado peque\xF1os para el volumen de aire hoy.","El filtro de aire est\xE1 completamente tapado y no deja pasar el flujo hoy.","El motor del soplador est\xE1 girando en sentido contrario al de dise\xF1o hoy."],respuesta_correcta:0,explicacion:'Presi\xF3n est\xE1tica de 0.9" en suministro frente a 0.2" en retorno muestra que la restricci\xF3n del sistema est\xE1 concentrada en el lado de suministro. Conductos restringidos o difusores cerrados son la causa directa.'},{id:"ns_0988",categoria:"NATE_SR_HEATPUMP",pregunta:"Una bomba de calor tiene un Delta T de 15\xB0F en modo calor. \xBFEs aceptable?",opciones:["No, un Delta T saludable en modo calor debe estar entre 20\xB0F y 30\xB0F hoy.","S\xED, las bombas de calor siempre tienen un diferencial menor que hornos hoy.","Depende de la temperatura exterior; si hace calor afuera, el Delta T sube.","No, indica que las resistencias de apoyo no est\xE1n funcionando en el ciclo."],respuesta_correcta:0,explicacion:"Un Delta T de 15F en modo calor es inferior al rango normal de 20-30F. Refleja capacidad insuficiente, cuyas causas comunes son baja carga de refrigerante, flujo de aire excesivo o mala absorcion de calor en el serpentin exterior."},{id:"ns_0989",categoria:"NATE_SR_MANAGEMENT",pregunta:"Un Senior lidera reemplazo de compresor 10 HP. \xBFQu\xE9 paso es vital post-quemadura?",opciones:["Realizar prueba acidez aceite y usar filtros succi\xF3n de limpieza hoy hoy.","A\xF1adir aditivo sellador de fugas para prevenir fallas futuras en l\xEDneas hoy.","Cambiar el contactor y el capacitor aunque parezcan estar en buen estado.","Aumentar la carga de refrigerante un 5% para enfriar el motor nuevo hoy."],respuesta_correcta:0,explicacion:"El paso m\xE1s importante tras un burnout es evaluar la contaminaci\xF3n con una prueba de acidez del aceite e instalar filtros de succi\xF3n de limpieza. Sin estos pasos, los \xE1cidos y residuos del compresor quemado destruir\xE1n el compresor de reemplazo."},{id:"ns_0990",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene purga que marca 'Water Detected'. \xBFQu\xE9 acci\xF3n es urgente?",opciones:["Realizar prueba presi\xF3n a tubos del evaporador para buscar rupturas hoy hoy.","Cambiar el filtro deshidratador de la purga y seguir operando el sistema hoy.","Aumentar la temperatura del agua helada para evitar que vapor condense hoy.","Drenar el aceite del compresor y reemplazarlo por aceite con aditivo hoy."],respuesta_correcta:0,explicacion:"Water Detected por la purga requiere acci\xF3n urgente: prueba de presi\xF3n a los tubos del evaporador para identificar la ruptura que est\xE1 permitiendo la infiltraci\xF3n de agua al refrigerante."},{id:"ns_0991",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene succi\xF3n 130 PSI y descarga 380 PSI. Subenfriamiento 12\xB0F. \xBFEstado?",opciones:["Funcionamiento \xF3ptimo; las presiones y el subenfriamiento est\xE1n en rango.","Falta de refrigerante l\xEDquido; el subenfriamiento deber\xEDa ser 15 grados hoy.","Exceso de carga; el subenfriamiento indica que el condensador est\xE1 lleno hoy.","Compresor fallando; la diferencia presi\xF3n entre succi\xF3n y descarga es baja hoy."],respuesta_correcta:0,explicacion:"Presiones de 130/380 PSI con subenfriamiento de 12\xB0F est\xE1n dentro del rango \xF3ptimo para R-410A. El subenfriamiento entre 10-15\xB0F confirma carga correcta y todos los componentes funcionando adecuadamente."},{id:"ns_0992",categoria:"NATE_SR_PACKAGE",pregunta:"En unidad paquete, contactor compresor zumba pero no cierra. \xBFQu\xE9 revisa?",opciones:["Voltaje en la bobina (24V) y si hay suciedad u \xF3xido en el n\xFAcleo hoy hoy.","Si los contactos principales est\xE1n quemados o soldados entre s\xED hoy hoy hoy.","El capacitor de arranque del compresor que podr\xEDa estar descargado hoy hoy.","La continuidad de los fusibles de potencia de la l\xEDnea de 240 voltios hoy."],respuesta_correcta:0,explicacion:"El diagn\xF3stico de un contactor que zumba sin cerrar siempre comienza midiendo el voltaje de la bobina y verificando el estado mec\xE1nico del n\xFAcleo. Estas dos condiciones determinan directamente si la fuerza electromagn\xE9tica es suficiente para vencer el resorte y cerrar los contactos de potencia."},{id:"ns_0993",categoria:"NATE_SR_CEO",pregunta:"Un CEO descubre que un t\xE9cnico cobra 'por fuera' a clientes. \xBFQu\xE9 acci\xF3n toma?",opciones:["Despido inmediato y posible acci\xF3n legal seg\xFAn contrato de trabajo hoy hoy.","Hablar con el t\xE9cnico y pedirle una comisi\xF3n por esos trabajos extras hoy.","Ignorar la situaci\xF3n si el t\xE9cnico es el que m\xE1s dinero genera hoy hoy hoy.","Darle una advertencia verbal y pedirle que no lo vuelva a hacer en horas hoy."],respuesta_correcta:0,explicacion:"El cobro por fuera a clientes es fraude laboral grave; el despido inmediato con posible acci\xF3n legal seg\xFAn el contrato es la respuesta proporcional y necesaria."},{id:"ns_0994",categoria:"NATE_SR_RACK",pregunta:"Un rack usa R-448A. \xBFPor qu\xE9 es fundamental cargar l\xEDquido en recibidor?",opciones:["Para evitar fraccionamiento de mezcla y asegurar composici\xF3n correcta hoy.","Para que el refrigerante se mezcle m\xE1s r\xE1pido con aceite POE del rack hoy.","Para prevenir que v\xE1lvulas de descarga de compresores se calienten hoy hoy.","Porque el R-448A no existe en fase gaseosa a temperatura ambiente normal."],respuesta_correcta:0,explicacion:"Toda mezcla zeotr\xF3pica como el R-448A debe cargarse en fase l\xEDquida. Esto asegura que los cinco componentes de la mezcla entren al sistema en la proporci\xF3n especificada, evitando el fraccionamiento que alterar\xEDa el rendimiento del sistema."},{id:"ns_0995",categoria:"NATE_SR_CHILLERS",pregunta:"Un chiller tiene sensor de 'Entering Water' roto. \xBFEfecto Senior?",opciones:["El controlador no podr\xE1 calcular la carga t\xE9rmica real del edificio hoy hoy.","El compresor se apagar\xE1 inmediatamente por seguridad de flujo de agua hoy.","La unidad operar\xE1 siempre al 100% de su capacidad nominal sin modular hoy.","No hay efecto si el sensor de 'Leaving Water' est\xE1 operando correctamente hoy."],respuesta_correcta:0,explicacion:"Sin sensor de entering water operativo, el controlador no puede calcular la carga t\xE9rmica del edificio (Delta T), afectando directamente su capacidad de modular la operaci\xF3n del chiller."},{id:"ns_0996",categoria:"NATE_SR_HVAC",pregunta:"Un sistema tiene descarga de 550 PSI con R-410A. Condensador limpio. \xBFCausa?",opciones:["Incondensables (aire) en el sistema o ventilador exterior fallando hoy hoy.","Falta de refrigerante l\xEDquido que impide que el sistema enfr\xEDe el aire hoy.","V\xE1lvula de expansi\xF3n electr\xF3nica bloqueada en posici\xF3n de abierta total hoy.","El compresor est\xE1 perdiendo eficiencia y no logra comprimir el gas ralo hoy."],respuesta_correcta:0,explicacion:"Con condensador limpio, una descarga de 550 PSI indica incondensables (aire o nitr\xF3geno) atrapados en el sistema que elevan artificialmente la presi\xF3n, o un ventilador exterior que no funciona correctamente impidiendo la convecci\xF3n forzada necesaria."},{id:"ns_0997",categoria:"NATE_SR_CEO",pregunta:"Un CEO quiere entrar al mercado 'Smart Homes'. \xBFQu\xE9 equipo t\xE9cnico requiere?",opciones:["T\xE9cnicos capacitados en redes, protocolos de comunicaci\xF3n e integraci\xF3n hoy.","Personal experto en la instalaci\xF3n de conductos de l\xE1mina galvanizada hoy.","Instaladores de paneles solares con certificaci\xF3n el\xE9ctrica industrial hoy.","Vendedores que se enfoquen en la eficiencia SEER de los equipos b\xE1sicos hoy."],respuesta_correcta:0,explicacion:"Smart Homes necesita t\xE9cnicos capacitados en redes y protocolos de comunicaci\xF3n para integrar sistemas HVAC inteligentes con la infraestructura tecnol\xF3gica del hogar."},{id:"ns_0998",categoria:"NATE_SR_RACK",pregunta:"En rack paralelo, \xBFqu\xE9 indica una temperatura de succi\xF3n muy alta en cabezal?",opciones:["Sobrecalentamiento excesivo que da\xF1ar\xE1 la lubricaci\xF3n de compresores pronto.","Que el sistema est\xE1 operando a su m\xE1xima eficiencia de evaporaci\xF3n hoy hoy.","Falta de refrigerante l\xEDquido en recibidor principal del rack paralelo hoy.","Que las v\xE1lvulas EPR de todas las vitrinas est\xE1n cerradas por temperatura."],respuesta_correcta:0,explicacion:"Un sobrecalentamiento excesivo en el cabezal de succi\xF3n significa que los compresores operan con gas demasiado caliente, lo que reduce la capacidad lubricante del aceite, aumenta la temperatura de descarga y puede da\xF1ar permanentemente los devanados del motor."},{id:"ns_0999",categoria:"NATE_SR_MINISPLIT",pregunta:"Un mini-split inverter no calienta. Voltaje entre S2 y S3 es 24V fijos. \xBFCausa?",opciones:["Falla de comunicaci\xF3n; el voltaje deber\xEDa fluctuar entre 0 y 24V hoy hoy hoy.","La placa exterior est\xE1 operando correctamente enviando la se\xF1al de control.","El compresor inverter est\xE1 aterrizado y consume el voltaje de comunicaci\xF3n.","Falta de alimentaci\xF3n de 240VAC en los terminales L1 y L2 de la exterior hoy."],respuesta_correcta:0,explicacion:"La comunicaci\xF3n inverter entre S2 y S3 usa voltaje DC pulsante. Un valor fijo de 24V indica que no hay modulaci\xF3n de se\xF1al, confirmando una falla de comunicaci\xF3n digital entre las unidades."},{id:"ns_1000",categoria:"NATE_SR_PACKAGE",pregunta:"Para un CEO/Senior, \xBFcu\xE1l es el indicador de \xE9xito t\xE9cnico y comercial definitivo?",opciones:["Cero callbacks, alta rentabilidad neta y t\xE9cnicos certificados en formaci\xF3n.","Tener la mayor cantidad de clientes en la base de datos de la ciudad hoy.","Comprar la flota de camionetas m\xE1s modernas cada a\xF1o de forma constante hoy.","Que el termostato del cliente siempre marque 72 grados sin importar el clima."],respuesta_correcta:0,explicacion:"Cero callbacks significa trabajo hecho correctamente la primera vez, alta rentabilidad refleja eficiencia operativa, y t\xE9cnicos certificados en formaci\xF3n aseguran crecimiento sostenible. Estos tres indicadores combinan calidad t\xE9cnica con visi\xF3n empresarial a largo plazo."}],NATE_SR_CATEGORIAS={NATE_SR_CHILLERS:{nombre:"Chillers",en:"Chillers",icon:"\u{1F3ED}",color:"#0277BD",count:180},NATE_SR_RACK:{nombre:"Rack & Refrigeraci\xF3n Comercial",en:"Rack & Commercial Refrigeration",icon:"\u{1F9CA}",color:"#00838F",count:142},NATE_SR_HVAC:{nombre:"HVAC Central & Controles",en:"Central HVAC & Controls",icon:"\u{1F3E0}",color:"#2E7D32",count:147},NATE_SR_MINISPLIT:{nombre:"Mini-Splits & VRF",en:"Mini-Splits & VRF",icon:"\u2744\uFE0F",color:"#1565C0",count:99},NATE_SR_HEATPUMP:{nombre:"Heat Pumps",en:"Heat Pumps",icon:"\u{1F504}",color:"#C62828",count:91},NATE_SR_PACKAGE:{nombre:"Package Units & Especialidades",en:"Package Units & Specialties",icon:"\u{1F4E6}",color:"#6A1B9A",count:64},NATE_SR_MANAGEMENT:{nombre:"Gesti\xF3n & Liderazgo",en:"Management & Leadership",icon:"\u{1F477}",color:"#E65100",count:99},NATE_SR_CEO:{nombre:"CEO & Estrategia Empresarial",en:"CEO & Business Strategy",icon:"\u{1F4BC}",color:"#37474F",count:178}};
